System.out.println(s.charAt(s.length() - 1));
System.out.println(s.substring(1, 3));</pre><div style="border-left:3px solid var(--accent); background:var(--surface-2); padding:8px 12px; margin:8px 0 4px; font-family:ui-monospace,Menlo,monospace; font-size:12.5px; white-space:pre-wrap;">4
