lo,monospace">a</text><rect x="240" y="28" width="50" height="36" rx="5" fill="none" stroke="var(--text)" stroke-width="1.4"/><text x="265" y="50" fill="var(--text)" font-size="13" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">7</text><text x="265" y="78" fill="var(--text-3)" font-size="11" font-weight="400" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">b</text><rect x="210" y="92" width="50" height="30" rx="5" fill="none" stroke="#0ea5e9" stroke-width="1.4" stroke-dasharray="4 3"/><text x="235" y="111" fill="#0ea5e9" font-size="12" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">3</text><text x="235" y="134" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">temp</text><text x="395" y="18" fill="var(--text)" font-size="10.5" font-weight="700" text-anchor="middle">③ b = temp;</text><rect x="340" y="28" width="50" height="36" rx="5" fill="none" stroke="var(--text)" stroke-width="1.4"/><text x="365" y="50" fill="var(--text)" font-size="13" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">7</text><text x="365" y="78" fill="var(--text-3)" font-size="11" font-weight="400" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">a</text><rect x="400" y="28" width="50" height="36" rx="5" fill="none" stroke="var(--text)" stroke-width="1.4"/><text x="425" y="50" fill="var(--text)" font-size="13" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">3</text><text x="425" y="78" fill="var(--text-3)" font-size="11" font-weight="400" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">b</text><rect x="370" y="92" width="50" height="30" rx="5" fill="none" stroke="#0ea5e9" stroke-width="1.4" stroke-dasharray="4 3"/><text x="395" y="111" fill="#0ea5e9" font-size="12" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">3</text><text x="395" y="134" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">temp</text><text x="235" y="158" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-style="italic">Without temp, step ② destroys the 3 — both variables end up 7. The spare box preserves it.</text></svg></div></div><i data-tbd286bz56="1" style="display:none"></i><div class="vl" data-mathvis="1" data-c959fig="1" style="margin-top:18px;"><div style="font-weight:700; font-size:12.5px; letter-spacing:0.05em; margin-bottom:6px;">📊 FIGURE — the same swap done to two slots of one array</div><div style="border:1px solid var(--border); border-radius:12px; background:var(--surface-2); padding:14px 10px; overflow-x:auto;"><svg viewBox="0 0 680 376" style="width:100%; max-width:680px; display:block; margin:0 auto; font-family:inherit;" xmlns="http://www.w3.org/2000/svg"><defs><marker id="fk241a" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0,1 L9,5 L0,9 z" fill="var(--text)"/></marker></defs><text x="340" y="24" fill="var(--text)" font-size="12.5" font-weight="700" text-anchor="middle">the same three statements, now addressing array slots</text><text x="20" y="78" fill="var(--text-3)" font-size="11.5" font-weight="700" text-anchor="start" font-family="ui-monospace,Menlo,monospace">before</text><rect x="178" y="58" width="54" height="36" rx="7" fill="rgba(14,165,233,0.13)" stroke="#0ea5e9" stroke-width="1.5"/><text x="205" y="81" fill="var(--text)" font-size="13" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">4</text><text x="205" y="110" fill="#0ea5e9" font-size="10" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">[0]</text><rect x="240" y="58" width="54" height="36" rx="7" fill="rgba(14,165,233,0.13)" stroke="#0ea5e9" stroke-width="1.5"/><text x="267" y="81" fill="var(--