hor="middle">8</text><text x="521" y="272" fill="var(--text-3)" font-size="9" font-weight="400" text-anchor="middle">9</text><text x="547" y="272" fill="var(--text-3)" font-size="9" font-weight="400" text-anchor="middle">10</text><text x="288" y="297" fill="var(--text)" font-size="11.5" font-weight="700" text-anchor="end" font-family="ui-monospace,Menlo,monospace">%f</text><rect x="300" y="278" width="26" height="28" rx="0" fill="none" stroke="var(--border)" stroke-width="1"/><text x="313" y="297" fill="var(--text)" font-size="13" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">3</text><rect x="326" y="278" width="26" height="28" rx="0" fill="none" stroke="var(--border)" stroke-width="1"/><text x="339" y="297" fill="var(--text)" font-size="13" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">.</text><rect x="352" y="278" width="26" height="28" rx="0" fill="none" stroke="var(--border)" stroke-width="1"/><text x="365" y="297" fill="var(--text)" font-size="13" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">1</text><rect x="378" y="278" width="26" height="28" rx="0" fill="none" stroke="var(--border)" stroke-width="1"/><text x="391" y="297" fill="var(--text)" font-size="13" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">4</text><rect x="404" y="278" width="26" height="28" rx="0" fill="none" stroke="var(--border)" stroke-width="1"/><text x="417" y="297" fill="var(--text)" font-size="13" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">1</text><rect x="430" y="278" width="26" height="28" rx="0" fill="none" stroke="var(--border)" stroke-width="1"/><text x="443" y="297" fill="var(--text)" font-size="13" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">5</text><rect x="456" y="278" width="26" height="28" rx="0" fill="none" stroke="var(--border)" stroke-width="1"/><text x="469" y="297" fill="var(--text)" font-size="13" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">9</text><rect x="482" y="278" width="26" height="28" rx="0" fill="none" stroke="var(--border)" stroke-width="1"/><text x="495" y="297" fill="var(--text)" font-size="13" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">0</text><rect x="508" y="278" width="26" height="28" rx="0" fill="none" stroke="var(--border)" stroke-width="1"/><rect x="534" y="278" width="26" height="28" rx="0" fill="none" stroke="var(--border)" stroke-width="1"/><text x="288" y="329" fill="var(--text)" font-size="11.5" font-weight="700" text-anchor="end" font-family="ui-monospace,Menlo,monospace">%.2f</text><rect x="300" y="310" width="26" height="28" rx="0" fill="none" stroke="var(--border)" stroke-width="1"/><text x="313" y="329" fill="var(--text)" font-size="13" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">3</text><rect x="326" y="310" width="26" height="28" rx="0" fill="none" stroke="var(--border)" stroke-width="1"/><text x="339" y="329" fill="var(--text)" font-size="13" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">.</text><rect x="352" y="310" width="26" height="28" rx="0" fill="none" stroke="var(--border)" stroke-width="1"/><text x="365" y="329" fill="var(--text)" font-size="13" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">1</text><rect x="378" y="310" width="26" height="28" rx="0" fill="none" stroke="var(--border)" stroke-width="1"/><text x="391" y="329" fill="var(--text)" font-size="13" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">4</text><rect x="404" y="310" width="26" height="28" rx="0" fill="none" stroke="var(--border)" stroke-width="1"/><rect x="430" y="310" width="26" height="28" rx="0" fill="none" stroke="var(--border)" stroke-width="1"/><rect x="456" y="310" width="26" height="28" rx="0" fill="none" stroke="var(--border)" stroke-width="1"/><rect x="482" y="310" width="26" height="28" rx="0" fill="none" stroke="var(--border)" stroke-width="1"/><rect x="508" y="310" width="26" height="28" rx="0" fill="none" stroke="var(--border)" stroke-width="1"/><rect x="534" y="310" width="26" height="28" rx="0" fill="none" stroke="var(--border)" stroke-width="1"/><text x="288" y="361" fill="var(--text)" font-size="11.5" font-weight="700" text-anchor="end" font-family="ui-monospace,Menlo,monospace">%9.2f</text><rect x="300" y="342" width="26" height="28" rx="0" fill="var(--accent-bg)" stroke="var(--border)" stroke-width="1"/><rect x="326" y="342" width="26" height="28" rx="0" fill="var(--accent-bg)" stroke="var(--border)" stroke-width="1"/><rect x="352" y="342" width="26" height="28" rx="0" fill="var(--accent-bg)" stroke="var(--border)" stroke-width="1"/><rect x="378" y="342" width="26" height="28" rx="0" fill="var(--accent-bg)" stroke="var(--border)" stroke-width="1"/><rect x="404" y="342" width="26" height="28" rx="0" fill="var(--accent-bg)" stroke="var(--border)" stroke-width="1"/><rect x="430" y="342" width="26" height="28" rx="0" fill="none" stroke="var(--border)" stroke-width="1"/><text x="443" y="361" fill="var(--text)" font-size="13" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">3</text><rect x="456" y="342" width="26" height="28" rx="0" fill="none" stroke="var(--border)" stroke-width="1"/><text x="469" y="361" fill="var(--text)" font-size="13" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">.</text><rect x="482" y="342" width="26" height="28" rx="0" fill="none" stroke="var(--border)" stroke-width="1"/><text x="495" y="361" fill="var(--text)" font-size="13" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">1</text><rect x="508" y="342" width="26" height="28" rx="0" fill="none" stroke="var(--border)" stroke-width="1"/><text x="521" y="361" fill="var(--text)" font-size="13" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">4</text><rect x="534" y="342" width="26" height="28" rx="0" fill="none" stroke="var(--border)" stroke-width="1"/><text x="288" y="393" fill="var(--text)" font-size="11.5" font-weight="700" text-anchor="end" font-family="ui-monospace,Menlo,monospace">%-9.2f</text><rect x="300" y="374" width="26" height="28" rx="0" fill="none" stroke="var(--border)" stroke-width="1"/><text x="313" y="393" fill="var(--text)" font-size="13" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">3</text><rect x="326" y="374" width="26" height="28" rx="0" fill="none" stroke="var(--border)" stroke-width="1"/><text x="339" y="393" fill="var(--text)" font-size="13" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">.</text><rect x="352" y="374" width="26" height="28" rx="0" fill="none" stroke="var(--border)" stroke-width="1"/><text x="365" y="393" fill="var(--text)" font-size="13" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">1</text><rect x="378" y="374" width="26" height="28" rx="0" fill="none" stroke="var(--border)" stroke-width="1"/><text x="391" y="393" fill="var(--text)" font-size="13" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">4</text><rect x="404" y="374" width="26" height="28" rx="0" fill="var(--accent-bg)" stroke="var(--border)" stroke-width="1"/><rect x="430" y="374" width="26" height="28" rx="0" fill="var(--accent-bg)" stroke="var(--border)" stroke-width="1"/><rect x="456" y="374" width="26" height="28" rx="0" fill="var(--accent-bg)" stroke="var(--border)" stroke-width="1"/><rect x="482" y="374" width="26" height="28" rx="0" fill="var(--accent-bg)" stroke="var(--border)" stroke-width="1"/><rect x="508" y="374" width="26" height="28" rx="0" fill="var(--accent-bg)" stroke="var(--border)" stroke-width="1"/><rect x="534" y="374" width="26" height="28" rx="0" fill="none" stroke="var(--border)" stroke-width="1"/><line x1="300" y1="262" x2="534" y2="262" stroke="var(--accent)" stroke-width="1.4"/><line x1="300" y1="256" x2="300" y2="262" stroke="var(--accent)" stroke-width="1.4"/><line x1="534" y1="256" x2="534" y2="262" stroke="var(--accent)" stroke-width="1.4"/><text x="417" y="252" fill="var(--accent)" font-size="10" font-weight="700" text-anchor="middle">field width 9</text><text x="140" y="308" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-style="italic">no width →</text><text x="140" y="323" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-style="italic">no padding</text><text x="140" y="358" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-style="italic">width 9, right-</text><text x="140" y="373" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-style="italic">aligned by default</text></svg></div></div><div class="callout" data-lb="key" style="border-left-color:#0ea5e9;"><div class="callout-label">▸ WORKED EXAMPLE — EVERY SPECIFIER, WITH THE BRACKETS SHOWN</div><p>Printing each result inside <code>[ ]</code> makes the padding visible, which is the only way to check a format string without counting spaces by hand.</p><pre style="background:var(--surface-2); border:1px solid var(--border); border-radius:8px; padding:11px 13px; overflow-x:auto; font-size:13px; line-height:1.55; margin:10px 0;"><code>double v = 3.14159;
System.out.printf("[%f]%n", v);
System.out.printf("[%.2f]%n", v);
System.out.printf("[%8.2f]%n", v);
System.out.printf("[%-8.2f]%n", v);
System.out.printf("[%d]%n", 42);
System.out.printf("[%5d]%n", 42);
System.out.printf("[%-5d]|%n", 42);
System.out.printf("[%s]%n", "Ana");
System.out.printf("[%10s]%n", "Ana");
System.out.printf("[%-10s]|%n", "Ana");
System.out.printf("[%c] [%b] [%%]%n", 'A', true);
System.out.printf("%.2f %.2f %.2f%n", 3.567, 2.5, 3.5);
System.out.printf("%.0f %.0f%n", 2.5, 3.5);</code></pre><div style="margin:9px 0 4px;"><span style="font-size:11px; font-weight:700; letter-spacing:0.05em; color:var(--text-3);">OUTPUT</span></div><pre style="background:var(--surface-3, var(--surface-2)); border-left:3px solid var(--accent); border-radius:0 8px 8px 0; padding:9px 13px; overflow-x:auto; font-size:13px; line-height:1.5; margin:0 0 10px;"><code>[3.141590]
[3.14]
[    3.14]
[3.14    ]
[42]
[   42]
[42   ]|
[Ana]
[       Ana]
[Ana       ]|
[A] [true] [%]
3.57 2.50 3.50
3 4</code></pre><ol style="margin:8px 0 4px 18px; padding:0; line-height:1.65;"><li style="margin-bottom:5px;"><strong><code>%f</code> with no precision gives six decimals</strong> — <code>3.141590</code>, not <code>3.14159</code>. That default catches people out constantly; if you want a specific number of places you must say so.</li><li style="margin-bottom:5px;"><code>%8.2f</code> produces <code>3.14</code> preceded by four spaces: the value is 4 characters and the field is 8, so 4 spaces are added <em>in front</em> because numbers are right-aligned by default.</li><li style="margin-bottom:5px;"><code>%-8.2f</code> puts the same four spaces <em>after</em>. The minus sign is a left-align flag, never a negative number.</li><li style="margin-bottom:5px;"><code>%5d</code> and <code>%-5d</code> behave identically for integers — width is width, regardless of conversion.</li><li style="margin-bottom:5px;">Strings pad the same way: <code>%10s</code> right-aligns, <code>%-10s</code> left-aligns. In practice you left-align text columns and right-align number columns, which is why a report almost always mixes them.</li><li style="margin-bottom:5px;"><strong>Rounding, not truncation.</strong> <code>3.567</code> at two places becomes <code>3.57</code>, and <code>2.5</code> and <code>3.5</code> at zero places become <code>3</code> and <code>4</code> — Java rounds half away from zero here, so <code>2.5</code> goes up rather than to the even number.</li><li style="margin-bottom:5px;"><code>%%</code> prints one literal percent sign. A single <code>%</code> followed by an ordinary letter is an unknown conversion and throws.</li></ol></div><div class="callout" data-lb="key" style="border-left-color:#0ea5e9;"><div class="callout-label">▸ WORKED EXAMPLE — AN ALIGNED REPORT, AND THE THREE WAYS IT CAN THROW</div><p>Column alignment is the reason <code>printf</code> exists. It is also the place mismatched arguments show up, and the failures are all at <em>run</em> time.</p><pre style="background:var(--surface-2); border:1px solid var(--border); border-radius:8px; padding:11px 13px; overflow-x:auto; font-size:13px; line-height:1.55; margin:10px 0;"><code>record Row(String item, int qty, double price) {}

Row[] rows = {
    new Row("Widget", 12, 4.5),
    new Row("Bracket", 3, 19.99),
    new Row("Gasket kit", 140, 0.75)
};
System.out.printf("%-12s %5s %9s %10s%n", "ITEM", "QTY", "PRICE", "TOTAL");
double grand = 0;
for (Row r : rows) {
    double line = r.qty() * r.price();
    grand += line;
    System.out.printf("%-12s %5d %9.2f %10.2f%n", r.item(), r.qty(), r.price(), line);
}
System.out.printf("%-12s %5s %9s %10.2f%n", "GRAND", "", "", grand);</code></pre><div style="margin:9px 0 4px;"><span style="font-size:11px; font-weight:700; letter-spacing:0.05em; color:var(--text-3);">OUTPUT</span></div><pre style="background:var(--surface-3, var(--surface-2)); border-left:3px solid var(--accent); border-radius:0 8px 8px 0; padding:9px 13px; overflow-x:auto; font-size:13px; line-height:1.5; margin:0 0 10px;"><code>ITEM           QTY     PRICE      TOTAL
Widget          12      4.50      54.00
Bracket          3     19.99      59.97
Gasket kit     140      0.75     105.00
GRAND                            218.97</code></pre><ol style="margin:8px 0 4px 18px; padding:0; line-height:1.65;"><li style="margin-bottom:5px;">The header uses <code>%5s</code>, <code>%9s</code> and <code>%10s</code> — the <em>same widths</em> as the data rows but with the <code>s</code> conversion, because "QTY" is text. Matching the widths is what makes the columns line up.</li><li style="margin-bottom:5px;"><code>%-12s</code> left-aligns the item names; every numeric column is right-aligned so the decimal points stack.</li><li style="margin-bottom:5px;">The total line reuses the layout with empty strings as placeholders, keeping <code>218.97</code> in the same column as the other totals.</li></ol><p>Now the failures. Each of these compiles cleanly and throws when the line executes:</p><pre style="background:var(--surface-2); border:1px solid var(--border); border-radius:8px; padding:11px 13px; overflow-x:auto; font-size:13px; line-height:1.55; margin:10px 0;"><code>System.out.printf("%d%n", 4.5);                 // double into %d
System.out.printf("%s scored %d%n", "Ana");      // one argument short
System.out.printf("%s%n", "Ana", "ignored");     // one argument too many
String s = String.format("%05.1f", 3.14159);    // zero-padding flag</code></pre><div style="margin:9px 0 4px;"><span style="font-size:11px; font-weight:700; letter-spacing:0.05em; color:var(--text-3);">OUTPUT</span></div><pre style="background:var(--surface-3, var(--surface-2)); border-left:3px solid var(--accent); border-radius:0 8px 8px 0; padding:9px 13px; overflow-x:auto; font-size:13px; line-height:1.5; margin:0 0 10px;"><code>threw IllegalFormatConversionException
Ana scored threw MissingFormatArgumentException
Ana
003.1</code></pre><ol style="margin:8px 0 4px 18px; padding:0; line-height:1.65;"><li style="margin-bottom:5px;"><code>%d</code> with a <code>double</code> throws <code>IllegalFormatConversionException</code>. The compiler cannot check the pairing, because the arguments are a varargs array of <code>Object</code>.</li><li style="margin-bottom:5px;">Too <strong>few</strong> arguments throws <code>MissingFormatArgumentException</code> — and notice <code>Ana scored </code> was already printed before it threw. <code>printf</code> writes as it goes, so a partial line reaches the screen first.</li><li style="margin-bottom:5px;">Too <strong>many</strong> arguments is not an error at all: extras are silently ignored, which is why a value that "disappeared" is usually a missing specifier rather than a missing argument.</li><li style="margin-bottom:5px;"><code>%05.1f</code> uses the <code>0</code> flag: pad the field with zeros instead of spaces. Width 5, one decimal, so <code>3.1</code> becomes <code>003.1</code>.</li><li style="margin-bottom:5px;"><code>String.format</code> takes exactly the same arguments as <code>printf</code> and returns the text instead of printing it — the right choice when the result is going into a file, a label or a message.</li></ol></div><div class="callout" data-lb="key" style="border-left-color:#e11d48;"><div class="callout-label">🎯 EXAM TIP</div><p><strong>Read the specifier right to left.</strong> The last letter is the type, the number after the dot is the decimals, the number before it is the total width, and a minus sign means left-aligned. <code>%-10.3f</code> = float, 3 decimals, 10 wide, left.</p><p>Two answers worth memorising because they are asked directly:</p><p>① <code>printf("%.2f", 3.567)</code> gives <strong>3.57</strong> — it <em>rounds</em>. Any option offering 3.56 is testing whether you think it truncates.<br>② <code>%f</code> with no precision gives <strong>six</strong> decimal places.</p><p>For "what does this print" questions, count the padding by writing the value out and subtracting its length from the width. <code>%8.2f</code> on 3.14159 → the text is <code>3.14</code>, 4 characters, so 4 leading spaces.</p><p>Finally: <code>%n</code> versus <code>\n</code>. Both end the line; <code>%n</code> is the portable one and is what <code>printf</code> examples use. <code>\n</code> inside a format string works too — it is just a character in the text.</p></div>"},"D286/u9/z9_3":{"body":"<p>A <code>Scanner</code> can read from a String exactly as it reads from the keyboard, which makes it the simplest way to pull a line apart into typed pieces.</p><pre style="background:var(--bg-2, var(--surface-2)); padding:12px; border-radius:8px; font-size:13px; overflow-x:auto; line-height:1.55;">Scanner s = new Scanner("Ada 95 3.7");
String name = s.next();        // "Ada"
int score   = s.nextInt();     // 95
double gpa  = s.nextDouble();  // 3.7

// splitting on something other than whitespace
String csv = "Ada,95,3.7";
String[] parts = csv.split(",");        // {"Ada", "95", "3.7"}
int n = Integer.parseInt(parts[1]);     // Strings must be parsed (7.13)

// building a String piece by piece
StringBuilder sb = new StringBuilder();
sb.append("Ada").append(": ").append(95);</pre><p><code>split</code> returns an array of Strings, always — even the numeric-looking pieces. Converting them is <code>Integer.parseInt</code> or <code>Double.parseDouble</code>, and a piece that is not a number throws <code>NumberFormatException</code>, which is one of the cases Unit 12 handles.</p><pre style="background:var(--bg-2, var(--surface-2)); padding:12px; border-radius:8px; font-size:13px; overflow-x:auto; line-height:1.55;">StringBuilder sb = new StringBuilder();
for (String w : words) sb.append(w).append(" ");
String line = sb.toString();          // ONE String at the end

String[] parts = "a,b,c".split(",");  // {"a","b","c"}
String joined  = String.join("-", parts);   // "a-b-c"</pre><p>A String is immutable, so <code>+=</code> in a loop allocates a new String every pass. <code>StringBuilder</code> is mutable — <code>append</code> writes into a buffer that grows — so <em>n</em> appends cost one object rather than <em>n</em>.</p><p><code>split</code> takes a regular expression, not a plain string, so splitting on a dot needs <code>split("\\.")</code> — a bare <code>"."</code> matches every character and returns an empty array. A <code>Scanner</code> over a String is the alternative when the input is whitespace-separated and typed.</p><i data-d286u811="1" style="display:none"></i><div class="callout" data-lb="why" style="border-left-color:#4f46e5;"><div class="callout-label">📘 DEFINITION</div><p style="margin:0 0 7px;"><strong>Scanner over a String:</strong> parsing a String with the same next/nextInt methods used for input</p><p style="margin:0 0 7px;"><strong>split(delimiter):</strong> breaks a String into an array on a delimiter; takes a regular expression</p><p style="margin:0 0 7px;"><strong>StringBuilder:</strong> a mutable buffer for assembling text without creating a String per step (4.6)</p></div><div class="callout" data-lb="oa" style="border-left-color:#e11d48;"><div class="callout-label">🎯 EXAM TIP</div><p><code>split</code> takes a <em>regular expression</em>, so characters like <code>.</code> and <code>|</code> must be escaped: <code>split("\\.")</code> to split on a dot. Splitting a domain name on <code>"."</code> unescaped returns an empty array.</p></div><i data-tbc93="1" style="display:none"></i><div class="vl" data-mathvis="1" data-c959fig="1" style="margin-top:18px;"><div style="font-weight:700; font-size:12.5px; letter-spacing:0.05em; margin-bottom:6px;">📊 FIGURE — ONE STRING, TWO WAYS TO TAKE IT APART</div><div style="border:1px solid var(--border); border-radius:12px; background:var(--surface-2); padding:14px 10px; overflow-x:auto;"><svg viewBox="0 0 820 430" style="width:100%; max-width:760px; display:block; margin:0 auto; font-family:inherit;" xmlns="http://www.w3.org/2000/svg"><defs><marker id="fk254a" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0,1 L9,5 L0,9 z" fill="var(--text)"/></marker></defs><text x="170" y="24" fill="var(--accent)" font-size="11.5" font-weight="700" text-anchor="middle">A.  split(",")  →  String[]  →  parse</text><rect x="40" y="40" width="300" height="34" rx="7" fill="var(--surface)" stroke="var(--text)" stroke-width="1.5"/><text x="190" y="61.5" fill="var(--text)" font-size="12" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">"Ada Lovelace,95,3.71"</text><line x1="190" y1="74" x2="190" y2="96" stroke="var(--text)" stroke-width="1.6" marker-end="url(#fk254a)"/><text x="258" y="90" fill="var(--accent)" font-size="10.5" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">split(",")</text><rect x="40" y="100" width="130" height="32" rx="7" fill="var(--surface)" stroke="var(--text)" stroke-width="1.5"/><text x="105" y="120.5" fill="var(--text)" font-size="10" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">"Ada Lovelace"</text><rect x="178" y="100" width="74" height="32" rx="7" fill="var(--surface)" stroke="var(--text)" stroke-width="1.5"/><text x="215" y="120.5" fill="var(--text)" font-size="10" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">"95"</text><rect x="260" y="100" width="80" height="32" rx="7" fill="var(--surface)" stroke="var(--text)" stroke-width="1.5"/><text x="300" y="120.5" fill="var(--text)" font-size="10" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">"3.71"</text><text x="105" y="148" fill="var(--text-3)" font-size="9.5" font-weight="400" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">[0]</text><text x="215" y="148" fill="var(--text-3)" font-size="9.5" font-weight="400" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">[1]</text><text x="300" y="148" fill="var(--text-3)" font-size="9.5" font-weight="400" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">[2]</text><text x="190" y="166" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-style="italic">every piece is a String — even the numeric ones</text><text x="258" y="190" fill="var(--accent)" font-size="9.5" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">Integer.parseInt      Double.parseDouble</text><line x1="215" y1="196" x2="215" y2="214" stroke="var(--text)" stroke-width="1.6" marker-end="url(#fk254a)"/><line x1="300" y1="196" x2="300" y2="214" stroke="var(--text)" stroke-width="1.6" marker-end="url(#fk254a)"/><rect x="178" y="218" width="74" height="32" rx="7" fill="var(--accent-bg)" stroke="var(--accent)" stroke-width="1.5"/><text x="215" y="238.5" fill="var(--text)" font-size="12" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">95</text><rect x="260" y="218" width="80" height="32" rx="7" fill="var(--accent-bg)" stroke="var(--accent)" stroke-width="1.5"/><text x="300" y="238.5" fill="var(--text)" font-size="12" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">3.71</text><text x="258" y="266" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-style="italic">int and double at last</text><line x1="410" y1="30" x2="410" y2="276" stroke="var(--border)" stroke-width="1"/><text x="618" y="24" fill="var(--accent)" font-size="11.5" font-weight="700" text-anchor="middle">B.  a Scanner over the same text keeps a CURSOR</text><rect x="452" y="40" width="330" height="34" rx="7" fill="var(--surface)" stroke="var(--text)" stroke-width="1.5"/><text x="617" y="61.5" fill="var(--text)" font-size="12" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">"Ada 95 3.71"</text><text x="452" y="104" fill="var(--text-3)" font-size="10" font-weight="400" text-anchor="start">start</text><line x1="492" y1="92" x2="492" y2="74" stroke="var(--accent)" stroke-width="1.6" marker-end="url(#fk254a)"/><text x="560" y="104" fill="var(--text-3)" font-size="10" font-weight="400" text-anchor="middle">after next()</text><line x1="560" y1="92" x2="560" y2="74" stroke="var(--accent)" stroke-width="1.6" marker-end="url(#fk254a)"/><text x="650" y="128" fill="var(--text-3)" font-size="10" font-weight="400" text-anchor="middle">after nextInt()</text><line x1="650" y1="116" x2="650" y2="74" stroke="var(--accent)" stroke-width="1.6" marker-end="url(#fk254a)"/><text x="748" y="152" fill="var(--text-3)" font-size="10" font-weight="400" text-anchor="middle">after nextDouble()</text><line x1="748" y1="140" x2="748" y2="74" stroke="var(--accent)" stroke-width="1.6" marker-end="url(#fk254a)"/><rect x="452" y="172" width="100" height="30" rx="7" fill="var(--surface)" stroke="var(--text)" stroke-width="1.5"/><text x="502" y="191.5" fill="var(--text)" font-size="11" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">"Ada"</text><rect x="568" y="172" width="76" height="30" rx="7" fill="var(--accent-bg)" stroke="var(--accent)" stroke-width="1.5"/><text x="606" y="191.5" fill="var(--text)" font-size="11" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">95</text><rect x="660" y="172" width="90" height="30" rx="7" fill="var(--accent-bg)" stroke="var(--accent)" stroke-width="1.5"/><text x="705" y="191.5" fill="var(--text)" font-size="11" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">3.71</text><text x="618" y="222" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-style="italic">each call consumes one token and returns it already typed —</text><text x="618" y="238" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-style="italic">no parsing step, and hasNext() reports what is left</text><line x1="30" y1="278" x2="790" y2="278" stroke="var(--border)" stroke-width="1"/><text x="410" y="304" fill="var(--accent)" font-size="11.5" font-weight="700" text-anchor="middle">BUILDING TEXT: += ALLOCATES, StringBuilder DOES NOT</text><text x="64" y="336" fill="var(--text)" font-size="11" font-weight="700" text-anchor="start" font-family="ui-monospace,Menlo,monospace">s += w  (3 words)</text><rect x="50" y="348" width="84" height="30" rx="7" fill="var(--surface)" stroke="var(--text-3)" stroke-width="1.5" stroke-dasharray="4 3"/><text x="92" y="367.5" fill="var(--text-3)" font-size="10" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">"total"</text><rect x="154" y="348" width="118" height="30" rx="7" fill="var(--surface)" stroke="var(--text-3)" stroke-width="1.5" stroke-dasharray="4 3"/><text x="213" y="367.5" fill="var(--text-3)" font-size="10" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">"total orders"</text><rect x="292" y="348" width="158" height="30" rx="7" fill="var(--surface)" stroke="var(--text)" stroke-width="1.5"/><text x="371" y="367.5" fill="var(--text)" font-size="9.5" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">"total orders shipped"</text><line x1="134" y1="363" x2="152" y2="363" stroke="var(--text-3)" stroke-width="1.6" marker-end="url(#fk254a)"/><line x1="272" y1="363" x2="290" y2="363" stroke="var(--text-3)" stroke-width="1.6" marker-end="url(#fk254a)"/><text x="250" y="398" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-style="italic">3 String objects, 2 of them instant garbage</text><text x="506" y="336" fill="var(--text)" font-size="11" font-weight="700" text-anchor="start" font-family="ui-monospace,Menlo,monospace">sb.append(w)</text><rect x="506" y="348" width="250" height="30" rx="7" fill="var(--accent-bg)" stroke="var(--accent)" stroke-width="2.2"/><text x="631" y="367.5" fill="var(--text)" font-size="10" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">total orders shipped</text><text x="631" y="398" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-style="italic">ONE growable buffer, written in place</text></svg></div></div><div class="callout" data-lb="key" style="border-left-color:#0ea5e9;"><div class="callout-label">▸ WORKED EXAMPLE — PARSING A CSV RECORD BOTH WAYS</div><p>Two tools, two shapes of input. <code>split</code> handles a delimiter you choose; a <code>Scanner</code> handles whitespace-separated tokens and does the typing for you.</p><pre style="background:var(--surface-2); border:1px solid var(--border); border-radius:8px; padding:11px 13px; overflow-x:auto; font-size:13px; line-height:1.55; margin:10px 0;"><code>String record = "Ada Lovelace,95,3.71";
String[] parts = record.split(",");
System.out.println("pieces: " + parts.length);
for (int i = 0; i &lt; parts.length; i++)
    System.out.println(i + " -&gt; [" + parts[i] + "]");

String name  = parts[0];
int    score = Integer.parseInt(parts[1]);
double gpa   = Double.parseDouble(parts[2]);
System.out.printf("%s | %d | %.2f%n", name, score + 5, gpa);

Scanner s = new Scanner("Ada 95 3.71");
String first = s.next();
int    sc    = s.nextInt();
double g     = s.nextDouble();
System.out.println(first + "/" + sc + "/" + g);
System.out.println("more tokens? " + s.hasNext());</code></pre><ol style="margin:8px 0 4px 18px; padding:0; line-height:1.65;"><li style="margin-bottom:5px;"><code>split(",")</code> cuts at every comma and returns a <code>String[]</code> of length 3. The name keeps its internal space, because only commas were delimiters.</li><li style="margin-bottom:5px;">Printing each piece inside <code>[ ]</code> is worth doing while debugging — it exposes stray spaces that <code>parseInt</code> would reject.</li><li style="margin-bottom:5px;"><code>parts[1]</code> is the <em>String</em> <code>"95"</code>, not the number 95. <code>Integer.parseInt</code> converts it; <code>score + 5</code> then prints 100, which proves the conversion happened. Had you written <code>parts[1] + 5</code> you would have got the text <code>955</code>.</li><li style="margin-bottom:5px;"><code>Double.parseDouble("3.71")</code> gives the double 3.71, printed as <code>3.71</code> by <code>%.2f</code>.</li><li style="margin-bottom:5px;">The Scanner version never mentions parsing: <code>next()</code>, <code>nextInt()</code> and <code>nextDouble()</code> each consume one whitespace-separated token and return it already typed.</li><li style="margin-bottom:5px;"><code>hasNext()</code> is false afterwards because all three tokens were consumed — the cursor is at the end of the String.</li></ol><div style="margin:9px 0 4px;"><span style="font-size:11px; font-weight:700; letter-spacing:0.05em; color:var(--text-3);">OUTPUT</span></div><pre style="background:var(--surface-3, var(--surface-2)); border-left:3px solid var(--accent); border-radius:0 8px 8px 0; padding:9px 13px; overflow-x:auto; font-size:13px; line-height:1.5; margin:0 0 10px;"><code>pieces: 3
0 -&gt; [Ada Lovelace]
1 -&gt; [95]
2 -&gt; [3.71]
Ada Lovelace | 100 | 3.71
Ada/95/3.71
more tokens? false</code></pre><p>Choose by the separator: commas, tabs or semicolons mean <code>split</code>; plain spaces mean a <code>Scanner</code>. A Scanner cannot easily read <code>Ada Lovelace</code> as one field, because the space inside it is a token boundary.</p></div><div class="callout" data-lb="key" style="border-left-color:#0ea5e9;"><div class="callout-label">▸ WORKED EXAMPLE — THE REGEX TRAP AND THE BUFFER</div><p><code>split</code> takes a <strong>regular expression</strong>, not a literal string, and <code>String</code> is immutable. Both facts have visible consequences.</p><pre style="background:var(--surface-2); border:1px solid var(--border); border-radius:8px; padding:11px 13px; overflow-x:auto; font-size:13px; line-height:1.55; margin:10px 0;"><code>String[] words = { "total", "orders", "shipped" };
StringBuilder sb = new StringBuilder();
for (String w : words) sb.append(w).append(" ");
System.out.println("[" + sb.toString().trim() + "]");
System.out.println("length " + sb.length());

String host = "shop.example.co.uk";
System.out.println(host.split("\\.").length);
System.out.println(host.split("\\.")[0]);
System.out.println("dot-unescaped pieces: " + host.split(".").length);

String csv = "12,,7";
System.out.println("empty middle -&gt; " + csv.split(",").length + " [" + csv.split(",")[1] + "]");
System.out.println(String.join("-", "a", "b", "c"));

String s = "hi";
String t = s;
s += "!";
System.out.println(s + " " + t);</code></pre><ol style="margin:8px 0 4px 18px; padding:0; line-height:1.65;"><li style="margin-bottom:5px;">The <code>StringBuilder</code> ends up holding <code>"total orders shipped "</code> — 21 characters including the trailing space, which is why <code>sb.length()</code> is 21 while the trimmed text printed is 20.</li><li style="margin-bottom:5px;"><code>split("\\.")</code> — a backslash-escaped dot in the regex, written as <code>\\.</code> in Java source — splits on literal dots and gives <strong>4</strong> pieces, the first being <code>shop</code>.</li><li style="margin-bottom:5px;"><code>split(".")</code> is the bug. In a regex <code>.</code> means "any character", so every character is a delimiter, every piece is empty, trailing empties are discarded, and the result is an array of length <strong>0</strong>. No exception is thrown — you simply get nothing.</li><li style="margin-bottom:5px;"><code>"12,,7".split(",")</code> gives 3 pieces with an <strong>empty String</strong> in the middle. Empty fields are preserved <em>inside</em> the data; only trailing ones are dropped. This is exactly what breaks a naive <code>parseInt</code> on real CSV.</li><li style="margin-bottom:5px;"><code>String.join("-", ...)</code> is the inverse of split.</li><li style="margin-bottom:5px;">The last three lines are immutability: <code>s += "!"</code> does not edit the original text, it builds a new String and points <code>s</code> at it. <code>t</code> still names the old one, so the output is <code>hi! hi</code>.</li></ol><div style="margin:9px 0 4px;"><span style="font-size:11px; font-weight:700; letter-spacing:0.05em; color:var(--text-3);">OUTPUT</span></div><pre style="background:var(--surface-3, var(--surface-2)); border-left:3px solid var(--accent); border-radius:0 8px 8px 0; padding:9px 13px; overflow-x:auto; font-size:13px; line-height:1.5; margin:0 0 10px;"><code>[total orders shipped]
length 21
4
shop
dot-unescaped pieces: 0
empty middle -&gt; 3 []
a-b-c
hi! hi</code></pre><p>That final pair is why <code>+=</code> in a loop is expensive: each pass allocates a brand-new String and abandons the previous one. A hundred appends means a hundred objects; a <code>StringBuilder</code> means one buffer.</p></div><div class="callout" data-lb="key" style="border-left-color:#f59e0b;"><div class="callout-label">⚠️ COMMON MISTAKE</div><p><strong>Treating <code>split</code>'s argument as plain text.</strong> It is a regular expression, so the characters <code>. | * + ? ( ) [ ] { } ^ $ \</code> all mean something else. The two that bite in this course:</p><p><code>split(".")</code> returns an <strong>empty array</strong> — length 0, no exception. Splitting a filename or a domain this way silently produces nothing, and the next line throws <code>ArrayIndexOutOfBoundsException</code> a long way from the real cause.<br><code>split("|")</code> on pipe-delimited data splits between <em>every character</em>, because <code>|</code> is the regex alternation operator with two empty alternatives.</p><p>How to notice it: print <code>parts.length</code> immediately after the split. If it is 0 or suspiciously large, the delimiter needs escaping — <code>split("\\.")</code> and <code>split("\\|")</code>. Alphanumeric delimiters and the comma need no escape, which is why <code>split(",")</code> lulls you into trusting the rest.</p></div>"},"D286/u9/z9_4":{"body":"<p>File input is 9.1 with a different source, plus two obligations the keyboard did not have: the file may not exist, and the file must be closed.</p><pre style="background:var(--bg-2, var(--surface-2)); padding:12px; border-radius:8px; font-size:13px; overflow-x:auto; line-height:1.55;">import java.io.File;
import java.io.FileNotFoundException;
import java.util.Scanner;

public static void main(String[] args) throws FileNotFoundException {
    File f = new File("data.txt");
    Scanner in = new Scanner(f);            // may throw FileNotFoundException

    while (in.hasNextLine()) {              // the standard read-until-empty loop
        String line = in.nextLine();
        System.out.println(line);
    }
    in.close();                              // release the handle
}</pre><p><code>hasNextLine()</code> is what replaces the sentinel value of 4.2 — the stream itself reports when it is exhausted, so no magic value is needed. The <code>throws</code> clause on <code>main</code> is the minimal way to satisfy the compiler; <code>try-catch</code> (12.3) is the version that can actually respond to a missing file.</p><pre style="background:var(--bg-2, var(--surface-2)); padding:12px; border-radius:8px; font-size:13px; overflow-x:auto; line-height:1.55;">try (Scanner in = new Scanner(new File("data.txt"))) {
    while (in.hasNextLine()) {
        String line = in.nextLine();
        // ...
    }
} catch (FileNotFoundException e) {
    System.out.println("Could not open the file");
}</pre><p><code>FileNotFoundException</code> is a <strong>checked</strong> exception: the compiler refuses to build code that neither catches it nor declares <code>throws</code>. That is the difference from <code>ArrayIndexOutOfBounds</code>, which is unchecked and only appears at run time.</p><p><code>hasNextLine()</code> before <code>nextLine()</code> is what stops the read at the end of the file; calling <code>nextLine()</code> with nothing left throws <code>NoSuchElementException</code>. The same pairing applies to <code>hasNextInt</code>/<code>nextInt</code>.</p><p>The resource declared in the <code>try(...)</code> parentheses is closed automatically, in reverse order, before any <code>catch</code> runs — which is why this form is preferred over closing by hand in a <code>finally</code> block. A relative path is resolved against the directory the program was started from, not the source file's directory.</p><i data-d286u811="1" style="display:none"></i><div class="callout" data-lb="why" style="border-left-color:#4f46e5;"><div class="callout-label">📘 DEFINITION</div><p style="margin:0 0 7px;"><strong>File:</strong> an object naming a path; creating one does not open or read anything</p><p style="margin:0 0 7px;"><strong>FileNotFoundException:</strong> a checked exception — the compiler forces you to handle or declare it</p><p style="margin:0 0 7px;"><strong>hasNextLine() / hasNextInt():</strong> tests whether more input of that kind is available</p><p style="margin:0 0 7px;"><strong>close():</strong> releases the operating-system file handle</p></div><div class="callout" data-lb="warn" style="border-left-color:#f59e0b;"><div class="callout-label">⚠ COMMON MISTAKE</div><p>Forgetting <code>close()</code> leaves the handle open — and the garbage collector will not fix it (8.4), because collection is about memory, not operating-system resources. Use try-with-resources if the syntax is available to you.</p></div><p data-xref="1" style="margin:26px 0 0; padding-top:12px; border-top:1px solid var(--border);font-size:12.5px; opacity:0.72;">✅ Also covered in depth: <strong>Advanced → try-with-resources and File I/O</strong></p><i data-tbc94="1" style="display:none"></i><div class="vl" data-mathvis="1" data-c959fig="1" style="margin-top:18px;"><div style="font-weight:700; font-size:12.5px; letter-spacing:0.05em; margin-bottom:6px;">📊 FIGURE — READING A FILE: THE SAME LOOP, A DIFFERENT SOURCE</div><div style="border:1px solid var(--border); border-radius:12px; background:var(--surface-2); padding:14px 10px; overflow-x:auto;"><svg viewBox="0 0 820 400" style="width:100%; max-width:760px; display:block; margin:0 auto; font-family:inherit;" xmlns="http://www.w3.org/2000/svg"><defs><marker id="fk255a" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0,1 L9,5 L0,9 z" fill="var(--text)"/></marker></defs><rect x="30" y="52" width="120" height="108" rx="8" fill="var(--surface)" stroke="var(--text)" stroke-width="1.6"/><line x1="30" y1="76" x2="150" y2="76" stroke="var(--text)" stroke-width="1.4"/><text x="90" y="69" fill="var(--text)" font-size="10.5" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">readings.txt</text><text x="90" y="96" fill="var(--text-3)" font-size="10" font-weight="400" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">Ana 22.50</text><text x="90" y="116" fill="var(--text-3)" font-size="10" font-weight="400" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">Ben 14.00</text><text x="90" y="136" fill="var(--text-3)" font-size="10" font-weight="400" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">Cy 31.25</text><text x="90" y="178" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-style="italic">bytes on disk</text><line x1="150" y1="106" x2="248" y2="106" stroke="var(--text)" stroke-width="1.6" marker-end="url(#fk255a)"/><text x="199" y="96" fill="var(--text-3)" font-size="9.5" font-weight="400" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">new File(…)</text><rect x="252" y="84" width="150" height="44" rx="7" fill="var(--accent-bg)" stroke="var(--accent)" stroke-width="2.2"/><text x="327" y="103" fill="var(--text)" font-size="12.5" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">Scanner</text><text x="327" y="119" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle">holds an OS handle</text><text x="327" y="148" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-style="italic">a cursor over the stream</text><line x1="402" y1="96" x2="486" y2="96" stroke="var(--text)" stroke-width="1.6" marker-end="url(#fk255a)"/><text x="444" y="86" fill="var(--text-3)" font-size="9.5" font-weight="400" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">hasNextLine()</text><rect x="490" y="60" width="214" height="72" rx="7" fill="var(--surface)" stroke="var(--text)" stroke-width="1.5"/><text x="597" y="93" fill="var(--text)" font-size="12" font-weight="700" text-anchor="middle">the read loop</text><text x="597" y="109" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle">nextLine() → parse → accumulate</text><line x1="486" y1="120" x2="402" y2="120" stroke="var(--text)" stroke-width="1.6" marker-end="url(#fk255a)"/><text x="444" y="138" fill="var(--text-3)" font-size="9.5" font-weight="400" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">nextLine()</text><line x1="704" y1="96" x2="752" y2="96" stroke="var(--text)" stroke-width="1.6" marker-end="url(#fk255a)"/><text x="782" y="92" fill="var(--text)" font-size="11" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">total</text><text x="782" y="108" fill="var(--accent)" font-size="11" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">67.75</text><line x1="30" y1="212" x2="790" y2="212" stroke="var(--border)" stroke-width="1"/><text x="410" y="238" fill="var(--accent)" font-size="11.5" font-weight="700" text-anchor="middle">THE TWO OBLIGATIONS THE KEYBOARD DID NOT HAVE</text><rect x="56" y="258" width="320" height="46" rx="7" fill="var(--accent-bg)" stroke="var(--accent)" stroke-width="1.5"/><text x="216" y="278" fill="var(--text)" font-size="12" font-weight="700" text-anchor="middle">① the file may not exist</text><text x="216" y="294" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle">FileNotFoundException — CHECKED, so catch or declare</text><line x1="216" y1="304" x2="216" y2="328" stroke="var(--text)" stroke-width="1.6" marker-end="url(#fk255a)"/><rect x="56" y="328" width="148" height="40" rx="7" fill="var(--surface)" stroke="var(--text)" stroke-width="1.5"/><text x="130" y="345" fill="var(--text)" font-size="11.5" font-weight="700" text-anchor="middle">catch it</text><text x="130" y="361" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle">recover, use defaults</text><rect x="228" y="328" width="148" height="40" rx="7" fill="var(--surface)" stroke="var(--text)" stroke-width="1.5"/><text x="302" y="345" fill="var(--text)" font-size="11.5" font-weight="700" text-anchor="middle">throws on main</text><text x="302" y="361" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle">crash with a trace</text><rect x="444" y="258" width="320" height="46" rx="7" fill="var(--accent-bg)" stroke="var(--accent)" stroke-width="1.5"/><text x="604" y="278" fill="var(--text)" font-size="12" font-weight="700" text-anchor="middle">② the handle must be released</text><text x="604" y="294" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle">close() — the collector will NOT do it for you</text><line x1="604" y1="304" x2="604" y2="328" stroke="var(--text)" stroke-width="1.6" marker-end="url(#fk255a)"/><rect x="444" y="328" width="148" height="40" rx="7" fill="var(--surface)" stroke="var(--text)" stroke-width="1.5"/><text x="518" y="345" fill="var(--text)" font-size="11.5" font-weight="700" text-anchor="middle">close() by hand</text><text x="518" y="361" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle">in a finally block</text><rect x="616" y="328" width="148" height="40" rx="7" fill="var(--surface)" stroke="var(--text)" stroke-width="1.5"/><text x="690" y="345" fill="var(--text)" font-size="11.5" font-weight="700" text-anchor="middle">try-with-resources</text><text x="690" y="361" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle">closed automatically</text></svg></div></div><div class="callout" data-lb="key" style="border-left-color:#0ea5e9;"><div class="callout-label">▸ WORKED EXAMPLE — WRITE A FILE, READ IT BACK, THEN ASK FOR ONE THAT IS NOT THERE</div><p>Everything about file input is in this one program: creating the file, the read-until-exhausted loop, and what happens when the path is wrong.</p><pre style="background:var(--surface-2); border:1px solid var(--border); border-radius:8px; padding:11px 13px; overflow-x:auto; font-size:13px; line-height:1.55; margin:10px 0;"><code>File f = new File("readings.txt");
try (PrintWriter setup = new PrintWriter(f)) {
    setup.println("Ana 22.50");
    setup.println("Ben 14.00");
    setup.println("Cy 31.25");
}
System.out.println("exists? " + f.exists() + "  (a File object alone creates nothing)");

double total = 0;
int lines = 0;
try (Scanner in = new Scanner(f)) {
    while (in.hasNextLine()) {
        String line = in.nextLine();
        lines++;
        String[] p = line.split(" ");
        total += Double.parseDouble(p[1]);
    }
}
System.out.println("lines=" + lines);
System.out.printf("total=%.2f%n", total);

File missing = new File("nope.txt");
System.out.println("missing exists? " + missing.exists());
try {
    Scanner bad = new Scanner(missing);
} catch (FileNotFoundException e) {
    System.out.println("caught " + e.getClass().getSimpleName());
}</code></pre><ol style="margin:8px 0 4px 18px; padding:0; line-height:1.65;"><li style="margin-bottom:5px;"><code>new File("readings.txt")</code> builds an object that <em>names a path</em>. On its own it opens nothing, creates nothing and reads nothing — which is why the last few lines can construct a <code>File</code> for a non-existent path without any error at all.</li><li style="margin-bottom:5px;">The <code>PrintWriter</code> is what actually creates the file. <code>f.exists()</code> is then true.</li><li style="margin-bottom:5px;"><code>new Scanner(f)</code> opens the file for reading. This is the call that can throw <code>FileNotFoundException</code>, and because it is <em>checked</em>, the compiler will not let the line stand unguarded.</li><li style="margin-bottom:5px;">The loop shape is <code>while (hasNextLine()) { nextLine(); }</code>. The stream itself reports when it is exhausted — no sentinel value, no line count known in advance.</li><li style="margin-bottom:5px;">Each line is split on the space and <code>p[1]</code> parsed as a double: 22.50 + 14.00 + 31.25 = <strong>67.75</strong>, and three lines were read.</li><li style="margin-bottom:5px;">The failure case is explicit at the end: <code>missing.exists()</code> is false, and constructing the Scanner throws <code>FileNotFoundException</code>, caught and named.</li></ol><div style="margin:9px 0 4px;"><span style="font-size:11px; font-weight:700; letter-spacing:0.05em; color:var(--text-3);">OUTPUT</span></div><pre style="background:var(--surface-3, var(--surface-2)); border-left:3px solid var(--accent); border-radius:0 8px 8px 0; padding:9px 13px; overflow-x:auto; font-size:13px; line-height:1.5; margin:0 0 10px;"><code>exists? true  (a File object alone creates nothing)
lines=3
total=67.75
missing exists? false
caught FileNotFoundException</code></pre><p>Both Scanners are declared inside <code>try (...)</code>, so both are closed automatically at the end of their block — before any catch runs, and whether or not anything threw.</p></div><div class="callout" data-lb="key" style="border-left-color:#0ea5e9;"><div class="callout-label">▸ WORKED EXAMPLE — READING PAST THE END, AND THE nextInt / nextLine COLLISION</div><p>Two failures that look like file problems and are actually cursor problems. Both are reproduced here with a String source so the behaviour is identical and visible.</p><pre style="background:var(--surface-2); border:1px solid var(--border); border-radius:8px; padding:11px 13px; overflow-x:auto; font-size:13px; line-height:1.55; margin:10px 0;"><code>Scanner in = new Scanner("7\nAda Lovelace\n");
int    n    = in.nextInt();
String rest = in.nextLine();
String name = in.nextLine();
System.out.println("n=" + n);
System.out.println("rest=[" + rest + "]");
System.out.println("name=[" + name + "]");

Scanner two = new Scanner("42");
System.out.println(two.nextInt());
System.out.println("hasNextInt now? " + two.hasNextInt());
try {
    two.nextInt();
} catch (NoSuchElementException e) {
    System.out.println("caught " + e.getClass().getSimpleName());
}</code></pre><ol style="margin:8px 0 4px 18px; padding:0; line-height:1.65;"><li style="margin-bottom:5px;"><code>nextInt()</code> reads <code>7</code> and stops. The newline after the 7 is still sitting in the stream — token reads never consume the line ending.</li><li style="margin-bottom:5px;">The first <code>nextLine()</code> therefore returns everything from the cursor to that newline, which is <strong>nothing</strong>: <code>rest</code> is the empty String.</li><li style="margin-bottom:5px;">The second <code>nextLine()</code> gets <code>Ada Lovelace</code>. In a real program, that is the input the user thought they were giving to the <em>first</em> prompt — the notorious "it skipped my question" bug.</li><li style="margin-bottom:5px;">The second Scanner reads its only token, <code>42</code>. <code>hasNextInt()</code> is then false because the stream is exhausted.</li><li style="margin-bottom:5px;">Calling <code>nextInt()</code> anyway throws <code>NoSuchElementException</code>. This is the exception you get from reading past the end of a file, and it is exactly what the <code>hasNextLine()</code> / <code>hasNextInt()</code> test exists to prevent.</li></ol><div style="margin:9px 0 4px;"><span style="font-size:11px; font-weight:700; letter-spacing:0.05em; color:var(--text-3);">OUTPUT</span></div><pre style="background:var(--surface-3, var(--surface-2)); border-left:3px solid var(--accent); border-radius:0 8px 8px 0; padding:9px 13px; overflow-x:auto; font-size:13px; line-height:1.5; margin:0 0 10px;"><code>n=7
rest=[]
name=[Ada Lovelace]
42
hasNextInt now? false
caught NoSuchElementException</code></pre><p>The fix for the first is one throwaway <code>in.nextLine();</code> after the <code>nextInt()</code>. The fix for the second is never calling a <code>next…</code> method without the matching <code>hasNext…</code> test in front of it.</p></div><div class="callout" data-lb="key" style="border-left-color:#e11d48;"><div class="callout-label">🎯 EXAM TIP</div><p><strong>Pair every read with its test.</strong> <code>hasNextLine()</code> guards <code>nextLine()</code>; <code>hasNextInt()</code> guards <code>nextInt()</code>. Mixing them — <code>while (in.hasNextLine()) { in.nextInt(); }</code> — is a favourite wrong answer, because a line that exists is not necessarily an int.</p><p><strong>Know which exception goes with which mistake:</strong></p><div style="overflow-x:auto; margin:14px 0;"><table style="border-collapse:collapse; width:100%; font-size:14.5px;"><thead><tr><th style="text-align:left; padding:7px 12px 7px 0; border-bottom:2px solid var(--border); font-size:12.5px; letter-spacing:0.04em;">Situation</th><th style="text-align:left; padding:7px 12px 7px 0; border-bottom:2px solid var(--border); font-size:12.5px; letter-spacing:0.04em;">Exception</th><th style="text-align:left; padding:7px 12px 7px 0; border-bottom:2px solid var(--border); font-size:12.5px; letter-spacing:0.04em;">Checked?</th></tr></thead><tbody><tr><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border); font-weight:600;">the file does not exist</td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);"><code>FileNotFoundException</code></td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);"><strong>yes</strong> — catch or declare</td></tr><tr><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border); font-weight:600;">reading past the end</td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);"><code>NoSuchElementException</code></td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);">no</td></tr><tr><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border); font-weight:600;">the token is the wrong type</td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);"><code>InputMismatchException</code></td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);">no</td></tr><tr><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border); font-weight:600;">the text will not parse</td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);"><code>NumberFormatException</code></td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);">no</td></tr></tbody></table></div><p>Only the first one the compiler forces you to deal with — which is why <code>throws FileNotFoundException</code> appears on so many <code>main</code> methods in examples. That is the minimum to compile, not the right answer to a design question: a program that can respond usefully should <code>catch</code> instead.</p><p>And remember that a relative path is resolved against the directory the program was <em>launched</em> from, not the folder holding the source file. "File not found" when the file is plainly there is almost always this.</p></div>"},"D286/u9/z9_5":{"body":"<p>File output mirrors input, with one extra hazard: opening a file for writing <strong>erases</strong> it unless you explicitly ask to append.</p><pre style="background:var(--bg-2, var(--surface-2)); padding:12px; border-radius:8px; font-size:13px; overflow-x:auto; line-height:1.55;">import java.io.PrintWriter;
import java.io.FileWriter;
import java.io.IOException;

PrintWriter out = new PrintWriter("out.txt");        // TRUNCATES the file
out.println("Ada,95");
out.printf("%.2f%n", 3.7);                            // same formatting as 9.2
out.close();                                          // REQUIRED — flushes the buffer

// appending instead of overwriting
PrintWriter app = new PrintWriter(new FileWriter("out.txt", true));</pre><p><code>close()</code> is not optional here in a way it almost is for reading: output is buffered, so without the close the last writes may never reach the disk and the file ends up short or empty. That is the single most common file-output bug.</p><pre style="background:var(--bg-2, var(--surface-2)); padding:12px; border-radius:8px; font-size:13px; overflow-x:auto; line-height:1.55;">try (PrintWriter out = new PrintWriter("report.txt")) {
    out.println("Total: " + total);
    out.printf("%-10s %6.2f%n", name, pay);
}                                  // closed here — and only now guaranteed on disk</pre><p><code>new PrintWriter("report.txt")</code> creates the file if it does not exist and <strong>truncates it to empty if it does</strong>. There is no warning and no undo. Appending instead needs <code>new PrintWriter(new FileWriter("report.txt", true))</code> — the <code>true</code> is the append flag.</p><p>Output is buffered, so text may sit in memory rather than on disk until the writer is closed or flushed. A program that writes and then crashes without closing leaves an empty or truncated file, which is the usual explanation for "my file is blank".</p><p><code>PrintWriter</code> offers the same <code>print</code>, <code>println</code> and <code>printf</code> as <code>System.out</code>, so formatting code moves between console and file unchanged.</p><i data-d286u811="1" style="display:none"></i><div class="callout" data-lb="why" style="border-left-color:#4f46e5;"><div class="callout-label">📘 DEFINITION</div><p style="margin:0 0 7px;"><strong>PrintWriter:</strong> a writer offering print, println and printf to a file</p><p style="margin:0 0 7px;"><strong>FileWriter(path, true):</strong> the append mode constructor; false or omitted truncates</p><p style="margin:0 0 7px;"><strong>Flush:</strong> forcing buffered output out to the destination; close() flushes</p><p style="margin:0 0 7px;"><strong>IOException:</strong> the checked exception for output failures</p></div><div class="callout" data-lb="oa" style="border-left-color:#e11d48;"><div class="callout-label">🎯 EXAM TIP</div><p>A missing input file throws; a missing output file is created. The asymmetry catches people out — and an existing output file is silently destroyed, which is worth remembering before you run the program on real data.</p></div><p data-xref="1" style="margin:26px 0 0; padding-top:12px; border-top:1px solid var(--border);font-size:12.5px; opacity:0.72;">✅ Also covered in depth: <strong>Advanced → try-with-resources and File I/O</strong></p><i data-tbc95="1" style="display:none"></i><div class="vl" data-mathvis="1" data-c959fig="1" style="margin-top:18px;"><div style="font-weight:700; font-size:12.5px; letter-spacing:0.05em; margin-bottom:6px;">📊 FIGURE — OUTPUT SITS IN A BUFFER UNTIL YOU FLUSH OR CLOSE</div><div style="border:1px solid var(--border); border-radius:12px; background:var(--surface-2); padding:14px 10px; overflow-x:auto;"><svg viewBox="0 0 820 400" style="width:100%; max-width:760px; display:block; margin:0 auto; font-family:inherit;" xmlns="http://www.w3.org/2000/svg"><defs><marker id="fk256a" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0,1 L9,5 L0,9 z" fill="var(--text)"/></marker></defs><rect x="40" y="70" width="128" height="56" rx="7" fill="var(--surface)" stroke="var(--text)" stroke-width="1.5"/><text x="104" y="95" fill="var(--text)" font-size="12" font-weight="700" text-anchor="middle">your program</text><text x="104" y="111" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle">println / printf</text><line x1="168" y1="98" x2="236" y2="98" stroke="var(--text)" stroke-width="1.6" marker-end="url(#fk256a)"/><rect x="236" y="62" width="190" height="72" rx="7" fill="var(--accent-bg)" stroke="var(--accent)" stroke-width="2.2"/><text x="331" y="95" fill="var(--text)" font-size="13" font-weight="700" text-anchor="middle">BUFFER</text><text x="331" y="111" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle">in memory — not on disk yet</text><line x1="426" y1="98" x2="512" y2="98" stroke="var(--accent)" stroke-width="1.6" marker-end="url(#fk256a)"/><text x="469" y="50" fill="var(--accent)" font-size="10" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">flush() / close()</text><rect x="512" y="62" width="128" height="96" rx="8" fill="var(--surface)" stroke="var(--text)" stroke-width="1.6"/><line x1="512" y1="86" x2="640" y2="86" stroke="var(--text)" stroke-width="1.4"/><text x="576" y="79" fill="var(--text)" font-size="10.5" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">notes.txt</text><text x="576" y="106" fill="var(--text-3)" font-size="10" font-weight="400" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">line one</text><text x="576" y="124" fill="var(--text-3)" font-size="10" font-weight="400" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">line two</text><text x="576" y="142" fill="var(--text-3)" font-size="10" font-weight="400" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">line three</text><line x1="331" y1="134" x2="331" y2="168" stroke="var(--text-3)" stroke-width="1.6" stroke-dasharray="5 4"/><line x1="331" y1="168" x2="331" y2="186" stroke="var(--text-3)" stroke-width="1.6" stroke-dasharray="5 4" marker-end="url(#fk256a)"/><rect x="224" y="186" width="214" height="40" rx="7" fill="var(--surface)" stroke="var(--text-3)" stroke-width="1.5" stroke-dasharray="5 4"/><text x="331" y="203" fill="var(--text-3)" font-size="11" font-weight="700" text-anchor="middle">program ends without close()</text><text x="331" y="219" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle">the buffer is simply lost</text><text x="690" y="100" fill="var(--text-3)" font-size="10" font-weight="700" text-anchor="middle">measured</text><text x="690" y="118" fill="var(--accent)" font-size="11" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">0 → 18 → 29</text><text x="690" y="134" fill="var(--text-3)" font-size="10" font-weight="400" text-anchor="middle">bytes on disk</text><line x1="30" y1="250" x2="790" y2="250" stroke="var(--border)" stroke-width="1"/><text x="410" y="276" fill="var(--accent)" font-size="11.5" font-weight="700" text-anchor="middle">AND OPENING FOR WRITING DESTROYS WHAT WAS THERE</text><rect x="44" y="296" width="340" height="44" rx="7" fill="var(--accent-bg)" stroke="var(--accent)" stroke-width="1.5"/><text x="214" y="315" fill="var(--text)" font-size="11.5" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">new PrintWriter("payroll.txt")</text><text x="214" y="331" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle">creates it — or TRUNCATES it to empty</text><line x1="214" y1="340" x2="214" y2="362" stroke="var(--text)" stroke-width="1.6" marker-end="url(#fk256a)"/><text x="214" y="378" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle">file now contains only what you write next</text><rect x="436" y="296" width="340" height="44" rx="7" fill="var(--surface)" stroke="var(--text)" stroke-width="1.5"/><text x="606" y="315" fill="var(--text)" font-size="10.5" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">new PrintWriter(new FileWriter(f, true))</text><text x="606" y="331" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle">the true is the APPEND flag — existing text kept</text><line x1="606" y1="340" x2="606" y2="362" stroke="var(--text)" stroke-width="1.6" marker-end="url(#fk256a)"/><text x="606" y="378" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle">new lines are added at the end</text></svg></div></div><div class="callout" data-lb="key" style="border-left-color:#0ea5e9;"><div class="callout-label">▸ WORKED EXAMPLE — THE BUFFER, MEASURED IN BYTES</div><p>"Close the writer or your file may be empty" is usually asserted. Here it is measured: the file length is checked on disk after each step.</p><pre style="background:var(--surface-2); border:1px solid var(--border); border-radius:8px; padding:11px 13px; overflow-x:auto; font-size:13px; line-height:1.55; margin:10px 0;"><code>PrintWriter out = new PrintWriter("notes.txt");
out.println("line one");
out.println("line two");
System.out.println("written, not closed: " + new File("notes.txt").length() + " bytes");
out.flush();
System.out.println("after flush()        : " + new File("notes.txt").length() + " bytes");
out.println("line three");
out.close();
System.out.println("after close()        : " + new File("notes.txt").length() + " bytes");

PrintWriter w = new PrintWriter("out.txt");
w.println("this never reaches the disk");
System.out.println("no close at all      : " + new File("out.txt").length() + " bytes");</code></pre><ol style="margin:8px 0 4px 18px; padding:0; line-height:1.65;"><li style="margin-bottom:5px;">Two full lines have been "written" and the file is <strong>0 bytes</strong>. The text is in a buffer in memory; the constructor created the file, but nothing has travelled to the disk.</li><li style="margin-bottom:5px;"><code>flush()</code> pushes the buffer out. The file jumps to <strong>18 bytes</strong> — "line one\n" and "line two\n", nine characters each.</li><li style="margin-bottom:5px;">A third line is written and <code>close()</code> called. <code>close()</code> flushes first, then releases the handle, so the file reaches <strong>29 bytes</strong> (18 + "line three\n").</li><li style="margin-bottom:5px;">The last two lines are the failure: a writer that is never closed and never flushed leaves the file at <strong>0 bytes</strong> even though the program clearly wrote to it. The JVM exiting does not rescue you.</li></ol><div style="margin:9px 0 4px;"><span style="font-size:11px; font-weight:700; letter-spacing:0.05em; color:var(--text-3);">OUTPUT</span></div><pre style="background:var(--surface-3, var(--surface-2)); border-left:3px solid var(--accent); border-radius:0 8px 8px 0; padding:9px 13px; overflow-x:auto; font-size:13px; line-height:1.5; margin:0 0 10px;"><code>written, not closed: 0 bytes
after flush()        : 18 bytes
after close()        : 29 bytes
no close at all      : 0 bytes</code></pre><p>This is the whole explanation for "my output file is blank". The program ran, the writes happened, and the buffer was discarded at exit. <code>close()</code> — or a <code>try (PrintWriter out = ...)</code> that calls it for you — is what makes the writing real.</p></div><div class="callout" data-lb="key" style="border-left-color:#0ea5e9;"><div class="callout-label">▸ WORKED EXAMPLE — TRUNCATE VERSUS APPEND, DEMONSTRATED ON THE SAME FILE</div><p>The same file is written three times. Watch the length: the second open destroys the first two lines, and only the third open preserves anything.</p><pre style="background:var(--surface-2); border:1px solid var(--border); border-radius:8px; padding:11px 13px; overflow-x:auto; font-size:13px; line-height:1.55; margin:10px 0;"><code>static void dump(String path) throws IOException {
    File f = new File(path);
    System.out.println("--- " + path + " (" + f.length() + " bytes)");
    try (Scanner in = new Scanner(f)) {
        while (in.hasNextLine()) System.out.println("| " + in.nextLine());
    }
}

try (PrintWriter out = new PrintWriter("payroll.txt")) {
    out.printf("%-10s %8.2f%n", "Ana", 22.5 * 40);
    out.printf("%-10s %8.2f%n", "Ben", 14.0 * 40);
}
dump("payroll.txt");

try (PrintWriter again = new PrintWriter("payroll.txt")) {      // TRUNCATES
    again.printf("%-10s %8.2f%n", "Cy", 31.25 * 40);
}
dump("payroll.txt");

try (PrintWriter app = new PrintWriter(new FileWriter("payroll.txt", true))) {
    app.printf("%-10s %8.2f%n", "Dee", 18.0 * 40);
}
dump("payroll.txt");</code></pre><ol style="margin:8px 0 4px 18px; padding:0; line-height:1.65;"><li style="margin-bottom:5px;">The first block writes two payroll lines. <code>%-10s</code> left-aligns the name in ten columns and <code>%8.2f</code> right-aligns the pay in eight — the identical formatting you would use on the console, because <code>PrintWriter</code> offers the same <code>print</code>, <code>println</code> and <code>printf</code>. 40 bytes: two lines of 20.</li><li style="margin-bottom:5px;"><code>new PrintWriter("payroll.txt")</code> a second time <strong>truncates the file to empty before writing a single character</strong>. Ana and Ben are gone with no warning and no way back; the file is down to 20 bytes holding only Cy.</li><li style="margin-bottom:5px;">The third block wraps a <code>FileWriter</code> with the append flag set to <code>true</code>. Now Dee is added <em>after</em> Cy and the file grows to 40 bytes again.</li><li style="margin-bottom:5px;">Each block is a try-with-resources, so each writer is closed at its closing brace — which is why <code>dump</code> can read complete, flushed data immediately afterwards.</li></ol><div style="margin:9px 0 4px;"><span style="font-size:11px; font-weight:700; letter-spacing:0.05em; color:var(--text-3);">OUTPUT</span></div><pre style="background:var(--surface-3, var(--surface-2)); border-left:3px solid var(--accent); border-radius:0 8px 8px 0; padding:9px 13px; overflow-x:auto; font-size:13px; line-height:1.5; margin:0 0 10px;"><code>--- payroll.txt (40 bytes)
| Ana          900.00
| Ben          560.00
--- payroll.txt (20 bytes)
| Cy          1250.00
--- payroll.txt (40 bytes)
| Cy          1250.00
| Dee          720.00</code></pre><p>The append constructor is the awkward one to remember because it is on <code>FileWriter</code>, not <code>PrintWriter</code>: <code>new PrintWriter(new FileWriter(path, true))</code>. There is no <code>new PrintWriter(path, true)</code> that means append — that overload sets the character encoding.</p></div><div class="callout" data-lb="key" style="border-left-color:#f59e0b;"><div class="callout-label">⚠️ COMMON MISTAKE</div><p><strong>Opening an output file to "check" it, or to write a second batch.</strong> <code>new PrintWriter(path)</code> truncates on construction — before any <code>println</code>, before any condition is tested, before you decide you had nothing to write after all. Running the program twice therefore leaves you with only the second run's output, and running it once on a file of real data destroys that data.</p><p>How to notice it: the file is shorter than expected, or contains only the last few records. If a program opens the same path in a loop — <code>for (Order o : orders) { PrintWriter p = new PrintWriter("out.txt"); ... }</code> — the finished file holds exactly one record, the last, which is the classic symptom.</p><p>The rule to carry: <strong>open once outside the loop</strong>, write inside it, close at the end. And when you genuinely want to add to an existing file, it must be <code>new FileWriter(path, true)</code> — nothing else appends.</p></div>"},"D286/u10/z10_1":{"body":"<p>Two classes often share most of their content — a <code>Manager</code> is an <code>Employee</code> with a bonus. <strong>Inheritance</strong> lets the second class take everything the first has and add to it, so the shared part is written once.</p><pre style="background:var(--bg-2, var(--surface-2)); padding:12px; border-radius:8px; font-size:13px; overflow-x:auto; line-height:1.55;">public class Employee {
    protected String name;                    // protected: visible to subclasses
    private double salary;
    public Employee(String n, double s) { name = n; salary = s; }
    public double getSalary() { return salary; }
}

public class Manager extends Employee {
    private double bonus;

    public Manager(String n, double s, double b) {
        super(n, s);                          // MUST be the first statement
        bonus = b;
    }

    public double totalPay() { return getSalary() + bonus; }
}</pre><p><code>super(...)</code> calls the parent constructor, and it has to come first for the same reason <code>this(...)</code> does (7.9): the inherited part of the object must be built before the subclass can add to it. If you omit it, Java inserts a call to the parent’s <em>no-argument</em> constructor — and if the parent has none, that is a compile error.</p><pre style="background:var(--bg-2, var(--surface-2)); padding:12px; border-radius:8px; font-size:13px; overflow-x:auto; line-height:1.55;">public class Employee { ... }
public class Manager extends Employee {      // Manager IS-A Employee
    public Manager(String n, double r) {
        super(n, r);                         // FIRST statement, always
    }
}</pre><p>A derived class inherits every field and method of its base class and adds its own. Java allows a class to extend exactly <strong>one</strong> class — single inheritance — while it may implement any number of interfaces.</p><p>Constructors are <em>not</em> inherited. The subclass constructor must run a superclass constructor first, and if you do not write <code>super(...)</code> Java inserts <code>super()</code> — the no-argument one. If the base class has no no-argument constructor, that inserted call does not compile, which is the usual cause of "constructor Employee in class Employee cannot be applied to given types".</p><p>Construction runs base-first: <code>Employee</code>'s constructor completes before <code>Manager</code>'s body starts, so the inherited half of the object is ready before the subclass touches it.</p><i data-d286u811="1" style="display:none"></i><div class="callout" data-lb="why" style="border-left-color:#4f46e5;"><div class="callout-label">📘 DEFINITION</div><p style="margin:0 0 7px;"><strong>Inheritance:</strong> a class taking on the fields and methods of another</p><p style="margin:0 0 7px;"><strong>Superclass / base class:</strong> the class being extended</p><p style="margin:0 0 7px;"><strong>Subclass / derived class:</strong> the class doing the extending</p><p style="margin:0 0 7px;"><strong>extends:</strong> the keyword declaring inheritance; a class may extend only one class</p><p style="margin:0 0 7px;"><strong>super(...):</strong> calls the superclass constructor; must be the first statement</p></div><div class="callout" data-lb="key" style="border-left-color:#22c55e;"><div class="callout-label">💡 WHY IT MATTERS</div><p>Inheritance is why Unit 12 works: every exception type extends <code>Exception</code>, so one <code>catch (Exception e)</code> can catch all of them. It is also the mechanism behind every collection interface in Unit 14.</p></div><p data-xref="1" style="margin:26px 0 0; padding-top:12px; border-top:1px solid var(--border);font-size:12.5px; opacity:0.72;">✅ Also covered in depth: <strong>Inheritance → Inheritance with extends and super</strong></p><i data-tbc101="1" style="display:none"></i><div class="vl" data-mathvis="1" data-c959fig="1" style="margin-top:18px;"><div style="font-weight:700; font-size:12.5px; letter-spacing:0.05em; margin-bottom:6px;">📊 FIGURE — ONE OBJECT, TWO HALVES — AND THE BASE HALF IS BUILT FIRST</div><div style="border:1px solid var(--border); border-radius:12px; background:var(--surface-2); padding:14px 10px; overflow-x:auto;"><svg viewBox="0 0 820 350" style="width:100%; max-width:760px; display:block; margin:0 auto; font-family:inherit;" xmlns="http://www.w3.org/2000/svg"><defs><marker id="fk257a" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0,1 L9,5 L0,9 z" fill="var(--text)"/></marker></defs><text x="200" y="24" fill="var(--accent)" font-size="11.5" font-weight="700" text-anchor="middle">THE OBJECT ON THE HEAP</text><rect x="40" y="40" width="320" height="150" rx="10" fill="none" stroke="var(--text)" stroke-width="2"/><text x="200" y="60" fill="var(--text)" font-size="12.5" font-weight="700" text-anchor="middle">one Manager object</text><rect x="62" y="74" width="276" height="56" rx="6" fill="var(--surface)" stroke="var(--text-3)" stroke-width="1.4"/><text x="200" y="94" fill="var(--text-3)" font-size="11" font-weight="700" text-anchor="middle">the Employee part</text><text x="200" y="114" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">name    salary</text><rect x="62" y="136" width="276" height="42" rx="6" fill="var(--accent-bg)" stroke="var(--accent)" stroke-width="1.6"/><text x="200" y="155" fill="var(--accent)" font-size="11" font-weight="700" text-anchor="middle">the Manager part</text><text x="200" y="171" fill="var(--accent)" font-size="10.5" font-weight="400" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">bonus</text><text x="200" y="210" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-style="italic">inherited fields are not copies — they are part of the same object</text><line x1="400" y1="30" x2="400" y2="250" stroke="var(--border)" stroke-width="1"/><text x="618" y="24" fill="var(--accent)" font-size="11.5" font-weight="700" text-anchor="middle">THE ORDER THE CONSTRUCTORS RUN</text><rect x="440" y="42" width="356" height="32" rx="7" fill="var(--surface)" stroke="var(--text)" stroke-width="1.5"/><text x="618" y="62.5" fill="var(--text)" font-size="11" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">new Manager("Ada", 90000, 10000)</text><line x1="618" y1="74" x2="618" y2="92" stroke="var(--text)" stroke-width="1.6" marker-end="url(#fk257a)"/><rect x="440" y="92" width="356" height="32" rx="7" fill="var(--accent-bg)" stroke="var(--accent)" stroke-width="1.5"/><text x="618" y="112.5" fill="var(--text)" font-size="10.5" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">Manager(…) — first statement: super(n, s)</text><line x1="618" y1="124" x2="618" y2="142" stroke="var(--text)" stroke-width="1.6" marker-end="url(#fk257a)"/><rect x="440" y="142" width="356" height="32" rx="7" fill="var(--surface)" stroke="var(--text)" stroke-width="1.5"/><text x="618" y="162.5" fill="var(--text)" font-size="10.5" font-weight="700" text-anchor="middle">Employee(…) body runs — name and salary set</text><line x1="618" y1="174" x2="618" y2="192" stroke="var(--text)" stroke-width="1.6" marker-end="url(#fk257a)"/><rect x="440" y="192" width="356" height="32" rx="7" fill="var(--surface)" stroke="var(--text)" stroke-width="1.5"/><text x="618" y="212.5" fill="var(--text)" font-size="10.5" font-weight="700" text-anchor="middle">Manager(…) body resumes — bonus set</text><text x="618" y="244" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-style="italic">base first, always — the inherited half must exist before you extend it</text><line x1="30" y1="268" x2="790" y2="268" stroke="var(--border)" stroke-width="1"/><text x="410" y="294" fill="var(--accent)" font-size="11.5" font-weight="700" text-anchor="middle">WHAT extends GIVES YOU</text><rect x="52" y="306" width="224" height="34" rx="7" fill="var(--surface)" stroke="var(--text)" stroke-width="1.5"/><text x="164" y="327.5" fill="var(--text)" font-size="11.5" font-weight="700" text-anchor="middle">every field and method</text><rect x="298" y="306" width="224" height="34" rx="7" fill="var(--surface)" stroke="var(--text)" stroke-width="1.5"/><text x="410" y="327.5" fill="var(--text)" font-size="11.5" font-weight="700" text-anchor="middle">exactly ONE superclass</text><rect x="544" y="306" width="224" height="34" rx="7" fill="var(--accent-bg)" stroke="var(--accent)" stroke-width="1.5"/><text x="656" y="327.5" fill="var(--text)" font-size="11.5" font-weight="700" text-anchor="middle">NOT the constructors</text></svg></div></div><div class="callout" data-lb="key" style="border-left-color:#0ea5e9;"><div class="callout-label">▸ WORKED EXAMPLE — WATCHING THE CONSTRUCTORS RUN IN ORDER</div><p>Printing inside both constructors makes the ordering visible instead of asserted.</p><pre style="background:var(--surface-2); border:1px solid var(--border); border-radius:8px; padding:11px 13px; overflow-x:auto; font-size:13px; line-height:1.55; margin:10px 0;"><code>static class Employee {
    protected String name;
    private double salary;
    Employee(String n, double s) {
        System.out.println("  Employee ctor: " + n);
        name = n; salary = s;
    }
    double getSalary() { return salary; }
}
static class Manager extends Employee {
    private double bonus;
    Manager(String n, double s, double b) {
        super(n, s);                                   // MUST be first
        System.out.println("  Manager ctor: bonus " + b);
        bonus = b;
    }
    double totalPay() { return getSalary() + bonus; }
}

public static void main(String[] args) {
    System.out.println("building a Manager:");
    Manager m = new Manager("Ada", 90000, 10000);
    System.out.println("name    = " + m.name);
    System.out.println("salary  = " + m.getSalary());
    System.out.println("total   = " + m.totalPay());
}</code></pre><ol style="margin:8px 0 4px 18px; padding:0; line-height:1.65;"><li style="margin-bottom:5px;"><code>new Manager(...)</code> allocates <strong>one</strong> object big enough for both halves, then runs Manager's constructor.</li><li style="margin-bottom:5px;">The first statement is <code>super(n, s)</code>, so Employee's constructor runs to completion before anything else — its print appears first.</li><li style="margin-bottom:5px;">Only then does Manager's own body execute. The output order proves it: Employee, then Manager, never the reverse.</li><li style="margin-bottom:5px;"><code>m.name</code> works because <code>name</code> is <code>protected</code> and Manager inherited it. It is not a copy — it is the same field, in the same object.</li><li style="margin-bottom:5px;"><code>m.getSalary()</code> works even though <code>salary</code> is <code>private</code>. The field is inside the object; the inherited public method is the only way to read it, which is encapsulation surviving inheritance intact.</li><li style="margin-bottom:5px;"><code>totalPay()</code> is Manager's own addition, combining an inherited method with a new field: 90000 + 10000 = 100000.</li></ol><div style="margin:9px 0 4px;"><span style="font-size:11px; font-weight:700; letter-spacing:0.05em; color:var(--text-3);">OUTPUT</span></div><pre style="background:var(--surface-3, var(--surface-2)); border-left:3px solid var(--accent); border-radius:0 8px 8px 0; padding:9px 13px; overflow-x:auto; font-size:13px; line-height:1.5; margin:0 0 10px;"><code>building a Manager:
  Employee ctor: Ada
  Manager ctor: bonus 10000.0
name    = Ada
salary  = 90000.0
total   = 100000.0</code></pre></div><div class="callout" data-lb="key" style="border-left-color:#0ea5e9;"><div class="callout-label">▸ WORKED EXAMPLE — THE INVISIBLE super() — AND WHEN IT STOPS COMPILING</div><p>If you do not write <code>super(...)</code>, Java inserts <code>super()</code> — the no-argument one. Here the chain is three deep, so the effect is easy to see.</p><pre style="background:var(--surface-2); border:1px solid var(--border); border-radius:8px; padding:11px 13px; overflow-x:auto; font-size:13px; line-height:1.55; margin:10px 0;"><code>static class Vehicle {
    Vehicle() { System.out.println("Vehicle()"); }
    Vehicle(String tag) { System.out.println("Vehicle(" + tag + ")"); }
}
static class Car extends Vehicle {
    Car() { System.out.println("Car()"); }                 // implicit super()
    Car(String tag) { super(tag); System.out.println("Car(" + tag + ")"); }
}
static class Taxi extends Car {
    Taxi() { super("fleet"); System.out.println("Taxi()"); }
}

public static void main(String[] args) {
    new Car();
    System.out.println("---");
    new Taxi();
}</code></pre><ol style="margin:8px 0 4px 18px; padding:0; line-height:1.65;"><li style="margin-bottom:5px;"><code>new Car()</code> runs <code>Car()</code>, which contains no <code>super</code> call — so the compiler put <code>super();</code> at the top for you. <code>Vehicle()</code> prints first, then <code>Car()</code>.</li><li style="margin-bottom:5px;"><code>new Taxi()</code> runs <code>Taxi()</code>, whose explicit <code>super("fleet")</code> selects <code>Car(String)</code>.</li><li style="margin-bottom:5px;"><code>Car(String)</code> in turn calls <code>super(tag)</code>, selecting <code>Vehicle(String)</code>. The chain runs to the top before any body executes.</li><li style="margin-bottom:5px;">Unwinding, the bodies print from the top down: Vehicle, then Car, then Taxi. <strong>Every constructor chain runs root-first.</strong></li></ol><div style="margin:9px 0 4px;"><span style="font-size:11px; font-weight:700; letter-spacing:0.05em; color:var(--text-3);">OUTPUT</span></div><pre style="background:var(--surface-3, var(--surface-2)); border-left:3px solid var(--accent); border-radius:0 8px 8px 0; padding:9px 13px; overflow-x:auto; font-size:13px; line-height:1.5; margin:0 0 10px;"><code>Vehicle()
Car()
---
Vehicle(fleet)
Car(fleet)
Taxi()</code></pre><p>Now remove <code>Vehicle()</code>, leaving only <code>Vehicle(String)</code>. The inserted <code>super()</code> in <code>Car()</code> has nothing to call, and the compiler says so:</p><pre style="background:var(--surface-2); border:1px solid var(--border); border-radius:8px; padding:11px 13px; overflow-x:auto; font-size:13px; line-height:1.55; margin:10px 0;"><code>class Employee {
    Employee(String n) { }        // no no-arg constructor
}
class Manager extends Employee {
    Manager() { }                  // compiler inserts super();
}</code></pre><div style="margin:9px 0 4px;"><span style="font-size:11px; font-weight:700; letter-spacing:0.05em; color:var(--text-3);">OUTPUT</span></div><pre style="background:var(--surface-3, var(--surface-2)); border-left:3px solid var(--accent); border-radius:0 8px 8px 0; padding:9px 13px; overflow-x:auto; font-size:13px; line-height:1.5; margin:0 0 10px;"><code>error: constructor Employee in class Employee cannot be applied to given types;
    Manager() { }
              ^
  required: String
  found:    no arguments</code></pre><p>That message is one of the most common in this course, and the cause is always the same: a base class with no no-argument constructor, and a subclass constructor that did not call <code>super(...)</code> explicitly. The fix is to write the call.</p></div><div class="callout" data-lb="key" style="border-left-color:#f59e0b;"><div class="callout-label">⚠️ COMMON MISTAKE</div><p><strong>Expecting constructors to be inherited.</strong> They are not. Giving <code>Employee</code> a <code>(String, double)</code> constructor does <em>not</em> give <code>Manager</code> one — <code>new Manager("Ada", 90000)</code> will not compile unless Manager declares that constructor itself and passes the values up with <code>super(...)</code>.</p><p>The related slip: putting <code>super(...)</code> somewhere other than the first line, usually after a validation check. That is a compile error — "call to super must be first statement in constructor" — because the inherited half of the object has to be built before any code can touch it. Validate <em>inside the argument</em> instead, or use a static helper method in the call.</p><p>How to notice both: any error mentioning <em>constructor … cannot be applied</em> or <em>call to super must be first statement</em> is this, not a problem with the fields.</p></div><div class="callout" data-lb="key" style="border-left-color:#e11d48;"><div class="callout-label">🎯 EXAM TIP</div><p>Four facts about <code>extends</code> answer nearly every question in this section:</p><p>① <strong>One superclass only.</strong> <code>class A extends B, C</code> is a compile error. Multiple <em>interfaces</em> are fine — that is the distinction being tested.<br>② <strong>Constructors are never inherited</strong>, and <code>super(...)</code> must be the first statement.<br>③ <strong>Construction runs base-first</strong>, so if a question prints from several constructors, the topmost class prints first.<br>④ <strong>Private members are inherited but not accessible.</strong> The field exists in the object; the subclass simply cannot name it.</p><p>When a question shows a hierarchy and asks "what prints?", write the constructor chain top-down before you read the options. The order of print statements is usually the whole answer.</p></div>"},"D286/u10/z10_2":{"body":"<p>Access modifiers decide what a subclass can reach, and this is where <code>protected</code> finally earns its place — it is the level that exists specifically for inheritance.</p><pre style="background:var(--bg-2, var(--surface-2)); padding:12px; border-radius:8px; font-size:13px; overflow-x:auto; line-height:1.55;">                same class   same package   subclass   everywhere
public              yes           yes            yes        yes
protected           yes           yes            yes        no
(no modifier)       yes           yes            no         no
private             yes           no             no         no</pre><p>So a subclass cannot touch a <code>private</code> field of its parent — not because inheritance is broken, but because <code>private</code> means private. The inherited field is there in the object; it is simply reachable only through the parent’s public or protected methods.</p><pre style="background:var(--bg-2, var(--surface-2)); padding:12px; border-radius:8px; font-size:13px; overflow-x:auto; line-height:1.55;">public class Manager extends Employee {
    void demo() {
        name = "x";           // OK if name is protected
        salary = 1;           // ERROR if salary is private
        getSalary();          // the correct route
    }
}</pre><div style="overflow-x:auto; margin:14px 0;"><table style="border-collapse:collapse; width:100%; font-size:14.5px;"><thead><tr><th style="text-align:left; padding:7px 12px 7px 0; border-bottom:2px solid var(--border); font-size:12.5px; letter-spacing:.03em; text-transform:uppercase; opacity:.75;">Modifier</th><th style="text-align:left; padding:7px 12px 7px 0; border-bottom:2px solid var(--border); font-size:12.5px; letter-spacing:.03em; text-transform:uppercase; opacity:.75;">Subclass in another package can see it?</th></tr></thead><tbody><tr><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;"><code>public</code></td><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">yes</td></tr><tr><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;"><code>protected</code></td><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;"><strong>yes</strong> — this is what protected is for</td></tr><tr><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">package-private (no modifier)</td><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">no</td></tr><tr><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;"><code>private</code></td><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;"><strong>no</strong> — not even a subclass</td></tr></tbody></table></div><p>A private field <em>is</em> inherited — the subclass object contains it — but the subclass cannot name it. It must go through an inherited <code>public</code> or <code>protected</code> accessor, which is exactly the encapsulation of 7.4 continuing to hold.</p><p><code>protected</code> is the middle setting that exists for inheritance: visible to subclasses anywhere and to the whole of its own package, but not to unrelated classes. Making everything protected "so subclasses can get at it" gives away the ability to change those fields later.</p><i data-d286u811="1" style="display:none"></i><div class="callout" data-lb="why" style="border-left-color:#4f46e5;"><div class="callout-label">📘 DEFINITION</div><p style="margin:0 0 7px;"><strong>protected:</strong> accessible within the package and to subclasses anywhere</p><p style="margin:0 0 7px;"><strong>Package-private:</strong> the default with no modifier; package only, not subclasses in other packages</p><p style="margin:0 0 7px;"><strong>Inherited but inaccessible:</strong> a private field exists in the subclass object but cannot be named there</p></div><div class="callout" data-lb="oa" style="border-left-color:#e11d48;"><div class="callout-label">🎯 EXAM TIP</div><p>Prefer <code>private</code> plus a <code>protected</code> getter over a <code>protected</code> field. It keeps the validation point of 7.4 intact even for subclasses.</p></div><p data-xref="1" style="margin:26px 0 0; padding-top:12px; border-top:1px solid var(--border);font-size:12.5px; opacity:0.72;">✅ Also covered in depth: <strong>Inheritance → Inheritance with extends and super</strong></p><i data-tbc102="1" style="display:none"></i><div class="vl" data-mathvis="1" data-c959fig="1" style="margin-top:18px;"><div style="font-weight:700; font-size:12.5px; letter-spacing:0.05em; margin-bottom:6px;">📊 FIGURE — HOW FAR EACH MODIFIER REACHES</div><div style="border:1px solid var(--border); border-radius:12px; background:var(--surface-2); padding:14px 10px; overflow-x:auto;"><svg viewBox="0 0 820 300" style="width:100%; max-width:760px; display:block; margin:0 auto; font-family:inherit;" xmlns="http://www.w3.org/2000/svg"><defs><marker id="fk258a" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0,1 L9,5 L0,9 z" fill="var(--text)"/></marker></defs><text x="269" y="34" fill="var(--text-3)" font-size="10.5" font-weight="700" text-anchor="middle">the same class</text><text x="407" y="34" fill="var(--text-3)" font-size="10.5" font-weight="700" text-anchor="middle">the same package</text><text x="545" y="34" fill="var(--text-3)" font-size="10.5" font-weight="700" text-anchor="middle">a SUBCLASS</text><text x="545" y="47" fill="var(--text-3)" font-size="9.5" font-weight="400" text-anchor="middle">in another package</text><text x="683" y="34" fill="var(--text-3)" font-size="10.5" font-weight="700" text-anchor="middle">anywhere else</text><text x="184" y="78" fill="var(--text)" font-size="11.5" font-weight="700" text-anchor="end" font-family="ui-monospace,Menlo,monospace">public</text><rect x="200" y="58" width="138" height="30" rx="0" fill="var(--accent-bg)" stroke="var(--border)" stroke-width="1.2"/><text x="269" y="78" fill="var(--accent)" font-size="11" font-weight="700" text-anchor="middle">reaches</text><rect x="338" y="58" width="138" height="30" rx="0" fill="var(--accent-bg)" stroke="var(--border)" stroke-width="1.2"/><text x="407" y="78" fill="var(--accent)" font-size="11" font-weight="700" text-anchor="middle">reaches</text><rect x="476" y="58" width="138" height="30" rx="0" fill="var(--accent-bg)" stroke="var(--border)" stroke-width="1.2"/><text x="545" y="78" fill="var(--accent)" font-size="11" font-weight="700" text-anchor="middle">reaches</text><rect x="614" y="58" width="138" height="30" rx="0" fill="var(--accent-bg)" stroke="var(--border)" stroke-width="1.2"/><text x="683" y="78" fill="var(--accent)" font-size="11" font-weight="700" text-anchor="middle">reaches</text><text x="184" y="116" fill="var(--text)" font-size="11.5" font-weight="700" text-anchor="end" font-family="ui-monospace,Menlo,monospace">protected</text><rect x="200" y="96" width="138" height="30" rx="0" fill="var(--accent-bg)" stroke="var(--border)" stroke-width="1.2"/><text x="269" y="116" fill="var(--accent)" font-size="11" font-weight="700" text-anchor="middle">reaches</text><rect x="338" y="96" width="138" height="30" rx="0" fill="var(--accent-bg)" stroke="var(--border)" stroke-width="1.2"/><text x="407" y="116" fill="var(--accent)" font-size="11" font-weight="700" text-anchor="middle">reaches</text><rect x="476" y="96" width="138" height="30" rx="0" fill="var(--accent-bg)" stroke="var(--border)" stroke-width="1.2"/><text x="545" y="116" fill="var(--accent)" font-size="11" font-weight="700" text-anchor="middle">reaches</text><rect x="614" y="96" width="138" height="30" rx="0" fill="none" stroke="var(--border)" stroke-width="1.2"/><text x="683" y="116" fill="var(--text-3)" font-size="11" font-weight="400" text-anchor="middle">—</text><text x="184" y="154" fill="var(--text)" font-size="11.5" font-weight="700" text-anchor="end" font-family="ui-monospace,Menlo,monospace">(no modifier)</text><rect x="200" y="134" width="138" height="30" rx="0" fill="var(--accent-bg)" stroke="var(--border)" stroke-width="1.2"/><text x="269" y="154" fill="var(--accent)" font-size="11" font-weight="700" text-anchor="middle">reaches</text><rect x="338" y="134" width="138" height="30" rx="0" fill="var(--accent-bg)" stroke="var(--border)" stroke-width="1.2"/><text x="407" y="154" fill="var(--accent)" font-size="11" font-weight="700" text-anchor="middle">reaches</text><rect x="476" y="134" width="138" height="30" rx="0" fill="none" stroke="var(--border)" stroke-width="1.2"/><text x="545" y="154" fill="var(--text-3)" font-size="11" font-weight="400" text-anchor="middle">—</text><rect x="614" y="134" width="138" height="30" rx="0" fill="none" stroke="var(--border)" stroke-width="1.2"/><text x="683" y="154" fill="var(--text-3)" font-size="11" font-weight="400" text-anchor="middle">—</text><text x="184" y="192" fill="var(--text)" font-size="11.5" font-weight="700" text-anchor="end" font-family="ui-monospace,Menlo,monospace">private</text><rect x="200" y="172" width="138" height="30" rx="0" fill="var(--accent-bg)" stroke="var(--border)" stroke-width="1.2"/><text x="269" y="192" fill="var(--accent)" font-size="11" font-weight="700" text-anchor="middle">reaches</text><rect x="338" y="172" width="138" height="30" rx="0" fill="none" stroke="var(--border)" stroke-width="1.2"/><text x="407" y="192" fill="var(--text-3)" font-size="11" font-weight="400" text-anchor="middle">—</text><rect x="476" y="172" width="138" height="30" rx="0" fill="none" stroke="var(--border)" stroke-width="1.2"/><text x="545" y="192" fill="var(--text-3)" font-size="11" font-weight="400" text-anchor="middle">—</text><rect x="614" y="172" width="138" height="30" rx="0" fill="none" stroke="var(--border)" stroke-width="1.2"/><text x="683" y="192" fill="var(--text-3)" font-size="11" font-weight="400" text-anchor="middle">—</text><text x="410" y="224" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-style="italic">protected is the one level that exists FOR inheritance — the only difference from package-private</text><text x="410" y="242" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-style="italic">is that third column, and that is exactly what the exam asks about</text><line x1="476" y1="52" x2="476" y2="202" stroke="var(--accent)" stroke-width="2" stroke-dasharray="6 4"/><line x1="614" y1="52" x2="614" y2="202" stroke="var(--accent)" stroke-width="2" stroke-dasharray="6 4"/><text x="410" y="276" fill="var(--accent)" font-size="11.5" font-weight="700" text-anchor="middle">A PRIVATE FIELD IS STILL IN THE OBJECT — THE SUBCLASS JUST CANNOT NAME IT</text></svg></div></div><div class="callout" data-lb="key" style="border-left-color:#0ea5e9;"><div class="callout-label">▸ WORKED EXAMPLE — WHAT A SUBCLASS CAN TOUCH, LINE BY LINE</div><p>Three fields with three different modifiers, and a subclass that uses each in the only way it is allowed to.</p><pre style="background:var(--surface-2); border:1px solid var(--border); border-radius:8px; padding:11px 13px; overflow-x:auto; font-size:13px; line-height:1.55; margin:10px 0;"><code>static class Account {
    public    String id      = "AC-1";
    protected double balance = 250.00;
    private   String pin     = "1234";
    protected double read() { return balance; }
    public String toString() { return id + " " + balance + " " + pin; }
}
static class Savings extends Account {
    double withdraw(double amt) {
        // pin;                                   // would NOT compile
        if (amt &lt;= balance) { balance -= amt; }   // protected — fine
        return balance;
    }
    String describe() { return id + " has " + read(); }   // public + protected
}

Savings s = new Savings();
System.out.println(s.describe());
System.out.println(s.withdraw(80));
System.out.println(s);</code></pre><ol style="margin:8px 0 4px 18px; padding:0; line-height:1.65;"><li style="margin-bottom:5px;"><code>id</code> is <code>public</code>, so <code>describe()</code> names it directly.</li><li style="margin-bottom:5px;"><code>balance</code> is <code>protected</code>, so <code>withdraw</code> can both read and assign it. This is the level that exists specifically so subclasses can work with inherited state.</li><li style="margin-bottom:5px;"><code>read()</code> is a protected <em>method</em> — inherited and callable from the subclass for the same reason.</li><li style="margin-bottom:5px;"><code>pin</code> is <code>private</code>. The commented line would fail with <code>error: pin has private access in Account</code>. Note the wording: the field is <em>there</em>, it simply has private access.</li><li style="margin-bottom:5px;">The proof that <code>pin</code> exists in the Savings object is the last line. <code>toString()</code> was inherited from Account, it prints <code>pin</code>, and it prints correctly — because that method is <em>inside</em> Account, where <code>pin</code> is visible.</li><li style="margin-bottom:5px;"><code>withdraw(80)</code> takes the balance from 250.00 to 170.00, and the final <code>toString()</code> shows all three fields including the one the subclass could never name.</li></ol><div style="margin:9px 0 4px;"><span style="font-size:11px; font-weight:700; letter-spacing:0.05em; color:var(--text-3);">OUTPUT</span></div><pre style="background:var(--surface-3, var(--surface-2)); border-left:3px solid var(--accent); border-radius:0 8px 8px 0; padding:9px 13px; overflow-x:auto; font-size:13px; line-height:1.5; margin:0 0 10px;"><code>AC-1 has 250.0
170.0
AC-1 170.0 1234</code></pre><p>That is the whole idea of "inherited but inaccessible": the data is part of the object, and the base class's own methods are the door to it.</p></div><div class="callout" data-lb="key" style="border-left-color:#0ea5e9;"><div class="callout-label">▸ WORKED EXAMPLE — CHOOSING A MODIFIER FOR A REAL FIELD</div><p>The question is never "what is legal" but "who should be able to change this". Work through <code>balance</code> on an <code>Account</code> with a <code>Savings</code> subclass in another package.</p><div style="overflow-x:auto; margin:14px 0;"><table style="border-collapse:collapse; width:100%; font-size:14.5px;"><thead><tr><th style="text-align:left; padding:7px 12px 7px 0; border-bottom:2px solid var(--border); font-size:12.5px; letter-spacing:0.04em;">Choice</th><th style="text-align:left; padding:7px 12px 7px 0; border-bottom:2px solid var(--border); font-size:12.5px; letter-spacing:0.04em;">Who can assign <code>balance</code></th><th style="text-align:left; padding:7px 12px 7px 0; border-bottom:2px solid var(--border); font-size:12.5px; letter-spacing:0.04em;">What goes wrong</th></tr></thead><tbody><tr><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border); font-weight:600;"><code>public double balance</code></td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);">every class in the program</td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);">any code anywhere can set a negative balance; the class can no longer guarantee anything about its own state</td></tr><tr><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border); font-weight:600;"><code>protected double balance</code></td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);">Account, its package, and every subclass</td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);">safer, but every future subclass can still bypass validation — and subclasses are written by people who did not read your rules</td></tr><tr><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border); font-weight:600;"><code>private double balance</code> + <code>protected double getBalance()</code></td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);">Account only; subclasses read through the method</td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);">nothing — the single assignment point stays inside Account, where the checks live</td></tr></tbody></table></div><ol style="margin:8px 0 4px 18px; padding:0; line-height:1.65;"><li style="margin-bottom:5px;">Start at <code>private</code> and widen only when something concrete cannot be written. That is the opposite of the instinct to make everything <code>protected</code> "so subclasses can get at it".</li><li style="margin-bottom:5px;">A <code>protected</code> field is part of your class's permanent contract with every subclass, present and future. You cannot rename it, retype it, or start validating it later without breaking them.</li><li style="margin-bottom:5px;">A <code>protected</code> <em>method</em> costs far less: you can change the field behind it whenever you like, as long as the method keeps behaving.</li><li style="margin-bottom:5px;">The default — no modifier at all — is package-private, and the important thing to know is that it does <strong>not</strong> reach subclasses in other packages. It is the one people assume means "protected-ish", and it does not.</li></ol><p>So the practical rule for this course: <strong>fields private, accessors protected or public</strong>. The worked example above is the proof it costs nothing — <code>Savings</code> got everything it needed through <code>read()</code>.</p></div><div class="callout" data-lb="key" style="border-left-color:#f59e0b;"><div class="callout-label">⚠️ COMMON MISTAKE</div><p><strong>Believing "no modifier" means public, or means protected.</strong> It means <em>package-private</em>: visible to the whole package, invisible to a subclass in a different package. In single-file exercises everything is in one package, so the mistake is invisible — and then it appears the first time real code is split into packages.</p><p>The second half of the same trap: expecting <code>protected</code> to be <strong>narrower</strong> than package-private. It is not — it is wider in one direction and equal in the other. <code>protected</code> = package-private <em>plus</em> subclasses anywhere. There is no modifier meaning "subclasses only, not the package".</p><p>How to notice it: whenever an exam option involves "a subclass in a different package", the answer hinges on exactly one row of the reach chart. <code>public</code> and <code>protected</code> reach it; the default and <code>private</code> do not.</p></div>"},"D286/u10/z10_3":{"body":"<p><strong>Overriding</strong> replaces an inherited method with a new version in the subclass. It is not overloading (6.12): overriding keeps the signature identical and changes the behaviour.</p><pre style="background:var(--bg-2, var(--surface-2)); padding:12px; border-radius:8px; font-size:13px; overflow-x:auto; line-height:1.55;">public class Employee {
    public String describe() { return "Employee " + name; }
}

public class Manager extends Employee {
    @Override
    public String describe() {
        return "Manager " + name + " (" + super.describe() + ")";
    }                          //          ^ calls the PARENT version
}</pre><p>The <code>@Override</code> annotation is optional and worth always writing: it makes the compiler check that you really are overriding something, which turns a silent typo — <code>describe()</code> misspelled as <code>discribe()</code> — into a compile error instead of a method nobody calls.</p><pre style="background:var(--bg-2, var(--surface-2)); padding:12px; border-radius:8px; font-size:13px; overflow-x:auto; line-height:1.55;">class Employee { public double pay() { return base; } }

class Manager extends Employee {
    @Override
    public double pay() {
        return super.pay() + bonus;      // reuse the base version, then extend
    }
}</pre><p>An override replaces an inherited method with one of the <strong>same signature</strong>. Same name, same parameter list — change either and it is an overload, a second unrelated method, and the base version still runs.</p><p><code>@Override</code> is optional and worth writing every time: it asks the compiler to check that something really is being overridden, which turns a silent typo (<code>Pay()</code>, or a wrong parameter type) into a compile error.</p><div style="overflow-x:auto; margin:14px 0;"><table style="border-collapse:collapse; width:100%; font-size:14.5px;"><thead><tr><th style="text-align:left; padding:7px 12px 7px 0; border-bottom:2px solid var(--border); font-size:12.5px; letter-spacing:.03em; text-transform:uppercase; opacity:.75;"></th><th style="text-align:left; padding:7px 12px 7px 0; border-bottom:2px solid var(--border); font-size:12.5px; letter-spacing:.03em; text-transform:uppercase; opacity:.75;">Overriding</th><th style="text-align:left; padding:7px 12px 7px 0; border-bottom:2px solid var(--border); font-size:12.5px; letter-spacing:.03em; text-transform:uppercase; opacity:.75;">Overloading</th></tr></thead><tbody><tr><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">where</td><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">subclass replaces a base method</td><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">same class, several methods, one name</td></tr><tr><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">signature</td><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">must be identical</td><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">must differ</td></tr><tr><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">chosen</td><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">at <strong>run time</strong>, by the object</td><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">at compile time, by the arguments</td></tr></tbody></table></div><p>An override may widen visibility (protected → public) but never narrow it, and must not throw broader checked exceptions.</p><i data-d286u811="1" style="display:none"></i><div class="callout" data-lb="why" style="border-left-color:#4f46e5;"><div class="callout-label">📘 DEFINITION</div><p style="margin:0 0 7px;"><strong>Overriding:</strong> redefining an inherited method with the same signature</p><p style="margin:0 0 7px;"><strong>@Override:</strong> an annotation asking the compiler to verify the override</p><p style="margin:0 0 7px;"><strong>super.method():</strong> calls the superclass version from inside the override</p><p style="margin:0 0 7px;"><strong>Covariant return:</strong> an override may return a subtype of the original return type</p></div><div class="callout" data-lb="warn" style="border-left-color:#f59e0b;"><div class="callout-label">⚠ COMMON MISTAKE</div><p>Overloading versus overriding is the most-tested pair in Unit 10. Same name, <em>different</em> parameters, same class → overloading, resolved at compile time. Same name, <em>same</em> parameters, subclass → overriding, resolved at run time.</p></div><p data-xref="1" style="margin:26px 0 0; padding-top:12px; border-top:1px solid var(--border);font-size:12.5px; opacity:0.72;">✅ Also covered in depth: <strong>Inheritance → Method Overriding and Polymorphism</strong></p><i data-d286fx18="1" style="display:none"></i><div class="vl" data-mathvis="1" data-c959fig="1" style="margin-top:18px;"><div style="font-weight:700; font-size:12.5px; letter-spacing:0.05em; margin-bottom:6px;">📊 FIGURE — OVERRIDING: THE OBJECT DECIDES, NOT THE VARIABLE</div><div style="border:1px solid var(--border); border-radius:12px; background:var(--surface-2); padding:14px 10px; overflow-x:auto;"><svg viewBox="0 0 480 230" style="width:100%; max-width:520px; display:block; margin:0 auto; font-family:inherit;" xmlns="http://www.w3.org/2000/svg"><defs><marker id="fk85a" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0,1 L9,5 L0,9 z" fill="var(--text)"/></marker></defs><rect x="160" y="16" width="160" height="58" rx="8" fill="none" stroke="var(--text)" stroke-width="1.4"/><text x="240" y="36" fill="var(--text)" font-size="12" font-weight="700" text-anchor="middle">Animal</text><text x="240" y="56" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">speak(): "..."</text><rect x="40" y="120" width="160" height="58" rx="8" fill="#6366f122" stroke="#6366f1" stroke-width="1.4"/><text x="120" y="140" fill="var(--text)" font-size="11" font-weight="700" text-anchor="middle">Dog extends Animal</text><text x="120" y="160" fill="var(--text)" font-size="9.5" font-weight="400" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">speak(): "Woof" @Override</text><rect x="280" y="120" width="160" height="58" rx="8" fill="none" stroke="var(--text)" stroke-width="1.4"/><text x="360" y="140" fill="var(--text)" font-size="11" font-weight="700" text-anchor="middle">Cat extends Animal</text><text x="360" y="160" fill="var(--text)" font-size="9.5" font-weight="400" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">speak(): "Meow" @Override</text><line x1="120" y1="118" x2="210" y2="76" stroke="var(--text)" stroke-width="1.6" marker-end="url(#fk85a)"/><line x1="360" y1="118" x2="270" y2="76" stroke="var(--text)" stroke-width="1.6" marker-end="url(#fk85a)"/><text x="240" y="200" fill="var(--text)" font-size="12" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">Animal a = new Dog();  a.speak()  →  "Woof"</text><text x="240" y="222" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-style="italic">The OBJECT’s type (Dog) picks the method at runtime, not the variable’s declared type (Animal).</text></svg></div></div><div class="callout" data-lb="key" style="border-left-color:#e11d48;"><div class="callout-label">🎯 EXAM TIP</div>Two-step check for these questions: ① does the declared type HAVE the method (else compiler error)? ② which class’s VERSION runs — always the actual object’s. Fields, unlike methods, follow the declared type.</div><i data-tbc103="1" style="display:none"></i><div class="callout" data-lb="key" style="border-left-color:#0ea5e9;"><div class="callout-label">▸ WORKED EXAMPLE — OVERRIDE, OVERLOAD AND FIELD HIDING IN ONE PROGRAM</div><p>Three things that look alike in source and behave completely differently at run time. The output separates them.</p><pre style="background:var(--surface-2); border:1px solid var(--border); border-radius:8px; padding:11px 13px; overflow-x:auto; font-size:13px; line-height:1.55; margin:10px 0;"><code>static class Employee {
    protected String name = "Employee";
    String describe() { return "Employee " + name; }
    String describe(String prefix) { return prefix + " " + describe(); }   // OVERLOAD
}
static class Manager extends Employee {
    protected String name = "Manager";                  // HIDES the field
    @Override String describe() { return "Manager (" + super.describe() + ")"; }
}

public static void main(String[] args) {
    Manager  m = new Manager();
    Employee e = m;                       // same object, base-typed variable
    System.out.println(m.describe());
    System.out.println(e.describe());
    System.out.println(e.describe("Staff:"));
    System.out.println(e.name);
    System.out.println(m.name);
    System.out.println(((Employee) m).name);
}</code></pre><ol style="margin:8px 0 4px 18px; padding:0; line-height:1.65;"><li style="margin-bottom:5px;"><code>m.describe()</code> runs Manager's override, which calls <code>super.describe()</code> — Employee's version. Inside <em>that</em> method, the unqualified <code>name</code> means <strong>Employee's</strong> field, because fields are resolved where the code is written. So it produces <code>Employee Employee</code>, wrapped as <code>Manager (Employee Employee)</code>.</li><li style="margin-bottom:5px;"><code>e.describe()</code> prints exactly the same thing. The variable is typed <code>Employee</code>, but the object is a Manager, and <strong>methods are chosen by the object</strong>.</li><li style="margin-bottom:5px;"><code>e.describe("Staff:")</code> resolves to the one-argument <em>overload</em>, which exists only in Employee. Overloads are picked at compile time from the argument list. That method then calls <code>describe()</code> with no arguments, which dispatches to Manager's override — so the Manager text still appears.</li><li style="margin-bottom:5px;"><code>e.name</code> prints <strong>Employee</strong>. Fields do not dispatch. Two fields named <code>name</code> exist in this object, and which one you get is decided by the <em>declared type of the variable</em>.</li><li style="margin-bottom:5px;"><code>m.name</code> prints <strong>Manager</strong> — same object, different variable type, different field.</li><li style="margin-bottom:5px;"><code>((Employee) m).name</code> prints <strong>Employee</strong>, proving the point: casting changes nothing about the object, only about which field name is visible.</li></ol><div style="margin:9px 0 4px;"><span style="font-size:11px; font-weight:700; letter-spacing:0.05em; color:var(--text-3);">OUTPUT</span></div><pre style="background:var(--surface-3, var(--surface-2)); border-left:3px solid var(--accent); border-radius:0 8px 8px 0; padding:9px 13px; overflow-x:auto; font-size:13px; line-height:1.5; margin:0 0 10px;"><code>Manager (Employee Employee)
Manager (Employee Employee)
Staff: Manager (Employee Employee)
Employee
Manager
Employee</code></pre><p>Lines 4 to 6 are why field hiding is a bug rather than a technique: the same object answers <code>name</code> differently depending on how you happen to be holding it. Give the subclass field a different name, or reuse the inherited one.</p></div><div class="callout" data-lb="key" style="border-left-color:#0ea5e9;"><div class="callout-label">▸ WORKED EXAMPLE — WHAT COUNTS AS AN OVERRIDE — AND WHAT THE COMPILER SAYS WHEN IT IS NOT</div><p>Same name is not enough. The parameter list must match exactly; the return type may narrow; the visibility may only widen.</p><pre style="background:var(--surface-2); border:1px solid var(--border); border-radius:8px; padding:11px 13px; overflow-x:auto; font-size:13px; line-height:1.55; margin:10px 0;"><code>static class Shape {
    double area() { return 0; }
    Object copy() { return this; }
    void scale(double f) { System.out.println("Shape.scale " + f); }
}
static class Circle extends Shape {
    double r;
    Circle(double r) { this.r = r; }
    @Override double area() { return Math.PI * r * r; }      // true override
    @Override Circle copy() { return new Circle(r); }        // COVARIANT return — still an override
    void scale(int f) { System.out.println("Circle.scale(int) " + f); }   // OVERLOAD
}

Shape s = new Circle(2);
System.out.printf("%.4f%n", s.area());
s.scale(3);
s.scale(3.0);
Circle c = new Circle(2);
c.scale(3);
c.scale(3.0);
Circle copy = new Circle(5).copy();
System.out.printf("%.4f%n", copy.area());</code></pre><ol style="margin:8px 0 4px 18px; padding:0; line-height:1.65;"><li style="margin-bottom:5px;"><code>s.area()</code> runs Circle's version: π × 2² = 12.5664. A genuine override, chosen by the object.</li><li style="margin-bottom:5px;"><code>s.scale(3)</code> — the variable is a <code>Shape</code>, and <code>Shape</code> has only <code>scale(double)</code>. The int 3 widens to 3.0 and Shape's method runs. <code>Circle.scale(int)</code> is invisible from this variable.</li><li style="margin-bottom:5px;"><code>s.scale(3.0)</code> — same method, same output. Nothing surprising yet.</li><li style="margin-bottom:5px;"><code>c.scale(3)</code> with a <code>Circle</code> variable now sees both methods, and <code>scale(int)</code> is an exact match, so <strong>Circle's runs</strong>. Changing only the variable's type changed which method executes — the signature of an overload, not an override.</li><li style="margin-bottom:5px;"><code>c.scale(3.0)</code> falls back to Shape's. One object, two methods called <code>scale</code>, chosen entirely at compile time by the argument type.</li><li style="margin-bottom:5px;"><code>copy()</code> returns <code>Circle</code> where the base returned <code>Object</code>. That is a <strong>covariant return</strong> and it is a legal override — which is why <code>Circle copy = ...copy();</code> compiles with no cast. π × 5² = 78.5398.</li></ol><div style="margin:9px 0 4px;"><span style="font-size:11px; font-weight:700; letter-spacing:0.05em; color:var(--text-3);">OUTPUT</span></div><pre style="background:var(--surface-3, var(--surface-2)); border-left:3px solid var(--accent); border-radius:0 8px 8px 0; padding:9px 13px; overflow-x:auto; font-size:13px; line-height:1.5; margin:0 0 10px;"><code>12.5664
Shape.scale 3.0
Shape.scale 3.0
Circle.scale(int) 3
Shape.scale 3.0
78.5398</code></pre><p>Two overrides that are <em>not</em> allowed, with the compiler's exact words:</p><pre style="background:var(--surface-2); border:1px solid var(--border); border-radius:8px; padding:11px 13px; overflow-x:auto; font-size:13px; line-height:1.55; margin:10px 0;"><code>class Sub extends Base { protected String describe() { … } }   // Base had public</code></pre><div style="margin:9px 0 4px;"><span style="font-size:11px; font-weight:700; letter-spacing:0.05em; color:var(--text-3);">OUTPUT</span></div><pre style="background:var(--surface-3, var(--surface-2)); border-left:3px solid var(--accent); border-radius:0 8px 8px 0; padding:9px 13px; overflow-x:auto; font-size:13px; line-height:1.5; margin:0 0 10px;"><code>error: describe() in Sub cannot override describe() in Base
  attempting to assign weaker access privileges; was public</code></pre><pre style="background:var(--surface-2); border:1px solid var(--border); border-radius:8px; padding:11px 13px; overflow-x:auto; font-size:13px; line-height:1.55; margin:10px 0;"><code>class Sub extends Base { @Override public String discribe() { … } }   // typo</code></pre><div style="margin:9px 0 4px;"><span style="font-size:11px; font-weight:700; letter-spacing:0.05em; color:var(--text-3);">OUTPUT</span></div><pre style="background:var(--surface-3, var(--surface-2)); border-left:3px solid var(--accent); border-radius:0 8px 8px 0; padding:9px 13px; overflow-x:auto; font-size:13px; line-height:1.5; margin:0 0 10px;"><code>error: method does not override or implement a method from a supertype</code></pre><p>The second is the whole argument for writing <code>@Override</code>: without it, <code>discribe()</code> compiles perfectly as a brand-new method that nothing ever calls, and the program silently keeps using the base version.</p></div>"},"D286/u10/z10_4":{"body":"<p>Every class in Java extends <code>Object</code>, directly or through its parents. That is why every object already has <code>toString()</code>, <code>equals()</code> and <code>hashCode()</code> — and why the inherited versions are usually not what you want.</p><pre style="background:var(--bg-2, var(--surface-2)); padding:12px; border-radius:8px; font-size:13px; overflow-x:auto; line-height:1.55;">public class Student {
    private String name;
    private int score;

    @Override
    public String toString() {                 // called automatically by println
        return name + " (" + score + ")";
    }

    @Override
    public boolean equals(Object o) {
        if (!(o instanceof Student)) { return false; }
        Student other = (Student) o;
        return name.equals(other.name) &amp;&amp; score == other.score;
    }
}</pre><p>Without the override, <code>System.out.println(student)</code> prints something like <code>Student@1b6d3586</code> — the class name and a hash. And <code>equals</code> inherited from <code>Object</code> is just <code>==</code>, which is the identity comparison of 7.10 and almost never the comparison you want.</p><p>Every class extends <code>Object</code>, directly or through its ancestors, so every object has these whether you write them or not.</p><div style="overflow-x:auto; margin:14px 0;"><table style="border-collapse:collapse; width:100%; font-size:14.5px;"><thead><tr><th style="text-align:left; padding:7px 12px 7px 0; border-bottom:2px solid var(--border); font-size:12.5px; letter-spacing:.03em; text-transform:uppercase; opacity:.75;">Method</th><th style="text-align:left; padding:7px 12px 7px 0; border-bottom:2px solid var(--border); font-size:12.5px; letter-spacing:.03em; text-transform:uppercase; opacity:.75;">Default behaviour</th><th style="text-align:left; padding:7px 12px 7px 0; border-bottom:2px solid var(--border); font-size:12.5px; letter-spacing:.03em; text-transform:uppercase; opacity:.75;">Override it to</th></tr></thead><tbody><tr><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;"><code>toString()</code></td><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;"><code>Student@1b6d</code> — class name and hash</td><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">print something meaningful</td></tr><tr><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;"><code>equals(Object)</code></td><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">reference comparison, same as <code>==</code></td><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">compare contents</td></tr><tr><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;"><code>hashCode()</code></td><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">derived from the address</td><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">agree with <code>equals</code></td></tr></tbody></table></div><p><code>System.out.println(obj)</code> and String concatenation both call <code>toString()</code> automatically — so the <code>Student@1b6d</code> output is the visible sign that a class has not defined one.</p><p>The contract that matters: if two objects are <code>equals</code> they must return the same <code>hashCode</code>. Overriding <code>equals</code> without <code>hashCode</code> breaks <code>HashMap</code> and <code>HashSet</code>, which look the object up by hash first and never find it.</p><i data-d286u811="1" style="display:none"></i><div class="callout" data-lb="why" style="border-left-color:#4f46e5;"><div class="callout-label">📘 DEFINITION</div><p style="margin:0 0 7px;"><strong>Object:</strong> the root of the class hierarchy; every class inherits from it</p><p style="margin:0 0 7px;"><strong>toString():</strong> the String form of an object; called implicitly by println and concatenation</p><p style="margin:0 0 7px;"><strong>equals(Object):</strong> content comparison; must take Object as its parameter to be a true override</p><p style="margin:0 0 7px;"><strong>hashCode():</strong> must be overridden alongside equals for HashMap and HashSet to work (14.3)</p></div><div class="callout" data-lb="warn" style="border-left-color:#f59e0b;"><div class="callout-label">⚠ COMMON MISTAKE</div><p>Writing <code>equals(Student o)</code> instead of <code>equals(Object o)</code> creates an <em>overload</em>, not an override. The inherited identity version is still what collections call — which is why <code>@Override</code> is worth writing.</p></div><p data-xref="1" style="margin:26px 0 0; padding-top:12px; border-top:1px solid var(--border);font-size:12.5px; opacity:0.72;">✅ Also covered in depth: <strong>Advanced → equals(), hashCode() and toString()</strong></p><i data-tbc104="1" style="display:none"></i><div class="vl" data-mathvis="1" data-c959fig="1" style="margin-top:18px;"><div style="font-weight:700; font-size:12.5px; letter-spacing:0.05em; margin-bottom:6px;">📊 FIGURE — EVERY CLASS DESCENDS FROM Object — AND THE HASH CONTRACT</div><div style="border:1px solid var(--border); border-radius:12px; background:var(--surface-2); padding:14px 10px; overflow-x:auto;"><svg viewBox="0 0 820 400" style="width:100%; max-width:760px; display:block; margin:0 auto; font-family:inherit;" xmlns="http://www.w3.org/2000/svg"><defs><marker id="fk259a" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0,1 L9,5 L0,9 z" fill="var(--text)"/></marker></defs><rect x="310" y="36" width="200" height="93" rx="5" fill="var(--accent-bg)" stroke="var(--accent)" stroke-width="2.2"/><line x1="310" y1="64" x2="510" y2="64" stroke="var(--text)" stroke-width="1.2"/><line x1="310" y1="76" x2="510" y2="76" stroke="var(--text)" stroke-width="1.2"/><text x="410" y="55" fill="var(--text)" font-size="12.5" font-weight="700" text-anchor="middle">Object</text><text x="318" y="92" fill="var(--text)" font-size="10" font-weight="400" text-anchor="start" font-family="ui-monospace,Menlo,monospace">toString()</text><text x="318" y="107" fill="var(--text)" font-size="10" font-weight="400" text-anchor="start" font-family="ui-monospace,Menlo,monospace">equals(Object)</text><text x="318" y="122" fill="var(--text)" font-size="10" font-weight="400" text-anchor="start" font-family="ui-monospace,Menlo,monospace">hashCode()</text><line x1="410" y1="152" x2="410" y2="141" stroke="var(--text)" stroke-width="1.5"/><path d="M402,141 L410,129 L418,141 Z" fill="var(--surface)" stroke="var(--text)" stroke-width="1.5"/><line x1="120" y1="152" x2="680" y2="152" stroke="var(--text)" stroke-width="1.5"/><line x1="120" y1="152" x2="120" y2="168" stroke="var(--text)" stroke-width="1.5"/><line x1="300" y1="152" x2="300" y2="168" stroke="var(--text)" stroke-width="1.5"/><line x1="480" y1="152" x2="480" y2="168" stroke="var(--text)" stroke-width="1.5"/><line x1="680" y1="152" x2="680" y2="168" stroke="var(--text)" stroke-width="1.5"/><rect x="56" y="168" width="128" height="32" rx="7" fill="var(--surface)" stroke="var(--text)" stroke-width="1.5"/><text x="120" y="188.5" fill="var(--text)" font-size="11.5" font-weight="700" text-anchor="middle">String</text><rect x="236" y="168" width="128" height="32" rx="7" fill="var(--surface)" stroke="var(--text)" stroke-width="1.5"/><text x="300" y="188.5" fill="var(--text)" font-size="11.5" font-weight="700" text-anchor="middle">ArrayList</text><rect x="416" y="168" width="128" height="32" rx="7" fill="var(--surface)" stroke="var(--text)" stroke-width="1.5"/><text x="480" y="188.5" fill="var(--text)" font-size="11.5" font-weight="700" text-anchor="middle">Exception</text><rect x="616" y="168" width="128" height="32" rx="7" fill="var(--accent-bg)" stroke="var(--accent)" stroke-width="1.5"/><text x="680" y="188.5" fill="var(--text)" font-size="11.5" font-weight="700" text-anchor="middle">your Student</text><text x="410" y="224" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-style="italic">you never write "extends Object" — it is automatic, which is why every object already has these three</text><line x1="30" y1="248" x2="790" y2="248" stroke="var(--border)" stroke-width="1"/><text x="410" y="274" fill="var(--accent)" font-size="11.5" font-weight="700" text-anchor="middle">WHY equals WITHOUT hashCode BREAKS A HashSet</text><rect x="40" y="292" width="150" height="40" rx="7" fill="var(--surface)" stroke="var(--text)" stroke-width="1.5"/><text x="115" y="309" fill="var(--text)" font-size="11" font-weight="700" text-anchor="middle">new Student("Ada")</text><text x="115" y="325" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle">hashCode → 4021</text><line x1="190" y1="312" x2="236" y2="312" stroke="var(--text)" stroke-width="1.6" marker-end="url(#fk259a)"/><rect x="240" y="288" width="300" height="76" rx="8" fill="none" stroke="var(--border)" stroke-width="1.2"/><text x="390" y="304" fill="var(--text-3)" font-size="10" font-weight="700" text-anchor="middle">HashSet buckets</text><rect x="256" y="312" width="60" height="34" rx="4" fill="var(--accent-bg)" stroke="var(--accent)" stroke-width="1.3"/><text x="286" y="333" fill="var(--accent)" font-size="10.5" font-weight="700" text-anchor="middle">Ada</text><rect x="326" y="312" width="60" height="34" rx="4" fill="none" stroke="var(--text)" stroke-width="1.3"/><rect x="396" y="312" width="60" height="34" rx="4" fill="none" stroke="var(--text)" stroke-width="1.3"/><rect x="466" y="312" width="60" height="34" rx="4" fill="none" stroke="var(--text)" stroke-width="1.3"/><text x="286" y="360" fill="var(--text-3)" font-size="9" font-weight="400" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">4021</text><text x="496" y="360" fill="var(--text-3)" font-size="9" font-weight="400" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">9917</text><line x1="600" y1="300" x2="528" y2="322" stroke="var(--text-3)" stroke-width="1.6" stroke-dasharray="5 4" marker-end="url(#fk259a)"/><rect x="596" y="292" width="200" height="40" rx="7" fill="var(--surface)" stroke="var(--text-3)" stroke-width="1.5" stroke-dasharray="5 4"/><text x="696" y="309" fill="var(--text-3)" font-size="11" font-weight="700" text-anchor="middle">an equal Student</text><text x="696" y="325" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle">hashCode → 9917 — WRONG BUCKET</text><text x="660" y="358" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-style="italic">contains() looks in one bucket only, so it never finds it</text></svg></div></div><div class="callout" data-lb="key" style="border-left-color:#0ea5e9;"><div class="callout-label">▸ WORKED EXAMPLE — WHAT toString, equals AND hashCode DO BEFORE AND AFTER YOU OVERRIDE THEM</div><p>The default versions are inherited from <code>Object</code> and are almost never what you want. This program shows both states side by side.</p><pre style="background:var(--surface-2); border:1px solid var(--border); border-radius:8px; padding:11px 13px; overflow-x:auto; font-size:13px; line-height:1.55; margin:10px 0;"><code>static class Plain { int id = 7; }                       // no overrides
static class Student {
    String name; int score;
    Student(String n, int s) { name = n; score = s; }
    @Override public String toString() { return name + " (" + score + ")"; }
    @Override public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof Student)) return false;
        Student other = (Student) o;
        return score == other.score &amp;&amp; name.equals(other.name);
    }
    @Override public int hashCode() { return Objects.hash(name, score); }
}

Plain p = new Plain();
String s = p.toString();
System.out.println(s.startsWith("M104a$Plain@"));
System.out.println(s.equals("M104a$Plain@" + Integer.toHexString(p.hashCode())));

Student a = new Student("Ada", 95);
Student b = new Student("Ada", 95);
System.out.println(a);
System.out.println("a == b      : " + (a == b));
System.out.println("a.equals(b) : " + a.equals(b));
System.out.println("same hash   : " + (a.hashCode() == b.hashCode()));

Set&lt;Student&gt; set = new HashSet&lt;&gt;();
set.add(a); set.add(b);
System.out.println("set size    : " + set.size());
System.out.println("contains    : " + set.contains(new Student("Ada", 95)));
System.out.println("list toString: " + Arrays.asList(a, b));</code></pre><ol style="margin:8px 0 4px 18px; padding:0; line-height:1.65;"><li style="margin-bottom:5px;"><code>Plain</code> overrides nothing, so its <code>toString()</code> is the inherited one. The two <code>true</code> results prove its exact recipe: <strong>the class name, an <code>@</code>, and the hash code in hexadecimal</strong>. That output — <code>Plain@1b6d3586</code> — is the visible sign that a class has no <code>toString</code>.</li><li style="margin-bottom:5px;"><code>System.out.println(a)</code> calls <code>toString()</code> automatically, so the Student prints as <code>Ada (95)</code>. The same happens inside String concatenation.</li><li style="margin-bottom:5px;"><code>a == b</code> is <strong>false</strong> — two separate objects, two different addresses. <code>==</code> compares identity and always will; overriding <code>equals</code> does not change it.</li><li style="margin-bottom:5px;"><code>a.equals(b)</code> is <strong>true</strong>, because the override compares contents. The <code>instanceof</code> test also handles <code>null</code> safely: <code>null instanceof Student</code> is false, so a null argument returns false rather than throwing.</li><li style="margin-bottom:5px;"><code>hashCode()</code> agrees with <code>equals</code>: equal objects give equal hashes.</li><li style="margin-bottom:5px;">That agreement is what makes the collection lines work. Adding both to a <code>HashSet</code> gives size <strong>1</strong>, and <code>contains</code> finds a brand-new but equal Student.</li><li style="margin-bottom:5px;">The last line shows <code>toString</code> being used by the collection itself — a list prints its elements by calling theirs.</li></ol><div style="margin:9px 0 4px;"><span style="font-size:11px; font-weight:700; letter-spacing:0.05em; color:var(--text-3);">OUTPUT</span></div><pre style="background:var(--surface-3, var(--surface-2)); border-left:3px solid var(--accent); border-radius:0 8px 8px 0; padding:9px 13px; overflow-x:auto; font-size:13px; line-height:1.5; margin:0 0 10px;"><code>true
true
Ada (95)
a == b      : false
a.equals(b) : true
same hash   : true
set size    : 1
contains    : true
list toString: [Ada (95), Ada (95)]</code></pre></div><div class="callout" data-lb="key" style="border-left-color:#0ea5e9;"><div class="callout-label">▸ WORKED EXAMPLE — THE TWO WAYS equals GOES WRONG, WITH THE DAMAGE MEASURED</div><p>One class overloads instead of overriding; the other overrides <code>equals</code> but forgets <code>hashCode</code>. Both compile. Both are broken, in different places.</p><pre style="background:var(--surface-2); border:1px solid var(--border); border-radius:8px; padding:11px 13px; overflow-x:auto; font-size:13px; line-height:1.55; margin:10px 0;"><code>static class Badly {
    String code;
    Badly(String c) { code = c; }
    public boolean equals(Badly o) { return code.equals(o.code); }   // OVERLOAD
}
static class Half {
    String code;
    Half(String c) { code = c; }
    @Override public boolean equals(Object o) {
        return (o instanceof Half) &amp;&amp; code.equals(((Half) o).code);
    }
    // hashCode deliberately NOT overridden
}

Badly x = new Badly("A1"), y = new Badly("A1");
System.out.println("Badly, typed:  " + x.equals(y));
Object yo = y;
System.out.println("Badly, as Object: " + x.equals(yo));
List&lt;Badly&gt; bl = new ArrayList&lt;&gt;(); bl.add(x);
System.out.println("list.contains: " + bl.contains(y));

Half h1 = new Half("A1"), h2 = new Half("A1");
System.out.println("Half equals:   " + h1.equals(h2));
List&lt;Half&gt; hl = new ArrayList&lt;&gt;(); hl.add(h1);
System.out.println("list.contains: " + hl.contains(h2));
Set&lt;Half&gt; hs = new HashSet&lt;&gt;(); hs.add(h1);
System.out.println("set.contains:  " + hs.contains(h2));</code></pre><ol style="margin:8px 0 4px 18px; padding:0; line-height:1.65;"><li style="margin-bottom:5px;"><code>x.equals(y)</code> with both typed <code>Badly</code> picks the <em>overload</em> and returns <strong>true</strong>. Everything looks fine, which is why this bug survives testing.</li><li style="margin-bottom:5px;">Assign <code>y</code> to an <code>Object</code> variable and call again: now the argument type is <code>Object</code>, so the <strong>inherited</strong> identity version runs and returns <strong>false</strong>. Same two objects, opposite answer.</li><li style="margin-bottom:5px;"><code>bl.contains(y)</code> is <strong>false</strong>, because <code>ArrayList.contains</code> is written against <code>equals(Object)</code> — the version that was never overridden. The library can only call the real override, and there isn't one.</li><li style="margin-bottom:5px;"><code>Half</code> gets this right: <code>equals(Object)</code>, so <code>h1.equals(h2)</code> is true and <code>hl.contains(h2)</code> is <strong>true</strong> — an ArrayList searches linearly, calling <code>equals</code> on each element.</li><li style="margin-bottom:5px;">But <code>hs.contains(h2)</code> is <strong>false</strong>. A <code>HashSet</code> computes the hash first to choose a bucket, and the inherited <code>hashCode</code> is address-based, so <code>h1</code> and <code>h2</code> land in different buckets. <code>contains</code> looks in one bucket and never sees the equal object sitting in another.</li></ol><div style="margin:9px 0 4px;"><span style="font-size:11px; font-weight:700; letter-spacing:0.05em; color:var(--text-3);">OUTPUT</span></div><pre style="background:var(--surface-3, var(--surface-2)); border-left:3px solid var(--accent); border-radius:0 8px 8px 0; padding:9px 13px; overflow-x:auto; font-size:13px; line-height:1.5; margin:0 0 10px;"><code>Badly, typed:  true
Badly, as Object: false
list.contains: false
Half equals:   true
list.contains: true
set.contains:  false</code></pre><p>The fix in both cases is mechanical. Write <code>equals(Object)</code>, mark it <code>@Override</code>, and override <code>hashCode()</code> in the same commit — <code>return Objects.hash(field1, field2);</code> using exactly the fields <code>equals</code> compares.</p></div><div class="callout" data-lb="key" style="border-left-color:#e11d48;"><div class="callout-label">🎯 EXAM TIP</div><p><strong>Recognise <code>Student@1b6d3586</code> instantly.</strong> It means "this class has no <code>toString()</code>", and the format is always <em>class name @ hash in hex</em>. If a question shows that output, the answer involves a missing override.</p><p><strong>The equals/hashCode contract, stated the way it is tested:</strong> if <code>a.equals(b)</code> then <code>a.hashCode() == b.hashCode()</code> <em>must</em> hold. The reverse is not required — unequal objects may share a hash, which is just a collision.</p><p>Three near-certain question shapes:</p><p>① <code>equals(Student o)</code> versus <code>equals(Object o)</code> — the first is an overload and collections ignore it.<br>② <code>==</code> versus <code>.equals()</code> on two objects with identical contents: <code>==</code> false, <code>equals</code> true (assuming a proper override).<br>③ Overriding <code>equals</code> without <code>hashCode</code> — breaks <code>HashSet</code> and <code>HashMap</code>, leaves <code>ArrayList.contains</code> working. The asymmetry is the point.</p><p>Also worth knowing: <code>toString()</code> is called <em>implicitly</em> by <code>println</code>, by String concatenation, and by a collection printing its elements. You never have to call it by name.</p></div>"},"D286/u10/z10_5":{"body":"<p><strong>Polymorphism</strong> is the payoff of the whole unit: a variable of the parent type can hold any subclass object, and calling an overridden method runs the <em>subclass</em> version. The decision is made at run time from the actual object, not at compile time from the declared type.</p><pre style="background:var(--bg-2, var(--surface-2)); padding:12px; border-radius:8px; font-size:13px; overflow-x:auto; line-height:1.55;">Employee e = new Manager("Ada", 90000, 10000);   // legal — a Manager IS an Employee

e.describe();      // runs Manager's version — DYNAMIC DISPATCH
e.totalPay();      // COMPILE ERROR — the declared type is Employee,
                   // which has no totalPay

((Manager) e).totalPay();       // a downcast makes it visible again</pre><p>The two halves are easy to state together: the <strong>declared type</strong> decides what you may call, and the <strong>actual object</strong> decides which version runs. Nearly every polymorphism exam question is that sentence applied to specific code.</p><pre style="background:var(--bg-2, var(--surface-2)); padding:12px; border-radius:8px; font-size:13px; overflow-x:auto; line-height:1.55;">Employee e = new Manager("Ana", 30);   // base-type reference, subclass object
e.pay();                               // runs MANAGER's pay — decided at run time
e.approveLeave();                      // COMPILE ERROR — not on Employee

Employee[] staff = { new Employee(...), new Manager(...) };
for (Employee x : staff) total += x.pay();   // each runs its own version</pre><p>Two different rules apply at two different times, and keeping them apart answers nearly every polymorphism question:</p><div style="overflow-x:auto; margin:14px 0;"><table style="border-collapse:collapse; width:100%; font-size:14.5px;"><thead><tr><th style="text-align:left; padding:7px 12px 7px 0; border-bottom:2px solid var(--border); font-size:12.5px; letter-spacing:.03em; text-transform:uppercase; opacity:.75;">Decided by</th><th style="text-align:left; padding:7px 12px 7px 0; border-bottom:2px solid var(--border); font-size:12.5px; letter-spacing:.03em; text-transform:uppercase; opacity:.75;">When</th><th style="text-align:left; padding:7px 12px 7px 0; border-bottom:2px solid var(--border); font-size:12.5px; letter-spacing:.03em; text-transform:uppercase; opacity:.75;">Governs</th></tr></thead><tbody><tr><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">the <strong>reference type</strong></td><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">compile time</td><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">which methods you are <em>allowed</em> to call</td></tr><tr><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">the <strong>object type</strong></td><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">run time</td><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">which version actually <em>runs</em></td></tr></tbody></table></div><p>So a base-type reference can only call base-type methods, but the subclass's override is what executes — dynamic dispatch. That is what lets one loop over an array of mixed subclasses do the right thing for each.</p><p>Fields do not work this way. A field with the same name in a subclass <em>hides</em> rather than overrides, and which one you get is decided by the reference type — which is why field hiding is a bug, not a technique.</p><i data-d286u811="1" style="display:none"></i><div class="callout" data-lb="why" style="border-left-color:#4f46e5;"><div class="callout-label">📘 DEFINITION</div><p style="margin:0 0 7px;"><strong>Polymorphism:</strong> one reference type behaving as any of its subtypes</p><p style="margin:0 0 7px;"><strong>Dynamic dispatch:</strong> choosing the method implementation at run time from the object’s real class</p><p style="margin:0 0 7px;"><strong>Upcast:</strong> treating a subclass reference as its parent type; always safe and implicit</p><p style="margin:0 0 7px;"><strong>Downcast:</strong> casting back to the subclass; requires an explicit cast and can throw ClassCastException</p></div><div class="callout" data-lb="oa" style="border-left-color:#e11d48;"><div class="callout-label">🎯 EXAM TIP</div><p>Guard a downcast with <code>instanceof</code>. <code>if (e instanceof Manager) { ((Manager) e).totalPay(); }</code> is the safe idiom; casting blind throws <code>ClassCastException</code> at run time.</p></div><p data-xref="1" style="margin:26px 0 0; padding-top:12px; border-top:1px solid var(--border);font-size:12.5px; opacity:0.72;">✅ Also covered in depth: <strong>Inheritance → Method Overriding and Polymorphism</strong></p><i data-tbc105="1" style="display:none"></i><div class="vl" data-mathvis="1" data-c959fig="1" style="margin-top:18px;"><div style="font-weight:700; font-size:12.5px; letter-spacing:0.05em; margin-bottom:6px;">📊 FIGURE — TWO DECISIONS, TWO DIFFERENT TIMES</div><div style="border:1px solid var(--border); border-radius:12px; background:var(--surface-2); padding:14px 10px; overflow-x:auto;"><svg viewBox="0 0 820 400" style="width:100%; max-width:760px; display:block; margin:0 auto; font-family:inherit;" xmlns="http://www.w3.org/2000/svg"><defs><marker id="fk260a" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0,1 L9,5 L0,9 z" fill="var(--text)"/></marker></defs><rect x="40" y="44" width="300" height="40" rx="7" fill="var(--surface)" stroke="var(--text)" stroke-width="1.5"/><text x="190" y="68.5" fill="var(--text)" font-size="11.5" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">Employee e = new Manager("Ada", …);</text><line x1="120" y1="84" x2="120" y2="108" stroke="var(--accent)" stroke-width="1.6" stroke-dasharray="5 4"/><line x1="120" y1="108" x2="120" y2="126" stroke="var(--accent)" stroke-width="1.6" stroke-dasharray="5 4" marker-end="url(#fk260a)"/><text x="128" y="102" fill="var(--accent)" font-size="9.5" font-weight="700" text-anchor="start">declared type</text><rect x="30" y="126" width="180" height="46" rx="7" fill="var(--accent-bg)" stroke="var(--accent)" stroke-width="2.2"/><text x="120" y="146" fill="var(--text)" font-size="12" font-weight="700" text-anchor="middle">COMPILE TIME</text><text x="120" y="162" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle">which methods may I call?</text><rect x="30" y="182" width="180" height="88" rx="7" fill="var(--surface)" stroke="var(--text)" stroke-width="1.5"/><text x="120" y="230.5" fill="var(--text)" font-size="11" font-weight="700" text-anchor="middle"></text><text x="120" y="202" fill="var(--text)" font-size="10.5" font-weight="700" text-anchor="middle">Employee's members only</text><text x="120" y="222" fill="var(--text)" font-size="10.5" font-weight="400" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">pay()   ✓</text><text x="120" y="240" fill="var(--text)" font-size="10.5" font-weight="400" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">role()  ✓</text><text x="120" y="258" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">approveLeave()  ✗</text><text x="120" y="292" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-style="italic">cannot find symbol</text><line x1="260" y1="84" x2="260" y2="108" stroke="var(--accent)" stroke-width="1.6" stroke-dasharray="5 4"/><line x1="400" y1="108" x2="400" y2="126" stroke="var(--accent)" stroke-width="1.6" stroke-dasharray="5 4" marker-end="url(#fk260a)"/><line x1="260" y1="108" x2="400" y2="108" stroke="var(--accent)" stroke-width="1.6" stroke-dasharray="5 4"/><text x="300" y="100" fill="var(--accent)" font-size="9.5" font-weight="700" text-anchor="middle">actual object</text><rect x="310" y="126" width="180" height="46" rx="7" fill="var(--accent-bg)" stroke="var(--accent)" stroke-width="2.2"/><text x="400" y="146" fill="var(--text)" font-size="12" font-weight="700" text-anchor="middle">RUN TIME</text><text x="400" y="162" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle">whose version runs?</text><rect x="320" y="182" width="142" height="34" rx="7" fill="var(--accent-bg)" stroke="var(--accent)" stroke-width="1.5"/><text x="391" y="203.5" fill="var(--text)" font-size="11" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">Manager.pay()</text><text x="378" y="238" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-style="italic">found here — stop</text><line x1="480" y1="216" x2="480" y2="262" stroke="var(--text-3)" stroke-width="1.5" stroke-dasharray="4 3"/><path d="M472,262 L480,250 L488,262 Z" fill="var(--surface)" stroke="var(--text-3)" stroke-width="1.5"/><rect x="320" y="250" width="142" height="34" rx="7" fill="var(--surface)" stroke="var(--text-3)" stroke-width="1.5" stroke-dasharray="4 3"/><text x="391" y="271.5" fill="var(--text-3)" font-size="10.5" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">Employee.pay()</text><line x1="480" y1="284" x2="480" y2="330" stroke="var(--text-3)" stroke-width="1.5" stroke-dasharray="4 3"/><path d="M472,330 L480,318 L488,330 Z" fill="var(--surface)" stroke="var(--text-3)" stroke-width="1.5"/><rect x="320" y="318" width="142" height="34" rx="7" fill="var(--surface)" stroke="var(--text-3)" stroke-width="1.5" stroke-dasharray="4 3"/><text x="391" y="339.5" fill="var(--text-3)" font-size="11" font-weight="700" text-anchor="middle">Object</text><text x="400" y="372" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-style="italic">the search starts at the ACTUAL class and walks up</text><line x1="520" y1="36" x2="520" y2="380" stroke="var(--border)" stroke-width="1"/><text x="670" y="60" fill="var(--accent)" font-size="11.5" font-weight="700" text-anchor="middle">THE TWO RULES</text><rect x="546" y="78" width="246" height="56" rx="7" fill="var(--surface)" stroke="var(--text)" stroke-width="1.5"/><text x="669" y="103" fill="var(--text)" font-size="12" font-weight="700" text-anchor="middle">the REFERENCE type</text><text x="669" y="119" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle">decides what you may call</text><text x="669" y="152" fill="var(--text-3)" font-size="10" font-weight="400" text-anchor="middle" font-style="italic">checked by the compiler</text><rect x="546" y="168" width="246" height="56" rx="7" fill="var(--accent-bg)" stroke="var(--accent)" stroke-width="2.2"/><text x="669" y="193" fill="var(--text)" font-size="12" font-weight="700" text-anchor="middle">the OBJECT type</text><text x="669" y="209" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle">decides which version runs</text><text x="669" y="242" fill="var(--accent)" font-size="10" font-weight="400" text-anchor="middle" font-style="italic">resolved by the JVM</text><text x="669" y="276" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-style="italic">nearly every polymorphism question is</text><text x="669" y="292" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-style="italic">these two sentences applied to code</text><rect x="546" y="312" width="246" height="44" rx="7" fill="var(--surface)" stroke="var(--text-3)" stroke-width="1.5" stroke-dasharray="5 4"/><text x="669" y="331" fill="var(--text-3)" font-size="11.5" font-weight="700" text-anchor="middle">fields do NOT dispatch</text><text x="669" y="347" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle">a field follows the reference type</text></svg></div></div><div class="callout" data-lb="key" style="border-left-color:#0ea5e9;"><div class="callout-label">▸ WORKED EXAMPLE — ONE OBJECT, THREE BEHAVIOURS, AND THE TWO RULES IN ACTION</div><p>Every line below is one of the two rules applied. Read the declared type to decide whether it compiles; read the object to decide what it prints.</p><pre style="background:var(--surface-2); border:1px solid var(--border); border-radius:8px; padding:11px 13px; overflow-x:auto; font-size:13px; line-height:1.55; margin:10px 0;"><code>static class Employee {
    String name; double base;
    Employee(String n, double b) { name = n; base = b; }
    double pay()   { return base; }
    String role()  { return "Employee"; }
    String card()  { return role() + " " + name + " earns " + pay(); }
}
static class Manager extends Employee {
    double bonus;
    Manager(String n, double b, double bo) { super(n, b); bonus = bo; }
    @Override double pay()  { return super.pay() + bonus; }
    @Override String role() { return "Manager"; }
    void approveLeave() { System.out.println(name + " approves leave"); }
}
static class Contractor extends Employee {
    double hours, rate;
    Contractor(String n, double h, double r) { super(n, 0); hours = h; rate = r; }
    @Override double pay()  { return hours * rate; }
    @Override String role() { return "Contractor"; }
}

Employee e = new Manager("Ada", 90000, 10000);
System.out.println(e.pay());
System.out.println(e.role());
System.out.println(e.card());
// e.approveLeave();                 // COMPILE ERROR
((Manager) e).approveLeave();

Employee c = new Contractor("Bo", 120, 85);
System.out.println(c.card());

Employee[] staff = { new Employee("Cy", 50000), e, c };
double total = 0;
for (Employee x : staff) { total += x.pay(); }
System.out.println("total " + total);</code></pre><ol style="margin:8px 0 4px 18px; padding:0; line-height:1.65;"><li style="margin-bottom:5px;"><code>e.pay()</code> — the variable is an <code>Employee</code>, so the call is legal; the object is a <code>Manager</code>, so Manager's override runs: 90000 + 10000 = <strong>100000.0</strong>.</li><li style="margin-bottom:5px;"><code>e.role()</code> is <strong>Manager</strong> for the same reason.</li><li style="margin-bottom:5px;"><code>e.card()</code> is the interesting one. <code>card()</code> exists only in <code>Employee</code> and was written long before Manager. Yet the <code>role()</code> and <code>pay()</code> calls inside it dispatch to Manager's versions — a parent method calling child methods without knowing they exist.</li><li style="margin-bottom:5px;"><code>e.approveLeave()</code> does not compile, because <code>Employee</code> has no such method. The error is <code>cannot find symbol … location: variable e of type Employee</code> — the compiler names the <em>declared</em> type explicitly.</li><li style="margin-bottom:5px;"><code>((Manager) e).approveLeave()</code> works: the cast changes what the compiler is willing to let you call. It changes nothing about the object.</li><li style="margin-bottom:5px;">The Contractor prints <code>Contractor Bo earns 10200.0</code> — 120 × 85 — through exactly the same <code>card()</code> method.</li><li style="margin-bottom:5px;">The loop adds 50000 + 100000 + 10200 = <strong>160200.0</strong>. It never mentions <code>Manager</code> or <code>Contractor</code>: adding a fourth subclass tomorrow would not change a character of it.</li></ol><div style="margin:9px 0 4px;"><span style="font-size:11px; font-weight:700; letter-spacing:0.05em; color:var(--text-3);">OUTPUT</span></div><pre style="background:var(--surface-3, var(--surface-2)); border-left:3px solid var(--accent); border-radius:0 8px 8px 0; padding:9px 13px; overflow-x:auto; font-size:13px; line-height:1.5; margin:0 0 10px;"><code>100000.0
Manager
Manager Ada earns 100000.0
Ada approves leave
Contractor Bo earns 10200.0
total 160200.0</code></pre></div><div class="callout" data-lb="key" style="border-left-color:#0ea5e9;"><div class="callout-label">▸ WORKED EXAMPLE — CASTING SAFELY — instanceof, THE PATTERN VARIABLE, AND THE CRASH</div><p>A downcast is a claim about the object. If the claim is false the JVM stops you, at run time, with no compiler warning beforehand.</p><pre style="background:var(--surface-2); border:1px solid var(--border); border-radius:8px; padding:11px 13px; overflow-x:auto; font-size:13px; line-height:1.55; margin:10px 0;"><code>Employee e = new Manager("Ada", 90000, 10000);
Employee c = new Contractor("Bo", 120, 85);

Object o = e;
System.out.println(o instanceof Manager);
System.out.println(c instanceof Manager);
try {
    Manager bad = (Manager) c;
} catch (ClassCastException ex) {
    System.out.println("caught " + ex.getClass().getSimpleName());
}</code></pre><ol style="margin:8px 0 4px 18px; padding:0; line-height:1.65;"><li style="margin-bottom:5px;"><code>o instanceof Manager</code> is <strong>true</strong>. The variable is typed <code>Object</code>, but <code>instanceof</code> asks about the object, not the variable.</li><li style="margin-bottom:5px;"><code>c instanceof Manager</code> is <strong>false</strong>: a Contractor is an Employee, but it is not a Manager. Sibling subclasses are unrelated to each other.</li><li style="margin-bottom:5px;"><code>(Manager) c</code> compiles — the compiler allows any cast between related types, because it cannot know what the variable will hold at run time.</li><li style="margin-bottom:5px;">At run time the JVM checks the actual class, finds a Contractor, and throws <code>ClassCastException</code>. That is the whole reason to test first.</li></ol><div style="margin:9px 0 4px;"><span style="font-size:11px; font-weight:700; letter-spacing:0.05em; color:var(--text-3);">OUTPUT</span></div><pre style="background:var(--surface-3, var(--surface-2)); border-left:3px solid var(--accent); border-radius:0 8px 8px 0; padding:9px 13px; overflow-x:auto; font-size:13px; line-height:1.5; margin:0 0 10px;"><code>true
false
caught ClassCastException</code></pre><p>The three shapes worth knowing, in increasing order of preference:</p><pre style="background:var(--surface-2); border:1px solid var(--border); border-radius:8px; padding:11px 13px; overflow-x:auto; font-size:13px; line-height:1.55; margin:10px 0;"><code>// ① blind — throws when it is wrong
Manager m = (Manager) e;

// ② guarded — the classic idiom
if (e instanceof Manager) {
    Manager m = (Manager) e;
    m.approveLeave();
}

// ③ pattern variable — test and declare in one step
if (e instanceof Manager m) {
    m.approveLeave();
}</code></pre><p>Also useful: an <strong>upcast</strong> is the opposite direction — <code>Employee e = new Manager(...)</code> — and needs no cast and can never fail, because a Manager genuinely is an Employee. Only downcasts are claims that can be wrong.</p></div><div class="callout" data-lb="key" style="border-left-color:#f59e0b;"><div class="callout-label">⚠️ COMMON MISTAKE</div><p><strong>Expecting fields to be polymorphic.</strong> They are not. If both classes declare a field with the same name, the one you get depends on the <em>declared type of the variable</em>, not the object — so <code>e.name</code> and <code>((Manager) e).name</code> can print different values for the very same object. Methods dispatch; fields do not.</p><p>The second half: <strong>expecting the cast to change the object</strong>. <code>((Manager) e).approveLeave()</code> does not turn <code>e</code> into a Manager and does not create one — it was always a Manager, and the cast merely persuades the compiler to let you say so. Casting a Contractor to Manager does not convert anything; it throws.</p><p>How to notice both: if an exam option claims a cast "converts" an object, or that a subclass field "overrides" the parent's, it is wrong. Only methods are overridden, and only objects decide which one runs.</p></div>"},"D286/u10/z10_6":{"body":"<p>Polymorphism plus a collection is where it becomes genuinely useful: one list holds mixed subclasses, and one loop calls the right version for each.</p><pre style="background:var(--bg-2, var(--surface-2)); padding:12px; border-radius:8px; font-size:13px; overflow-x:auto; line-height:1.55;">ArrayList<employee> staff = new ArrayList&lt;&gt;();
staff.add(new Employee("Bob", 50000));
staff.add(new Manager("Ada", 90000, 10000));

for (Employee e : staff) {
    System.out.println(e.describe());     // each runs ITS OWN version
}

// reaching subclass-only behaviour requires a check plus a cast
double total = 0;
for (Employee e : staff) {
    total += (e instanceof Manager) ? ((Manager) e).totalPay() : e.getSalary();
}</employee></pre><p>The loop never mentions <code>Manager</code> in the first case, and adding a third subclass tomorrow requires no change to it at all. That is the argument for polymorphism over a chain of <code>instanceof</code> checks — the second loop is the version you should be slightly unhappy about.</p><pre style="background:var(--bg-2, var(--surface-2)); padding:12px; border-radius:8px; font-size:13px; overflow-x:auto; line-height:1.55;">ArrayList&lt;Employee&gt; staff = new ArrayList&lt;&gt;();
staff.add(new Manager("Ana", 30));

for (Employee e : staff) {
    System.out.println(e.pay());          // polymorphic — no cast needed
    if (e instanceof Manager) {           // guard BEFORE casting
        Manager m = (Manager) e;
        m.approveLeave();                 // subclass-only method
    }
}</pre><p>A list declared with the base type holds any subclass, and calling an overridden method needs no cast — that is the whole benefit. A cast is needed only to reach something the subclass adds.</p><p>Casting without checking throws <code>ClassCastException</code> at run time, so <code>instanceof</code> comes first. Modern Java combines them: <code>if (e instanceof Manager m) { m.approveLeave(); }</code> tests and declares in one step.</p><p>Frequent <code>instanceof</code> chains usually mean the behaviour belongs in an overridden method instead — let each subclass answer for itself rather than asking the list what type everything is.</p><i data-d286u811="1" style="display:none"></i><div class="callout" data-lb="why" style="border-left-color:#4f46e5;"><div class="callout-label">📘 DEFINITION</div><p style="margin:0 0 7px;"><strong>Heterogeneous collection:</strong> a collection holding several subclasses through their common parent type</p><p style="margin:0 0 7px;"><strong>instanceof:</strong> tests whether an object is of a given type, including subtypes</p><p style="margin:0 0 7px;"><strong>ClassCastException:</strong> thrown at run time by a cast the actual object does not satisfy</p></div><div class="callout" data-lb="key" style="border-left-color:#22c55e;"><div class="callout-label">💡 WHY IT MATTERS</div><p>If you find yourself writing a long chain of <code>instanceof</code> tests, the behaviour probably belongs in an overridden method instead. That is the design lesson 10.7 formalises.</p></div><i data-tbc106="1" style="display:none"></i><div class="vl" data-mathvis="1" data-c959fig="1" style="margin-top:18px;"><div style="font-weight:700; font-size:12.5px; letter-spacing:0.05em; margin-bottom:6px;">📊 FIGURE — ONE LIST, ONE LOOP, THREE DIFFERENT METHOD BODIES</div><div style="border:1px solid var(--border); border-radius:12px; background:var(--surface-2); padding:14px 10px; overflow-x:auto;"><svg viewBox="0 0 820 380" style="width:100%; max-width:760px; display:block; margin:0 auto; font-family:inherit;" xmlns="http://www.w3.org/2000/svg"><defs><marker id="fk261a" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0,1 L9,5 L0,9 z" fill="var(--text)"/></marker></defs><rect x="34" y="96" width="120" height="60" rx="7" fill="var(--accent-bg)" stroke="var(--accent)" stroke-width="2.2"/><text x="94" y="123" fill="var(--text)" font-size="12" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">staff</text><text x="94" y="139" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle">ArrayList&lt;Employee&gt;</text><rect x="176" y="62" width="40" height="34" rx="4" fill="none" stroke="var(--text)" stroke-width="1.3"/><text x="196" y="84" fill="var(--text-3)" font-size="11" font-weight="400" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">0</text><rect x="176" y="108" width="40" height="34" rx="4" fill="none" stroke="var(--text)" stroke-width="1.3"/><text x="196" y="130" fill="var(--text-3)" font-size="11" font-weight="400" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">1</text><rect x="176" y="154" width="40" height="34" rx="4" fill="none" stroke="var(--text)" stroke-width="1.3"/><text x="196" y="176" fill="var(--text-3)" font-size="11" font-weight="400" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">2</text><line x1="154" y1="126" x2="176" y2="126" stroke="var(--text-3)" stroke-width="1.6"/><rect x="252" y="60" width="150" height="38" rx="7" fill="var(--surface)" stroke="var(--text)" stroke-width="1.5"/><text x="327" y="83.5" fill="var(--text)" font-size="11" font-weight="700" text-anchor="middle">Salaried "Ana"</text><rect x="252" y="106" width="150" height="38" rx="7" fill="var(--surface)" stroke="var(--text)" stroke-width="1.5"/><text x="327" y="129.5" fill="var(--text)" font-size="11" font-weight="700" text-anchor="middle">Hourly "Ben"</text><rect x="252" y="152" width="150" height="38" rx="7" fill="var(--surface)" stroke="var(--text)" stroke-width="1.5"/><text x="327" y="175.5" fill="var(--text)" font-size="11" font-weight="700" text-anchor="middle">Manager "Cy"</text><line x1="216" y1="79" x2="250" y2="79" stroke="var(--text)" stroke-width="1.6" marker-end="url(#fk261a)"/><line x1="216" y1="125" x2="250" y2="125" stroke="var(--text)" stroke-width="1.6" marker-end="url(#fk261a)"/><line x1="216" y1="171" x2="250" y2="171" stroke="var(--text)" stroke-width="1.6" marker-end="url(#fk261a)"/><rect x="430" y="96" width="150" height="60" rx="8" fill="var(--accent-bg)" stroke="var(--accent)" stroke-width="2"/><text x="505" y="120" fill="var(--accent)" font-size="9.5" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">for (Employee e : staff)</text><text x="505" y="138" fill="var(--accent)" font-size="9.5" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">total += e.pay();</text><line x1="402" y1="79" x2="470" y2="96" stroke="var(--text)" stroke-width="1.6" marker-end="url(#fk261a)"/><line x1="402" y1="125" x2="428" y2="125" stroke="var(--text)" stroke-width="1.6" marker-end="url(#fk261a)"/><line x1="402" y1="171" x2="470" y2="156" stroke="var(--text)" stroke-width="1.6" marker-end="url(#fk261a)"/><line x1="580" y1="108" x2="626" y2="84" stroke="var(--text)" stroke-width="1.6" marker-end="url(#fk261a)"/><line x1="580" y1="126" x2="626" y2="126" stroke="var(--text)" stroke-width="1.6" marker-end="url(#fk261a)"/><line x1="580" y1="144" x2="626" y2="168" stroke="var(--text)" stroke-width="1.6" marker-end="url(#fk261a)"/><rect x="630" y="66" width="168" height="36" rx="7" fill="var(--surface)" stroke="var(--text)" stroke-width="1.5"/><text x="714" y="81" fill="var(--text)" font-size="11" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">annual / 26</text><text x="714" y="97" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle">3000.00</text><rect x="630" y="108" width="168" height="36" rx="7" fill="var(--surface)" stroke="var(--text)" stroke-width="1.5"/><text x="714" y="123" fill="var(--text)" font-size="11" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">hours * rate</text><text x="714" y="139" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle">1620.00</text><rect x="630" y="150" width="168" height="36" rx="7" fill="var(--surface)" stroke="var(--text)" stroke-width="1.5"/><text x="714" y="165" fill="var(--text)" font-size="10" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">super.pay() + bonus</text><text x="714" y="181" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle">5500.00</text><text x="714" y="210" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-style="italic">three bodies, one call site</text><line x1="30" y1="236" x2="790" y2="236" stroke="var(--border)" stroke-width="1"/><text x="410" y="262" fill="var(--accent)" font-size="11.5" font-weight="700" text-anchor="middle">REACHING SUBCLASS-ONLY BEHAVIOUR NEEDS A CHECK FIRST</text><rect x="90" y="280" width="250" height="40" rx="7" fill="var(--accent-bg)" stroke="var(--accent)" stroke-width="1.5"/><text x="215" y="297" fill="var(--text)" font-size="12" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">e.pay()</text><text x="215" y="313" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle">on Employee — no cast needed</text><rect x="430" y="280" width="300" height="40" rx="7" fill="var(--surface)" stroke="var(--text)" stroke-width="1.5"/><text x="580" y="297" fill="var(--text)" font-size="12" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">e.approveLeave()</text><text x="580" y="313" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle">Manager only — instanceof, then cast</text><text x="410" y="348" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-style="italic">if you find yourself writing a long chain of instanceof tests, the behaviour belongs in an overridden method</text></svg></div></div><div class="callout" data-lb="key" style="border-left-color:#0ea5e9;"><div class="callout-label">▸ WORKED EXAMPLE — A MIXED PAYROLL IN ONE LIST</div><p>Four classes, three of them subclasses, one loop that mentions none of them.</p><pre style="background:var(--surface-2); border:1px solid var(--border); border-radius:8px; padding:11px 13px; overflow-x:auto; font-size:13px; line-height:1.55; margin:10px 0;"><code>static abstract class Employee {
    String name;
    Employee(String n) { name = n; }
    abstract double pay();
    @Override public String toString() {
        return String.format("%-10s %8.2f", name, pay());
    }
}
static class Salaried extends Employee {
    double annual;
    Salaried(String n, double a) { super(n); annual = a; }
    @Override double pay() { return annual / 26; }
}
static class Hourly extends Employee {
    double hours, rate;
    Hourly(String n, double h, double r) { super(n); hours = h; rate = r; }
    @Override double pay() { return hours * rate; }
}
static class Manager extends Salaried {
    double bonus;
    Manager(String n, double a, double b) { super(n, a); bonus = b; }
    @Override double pay() { return super.pay() + bonus; }
    void approveLeave() { System.out.println("  " + name + " approved leave"); }
}

ArrayList&lt;Employee&gt; staff = new ArrayList&lt;&gt;();
staff.add(new Salaried("Ana", 78000));
staff.add(new Hourly("Ben", 72, 22.50));
staff.add(new Manager("Cy", 104000, 1500));

double total = 0;
for (Employee e : staff) {
    System.out.println(e);
    total += e.pay();
}
System.out.printf("%-10s %8.2f%n", "TOTAL", total);

for (Employee e : staff) {
    if (e instanceof Manager m) { m.approveLeave(); }
}
System.out.println(staff.get(1).getClass().getSimpleName());
System.out.println(staff.get(2) instanceof Salaried);</code></pre><ol style="margin:8px 0 4px 18px; padding:0; line-height:1.65;"><li style="margin-bottom:5px;">The list is declared <code>ArrayList&lt;Employee&gt;</code>, so it accepts any subclass. That single declaration is what makes the mixture legal.</li><li style="margin-bottom:5px;"><code>System.out.println(e)</code> calls the inherited <code>toString()</code>, which calls <code>pay()</code> — and <code>pay()</code> dispatches to whichever subclass the element actually is. Ana: 78000 / 26 = <strong>3000.00</strong>. Ben: 72 × 22.50 = <strong>1620.00</strong>. Cy: 104000 / 26 = 4000, + 1500 = <strong>5500.00</strong>.</li><li style="margin-bottom:5px;"><code>Manager</code> extends <code>Salaried</code>, not <code>Employee</code> directly, so <code>super.pay()</code> reaches <em>Salaried's</em> version. Dispatch walks up from the actual class, however deep the chain is.</li><li style="margin-bottom:5px;">The total, 10120.00, was accumulated by a loop containing the single expression <code>e.pay()</code>.</li><li style="margin-bottom:5px;"><code>approveLeave()</code> exists only on Manager, so the second loop guards with <code>instanceof Manager m</code> — the pattern form, which tests and declares <code>m</code> in one step. Only Cy matches.</li><li style="margin-bottom:5px;"><code>getClass().getSimpleName()</code> reports <strong>Hourly</strong> for element 1 — the real class, regardless of the declared element type.</li><li style="margin-bottom:5px;"><code>staff.get(2) instanceof Salaried</code> is <strong>true</strong>: <code>instanceof</code> accepts any ancestor type, not just the exact class.</li></ol><div style="margin:9px 0 4px;"><span style="font-size:11px; font-weight:700; letter-spacing:0.05em; color:var(--text-3);">OUTPUT</span></div><pre style="background:var(--surface-3, var(--surface-2)); border-left:3px solid var(--accent); border-radius:0 8px 8px 0; padding:9px 13px; overflow-x:auto; font-size:13px; line-height:1.5; margin:0 0 10px;"><code>Ana         3000.00
Ben         1620.00
Cy          5500.00
TOTAL      10120.00
  Cy approved leave
Hourly
true</code></pre></div><div class="callout" data-lb="key" style="border-left-color:#0ea5e9;"><div class="callout-label">▸ WORKED EXAMPLE — WHY THE POLYMORPHIC LOOP BEATS THE instanceof CHAIN</div><p>Both versions produce the same total today. Only one of them survives a new requirement.</p><pre style="background:var(--surface-2); border:1px solid var(--border); border-radius:8px; padding:11px 13px; overflow-x:auto; font-size:13px; line-height:1.55; margin:10px 0;"><code>// ① the instanceof chain — every type named, in one place
double total = 0;
for (Employee e : staff) {
    if (e instanceof Manager m)        total += m.annual / 26 + m.bonus;
    else if (e instanceof Hourly h)    total += h.hours * h.rate;
    else if (e instanceof Salaried s)  total += s.annual / 26;
}

// ② the polymorphic loop — no type named at all
double total = 0;
for (Employee e : staff) total += e.pay();</code></pre><ol style="margin:8px 0 4px 18px; padding:0; line-height:1.65;"><li style="margin-bottom:5px;"><strong>Ordering.</strong> Version ① only works because <code>Manager</code> is tested before <code>Salaried</code>. <code>Manager</code> extends <code>Salaried</code>, so a Manager matches <em>both</em> tests — put <code>Salaried</code> first and every manager silently loses their bonus. Version ② has no ordering to get wrong.</li><li style="margin-bottom:5px;"><strong>Fields.</strong> Version ① reads <code>m.annual</code> and <code>h.rate</code> from outside, so those fields cannot be private and the payroll formula now lives in two places. Version ② asks the object and lets it answer.</li><li style="margin-bottom:5px;"><strong>Adding a class.</strong> A new <code>Intern</code> subclass needs a new branch in ① — and if you forget one, the total is quietly wrong rather than a compile error. In ② the new class supplies <code>pay()</code> and every existing loop is already correct.</li><li style="margin-bottom:5px;"><strong>Counting the branches.</strong> Version ① has one branch per subclass per loop. With four loops and five subclasses that is twenty places to keep in step; version ② has five method bodies and nothing to keep in step.</li></ol><p>The abstract <code>pay()</code> makes this enforceable rather than merely advisable: a subclass that fails to supply one <strong>does not compile</strong> — <code>error: Intern is not abstract and does not override abstract method pay()</code>. The compiler becomes the checklist that version ① needs a human for.</p><p>The legitimate use of <code>instanceof</code> is the one in the first worked example: reaching behaviour that genuinely exists on only one subclass, like <code>approveLeave()</code>. Reaching for it to compute something every subclass has is the smell.</p></div><div class="callout" data-lb="key" style="border-left-color:#f59e0b;"><div class="callout-label">⚠️ COMMON MISTAKE</div><p><strong>Testing subclasses in the wrong order.</strong> <code>instanceof</code> matches ancestors too, so in a hierarchy where <code>Manager extends Salaried</code>, the test <code>e instanceof Salaried</code> is <strong>true</strong> for a Manager. Put the general test first and the specific branch becomes unreachable — silently, at run time, with no compiler complaint at all (unlike catch blocks, where the compiler does object).</p><p>How to notice it: draw the hierarchy and check that each <code>instanceof</code> chain runs <em>most specific first</em>, exactly like catch blocks in Unit 12. If one type extends another in your chain, the deeper one must be tested earlier.</p><p>The second, quieter version: <code>e.getClass() == Manager.class</code> is <em>not</em> the same test as <code>e instanceof Manager</code>. The first is exact-class and excludes any future subclass of Manager; the second includes them. Mixing them up produces code that works until someone extends your class.</p></div><div class="callout" data-lb="key" style="border-left-color:#e11d48;"><div class="callout-label">🎯 EXAM TIP</div><p><strong>For "what does this loop print?" questions</strong>, resolve each element separately: what is the actual class, and does that class override the method being called? Work up the chain from the actual class until you find a body. The declared type of the list only decides <em>which methods you are allowed to call</em>.</p><p>Facts that get tested directly:</p><p>① <code>ArrayList&lt;Employee&gt;</code> can hold any subclass. It cannot hold an unrelated class, and it cannot hold a primitive — <code>ArrayList&lt;int&gt;</code> is a compile error.<br>② No cast is needed to call an <strong>overridden</strong> method; a cast is needed to call a method the subclass <strong>adds</strong>.<br>③ <code>instanceof</code> is true for the class and every ancestor, and false for <code>null</code> — which is why <code>if (x instanceof Manager)</code> never needs a null check in front of it.</p><p>Watch for the sneaky <code>ArrayList&lt;Object&gt;</code> variant: it holds anything, but you can then call only <code>Object</code>'s methods without casting, which is precisely the pre-generics problem Unit 13 exists to solve.</p></div>"},"D286/u10/z10_7":{"body":"<p>Sometimes the parent class has no sensible implementation of a method. What area does a generic <code>Shape</code> have? An <strong>abstract</strong> class answers this: it declares the method, refuses to implement it, and forbids anyone from creating a plain <code>Shape</code>.</p><pre style="background:var(--bg-2, var(--surface-2)); padding:12px; border-radius:8px; font-size:13px; overflow-x:auto; line-height:1.55;">public abstract class Shape {
    protected String name;
    public Shape(String n) { name = n; }        // abstract classes CAN have constructors

    public abstract double area();               // no body — subclasses must supply one

    public String describe() {                   // concrete method — inherited as is
        return name + " with area " + area();
    }
}

Shape s = new Shape("x");     // COMPILE ERROR — cannot instantiate an abstract class</pre><p>Note that <code>describe()</code> calls <code>area()</code>, a method that does not exist yet. That works because of dynamic dispatch (10.5): by the time it runs, the object is a real subclass with a real <code>area</code>.</p><pre style="background:var(--bg-2, var(--surface-2)); padding:12px; border-radius:8px; font-size:13px; overflow-x:auto; line-height:1.55;">public abstract class Shape {
    private String name;
    public Shape(String n) { name = n; }       // abstract classes DO have constructors
    public String getName() { return name; }   // concrete: inherited as-is
    public abstract double area();             // no body — subclasses must supply one
}

Shape s = new Shape("x");                      // COMPILE ERROR
Shape s = new Circle(2);                       // fine — Circle is concrete</pre><p>An abstract class cannot be instantiated because it is deliberately incomplete: there is no sensible <code>area()</code> for "a shape in general". It can still have fields, constructors and fully written methods, and its constructor runs via <code>super(...)</code> when a subclass is built.</p><p>Any class containing an abstract method must itself be declared abstract. A subclass must implement every inherited abstract method or be declared abstract in turn, which is how the requirement passes down until some class finally satisfies it.</p><i data-d286u811="1" style="display:none"></i><div class="callout" data-lb="why" style="border-left-color:#4f46e5;"><div class="callout-label">📘 DEFINITION</div><p style="margin:0 0 7px;"><strong>abstract class:</strong> a class that cannot be instantiated, meant to be extended</p><p style="margin:0 0 7px;"><strong>abstract method:</strong> a method with a signature and no body; subclasses must implement it</p><p style="margin:0 0 7px;"><strong>Concrete subclass:</strong> a subclass implementing every abstract method, so it can be instantiated</p></div><div class="callout" data-lb="warn" style="border-left-color:#f59e0b;"><div class="callout-label">⚠ COMMON MISTAKE</div><p>A subclass that does not implement every abstract method must itself be declared <code>abstract</code>, or it will not compile. There is no way to leave one unimplemented in a concrete class.</p></div><p data-xref="1" style="margin:26px 0 0; padding-top:12px; border-top:1px solid var(--border);font-size:12.5px; opacity:0.72;">✅ Also covered in depth: <strong>Inheritance → Abstract Classes and Interfaces</strong></p><i data-tbc107="1" style="display:none"></i><div class="vl" data-mathvis="1" data-c959fig="1" style="margin-top:18px;"><div style="font-weight:700; font-size:12.5px; letter-spacing:0.05em; margin-bottom:6px;">📊 FIGURE — AN ABSTRACT CLASS IS A CLASS WITH A HOLE IN IT</div><div style="border:1px solid var(--border); border-radius:12px; background:var(--surface-2); padding:14px 10px; overflow-x:auto;"><svg viewBox="0 0 820 380" style="width:100%; max-width:760px; display:block; margin:0 auto; font-family:inherit;" xmlns="http://www.w3.org/2000/svg"><defs><marker id="fk262a" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0,1 L9,5 L0,9 z" fill="var(--text)"/></marker></defs><rect x="300" y="40" width="220" height="104" rx="5" fill="var(--accent-bg)" stroke="var(--accent)" stroke-width="2.2"/><line x1="300" y1="68" x2="520" y2="68" stroke="var(--text)" stroke-width="1.2"/><line x1="300" y1="91" x2="520" y2="91" stroke="var(--text)" stroke-width="1.2"/><text x="410" y="59" fill="var(--text)" font-size="12.5" font-weight="700" text-anchor="middle" font-style="italic">Shape</text><text x="308" y="84" fill="var(--text-3)" font-size="10" font-weight="400" text-anchor="start" font-family="ui-monospace,Menlo,monospace">- name : String</text><text x="308" y="107" fill="var(--text)" font-size="10" font-weight="400" text-anchor="start" font-family="ui-monospace,Menlo,monospace">+ getName()</text><text x="308" y="122" fill="var(--text)" font-size="10" font-weight="400" text-anchor="start" font-family="ui-monospace,Menlo,monospace">+ describe()</text><text x="308" y="137" fill="var(--accent)" font-size="10" font-weight="400" text-anchor="start" font-family="ui-monospace,Menlo,monospace" font-style="italic">+ area()  {abstract}</text><text x="534" y="60" fill="var(--text-3)" font-size="9.5" font-weight="400" text-anchor="start" font-style="italic">(an italic name means abstract)</text><text x="534" y="78" fill="var(--accent)" font-size="9.5" font-weight="400" text-anchor="start" font-style="italic">area() has no body here</text><text x="44" y="90" fill="var(--text-3)" font-size="24" font-weight="700" text-anchor="middle">✗</text><rect x="66" y="62" width="200" height="34" rx="7" fill="var(--surface)" stroke="var(--text-3)" stroke-width="1.5" stroke-dasharray="5 4"/><text x="166" y="83.5" fill="var(--text-3)" font-size="12" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">new Shape("x")</text><text x="166" y="118" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-style="italic">error: Shape is abstract;</text><text x="166" y="133" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-style="italic">cannot be instantiated</text><line x1="410" y1="158" x2="410" y2="190" stroke="var(--text)" stroke-width="1.5"/><line x1="190" y1="190" x2="630" y2="190" stroke="var(--text)" stroke-width="1.5"/><line x1="410" y1="158" x2="410" y2="158" stroke="var(--text)" stroke-width="1.5"/><path d="M402,158 L410,146 L418,158 Z" fill="var(--surface)" stroke="var(--text)" stroke-width="1.5"/><line x1="190" y1="190" x2="190" y2="208" stroke="var(--text)" stroke-width="1.5"/><line x1="410" y1="190" x2="410" y2="208" stroke="var(--text)" stroke-width="1.5"/><line x1="630" y1="190" x2="630" y2="208" stroke="var(--text)" stroke-width="1.5"/><rect x="110" y="208" width="160" height="74" rx="5" fill="var(--surface)" stroke="var(--text)" stroke-width="1.5"/><line x1="110" y1="236" x2="270" y2="236" stroke="var(--text)" stroke-width="1.2"/><line x1="110" y1="259" x2="270" y2="259" stroke="var(--text)" stroke-width="1.2"/><text x="190" y="227" fill="var(--text)" font-size="12.5" font-weight="700" text-anchor="middle">Circle</text><text x="118" y="252" fill="var(--text-3)" font-size="10" font-weight="400" text-anchor="start" font-family="ui-monospace,Menlo,monospace">- r : double</text><text x="118" y="275" fill="var(--text)" font-size="10" font-weight="400" text-anchor="start" font-family="ui-monospace,Menlo,monospace">+ area()</text><rect x="330" y="208" width="160" height="74" rx="5" fill="var(--surface)" stroke="var(--text)" stroke-width="1.5"/><line x1="330" y1="236" x2="490" y2="236" stroke="var(--text)" stroke-width="1.2"/><line x1="330" y1="259" x2="490" y2="259" stroke="var(--text)" stroke-width="1.2"/><text x="410" y="227" fill="var(--text)" font-size="12.5" font-weight="700" text-anchor="middle">Rect</text><text x="338" y="252" fill="var(--text-3)" font-size="10" font-weight="400" text-anchor="start" font-family="ui-monospace,Menlo,monospace">- w, h : double</text><text x="338" y="275" fill="var(--text)" font-size="10" font-weight="400" text-anchor="start" font-family="ui-monospace,Menlo,monospace">+ area()</text><rect x="550" y="208" width="160" height="74" rx="5" fill="var(--surface)" stroke="var(--text)" stroke-width="1.5"/><line x1="550" y1="236" x2="710" y2="236" stroke="var(--text)" stroke-width="1.2"/><line x1="550" y1="259" x2="710" y2="259" stroke="var(--text)" stroke-width="1.2"/><text x="630" y="227" fill="var(--text)" font-size="12.5" font-weight="700" text-anchor="middle">Square</text><text x="558" y="252" fill="var(--text-3)" font-size="10" font-weight="400" text-anchor="start" font-family="ui-monospace,Menlo,monospace">- s : double</text><text x="558" y="275" fill="var(--text)" font-size="10" font-weight="400" text-anchor="start" font-family="ui-monospace,Menlo,monospace">+ area()</text><text x="410" y="320" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-style="italic">each subclass plugs the hole with its own area() — that is the only thing it is required to do</text><rect x="300" y="336" width="220" height="30" rx="7" fill="var(--accent-bg)" stroke="var(--accent)" stroke-width="1.5"/><text x="410" y="355.5" fill="var(--text)" font-size="10.5" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">Shape s = new Circle(2);</text><text x="120" y="352" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-style="italic">the TYPE may be abstract;</text><text x="120" y="367" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-style="italic">the OBJECT may not</text><text x="680" y="352" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-style="italic">describe() can call area()</text><text x="680" y="367" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-style="italic">because by then it exists</text></svg></div></div><div class="callout" data-lb="key" style="border-left-color:#0ea5e9;"><div class="callout-label">▸ WORKED EXAMPLE — A CONCRETE METHOD CALLING A METHOD THAT DOES NOT EXIST YET</div><p><code>Shape.describe()</code> calls <code>area()</code>, which has no body anywhere in <code>Shape</code>. It works, and the reason is dynamic dispatch.</p><pre style="background:var(--surface-2); border:1px solid var(--border); border-radius:8px; padding:11px 13px; overflow-x:auto; font-size:13px; line-height:1.55; margin:10px 0;"><code>static abstract class Shape {
    private String name;
    Shape(String n) { name = n; System.out.println("  Shape ctor for " + n); }
    String getName() { return name; }
    abstract double area();                               // no body
    String describe() { return String.format("%s area %.2f", name, area()); }
}
static class Circle extends Shape {
    private double r;
    Circle(double r) { super("Circle"); this.r = r; }
    @Override double area() { return Math.PI * r * r; }
}
static class Rect extends Shape {
    private double w, h;
    Rect(double w, double h) { super("Rect"); this.w = w; this.h = h; }
    @Override double area() { return w * h; }
}
static abstract class Quad extends Shape { Quad(String n) { super(n); } }   // still abstract
static class Square extends Quad {
    private double s;
    Square(double s) { super("Square"); this.s = s; }
    @Override double area() { return s * s; }
}

ArrayList&lt;Shape&gt; shapes = new ArrayList&lt;&gt;();
shapes.add(new Circle(2));
shapes.add(new Rect(3, 4));
shapes.add(new Square(5));
System.out.println("--");
for (Shape s : shapes) System.out.println(s.describe());
double total = 0;
for (Shape s : shapes) total += s.area();
System.out.printf("total %.2f%n", total);
System.out.println(shapes.get(2) instanceof Quad);
System.out.println(shapes.get(0).getClass().getSimpleName());</code></pre><ol style="margin:8px 0 4px 18px; padding:0; line-height:1.65;"><li style="margin-bottom:5px;"><strong>Abstract classes have constructors</strong>, and they run. All three "Shape ctor" lines appear before the <code>--</code>, once per object created — a constructor is not the same thing as an instantiation.</li><li style="margin-bottom:5px;"><code>describe()</code> is a fully written, inherited method. Its call to <code>area()</code> is a normal virtual call: by the time it executes, the object is a real Circle, Rect or Square, and the JVM finds a real body.</li><li style="margin-bottom:5px;">π × 2² = <strong>12.57</strong>, 3 × 4 = <strong>12.00</strong>, 5² = <strong>25.00</strong>. One method, three answers, and <code>Shape</code> knows about none of the formulas.</li><li style="margin-bottom:5px;"><code>Quad</code> extends <code>Shape</code> without implementing <code>area()</code>, so it must itself be declared <code>abstract</code> — the requirement is passed down rather than dropped.</li><li style="margin-bottom:5px;"><code>Square</code> extends <code>Quad</code> and finally supplies <code>area()</code>, which is what makes it concrete and instantiable.</li><li style="margin-bottom:5px;"><code>instanceof Quad</code> is true for the Square, and <code>getClass().getSimpleName()</code> reports <code>Circle</code> — the abstract types are perfectly real types, they simply have no instances of their own.</li></ol><div style="margin:9px 0 4px;"><span style="font-size:11px; font-weight:700; letter-spacing:0.05em; color:var(--text-3);">OUTPUT</span></div><pre style="background:var(--surface-3, var(--surface-2)); border-left:3px solid var(--accent); border-radius:0 8px 8px 0; padding:9px 13px; overflow-x:auto; font-size:13px; line-height:1.5; margin:0 0 10px;"><code>  Shape ctor for Circle
  Shape ctor for Rect
  Shape ctor for Square
--
Circle area 12.57
Rect area 12.00
Square area 25.00
total 49.57
true
Circle</code></pre><p>This is the <strong>template method</strong> shape: the parent writes the algorithm (<code>describe</code>) and leaves the varying step (<code>area</code>) abstract. Every subclass gets the formatting for free and supplies only what is genuinely different.</p></div><div class="callout" data-lb="key" style="border-left-color:#0ea5e9;"><div class="callout-label">▸ WORKED EXAMPLE — THE TWO COMPILE ERRORS ABSTRACTION IS BUILT FROM</div><p>An abstract class enforces its contract through the compiler. These are the exact messages, and each one is a rule stated as an error.</p><pre style="background:var(--surface-2); border:1px solid var(--border); border-radius:8px; padding:11px 13px; overflow-x:auto; font-size:13px; line-height:1.55; margin:10px 0;"><code>abstract class Shape { abstract double area(); }
class Use { void f() { Shape s = new Shape(); } }</code></pre><div style="margin:9px 0 4px;"><span style="font-size:11px; font-weight:700; letter-spacing:0.05em; color:var(--text-3);">OUTPUT</span></div><pre style="background:var(--surface-3, var(--surface-2)); border-left:3px solid var(--accent); border-radius:0 8px 8px 0; padding:9px 13px; overflow-x:auto; font-size:13px; line-height:1.5; margin:0 0 10px;"><code>error: Shape is abstract; cannot be instantiated
class Use { void f() { Shape s = new Shape(); } }
                                 ^</code></pre><ol style="margin:8px 0 4px 18px; padding:0; line-height:1.65;"><li style="margin-bottom:5px;">The caret points at <code>new</code>, not at the variable. <code>Shape s</code> is perfectly legal — declaring a variable of an abstract type is the entire reason abstract types exist. Only the <code>new</code> is refused.</li><li style="margin-bottom:5px;">The fix is never "remove <code>abstract</code>". It is to instantiate a concrete subclass and keep the variable typed as <code>Shape</code>: <code>Shape s = new Circle(2);</code></li></ol><pre style="background:var(--surface-2); border:1px solid var(--border); border-radius:8px; padding:11px 13px; overflow-x:auto; font-size:13px; line-height:1.55; margin:10px 0;"><code>abstract class Shape { abstract double area(); }
class Circle extends Shape { }        // forgot area()</code></pre><div style="margin:9px 0 4px;"><span style="font-size:11px; font-weight:700; letter-spacing:0.05em; color:var(--text-3);">OUTPUT</span></div><pre style="background:var(--surface-3, var(--surface-2)); border-left:3px solid var(--accent); border-radius:0 8px 8px 0; padding:9px 13px; overflow-x:auto; font-size:13px; line-height:1.5; margin:0 0 10px;"><code>error: Circle is not abstract and does not override abstract method area() in Shape
class Circle extends Shape { }
^</code></pre><ol style="margin:8px 0 4px 18px; padding:0; line-height:1.65;"><li style="margin-bottom:5px;">A concrete subclass must implement <strong>every</strong> inherited abstract method. There is no way to leave one out.</li><li style="margin-bottom:5px;">Two fixes exist, and the choice is a design decision: implement <code>area()</code>, or declare <code>Circle</code> itself <code>abstract</code> and push the obligation to <em>its</em> subclasses — which is exactly what <code>Quad</code> did in the previous example.</li><li style="margin-bottom:5px;">This is what makes the abstract method a genuine guarantee. Every object of type <code>Shape</code> that can exist has an <code>area()</code>, checked at compile time, in every subclass, for ever.</li></ol><p>Three further rules follow from the same idea, each worth checking against the code above:</p><div style="overflow-x:auto; margin:14px 0;"><table style="border-collapse:collapse; width:100%; font-size:14.5px;"><thead><tr><th style="text-align:left; padding:7px 12px 7px 0; border-bottom:2px solid var(--border); font-size:12.5px; letter-spacing:0.04em;">Rule</th><th style="text-align:left; padding:7px 12px 7px 0; border-bottom:2px solid var(--border); font-size:12.5px; letter-spacing:0.04em;">Why</th></tr></thead><tbody><tr><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border); font-weight:600;">a class with any abstract method <strong>must</strong> be declared abstract</td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);">otherwise it could be instantiated with a hole in it</td></tr><tr><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border); font-weight:600;">an abstract class <strong>may</strong> have zero abstract methods</td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);">the keyword alone prevents instantiation — useful for a base that is never meaningful alone</td></tr><tr><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border); font-weight:600;">an abstract class <strong>may</strong> have fields, constructors and full method bodies</td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);">it is a normal class in every respect except that <code>new</code> is refused</td></tr></tbody></table></div></div><div class="callout" data-lb="key" style="border-left-color:#e11d48;"><div class="callout-label">🎯 EXAM TIP</div><p><strong>The two-line test for any abstract-class question.</strong> Ask: (1) does this class still contain an unimplemented abstract method? If yes it must be declared <code>abstract</code>. (2) Is there a <code>new</code> on an abstract type? If yes, that line is the error.</p><p>Statements that are <strong>true</strong> and get offered as if they were false:</p><p>• an abstract class can have a constructor — and it runs, via <code>super(...)</code><br>• an abstract class can have concrete methods, fields and static members<br>• an abstract class can have <em>no</em> abstract methods at all<br>• <code>Shape[] arr = new Shape[3];</code> is legal — it creates references, not Shapes</p><p>Statements that are <strong>false</strong> and get offered as if they were true:</p><p>• "abstract methods can be private" — no: a private method cannot be overridden, so the combination is a compile error. The same goes for <code>abstract static</code> and <code>abstract final</code>.<br>• "an abstract class cannot be used as a variable type" — it is used that way constantly.</p></div>"},"D286/u10/z10_8":{"body":"<p>Working with abstract classes settles into one shape: the parent holds what is common, declares what varies, and every subclass fills in the gaps.</p><pre style="background:var(--bg-2, var(--surface-2)); padding:12px; border-radius:8px; font-size:13px; overflow-x:auto; line-height:1.55;">public class Circle extends Shape {
    private double radius;
    public Circle(double r) { super("Circle"); radius = r; }

    @Override
    public double area() { return Math.PI * radius * radius; }
}

public class Rectangle extends Shape {
    private double w, h;
    public Rectangle(double w, double h) { super("Rectangle"); this.w = w; this.h = h; }

    @Override
    public double area() { return w * h; }
}

ArrayList<shape> shapes = new ArrayList&lt;&gt;();
shapes.add(new Circle(2));
shapes.add(new Rectangle(3, 4));
for (Shape s : shapes) { System.out.println(s.describe()); }</shape></pre><p>The list is declared as <code>Shape</code> even though no <code>Shape</code> can exist. That is not a contradiction: the type is a promise about what every element can do, and abstract classes are useful precisely as that promise.</p><div style="overflow-x:auto; margin:14px 0;"><table style="border-collapse:collapse; width:100%; font-size:14.5px;"><thead><tr><th style="text-align:left; padding:7px 12px 7px 0; border-bottom:2px solid var(--border); font-size:12.5px; letter-spacing:.03em; text-transform:uppercase; opacity:.75;"></th><th style="text-align:left; padding:7px 12px 7px 0; border-bottom:2px solid var(--border); font-size:12.5px; letter-spacing:.03em; text-transform:uppercase; opacity:.75;">Abstract class</th><th style="text-align:left; padding:7px 12px 7px 0; border-bottom:2px solid var(--border); font-size:12.5px; letter-spacing:.03em; text-transform:uppercase; opacity:.75;">Interface</th></tr></thead><tbody><tr><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">a class may have</td><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">one</td><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">many</td></tr><tr><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">fields</td><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">yes, any kind</td><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">only <code>public static final</code> constants</td></tr><tr><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">constructors</td><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">yes</td><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">no</td></tr><tr><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">method bodies</td><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">yes</td><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;"><code>default</code> and <code>static</code> methods only</td></tr><tr><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">members are</td><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">any visibility</td><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">implicitly <code>public</code></td></tr><tr><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">expresses</td><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;"><strong>is-a</strong>, with shared code</td><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;"><strong>can-do</strong>, a capability</td></tr></tbody></table></div><p>Choose an abstract class when subclasses share state and implementation as well as a contract; choose an interface when unrelated classes need to promise the same capability. <code>Shape</code> is an abstract class; <code>Comparable</code> is an interface, and a <code>Student</code> and an <code>Invoice</code> can both be comparable while sharing nothing else.</p><p>Neither can be instantiated. Both can be used as a reference type, which is what makes polymorphism through them possible.</p><i data-d286u811="1" style="display:none"></i><div class="callout" data-lb="why" style="border-left-color:#4f46e5;"><div class="callout-label">📘 DEFINITION</div><p style="margin:0 0 7px;"><strong>Template method:</strong> a concrete parent method that calls abstract methods the subclasses supply</p><p style="margin:0 0 7px;"><strong>Common state:</strong> fields the parent holds on behalf of every subclass</p><p style="margin:0 0 7px;"><strong>Polymorphic collection of an abstract type:</strong> valid because every element is a concrete subclass</p></div><div class="callout" data-lb="oa" style="border-left-color:#e11d48;"><div class="callout-label">🎯 EXAM TIP</div><p>An abstract class may have zero abstract methods and still be abstract — the <code>abstract</code> keyword alone is enough to prevent instantiation.</p></div><p data-xref="1" style="margin:26px 0 0; padding-top:12px; border-top:1px solid var(--border);font-size:12.5px; opacity:0.72;">✅ Also covered in depth: <strong>Inheritance → Abstract Classes and Interfaces</strong></p><i data-tbc108="1" style="display:none"></i><div class="vl" data-mathvis="1" data-c959fig="1" style="margin-top:18px;"><div style="font-weight:700; font-size:12.5px; letter-spacing:0.05em; margin-bottom:6px;">📊 FIGURE — ABSTRACT CLASS versus INTERFACE — WHAT EACH ONE CAN CARRY</div><div style="border:1px solid var(--border); border-radius:12px; background:var(--surface-2); padding:14px 10px; overflow-x:auto;"><svg viewBox="0 0 820 400" style="width:100%; max-width:760px; display:block; margin:0 auto; font-family:inherit;" xmlns="http://www.w3.org/2000/svg"><defs><marker id="fk263a" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0,1 L9,5 L0,9 z" fill="var(--text)"/></marker></defs><text x="350" y="34" fill="var(--accent)" font-size="12.5" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">abstract class Shape</text><text x="646" y="34" fill="var(--accent)" font-size="12.5" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">interface Payable</text><text x="196" y="62" fill="var(--text)" font-size="11" font-weight="700" text-anchor="end">a class may have</text><rect x="210" y="44" width="280" height="28" rx="0" fill="none" stroke="var(--border)" stroke-width="1.1"/><text x="350" y="62" fill="var(--text)" font-size="10.5" font-weight="400" text-anchor="middle">ONE superclass</text><rect x="506" y="44" width="280" height="28" rx="0" fill="var(--accent-bg)" stroke="var(--border)" stroke-width="1.1"/><text x="646" y="62" fill="var(--accent)" font-size="10.5" font-weight="700" text-anchor="middle">ANY number of interfaces</text><text x="196" y="94" fill="var(--text)" font-size="11" font-weight="700" text-anchor="end">instance fields</text><rect x="210" y="76" width="280" height="28" rx="0" fill="var(--accent-bg)" stroke="var(--border)" stroke-width="1.1"/><text x="350" y="94" fill="var(--accent)" font-size="10.5" font-weight="700" text-anchor="middle">yes — any kind</text><rect x="506" y="76" width="280" height="28" rx="0" fill="none" stroke="var(--border)" stroke-width="1.1"/><text x="646" y="94" fill="var(--text)" font-size="10.5" font-weight="400" text-anchor="middle">no — only public static final</text><text x="196" y="126" fill="var(--text)" font-size="11" font-weight="700" text-anchor="end">constructors</text><rect x="210" y="108" width="280" height="28" rx="0" fill="var(--accent-bg)" stroke="var(--border)" stroke-width="1.1"/><text x="350" y="126" fill="var(--accent)" font-size="10.5" font-weight="700" text-anchor="middle">yes, run via super(…)</text><rect x="506" y="108" width="280" height="28" rx="0" fill="none" stroke="var(--border)" stroke-width="1.1"/><text x="646" y="126" fill="var(--text)" font-size="10.5" font-weight="400" text-anchor="middle">no</text><text x="196" y="158" fill="var(--text)" font-size="11" font-weight="700" text-anchor="end">method bodies</text><rect x="210" y="140" width="280" height="28" rx="0" fill="var(--accent-bg)" stroke="var(--border)" stroke-width="1.1"/><text x="350" y="158" fill="var(--accent)" font-size="10.5" font-weight="700" text-anchor="middle">yes, freely</text><rect x="506" y="140" width="280" height="28" rx="0" fill="none" stroke="var(--border)" stroke-width="1.1"/><text x="646" y="158" fill="var(--text)" font-size="10.5" font-weight="400" text-anchor="middle">default and static only</text><text x="196" y="190" fill="var(--text)" font-size="11" font-weight="700" text-anchor="end">member visibility</text><rect x="210" y="172" width="280" height="28" rx="0" fill="none" stroke="var(--border)" stroke-width="1.1"/><text x="350" y="190" fill="var(--text)" font-size="10.5" font-weight="400" text-anchor="middle">any — private, protected…</text><rect x="506" y="172" width="280" height="28" rx="0" fill="none" stroke="var(--border)" stroke-width="1.1"/><text x="646" y="190" fill="var(--text)" font-size="10.5" font-weight="400" text-anchor="middle">implicitly public</text><text x="196" y="222" fill="var(--text)" font-size="11" font-weight="700" text-anchor="end">can be instantiated</text><rect x="210" y="204" width="280" height="28" rx="0" fill="none" stroke="var(--border)" stroke-width="1.1"/><text x="350" y="222" fill="var(--text)" font-size="10.5" font-weight="400" text-anchor="middle">no</text><rect x="506" y="204" width="280" height="28" rx="0" fill="none" stroke="var(--border)" stroke-width="1.1"/><text x="646" y="222" fill="var(--text)" font-size="10.5" font-weight="400" text-anchor="middle">no</text><text x="196" y="254" fill="var(--text)" font-size="11" font-weight="700" text-anchor="end">usable as a type</text><rect x="210" y="236" width="280" height="28" rx="0" fill="none" stroke="var(--border)" stroke-width="1.1"/><text x="350" y="254" fill="var(--text)" font-size="10.5" font-weight="400" text-anchor="middle">yes</text><rect x="506" y="236" width="280" height="28" rx="0" fill="none" stroke="var(--border)" stroke-width="1.1"/><text x="646" y="254" fill="var(--text)" font-size="10.5" font-weight="400" text-anchor="middle">yes</text><text x="196" y="286" fill="var(--text)" font-size="11" font-weight="700" text-anchor="end">expresses</text><rect x="210" y="268" width="280" height="28" rx="0" fill="none" stroke="var(--border)" stroke-width="1.1"/><text x="350" y="286" fill="var(--text)" font-size="10.5" font-weight="400" text-anchor="middle">IS-A, with shared code</text><rect x="506" y="268" width="280" height="28" rx="0" fill="none" stroke="var(--border)" stroke-width="1.1"/><text x="646" y="286" fill="var(--text)" font-size="10.5" font-weight="400" text-anchor="middle">CAN-DO, a capability</text><text x="410" y="316" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-style="italic">both rows at the bottom are the same — which is why both support polymorphism identically</text><line x1="30" y1="336" x2="790" y2="336" stroke="var(--border)" stroke-width="1"/><rect x="46" y="352" width="340" height="34" rx="7" fill="var(--accent-bg)" stroke="var(--accent)" stroke-width="1.5"/><text x="216" y="373.5" fill="var(--text)" font-size="12" font-weight="700" text-anchor="middle">shared STATE and code → abstract class</text><rect x="434" y="352" width="340" height="34" rx="7" fill="var(--accent-bg)" stroke="var(--accent)" stroke-width="1.5"/><text x="604" y="373.5" fill="var(--text)" font-size="12" font-weight="700" text-anchor="middle">unrelated classes, same capability → interface</text></svg></div></div><div class="callout" data-lb="key" style="border-left-color:#0ea5e9;"><div class="callout-label">▸ WORKED EXAMPLE — THE SAME HIERARCHY USING BOTH AT ONCE</div><p>This is the normal arrangement in real code: an abstract class for the shared state, an interface for the capability, and a class that uses both.</p><pre style="background:var(--surface-2); border:1px solid var(--border); border-radius:8px; padding:11px 13px; overflow-x:auto; font-size:13px; line-height:1.55; margin:10px 0;"><code>interface Payable {
    double RATE = 15.0;                       // implicitly public static final
    double pay();                             // implicitly public abstract
    default String label() { return "Payable earning " + pay(); }
    static String unit() { return "USD"; }
}
interface Printable { void print(); }

static abstract class Person implements Payable {
    protected String name;                    // STATE — only a class can hold this
    Person(String n) { name = n; }            // a constructor — only a class can have one
    public String toString() { return name; }
}
static class Contractor extends Person implements Printable {
    double hours;
    Contractor(String n, double h) { super(n); hours = h; }
    public double pay() { return hours * RATE; }        // must be PUBLIC
    public void print() { System.out.println("Contractor " + name); }
}
static class Volunteer extends Person {
    Volunteer(String n) { super(n); }
    public double pay() { return 0; }
    @Override public String label() { return "Volunteer, unpaid"; }   // overrides the default
}

Contractor c = new Contractor("Bo", 20);
Volunteer  v = new Volunteer("Vi");
System.out.println(c.pay());
System.out.println(c.label());
System.out.println(v.label());
System.out.println(Payable.RATE + " " + Payable.unit());
Payable[] all = { c, v };
double t = 0;
for (Payable p : all) t += p.pay();
System.out.println("total " + t);
System.out.println(c instanceof Payable);
System.out.println(c instanceof Printable);
System.out.println(v instanceof Printable);
Printable p = c;
p.print();</code></pre><ol style="margin:8px 0 4px 18px; padding:0; line-height:1.65;"><li style="margin-bottom:5px;"><code>Person</code> is abstract and <code>implements Payable</code> without supplying <code>pay()</code>. That is legal precisely because it is abstract — the obligation is inherited by its subclasses.</li><li style="margin-bottom:5px;"><code>Contractor</code> extends one class and implements one interface. It could implement ten more; it could never extend a second class.</li><li style="margin-bottom:5px;"><code>RATE</code> is used unqualified inside <code>Contractor</code> because interface constants are inherited: 20 × 15.0 = <strong>300.0</strong>.</li><li style="margin-bottom:5px;"><code>label()</code> is a <strong>default method</strong> — an interface method with a body. Contractor never wrote one, so it gets the inherited version. Volunteer overrides it. Both compile, and neither had to.</li><li style="margin-bottom:5px;"><code>Payable.RATE</code> and <code>Payable.unit()</code> are reached through the interface name itself: constants and static methods belong to the interface, not to any instance.</li><li style="margin-bottom:5px;"><code>Payable[] all = { c, v };</code> — an interface is a perfectly good array element type, and the loop adds 300.0 + 0 = <strong>300.0</strong>. Polymorphism through an interface is identical to polymorphism through a class.</li><li style="margin-bottom:5px;"><code>c instanceof Printable</code> is true and <code>v instanceof Printable</code> is false: the two classes share a superclass but not this capability, which is exactly the distinction an interface exists to express.</li></ol><div style="margin:9px 0 4px;"><span style="font-size:11px; font-weight:700; letter-spacing:0.05em; color:var(--text-3);">OUTPUT</span></div><pre style="background:var(--surface-3, var(--surface-2)); border-left:3px solid var(--accent); border-radius:0 8px 8px 0; padding:9px 13px; overflow-x:auto; font-size:13px; line-height:1.5; margin:0 0 10px;"><code>300.0
Payable earning 300.0
Volunteer, unpaid
15.0 USD
total 300.0
true
true
false
Contractor Bo</code></pre></div><div class="callout" data-lb="key" style="border-left-color:#0ea5e9;"><div class="callout-label">▸ WORKED EXAMPLE — CHOOSING BETWEEN THEM — THREE REAL DECISIONS</div><p>The choice is decided by two questions: <em>is there shared state?</em> and <em>are the classes otherwise related?</em></p><div style="overflow-x:auto; margin:14px 0;"><table style="border-collapse:collapse; width:100%; font-size:14.5px;"><thead><tr><th style="text-align:left; padding:7px 12px 7px 0; border-bottom:2px solid var(--border); font-size:12.5px; letter-spacing:0.04em;">Requirement</th><th style="text-align:left; padding:7px 12px 7px 0; border-bottom:2px solid var(--border); font-size:12.5px; letter-spacing:0.04em;">Choice</th><th style="text-align:left; padding:7px 12px 7px 0; border-bottom:2px solid var(--border); font-size:12.5px; letter-spacing:0.04em;">Why</th></tr></thead><tbody><tr><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border); font-weight:600;">Circle, Rect and Square all have a <code>name</code>, print the same way, and each computes area differently</td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);"><strong>abstract class</strong></td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);">there is shared state (<code>name</code>) and shared code (<code>describe()</code>). An interface can hold neither.</td></tr><tr><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border); font-weight:600;">A <code>Student</code> and an <code>Invoice</code> must both be sortable</td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);"><strong>interface</strong> (<code>Comparable</code>)</td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);">the classes have nothing in common and already have their own parents. A capability, not a family.</td></tr><tr><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border); font-weight:600;">Employees share payroll fields, and <em>some</em> of them can also be printed to a report</td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);"><strong>both</strong></td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);"><code>abstract class Employee</code> for the shared state, <code>interface Printable</code> for the optional capability — exactly the arrangement in the previous example.</td></tr></tbody></table></div><ol style="margin:8px 0 4px 18px; padding:0; line-height:1.65;"><li style="margin-bottom:5px;"><strong>Ask about state first.</strong> If the types need to share a field, an abstract class is the only option — interfaces can hold constants and nothing else.</li><li style="margin-bottom:5px;"><strong>Then ask about the family.</strong> If the implementers are unrelated and would each need a different parent, only an interface is possible, because a class may extend one thing and implement many.</li><li style="margin-bottom:5px;"><strong>Then ask what happens next year.</strong> Adding a method to an interface breaks every existing implementer — unless you give it a <code>default</code> body, which is exactly why default methods were added to the language.</li><li style="margin-bottom:5px;"><strong>"Both" is a normal answer.</strong> The abstract class supplies the shared implementation, the interfaces supply the capabilities, and a class combines one of the first with any number of the second.</li></ol><p>One inheritance rule that follows from all this: an interface may <code>extends</code> <em>several</em> other interfaces (<code>interface A extends B, C</code>), because there is no state to inherit twice. A class still gets exactly one <code>extends</code>.</p></div><div class="callout" data-lb="key" style="border-left-color:#f59e0b;"><div class="callout-label">⚠️ COMMON MISTAKE</div><p><strong>Dropping <code>public</code> when implementing an interface method.</strong> Interface methods are implicitly <code>public</code>, and an override may never narrow visibility — so writing <code>double pay() { ... }</code> in the implementing class fails with <em>attempting to assign weaker access privileges; was public</em>. Nothing in the interface source shows the word <code>public</code>, which is what makes the omission feel reasonable.</p><p>Two more implicit-modifier surprises from the same source:</p><p>• A field in an interface is silently <code>public static final</code>. <code>RATE = 15.0;</code> is a constant, cannot be reassigned, and belongs to the interface rather than to any object. There is no such thing as an interface instance field.<br>• An interface method with no body is silently <code>public abstract</code>. Writing <code>private double pay();</code> is a compile error, not a stricter version of the same thing.</p><p>How to notice: any compile error mentioning <em>weaker access privileges</em> next to an <code>implements</code> clause is this, and the fix is a single missing keyword.</p></div>"},"D286/u10/z10_9":{"body":"<p>Two relationships between classes are constantly confused, and choosing the wrong one produces designs that fight you later.</p><pre style="background:var(--bg-2, var(--surface-2)); padding:12px; border-radius:8px; font-size:13px; overflow-x:auto; line-height:1.55;">IS-A  (inheritance)          A Manager IS-A Employee     -&gt; extends
HAS-A (composition)          A Car HAS-A Engine          -&gt; a field

class Car {
    private Engine engine;       // composition: Car HAS-A Engine
}

class SportsCar extends Car { }  // inheritance: SportsCar IS-A Car</pre><p>The test is the sentence. "A Car is an Engine" is nonsense, so <code>Car extends Engine</code> is wrong even though a Car needs an Engine. Composition is also the more flexible choice — an object can have many parts, but a class can extend only one class.</p><div style="overflow-x:auto; margin:14px 0;"><table style="border-collapse:collapse; width:100%; font-size:14.5px;"><thead><tr><th style="text-align:left; padding:7px 12px 7px 0; border-bottom:2px solid var(--border); font-size:12.5px; letter-spacing:.03em; text-transform:uppercase; opacity:.75;">Relationship</th><th style="text-align:left; padding:7px 12px 7px 0; border-bottom:2px solid var(--border); font-size:12.5px; letter-spacing:.03em; text-transform:uppercase; opacity:.75;">Means</th><th style="text-align:left; padding:7px 12px 7px 0; border-bottom:2px solid var(--border); font-size:12.5px; letter-spacing:.03em; text-transform:uppercase; opacity:.75;">Implemented as</th></tr></thead><tbody><tr><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;"><strong>is-a</strong></td><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">a Manager <em>is an</em> Employee</td><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;"><code>extends</code> — inheritance</td></tr><tr><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;"><strong>has-a</strong></td><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">a Car <em>has an</em> Engine</td><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">a field — composition</td></tr></tbody></table></div><p>The test is the sentence. "A Car is an Engine" is false, so <code>class Car extends Engine</code> is wrong however convenient the inherited methods look. "A Car has an Engine" is true, so <code>Engine</code> becomes a field.</p><p>Inheriting for convenience is the classic error: <code>Stack extends ArrayList</code> gives a stack every list method, including <code>add(int, E)</code> in the middle, which breaks the one rule a stack has. Composition — a private list inside the stack — exposes only what should be exposed.</p><p>The Square/Rectangle case is the standard warning: a square <em>is</em> a rectangle mathematically, but a <code>Square</code> that inherits <code>setWidth</code> and <code>setHeight</code> can be made non-square, so the inheritance breaks the type's own guarantee.</p><i data-d286u811="1" style="display:none"></i><div class="callout" data-lb="why" style="border-left-color:#4f46e5;"><div class="callout-label">📘 DEFINITION</div><p style="margin:0 0 7px;"><strong>Is-a relationship:</strong> a subtype relationship, expressed by extends or implements</p><p style="margin:0 0 7px;"><strong>Has-a relationship:</strong> containment, expressed by a field holding another object</p><p style="margin:0 0 7px;"><strong>Composition:</strong> building a class from other objects rather than by inheriting</p><p style="margin:0 0 7px;"><strong>Single inheritance:</strong> Java allows only one superclass; interfaces are the way around it (10.11)</p></div><div class="callout" data-lb="oa" style="border-left-color:#e11d48;"><div class="callout-label">🎯 EXAM TIP</div><p>When a question asks whether one class should extend another, read it out loud as "an X is a Y". If that sentence is false, the answer is a field.</p></div><p data-xref="1" style="margin:26px 0 0; padding-top:12px; border-top:1px solid var(--border);font-size:12.5px; opacity:0.72;">✅ Also covered in depth: <strong>Inheritance → Inheritance with extends and super</strong></p><i data-tbc109="1" style="display:none"></i><div class="vl" data-mathvis="1" data-c959fig="1" style="margin-top:18px;"><div style="font-weight:700; font-size:12.5px; letter-spacing:0.05em; margin-bottom:6px;">📊 FIGURE — IS-A POINTS UP, HAS-A POINTS ACROSS</div><div style="border:1px solid var(--border); border-radius:12px; background:var(--surface-2); padding:14px 10px; overflow-x:auto;"><svg viewBox="0 0 820 400" style="width:100%; max-width:760px; display:block; margin:0 auto; font-family:inherit;" xmlns="http://www.w3.org/2000/svg"><defs><marker id="fk264a" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0,1 L9,5 L0,9 z" fill="var(--text)"/></marker></defs><text x="190" y="24" fill="var(--accent)" font-size="11.5" font-weight="700" text-anchor="middle">IS-A  →  extends</text><rect x="110" y="40" width="170" height="74" rx="5" fill="var(--surface)" stroke="var(--text)" stroke-width="1.5"/><line x1="110" y1="68" x2="280" y2="68" stroke="var(--text)" stroke-width="1.2"/><line x1="110" y1="91" x2="280" y2="91" stroke="var(--text)" stroke-width="1.2"/><text x="195" y="59" fill="var(--text)" font-size="12.5" font-weight="700" text-anchor="middle">Car</text><text x="118" y="84" fill="var(--text-3)" font-size="10" font-weight="400" text-anchor="start" font-family="ui-monospace,Menlo,monospace">- model</text><text x="118" y="107" fill="var(--text)" font-size="10" font-weight="400" text-anchor="start" font-family="ui-monospace,Menlo,monospace">+ start()</text><line x1="195" y1="168" x2="195" y2="126" stroke="var(--text)" stroke-width="1.5"/><path d="M187,126 L195,114 L203,126 Z" fill="var(--surface)" stroke="var(--text)" stroke-width="1.5"/><rect x="110" y="168" width="170" height="63" rx="5" fill="var(--surface)" stroke="var(--text)" stroke-width="1.5"/><line x1="110" y1="196" x2="280" y2="196" stroke="var(--text)" stroke-width="1.2"/><line x1="110" y1="208" x2="280" y2="208" stroke="var(--text)" stroke-width="1.2"/><text x="195" y="187" fill="var(--text)" font-size="12.5" font-weight="700" text-anchor="middle">SportsCar</text><text x="118" y="224" fill="var(--text)" font-size="10" font-weight="400" text-anchor="start" font-family="ui-monospace,Menlo,monospace">(inherits everything)</text><text x="195" y="246" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-style="italic">"a SportsCar is a Car" — true,</text><text x="195" y="261" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-style="italic">so extends is right</text><line x1="330" y1="30" x2="330" y2="290" stroke="var(--border)" stroke-width="1"/><text x="560" y="24" fill="var(--accent)" font-size="11.5" font-weight="700" text-anchor="middle">HAS-A  →  a field</text><rect x="370" y="40" width="170" height="74" rx="5" fill="var(--accent-bg)" stroke="var(--accent)" stroke-width="1.5"/><line x1="370" y1="68" x2="540" y2="68" stroke="var(--text)" stroke-width="1.2"/><line x1="370" y1="91" x2="540" y2="91" stroke="var(--text)" stroke-width="1.2"/><text x="455" y="59" fill="var(--text)" font-size="12.5" font-weight="700" text-anchor="middle">Car</text><text x="378" y="84" fill="var(--text-3)" font-size="10" font-weight="400" text-anchor="start" font-family="ui-monospace,Menlo,monospace">- engine : Engine</text><text x="378" y="107" fill="var(--text)" font-size="10" font-weight="400" text-anchor="start" font-family="ui-monospace,Menlo,monospace">+ start()</text><rect x="620" y="40" width="170" height="74" rx="5" fill="var(--surface)" stroke="var(--text)" stroke-width="1.5"/><line x1="620" y1="68" x2="790" y2="68" stroke="var(--text)" stroke-width="1.2"/><line x1="620" y1="91" x2="790" y2="91" stroke="var(--text)" stroke-width="1.2"/><text x="705" y="59" fill="var(--text)" font-size="12.5" font-weight="700" text-anchor="middle">Engine</text><text x="628" y="84" fill="var(--text-3)" font-size="10" font-weight="400" text-anchor="start" font-family="ui-monospace,Menlo,monospace">- hp : int</text><text x="628" y="107" fill="var(--text)" font-size="10" font-weight="400" text-anchor="start" font-family="ui-monospace,Menlo,monospace">+ start()</text><path d="M546,66 L556,60 L566,66 L556,72 Z" fill="var(--text)" stroke="var(--text)" stroke-width="1.2"/><line x1="566" y1="66" x2="618" y2="66" stroke="var(--text)" stroke-width="1.5"/><text x="592" y="56" fill="var(--text-3)" font-size="9.5" font-weight="400" text-anchor="middle">1</text><text x="580" y="128" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-style="italic">"a Car is an Engine" — false.</text><text x="580" y="143" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-style="italic">"a Car HAS an Engine" — true, so it is a field</text><rect x="370" y="166" width="420" height="44" rx="7" fill="var(--surface)" stroke="var(--text)" stroke-width="1.5"/><text x="580" y="185" fill="var(--text)" font-size="11" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">void start() { engine.start(); }</text><text x="580" y="201" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle">delegation — Car forwards the request to its part</text><text x="580" y="232" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-style="italic">a class may have many parts; it may extend only one class</text><text x="580" y="248" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-style="italic">— which is why composition is the more flexible default</text><line x1="30" y1="302" x2="790" y2="302" stroke="var(--border)" stroke-width="1"/><text x="410" y="328" fill="var(--accent)" font-size="11.5" font-weight="700" text-anchor="middle">THE WARNING CASE: A SQUARE IS A RECTANGLE — UNTIL SOMEONE RESIZES IT</text><rect x="60" y="344" width="216" height="40" rx="7" fill="var(--surface)" stroke="var(--text)" stroke-width="1.5"/><text x="168" y="361" fill="var(--text)" font-size="11" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">new Square(4).area()</text><text x="168" y="377" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle">16.0 — correct</text><line x1="276" y1="364" x2="316" y2="364" stroke="var(--text)" stroke-width="1.6" marker-end="url(#fk264a)"/><rect x="320" y="344" width="216" height="40" rx="7" fill="var(--surface)" stroke="var(--text)" stroke-width="1.5"/><text x="428" y="361" fill="var(--text)" font-size="11" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">setWidth(10)</text><text x="428" y="377" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle">inherited from Rectangle</text><line x1="536" y1="364" x2="576" y2="364" stroke="var(--text)" stroke-width="1.6" marker-end="url(#fk264a)"/><rect x="580" y="344" width="200" height="40" rx="7" fill="var(--accent-bg)" stroke="var(--accent)" stroke-width="2.2"/><text x="680" y="361" fill="var(--text)" font-size="11" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">area() → 40.0</text><text x="680" y="377" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle">a 10 × 4 "square"</text></svg></div></div><div class="callout" data-lb="key" style="border-left-color:#0ea5e9;"><div class="callout-label">▸ WORKED EXAMPLE — THE SAME PROGRAM WRITTEN BOTH WAYS</div><p><code>SportsCar extends Car</code> and <code>Car has-a Engine</code> sit side by side here, so the difference in what each buys you is visible in one run.</p><pre style="background:var(--surface-2); border:1px solid var(--border); border-radius:8px; padding:11px 13px; overflow-x:auto; font-size:13px; line-height:1.55; margin:10px 0;"><code>static class Engine {
    int hp; boolean running;
    Engine(int hp) { this.hp = hp; }
    void start() { running = true; }
    String status() { return hp + "hp " + (running ? "running" : "stopped"); }
}
static class Car {
    private Engine engine;                    // HAS-A
    private String model;
    Car(String m, int hp) { model = m; engine = new Engine(hp); }
    void start() { engine.start(); }          // delegation
    String report() { return model + ": " + engine.status(); }
}
static class SportsCar extends Car {          // IS-A
    SportsCar(String m) { super(m, 460); }
}

Car c = new SportsCar("GT");
c.start();
System.out.println(c.report());
System.out.println(c instanceof Car);

ArrayList&lt;Car&gt; fleet = new ArrayList&lt;&gt;();
fleet.add(new Car("Sedan", 180));
fleet.add(new SportsCar("GT"));
for (Car x : fleet) System.out.println(x.report());</code></pre><ol style="margin:8px 0 4px 18px; padding:0; line-height:1.65;"><li style="margin-bottom:5px;"><code>SportsCar</code> adds nothing but a constructor. It still gets <code>start()</code>, <code>report()</code>, and — the part that matters — it <strong>is</strong> a <code>Car</code>, so it fits in a <code>Car</code> variable and a <code>List&lt;Car&gt;</code>.</li><li style="margin-bottom:5px;">That substitutability is what <code>extends</code> is for. Composition would not give it: a class holding a <code>Car</code> field is not a <code>Car</code> and cannot go in the list.</li><li style="margin-bottom:5px;"><code>Car</code> holds an <code>Engine</code> as a <strong>private field</strong>. <code>Car.start()</code> does not inherit engine behaviour, it <em>forwards</em> to it — one line of delegation.</li><li style="margin-bottom:5px;">The payoff is control. <code>Car</code> exposes <code>start()</code> and <code>report()</code> and nothing else; the <code>Engine</code>'s own methods are not part of <code>Car</code>'s interface unless <code>Car</code> chooses to forward them.</li><li style="margin-bottom:5px;">Only the GT is started, so the loop prints <code>Sedan: 180hp stopped</code> and <code>GT: 460hp stopped</code> — the second <code>SportsCar</code> is a different object from <code>c</code>, with its own engine.</li></ol><div style="margin:9px 0 4px;"><span style="font-size:11px; font-weight:700; letter-spacing:0.05em; color:var(--text-3);">OUTPUT</span></div><pre style="background:var(--surface-3, var(--surface-2)); border-left:3px solid var(--accent); border-radius:0 8px 8px 0; padding:9px 13px; overflow-x:auto; font-size:13px; line-height:1.5; margin:0 0 10px;"><code>GT: 460hp running
true
Sedan: 180hp stopped
GT: 460hp stopped</code></pre><p>Had <code>Car extends Engine</code> been used instead, <code>Car</code> would have inherited <code>hp</code> and <code>status()</code> and the code would compile — but every <code>Car</code> would then <em>be</em> an <code>Engine</code>, fit in a <code>List&lt;Engine&gt;</code>, and expose engine internals to the whole program. Convenience is not a reason to inherit.</p></div><div class="callout" data-lb="key" style="border-left-color:#0ea5e9;"><div class="callout-label">▸ WORKED EXAMPLE — WHEN "IS-A" IS TRUE IN ENGLISH AND WRONG IN CODE</div><p>A square is a rectangle — every geometry textbook says so. Inherit on that basis and you get a compiling program that breaks its own guarantee.</p><pre style="background:var(--surface-2); border:1px solid var(--border); border-radius:8px; padding:11px 13px; overflow-x:auto; font-size:13px; line-height:1.55; margin:10px 0;"><code>static class Rectangle {
    protected double w, h;
    void setWidth(double w)  { this.w = w; }
    void setHeight(double h) { this.h = h; }
    double area() { return w * h; }
}
static class Square extends Rectangle {
    Square(double s) { w = s; h = s; }
}

Rectangle r = new Square(4);
System.out.println("square area " + r.area());
r.setWidth(10);
System.out.println("after setWidth(10): " + r.area()
                 + "  still a Square? " + (r instanceof Square));</code></pre><ol style="margin:8px 0 4px 18px; padding:0; line-height:1.65;"><li style="margin-bottom:5px;"><code>new Square(4)</code> sets both sides to 4, so the area is <strong>16.0</strong>. Everything is fine so far.</li><li style="margin-bottom:5px;"><code>r</code> is declared <code>Rectangle</code>, so <code>setWidth</code> is available — it was inherited, and there is no way to un-inherit it.</li><li style="margin-bottom:5px;">After <code>setWidth(10)</code> the object has width 10 and height 4. Its area is <strong>40.0</strong>, and <code>instanceof Square</code> is still <strong>true</strong>.</li><li style="margin-bottom:5px;">The object now claims to be a Square while being 10 × 4. The class's one invariant — all sides equal — has been broken by a method the class never wrote and cannot remove.</li><li style="margin-bottom:5px;">Overriding <code>setWidth</code> to set both sides does not rescue it either: code written against <code>Rectangle</code> reasonably expects <code>setWidth(10); setHeight(4);</code> to give area 40, and would now silently get 16.</li></ol><div style="margin:9px 0 4px;"><span style="font-size:11px; font-weight:700; letter-spacing:0.05em; color:var(--text-3);">OUTPUT</span></div><pre style="background:var(--surface-3, var(--surface-2)); border-left:3px solid var(--accent); border-radius:0 8px 8px 0; padding:9px 13px; overflow-x:auto; font-size:13px; line-height:1.5; margin:0 0 10px;"><code>square area 16.0
after setWidth(10): 40.0  still a Square? true</code></pre><p>The test that catches this is stronger than the English sentence: <strong>can the subclass honour every promise the parent makes?</strong> A <code>Rectangle</code> promises independently settable sides; a <code>Square</code> cannot honour it. The fix is composition — a <code>Square</code> with a <code>side</code> field, offering only the operations it can actually support.</p><p>The everyday version of the same error is <code>class Stack extends ArrayList</code>: convenient, compiles, and hands every user <code>add(int, E)</code> so they can insert into the middle of a stack.</p></div><div class="callout" data-lb="key" style="border-left-color:#f59e0b;"><div class="callout-label">⚠️ COMMON MISTAKE</div><p><strong>Inheriting to reuse code.</strong> The reasoning goes: "<code>Invoice</code> needs the date-formatting methods in <code>Report</code>, so I will extend <code>Report</code>." It compiles, the methods work, and you have now declared that every <code>Invoice</code> <em>is</em> a <code>Report</code> — so it can be passed to any method expecting one, stored in a <code>List&lt;Report&gt;</code>, and given every other <code>Report</code> method whether it makes sense or not.</p><p>How to notice it: say the sentence out loud. If "an <code>Invoice</code> is a <code>Report</code>" makes you hesitate, the answer is a field — <code>private Report formatter;</code> — or a static utility method.</p><p>The second signal is <strong>overriding a method to make it do nothing</strong>, or to throw. If a subclass has to disable something it inherited, the is-a relationship was false; the parent promised behaviour the child cannot deliver. Composition exposes only what you choose to forward, and that is the whole difference.</p></div>"},"D286/u10/z10_10":{"body":"<p>A UML class diagram is the standard way to draw these relationships, and the exam expects you to read one rather than draw a beautiful one.</p><pre style="background:var(--bg-2, var(--surface-2)); padding:12px; border-radius:8px; font-size:13px; overflow-x:auto; line-height:1.55;">+-------------------+
|     Employee      |          - private
+-------------------+          + public
| - name : String   |          # protected
| - salary : double |
+-------------------+
| + getSalary()     |
| + describe()      |
+-------------------+
          ^
          | (hollow triangle = inheritance, points at the PARENT)
+-------------------+
|      Manager      |
+-------------------+</pre><p>Three arrows carry most of the meaning: a hollow triangle for inheritance pointing at the parent, a plain line or arrow for association (has-a), and a dashed line with a hollow triangle for implementing an interface.</p><pre style="background:var(--bg-2, var(--surface-2)); padding:12px; border-radius:8px; font-size:13px; overflow-x:auto; line-height:1.55;">+-------------------+
|     Employee      |     - private   + public   # protected
+-------------------+
| - name : String   |     fields on top
+-------------------+
| + pay() : double  |     methods below
+-------------------+
          ^                 hollow triangle, solid line = EXTENDS
          |
+-------------------+
|      Manager      |
+-------------------+</pre><div style="overflow-x:auto; margin:14px 0;"><table style="border-collapse:collapse; width:100%; font-size:14.5px;"><thead><tr><th style="text-align:left; padding:7px 12px 7px 0; border-bottom:2px solid var(--border); font-size:12.5px; letter-spacing:.03em; text-transform:uppercase; opacity:.75;">Notation</th><th style="text-align:left; padding:7px 12px 7px 0; border-bottom:2px solid var(--border); font-size:12.5px; letter-spacing:.03em; text-transform:uppercase; opacity:.75;">Means</th></tr></thead><tbody><tr><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">hollow triangle, solid line</td><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">inheritance — <em>is-a</em></td></tr><tr><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">hollow triangle, dashed line</td><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">implements an interface</td></tr><tr><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">filled diamond</td><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">composition — the part dies with the whole</td></tr><tr><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">hollow diamond</td><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">aggregation — the part can outlive it</td></tr><tr><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;"><code>+</code> / <code>-</code> / <code>#</code></td><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">public / private / protected</td></tr><tr><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;"><em>italic</em> class name</td><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">abstract</td></tr><tr><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">&lt;&lt;interface&gt;&gt;</td><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">the stereotype above an interface name</td></tr></tbody></table></div><p>The arrow always points from the subclass <em>up</em> to the base class, which is the direction people most often draw backwards.</p><i data-d286u811="1" style="display:none"></i><div class="callout" data-lb="why" style="border-left-color:#4f46e5;"><div class="callout-label">📘 DEFINITION</div><p style="margin:0 0 7px;"><strong>UML class diagram:</strong> a diagram of classes, their members and their relationships</p><p style="margin:0 0 7px;"><strong>Visibility markers:</strong> - private, + public, # protected</p><p style="margin:0 0 7px;"><strong>Generalisation arrow:</strong> the hollow triangle pointing from subclass to superclass</p><p style="margin:0 0 7px;"><strong>Multiplicity:</strong> the 1, 0..1 or * on an association showing how many objects are involved</p></div><div class="callout" data-lb="oa" style="border-left-color:#e11d48;"><div class="callout-label">🎯 EXAM TIP</div><p>The arrow always points from the more specific class to the more general one — subclass to superclass, implementer to interface. Reversing it is the usual diagram-reading error.</p></div><i data-tbc1010="1" style="display:none"></i><div class="vl" data-mathvis="1" data-c959fig="1" style="margin-top:18px;"><div style="font-weight:700; font-size:12.5px; letter-spacing:0.05em; margin-bottom:6px;">📊 FIGURE — READING A UML CLASS DIAGRAM</div><div style="border:1px solid var(--border); border-radius:12px; background:var(--surface-2); padding:14px 10px; overflow-x:auto;"><svg viewBox="0 0 820 420" style="width:100%; max-width:760px; display:block; margin:0 auto; font-family:inherit;" xmlns="http://www.w3.org/2000/svg"><defs><marker id="fk265a" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0,1 L9,5 L0,9 z" fill="var(--text)"/></marker></defs><text x="180" y="24" fill="var(--accent)" font-size="11.5" font-weight="700" text-anchor="middle">THE BOX</text><rect x="90" y="40" width="200" height="134" rx="5" fill="var(--surface)" stroke="var(--text)" stroke-width="2.2"/><line x1="90" y1="68" x2="290" y2="68" stroke="var(--text)" stroke-width="1.2"/><line x1="90" y1="121" x2="290" y2="121" stroke="var(--text)" stroke-width="1.2"/><text x="190" y="59" fill="var(--text)" font-size="12.5" font-weight="700" text-anchor="middle">Employee</text><text x="98" y="84" fill="var(--text-3)" font-size="10" font-weight="400" text-anchor="start" font-family="ui-monospace,Menlo,monospace">- name : String</text><text x="98" y="99" fill="var(--text-3)" font-size="10" font-weight="400" text-anchor="start" font-family="ui-monospace,Menlo,monospace"># salary : double</text><text x="98" y="114" fill="var(--text-3)" font-size="10" font-weight="400" text-anchor="start" font-family="ui-monospace,Menlo,monospace">+ ID_PREFIX : String</text><text x="98" y="137" fill="var(--text)" font-size="10" font-weight="400" text-anchor="start" font-family="ui-monospace,Menlo,monospace">+ getSalary() : double</text><text x="98" y="152" fill="var(--text)" font-size="10" font-weight="400" text-anchor="start" font-family="ui-monospace,Menlo,monospace"># raise(double) : void</text><text x="98" y="167" fill="var(--text)" font-size="10" font-weight="400" text-anchor="start" font-family="ui-monospace,Menlo,monospace">- audit() : void</text><line x1="290" y1="54" x2="330" y2="54" stroke="var(--text-3)" stroke-width="1.6"/><text x="336" y="58" fill="var(--text-3)" font-size="10" font-weight="400" text-anchor="start">class name</text><line x1="290" y1="92" x2="330" y2="92" stroke="var(--text-3)" stroke-width="1.6"/><text x="336" y="96" fill="var(--text-3)" font-size="10" font-weight="400" text-anchor="start">fields — name : type</text><line x1="290" y1="152" x2="330" y2="152" stroke="var(--text-3)" stroke-width="1.6"/><text x="336" y="156" fill="var(--text-3)" font-size="10" font-weight="400" text-anchor="start">methods — name(args) : return</text><text x="336" y="190" fill="var(--accent)" font-size="10.5" font-weight="700" text-anchor="start" font-family="ui-monospace,Menlo,monospace">−  private        +  public</text><text x="336" y="206" fill="var(--accent)" font-size="10.5" font-weight="700" text-anchor="start" font-family="ui-monospace,Menlo,monospace">#  protected      ~  package</text><text x="336" y="226" fill="var(--text-3)" font-size="10" font-weight="400" text-anchor="start" font-style="italic">an ITALIC class name means abstract</text><text x="336" y="242" fill="var(--text-3)" font-size="10" font-weight="400" text-anchor="start">an underlined member means static</text><line x1="30" y1="268" x2="790" y2="268" stroke="var(--border)" stroke-width="1"/><text x="410" y="294" fill="var(--accent)" font-size="11.5" font-weight="700" text-anchor="middle">THE FOUR CONNECTORS — AND THEY ALL POINT AWAY FROM THE SPECIFIC</text><line x1="76" y1="356" x2="76" y2="322" stroke="var(--text)" stroke-width="1.5"/><path d="M68,322 L76,310 L84,322 Z" fill="var(--surface)" stroke="var(--text)" stroke-width="1.5"/><text x="76" y="374" fill="var(--text)" font-size="10.5" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">extends</text><text x="76" y="390" fill="var(--text-3)" font-size="9.5" font-weight="400" text-anchor="middle">solid + hollow ▲</text><line x1="246" y1="356" x2="246" y2="322" stroke="var(--text)" stroke-width="1.5" stroke-dasharray="5 4"/><path d="M238,322 L246,310 L254,322 Z" fill="var(--surface)" stroke="var(--text)" stroke-width="1.5"/><text x="246" y="374" fill="var(--text)" font-size="10.5" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">implements</text><text x="246" y="390" fill="var(--text-3)" font-size="9.5" font-weight="400" text-anchor="middle">DASHED + hollow ▲</text><line x1="416" y1="340" x2="416" y2="314" stroke="var(--text)" stroke-width="1.5"/><path d="M416,310 L426,320 L416,330 L406,320 Z" fill="var(--text)" stroke="var(--text)" stroke-width="1.2"/><text x="416" y="374" fill="var(--text)" font-size="10.5" font-weight="700" text-anchor="middle">composition</text><text x="416" y="390" fill="var(--text-3)" font-size="9.5" font-weight="400" text-anchor="middle">FILLED ◆ — part dies with whole</text><line x1="606" y1="340" x2="606" y2="314" stroke="var(--text)" stroke-width="1.5"/><path d="M606,310 L616,320 L606,330 L596,320 Z" fill="var(--surface)" stroke="var(--text)" stroke-width="1.2"/><text x="606" y="374" fill="var(--text)" font-size="10.5" font-weight="700" text-anchor="middle">aggregation</text><text x="606" y="390" fill="var(--text-3)" font-size="9.5" font-weight="400" text-anchor="middle">HOLLOW ◇ — part can outlive it</text></svg></div></div><div class="callout" data-lb="key" style="border-left-color:#0ea5e9;"><div class="callout-label">▸ WORKED EXAMPLE — TRANSLATING A DIAGRAM INTO CODE, MEMBER BY MEMBER</div><p>Exam questions give you the picture and ask for the code, or give you the code and ask which picture matches. Both directions are the same table read in opposite orders.</p><div style="overflow-x:auto; margin:14px 0;"><table style="border-collapse:collapse; width:100%; font-size:14.5px;"><thead><tr><th style="text-align:left; padding:7px 12px 7px 0; border-bottom:2px solid var(--border); font-size:12.5px; letter-spacing:0.04em;">In the diagram</th><th style="text-align:left; padding:7px 12px 7px 0; border-bottom:2px solid var(--border); font-size:12.5px; letter-spacing:0.04em;">In the code</th></tr></thead><tbody><tr><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border); font-weight:600;"><code>Employee</code> in <em>italics</em></td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);"><code>public abstract class Employee</code></td></tr><tr><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border); font-weight:600;"><code>- name : String</code></td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);"><code>private String name;</code></td></tr><tr><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border); font-weight:600;"><code># salary : double</code></td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);"><code>protected double salary;</code></td></tr><tr><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border); font-weight:600;"><code>+ getSalary() : double</code></td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);"><code>public double getSalary()</code></td></tr><tr><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border); font-weight:600;"><code>+ area() : double</code> in italics</td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);"><code>public abstract double area();</code></td></tr><tr><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border); font-weight:600;">an <u>underlined</u> member</td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);"><code>static</code></td></tr><tr><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border); font-weight:600;">solid line, hollow triangle at <code>Employee</code></td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);"><code>class Manager extends Employee</code></td></tr><tr><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border); font-weight:600;">dashed line, hollow triangle at <code>Payable</code></td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);"><code>class Manager implements Payable</code></td></tr><tr><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border); font-weight:600;">filled diamond at <code>Car</code>, line to <code>Engine</code>, marked <code>1</code></td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);"><code>private Engine engine;</code> — one, owned</td></tr><tr><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border); font-weight:600;">hollow diamond at <code>Team</code>, line to <code>Player</code>, marked <code>*</code></td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);"><code>private List&lt;Player&gt; players;</code> — many, shared</td></tr></tbody></table></div><ol style="margin:8px 0 4px 18px; padding:0; line-height:1.65;"><li style="margin-bottom:5px;"><strong>Read the box top-down:</strong> name, then fields, then methods. The two horizontal lines are always in that order, and an empty compartment still gets drawn.</li><li style="margin-bottom:5px;"><strong>Read the symbol before every member</strong> — it is the access modifier, and it is the single most-tested detail in these questions. <code>-</code> is private, <code>+</code> public, <code>#</code> protected.</li><li style="margin-bottom:5px;"><strong>Type comes after the colon</strong>, which is the reverse of Java. <code>- name : String</code> becomes <code>String name</code>, never <code>name String</code>.</li><li style="margin-bottom:5px;"><strong>Italics mean abstract</strong>, for a class name and for a method alike. This is easy to miss in a printed exam and it changes the answer entirely.</li><li style="margin-bottom:5px;"><strong>Follow the arrow to decide extends vs implements:</strong> solid line for a class, dashed for an interface, hollow triangle either way.</li><li style="margin-bottom:5px;"><strong>A diamond means a field, not inheritance.</strong> Filled says the part is owned and dies with the whole; hollow says it is shared and can outlive it.</li></ol><p>Written out, the diagram above becomes:</p><pre style="background:var(--surface-2); border:1px solid var(--border); border-radius:8px; padding:11px 13px; overflow-x:auto; font-size:13px; line-height:1.55; margin:10px 0;"><code>public abstract class Employee {
    public static final String ID_PREFIX = "EMP-";
    private   String name;
    protected double salary;

    public    double getSalary() { return salary; }
    protected void   raise(double pct) { salary *= 1 + pct; }
    private   void   audit() { … }
}</code></pre></div><div class="callout" data-lb="key" style="border-left-color:#0ea5e9;"><div class="callout-label">▸ WORKED EXAMPLE — SPOTTING THE THREE MISTAKES IN A DRAWN DIAGRAM</div><p>A student draws a payroll model. Each of these is a real error with a specific consequence.</p><ol style="margin:8px 0 4px 18px; padding:0; line-height:1.65;"><li style="margin-bottom:5px;"><strong>The triangle points at <code>Manager</code>.</strong> A hollow triangle always sits at the <em>more general</em> end, so this diagram says "Employee extends Manager" — every Employee would be a Manager. The arrow direction is the most common diagram-reading error, in both directions: reading one and drawing one.</li><li style="margin-bottom:5px;"><strong><code>Payable</code> is joined with a solid line.</strong> A solid line plus a triangle means <code>extends</code>, so this claims <code>Payable</code> is a class. If <code>Payable</code> is an interface the line must be <strong>dashed</strong>, and the class would then be able to implement several of them.</li><li style="margin-bottom:5px;"><strong><code>Car</code> and <code>Engine</code> are joined with a triangle instead of a diamond.</strong> That turns a has-a into an is-a — the 10.9 error, drawn. It should be a filled diamond at the <code>Car</code> end, meaning <code>Car</code> holds an <code>Engine</code> field.</li></ol><p>The corrected reading, and the code it produces:</p><div style="overflow-x:auto; margin:14px 0;"><table style="border-collapse:collapse; width:100%; font-size:14.5px;"><thead><tr><th style="text-align:left; padding:7px 12px 7px 0; border-bottom:2px solid var(--border); font-size:12.5px; letter-spacing:0.04em;">Corrected notation</th><th style="text-align:left; padding:7px 12px 7px 0; border-bottom:2px solid var(--border); font-size:12.5px; letter-spacing:0.04em;">Meaning</th><th style="text-align:left; padding:7px 12px 7px 0; border-bottom:2px solid var(--border); font-size:12.5px; letter-spacing:0.04em;">Code</th></tr></thead><tbody><tr><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border); font-weight:600;">triangle at <code>Employee</code>, solid</td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);"><code>Manager</code> is more specific</td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);"><code>class Manager extends Employee</code></td></tr><tr><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border); font-weight:600;">triangle at <code>Payable</code>, dashed</td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);"><code>Payable</code> is an interface</td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);"><code>class Manager implements Payable</code></td></tr><tr><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border); font-weight:600;">filled diamond at <code>Car</code></td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);"><code>Car</code> owns an <code>Engine</code></td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);"><code>private Engine engine;</code></td></tr></tbody></table></div><p>A fourth detail worth checking on any diagram you are handed: <strong>multiplicity</strong>. A <code>1</code> at the far end of an association means one object; <code>*</code> means many, and in code that is a collection field rather than a single reference. <code>0..1</code> means the field may legitimately be <code>null</code>.</p></div><div class="callout" data-lb="key" style="border-left-color:#f59e0b;"><div class="callout-label">⚠️ COMMON MISTAKE</div><p><strong>Drawing the generalisation arrow from the parent down to the child.</strong> It goes the other way. The line starts at the subclass and the hollow triangle touches the superclass — the arrow points at the more general type, always. The same rule covers <code>implements</code>: the triangle sits at the interface.</p><p>How to notice it: read the picture as a sentence in the direction of the arrow. "Manager → Employee" reads "a Manager is an Employee", which is true. If the sentence comes out false, the arrow is backwards.</p><p>The other frequent mix-up is <strong>solid versus dashed</strong>. Solid + hollow triangle = <code>extends</code> a class; dashed + hollow triangle = <code>implements</code> an interface. Since a class can implement many interfaces but extend only one class, getting the line style wrong changes what the diagram claims is even legal.</p></div>"},"D286/u10/z10_11":{"body":"<p>An <strong>interface</strong> is a pure contract: a list of method signatures with no state and (traditionally) no bodies. A class can extend only one class but implement any number of interfaces, which is how Java gets the useful part of multiple inheritance without the ambiguity.</p><pre style="background:var(--bg-2, var(--surface-2)); padding:12px; border-radius:8px; font-size:13px; overflow-x:auto; line-height:1.55;">public interface Payable {
    double calculatePay();                 // implicitly public abstract
}

public interface Printable {
    void print();
}

public class Contractor implements Payable, Printable {
    public double calculatePay() { return hours * rate; }
    public void print() { System.out.println(name); }
}

Payable p = new Contractor();      // polymorphism through an interface
p.calculatePay();</pre><p>The choice between an abstract class and an interface comes down to whether there is shared <em>state</em>. Shared fields and partial implementation mean an abstract class; a capability that unrelated classes might have — comparable, printable, payable — means an interface.</p><pre style="background:var(--bg-2, var(--surface-2)); padding:12px; border-radius:8px; font-size:13px; overflow-x:auto; line-height:1.55;">public interface Payable {
    double pay();                          // implicitly public abstract
    double RATE = 15.0;                    // implicitly public static final

    default String label() { return "Payable"; }   // a body — optional to override
}

public class Contractor implements Payable, Comparable&lt;Contractor&gt; {
    public double pay() { ... }            // must be PUBLIC
}</pre><p>An interface is a contract: implement it and you promise to supply every abstract method. Missing one leaves the class abstract, and a concrete class then fails to compile.</p><p>Interface methods are implicitly <code>public</code>, so an implementation that writes them without <code>public</code> is <em>narrowing</em> visibility and will not compile — a very common slip.</p><p>Multiple interfaces are allowed because an interface carries no state, so there is nothing to inherit twice. A <code>default</code> method supplies a body so that adding a method to an interface does not break every existing implementer.</p><i data-d286u811="1" style="display:none"></i><div class="callout" data-lb="why" style="border-left-color:#4f46e5;"><div class="callout-label">📘 DEFINITION</div><p style="margin:0 0 7px;"><strong>Interface:</strong> a contract of method signatures a class promises to implement</p><p style="margin:0 0 7px;"><strong>implements:</strong> the keyword declaring that a class satisfies an interface</p><p style="margin:0 0 7px;"><strong>Multiple interfaces:</strong> a class may implement any number, unlike extends</p><p style="margin:0 0 7px;"><strong>default method:</strong> since Java 8, an interface method may have a body marked default</p></div><div class="callout" data-lb="oa" style="border-left-color:#e11d48;"><div class="callout-label">🎯 EXAM TIP</div><p><code>Comparable</code> (13.5) is the interface you will actually use. Implementing it means writing one <code>compareTo</code>, after which <code>Collections.sort</code> can sort your objects.</p></div><p data-xref="1" style="margin:26px 0 0; padding-top:12px; border-top:1px solid var(--border);font-size:12.5px; opacity:0.72;">✅ Also covered in depth: <strong>Inheritance → Abstract Classes and Interfaces</strong></p><i data-d286fx19="1" style="display:none"></i><div class="vl" data-mathvis="1" data-c959fig="1" style="margin-top:18px;"><div style="font-weight:700; font-size:12.5px; letter-spacing:0.05em; margin-bottom:6px;">📊 FIGURE — AN INTERFACE IS A CONTRACT</div><div style="border:1px solid var(--border); border-radius:12px; background:var(--surface-2); padding:14px 10px; overflow-x:auto;"><svg viewBox="0 0 490 218" style="width:100%; max-width:530px; display:block; margin:0 auto; font-family:inherit;" xmlns="http://www.w3.org/2000/svg"><defs><marker id="fk86a" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0,1 L9,5 L0,9 z" fill="var(--text)"/></marker></defs><rect x="150" y="14" width="190" height="52" rx="8" fill="none" stroke="var(--text)" stroke-width="1.4" stroke-dasharray="5 4"/><text x="245" y="34" fill="var(--text)" font-size="11.5" font-weight="700" text-anchor="middle" font-style="italic">«interface» Measurable</text><text x="245" y="52" fill="var(--text-3)" font-size="9.5" font-weight="400" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">double getArea();  // no body</text><rect x="50" y="120" width="150" height="50" rx="8" fill="none" stroke="var(--text)" stroke-width="1.4"/><text x="125" y="140" fill="var(--text)" font-size="11.5" font-weight="700" text-anchor="middle">Circle</text><text x="125" y="158" fill="var(--text)" font-size="9.5" font-weight="400" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">getArea() { πr² }</text><rect x="290" y="120" width="150" height="50" rx="8" fill="none" stroke="var(--text)" stroke-width="1.4"/><text x="365" y="140" fill="var(--text)" font-size="11.5" font-weight="700" text-anchor="middle">Rectangle</text><text x="365" y="158" fill="var(--text)" font-size="9.5" font-weight="400" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">getArea() { w×h }</text><line x1="125" y1="118" x2="210" y2="68" stroke="var(--text)" stroke-width="1.6" stroke-dasharray="5 4" marker-end="url(#fk86a)"/><line x1="365" y1="118" x2="280" y2="68" stroke="var(--text)" stroke-width="1.6" stroke-dasharray="5 4" marker-end="url(#fk86a)"/><text x="148" y="88" fill="var(--text-3)" font-size="9.5" font-weight="400" text-anchor="middle" font-style="italic">implements</text><text x="342" y="88" fill="var(--text-3)" font-size="9.5" font-weight="400" text-anchor="middle" font-style="italic">implements</text><text x="245" y="196" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-style="italic">An interface is a contract: every implementing class MUST provide every method. A class</text><text x="245" y="210" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-style="italic">extends ONE class but can implement MANY interfaces.</text></svg></div></div><i data-tbc1011="1" style="display:none"></i><div class="callout" data-lb="key" style="border-left-color:#0ea5e9;"><div class="callout-label">▸ WORKED EXAMPLE — IMPLEMENTING TWO INTERFACES AND EXTENDING A CLASS AT ONCE</div><p>The rule "one <code>extends</code>, many <code>implements</code>" is easiest to believe when you watch it work.</p><pre style="background:var(--surface-2); border:1px solid var(--border); border-radius:8px; padding:11px 13px; overflow-x:auto; font-size:13px; line-height:1.55; margin:10px 0;"><code>interface Payable {
    double RATE = 15.0;                                // public static final
    double pay();                                      // public abstract
    default String label() { return "Payable earning " + pay(); }
    static String unit() { return "USD"; }
}
interface Printable { void print(); }

static abstract class Person implements Payable {
    protected String name;
    Person(String n) { name = n; }
    public String toString() { return name; }
}
static class Contractor extends Person implements Printable {
    double hours;
    Contractor(String n, double h) { super(n); hours = h; }
    public double pay() { return hours * RATE; }
    public void print() { System.out.println("Contractor " + name); }
}
static class Volunteer extends Person {
    Volunteer(String n) { super(n); }
    public double pay() { return 0; }
    @Override public String label() { return "Volunteer, unpaid"; }
}

Contractor c = new Contractor("Bo", 20);
Volunteer  v = new Volunteer("Vi");
System.out.println(c.pay());
System.out.println(c.label());
System.out.println(v.label());
System.out.println(Payable.RATE + " " + Payable.unit());
System.out.println(c instanceof Payable);
System.out.println(c instanceof Printable);
System.out.println(v instanceof Printable);
Printable p = c;
p.print();</code></pre><ol style="margin:8px 0 4px 18px; padding:0; line-height:1.65;"><li style="margin-bottom:5px;"><code>Person implements Payable</code> but never writes <code>pay()</code>. Legal — because <code>Person</code> is <code>abstract</code>, so the obligation simply passes to its subclasses. A concrete class could not get away with it.</li><li style="margin-bottom:5px;"><code>Contractor</code> extends one class and implements one interface in the same declaration, and both obligations are checked: it must supply <code>pay()</code> (from <code>Payable</code>, via <code>Person</code>) and <code>print()</code> (from <code>Printable</code>).</li><li style="margin-bottom:5px;"><code>RATE</code> is used unqualified: interface constants are inherited by implementers. 20 × 15.0 = <strong>300.0</strong>.</li><li style="margin-bottom:5px;"><code>label()</code> is a <strong>default method</strong>. Contractor never declares it and gets the interface's body; Volunteer overrides it. Adding <code>label()</code> to <code>Payable</code> later therefore broke nothing — which is precisely what default methods are for.</li><li style="margin-bottom:5px;"><code>Payable.unit()</code> is a <strong>static</strong> interface method, called on the interface itself. It is <em>not</em> inherited by implementers — <code>c.unit()</code> would not compile.</li><li style="margin-bottom:5px;"><code>c instanceof Printable</code> is true, <code>v instanceof Printable</code> is false. The two share a superclass, but only one advertises this capability — which is exactly the distinction that makes interfaces worth having.</li><li style="margin-bottom:5px;"><code>Printable p = c;</code> — an interface is a reference type like any other, and calling <code>p.print()</code> dispatches to the Contractor's body.</li></ol><div style="margin:9px 0 4px;"><span style="font-size:11px; font-weight:700; letter-spacing:0.05em; color:var(--text-3);">OUTPUT</span></div><pre style="background:var(--surface-3, var(--surface-2)); border-left:3px solid var(--accent); border-radius:0 8px 8px 0; padding:9px 13px; overflow-x:auto; font-size:13px; line-height:1.5; margin:0 0 10px;"><code>300.0
Payable earning 300.0
Volunteer, unpaid
15.0 USD
true
true
false
Contractor Bo</code></pre></div><div class="callout" data-lb="key" style="border-left-color:#0ea5e9;"><div class="callout-label">▸ WORKED EXAMPLE — WHAT AN INTERFACE ACTUALLY ENFORCES</div><p>An interface is a promise the compiler checks. Here is each promise, broken, with the message it produces.</p><pre style="background:var(--surface-2); border:1px solid var(--border); border-radius:8px; padding:11px 13px; overflow-x:auto; font-size:13px; line-height:1.55; margin:10px 0;"><code>interface Payable { double pay(); }

class Contractor implements Payable {
    // pay() not written
}</code></pre><div style="margin:9px 0 4px;"><span style="font-size:11px; font-weight:700; letter-spacing:0.05em; color:var(--text-3);">OUTPUT</span></div><pre style="background:var(--surface-3, var(--surface-2)); border-left:3px solid var(--accent); border-radius:0 8px 8px 0; padding:9px 13px; overflow-x:auto; font-size:13px; line-height:1.5; margin:0 0 10px;"><code>error: Contractor is not abstract and does not override abstract method pay() in Payable</code></pre><p>The identical wording to the abstract-class error in 10.7 — because it is the identical rule. Implement it, or declare the class <code>abstract</code>.</p><pre style="background:var(--surface-2); border:1px solid var(--border); border-radius:8px; padding:11px 13px; overflow-x:auto; font-size:13px; line-height:1.55; margin:10px 0;"><code>class Contractor implements Payable {
    double pay() { return 0; }        // no "public"
}</code></pre><div style="margin:9px 0 4px;"><span style="font-size:11px; font-weight:700; letter-spacing:0.05em; color:var(--text-3);">OUTPUT</span></div><pre style="background:var(--surface-3, var(--surface-2)); border-left:3px solid var(--accent); border-radius:0 8px 8px 0; padding:9px 13px; overflow-x:auto; font-size:13px; line-height:1.5; margin:0 0 10px;"><code>error: pay() in Contractor cannot implement pay() in Payable
  attempting to assign weaker access privileges; was public</code></pre><p>Interface methods are implicitly <code>public</code>; leaving the keyword off is narrowing, and narrowing is never allowed on an override.</p><pre style="background:var(--surface-2); border:1px solid var(--border); border-radius:8px; padding:11px 13px; overflow-x:auto; font-size:13px; line-height:1.55; margin:10px 0;"><code>interface Payable { double RATE = 15.0; }

class Contractor implements Payable {
    void bump() { RATE = 20.0; }
}</code></pre><div style="margin:9px 0 4px;"><span style="font-size:11px; font-weight:700; letter-spacing:0.05em; color:var(--text-3);">OUTPUT</span></div><pre style="background:var(--surface-3, var(--surface-2)); border-left:3px solid var(--accent); border-radius:0 8px 8px 0; padding:9px 13px; overflow-x:auto; font-size:13px; line-height:1.5; margin:0 0 10px;"><code>error: cannot assign a value to final variable RATE</code></pre><ol style="margin:8px 0 4px 18px; padding:0; line-height:1.65;"><li style="margin-bottom:5px;">An interface field is implicitly <code>public static final</code> — a constant, shared, and unassignable. There is no way to declare an interface instance field.</li><li style="margin-bottom:5px;">These three messages cover almost every interface compile error you will meet: <em>does not override</em>, <em>weaker access privileges</em>, and <em>cannot assign a value to final variable</em>.</li><li style="margin-bottom:5px;">Notice what an interface does <strong>not</strong> enforce: nothing about how <code>pay()</code> is calculated, nothing about fields, nothing about constructors. It is a signature list, so implementers are free to be as unrelated as they like — which is the entire source of its usefulness.</li></ol><p>And the one rule that makes multiple interfaces safe: <strong>an interface carries no instance state</strong>, so there is nothing to inherit twice. That is why <code>class A implements B, C, D</code> is fine while <code>class A extends B, C</code> is not.</p></div><div class="callout" data-lb="key" style="border-left-color:#f59e0b;"><div class="callout-label">⚠️ COMMON MISTAKE</div><p><strong>Writing <code>implements</code> where a bound needs <code>extends</code>, and vice versa.</strong> Two different contexts use opposite keywords for the same idea:</p><p>• In a <em>class declaration</em>: <code>class Contractor extends Person implements Payable</code>. Class with <code>extends</code>, interface with <code>implements</code>.<br>• In a <em>generic bound</em> (13.2): <code>&lt;T extends Comparable&lt;T&gt;&gt;</code> — <code>extends</code>, even though <code>Comparable</code> is an interface. <code>&lt;T implements Comparable&gt;</code> does not compile.<br>• Between interfaces: <code>interface Manager extends Payable, Printable</code> — an interface <em>extends</em> other interfaces, and may extend several.</p><p>How to notice it: the compiler error for the class-declaration case is blunt — <em>interface expected here</em> or <em>no interface expected here</em> — and points straight at the keyword. The generic-bound case is the one worth memorising in advance, because there <code>extends</code> simply means "is or is below", covering classes and interfaces alike.</p></div>"},"D286/u10/z10_12":{"body":"<p>The employee example demonstrates overriding across a hierarchy, with each subclass computing pay its own way.</p><pre style="background:var(--bg-2, var(--surface-2)); padding:12px; border-radius:8px; font-size:13px; overflow-x:auto; line-height:1.55;">public class Employee {
    protected String name;
    protected double baseSalary;
    public Employee(String n, double s) { name = n; baseSalary = s; }

    public double pay() { return baseSalary; }

    @Override
    public String toString() { return name + ": " + pay(); }
}

public class Manager extends Employee {
    private double bonus;
    public Manager(String n, double s, double b) { super(n, s); bonus = b; }

    @Override
    public double pay() { return super.pay() + bonus; }
}

for (Employee e : staff) { System.out.println(e); }   // toString called implicitly</pre><p>Two mechanisms are quietly cooperating in the last line. <code>println</code> calls <code>toString()</code>, which is defined only in <code>Employee</code> — and inside it, <code>pay()</code> dispatches to the subclass version. The parent’s code calls the child’s method, which is the whole point of 10.5.</p><pre style="background:var(--bg-2, var(--surface-2)); padding:12px; border-radius:8px; font-size:13px; overflow-x:auto; line-height:1.55;">class Employee {
    public double pay() { return 40 * rate; }
    public String toString() { return name + ": " + pay(); }
}
class Manager extends Employee {
    @Override public double pay() { return super.pay() + bonus; }
}

for (Employee e : staff) System.out.println(e);   // each prints ITS OWN pay</pre><p><code>super.pay()</code> reaches the version this method is replacing — the way to extend behaviour rather than restate it. Without <code>super.</code>, calling <code>pay()</code> inside the override calls itself and recurses until the stack overflows.</p><p>Notice that the inherited <code>toString()</code> calls <code>pay()</code> and gets the <em>Manager</em> version for a Manager, even though <code>toString</code> was written in <code>Employee</code> and knows nothing about managers. That is dynamic dispatch doing the work, and it is the point the example exists to make.</p><i data-d286u811="1" style="display:none"></i><div class="callout" data-lb="why" style="border-left-color:#4f46e5;"><div class="callout-label">📘 DEFINITION</div><p style="margin:0 0 7px;"><strong>super.pay():</strong> reusing the parent implementation inside the override rather than duplicating it</p><p style="margin:0 0 7px;"><strong>Inherited toString:</strong> defined once in the parent, correct for every subclass through dispatch</p></div><div class="callout" data-lb="key" style="border-left-color:#22c55e;"><div class="callout-label">💡 WHY IT MATTERS</div><p>Adding a <code>Contractor</code> subclass tomorrow requires no change to <code>toString</code>, to the loop, or to anything else. That is what a hierarchy buys you.</p></div><i data-tbc1012="1" style="display:none"></i><div class="vl" data-mathvis="1" data-c959fig="1" style="margin-top:18px;"><div style="font-weight:700; font-size:12.5px; letter-spacing:0.05em; margin-bottom:6px;">📊 FIGURE — THE PARENT'S toString CALLS THE CHILD'S pay</div><div style="border:1px solid var(--border); border-radius:12px; background:var(--surface-2); padding:14px 10px; overflow-x:auto;"><svg viewBox="0 0 820 380" style="width:100%; max-width:760px; display:block; margin:0 auto; font-family:inherit;" xmlns="http://www.w3.org/2000/svg"><defs><marker id="fk266a" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0,1 L9,5 L0,9 z" fill="var(--text)"/></marker></defs><rect x="40" y="44" width="250" height="34" rx="7" fill="var(--accent-bg)" stroke="var(--accent)" stroke-width="1.5"/><text x="165" y="65.5" fill="var(--text)" font-size="12" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">System.out.println(e);</text><line x1="165" y1="78" x2="165" y2="100" stroke="var(--text)" stroke-width="1.6" marker-end="url(#fk266a)"/><rect x="40" y="100" width="250" height="44" rx="7" fill="var(--surface)" stroke="var(--text)" stroke-width="1.5"/><text x="165" y="119" fill="var(--text)" font-size="12" font-weight="700" text-anchor="middle">Employee.toString()</text><text x="165" y="135" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle">written once, knows nothing of Manager</text><text x="165" y="168" fill="var(--text)" font-size="11" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">name + ": " + pay()</text><line x1="290" y1="122" x2="356" y2="122" stroke="var(--text)" stroke-width="1.6" marker-end="url(#fk266a)"/><text x="323" y="112" fill="var(--accent)" font-size="10" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">pay()</text><rect x="360" y="100" width="210" height="44" rx="7" fill="var(--accent-bg)" stroke="var(--accent)" stroke-width="2.2"/><text x="465" y="119" fill="var(--text)" font-size="12" font-weight="700" text-anchor="middle">the OBJECT decides</text><text x="465" y="135" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle">dynamic dispatch</text><line x1="570" y1="112" x2="618" y2="78" stroke="var(--text)" stroke-width="1.6" marker-end="url(#fk266a)"/><line x1="570" y1="122" x2="618" y2="122" stroke="var(--text)" stroke-width="1.6" marker-end="url(#fk266a)"/><line x1="570" y1="132" x2="618" y2="166" stroke="var(--text)" stroke-width="1.6" marker-end="url(#fk266a)"/><rect x="622" y="60" width="174" height="36" rx="7" fill="var(--surface)" stroke="var(--text)" stroke-width="1.5"/><text x="709" y="75" fill="var(--text)" font-size="10.5" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">Employee.pay()</text><text x="709" y="91" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle">40 * rate</text><rect x="622" y="104" width="174" height="36" rx="7" fill="var(--accent-bg)" stroke="var(--accent)" stroke-width="1.5"/><text x="709" y="119" fill="var(--text)" font-size="10.5" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">Manager.pay()</text><text x="709" y="135" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle">super.pay() + bonus</text><rect x="622" y="148" width="174" height="36" rx="7" fill="var(--surface)" stroke="var(--text)" stroke-width="1.5"/><text x="709" y="163" fill="var(--text)" font-size="10.5" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">Contractor.pay()</text><text x="709" y="179" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle">hours * rate</text><line x1="30" y1="208" x2="790" y2="208" stroke="var(--border)" stroke-width="1"/><text x="410" y="234" fill="var(--accent)" font-size="11.5" font-weight="700" text-anchor="middle">super.pay() REACHES THE VERSION BEING REPLACED — WITHOUT IT, IT CALLS ITSELF</text><rect x="70" y="252" width="300" height="44" rx="7" fill="var(--accent-bg)" stroke="var(--accent)" stroke-width="1.5"/><text x="220" y="271" fill="var(--text)" font-size="11" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">return super.pay() + bonus;</text><text x="220" y="287" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle">runs Employee's body, then adds</text><rect x="450" y="252" width="300" height="44" rx="7" fill="var(--surface)" stroke="var(--text-3)" stroke-width="1.5" stroke-dasharray="5 4"/><text x="600" y="271" fill="var(--text-3)" font-size="11" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">return pay() + bonus;</text><text x="600" y="287" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle">calls ITSELF → StackOverflowError</text><path d="M417,296 C402,268 446,268 431,296" fill="none" stroke="var(--text)" stroke-width="1.6" marker-end="url(#fk266a)"/><text x="410" y="340" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-style="italic">one printed line, three different pay formulas, and toString never mentions a subclass</text><text x="410" y="358" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-style="italic">adding a fourth Employee type changes nothing here</text></svg></div></div><div class="callout" data-lb="key" style="border-left-color:#0ea5e9;"><div class="callout-label">▸ WORKED EXAMPLE — THE WHOLE HIERARCHY, PRINTED BY ONE LOOP</div><p>Three pay formulas, one <code>toString</code>, one loop. Watch which class each printed number came from.</p><pre style="background:var(--surface-2); border:1px solid var(--border); border-radius:8px; padding:11px 13px; overflow-x:auto; font-size:13px; line-height:1.55; margin:10px 0;"><code>static class Employee {
    protected String name;
    protected double rate;
    Employee(String n, double r) { name = n; rate = r; }
    double pay() { return 40 * rate; }
    @Override public String toString() {
        return String.format("%-9s %8.2f", name, pay());
    }
}
static class Manager extends Employee {
    private double bonus;
    Manager(String n, double r, double b) { super(n, r); bonus = b; }
    @Override double pay() { return super.pay() + bonus; }
}
static class Contractor extends Employee {
    private double hours;
    Contractor(String n, double r, double h) { super(n, r); hours = h; }
    @Override double pay() { return hours * rate; }
}

ArrayList&lt;Employee&gt; staff = new ArrayList&lt;&gt;();
staff.add(new Employee("Ana", 22.50));
staff.add(new Manager("Ben", 30.00, 500));
staff.add(new Contractor("Cy", 45.00, 12));
double total = 0;
for (Employee e : staff) { System.out.println(e); total += e.pay(); }
System.out.printf("%-9s %8.2f%n", "TOTAL", total);</code></pre><ol style="margin:8px 0 4px 18px; padding:0; line-height:1.65;"><li style="margin-bottom:5px;"><strong>Ana</strong> is a plain Employee: 40 × 22.50 = <strong>900.00</strong>.</li><li style="margin-bottom:5px;"><strong>Ben</strong> is a Manager. <code>super.pay()</code> runs <em>Employee's</em> body — 40 × 30.00 = 1200 — and the override adds the 500 bonus: <strong>1700.00</strong>.</li><li style="margin-bottom:5px;"><strong>Cy</strong> is a Contractor and ignores the 40-hour assumption entirely: 12 × 45.00 = <strong>540.00</strong>.</li><li style="margin-bottom:5px;"><code>System.out.println(e)</code> never calls <code>toString()</code> by name — <code>println</code> does it for you, and String concatenation would too.</li><li style="margin-bottom:5px;">The <code>toString()</code> being run is <strong>Employee's</strong>, in every case. It was written before Manager and Contractor existed and mentions neither. Its call to <code>pay()</code> dispatches to whichever subclass the object actually is.</li><li style="margin-bottom:5px;">The loop body accumulates the same dispatched values: 900 + 1700 + 540 = <strong>3140.00</strong>.</li><li style="margin-bottom:5px;"><code>%-9s %8.2f</code> is what lines the columns up — names left-aligned in nine characters, money right-aligned in eight with two decimals (9.2).</li></ol><div style="margin:9px 0 4px;"><span style="font-size:11px; font-weight:700; letter-spacing:0.05em; color:var(--text-3);">OUTPUT</span></div><pre style="background:var(--surface-3, var(--surface-2)); border-left:3px solid var(--accent); border-radius:0 8px 8px 0; padding:9px 13px; overflow-x:auto; font-size:13px; line-height:1.5; margin:0 0 10px;"><code>Ana         900.00
Ben        1700.00
Cy          540.00
TOTAL      3140.00</code></pre><p>A parent method calling a child method it has never heard of is the single most useful consequence of inheritance, and this output is the proof it happens.</p></div><div class="callout" data-lb="key" style="border-left-color:#0ea5e9;"><div class="callout-label">▸ WORKED EXAMPLE — WHAT super. IS FOR, AND WHAT HAPPENS WITHOUT IT</div><p><code>Manager.pay()</code> needs the base salary <em>and</em> the bonus. There are three ways to write it and only one is right.</p><div style="overflow-x:auto; margin:14px 0;"><table style="border-collapse:collapse; width:100%; font-size:14.5px;"><thead><tr><th style="text-align:left; padding:7px 12px 7px 0; border-bottom:2px solid var(--border); font-size:12.5px; letter-spacing:0.04em;">Version</th><th style="text-align:left; padding:7px 12px 7px 0; border-bottom:2px solid var(--border); font-size:12.5px; letter-spacing:0.04em;">Result</th><th style="text-align:left; padding:7px 12px 7px 0; border-bottom:2px solid var(--border); font-size:12.5px; letter-spacing:0.04em;">Verdict</th></tr></thead><tbody><tr><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border); font-weight:600;"><code>return super.pay() + bonus;</code></td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);">1700.00</td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);"><strong>correct</strong> — reuses the base formula</td></tr><tr><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border); font-weight:600;"><code>return 40 * rate + bonus;</code></td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);">1700.00 <em>today</em></td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);">duplicates the formula. Change the base to a 37-hour week and this silently keeps paying 40.</td></tr><tr><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border); font-weight:600;"><code>return pay() + bonus;</code></td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);"><code>StackOverflowError</code></td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);">calls itself — the unqualified name resolves to the override it is inside</td></tr></tbody></table></div><ol style="margin:8px 0 4px 18px; padding:0; line-height:1.65;"><li style="margin-bottom:5px;"><code>super.pay()</code> is the <strong>only</strong> syntax that reaches a method you are replacing. It is not "the parent object" — there is one object — it is an instruction to start the method lookup one level up.</li><li style="margin-bottom:5px;">The second version compiles and produces the right number, so tests pass. It is still wrong: the base formula now exists in two places, and the day it changes only one of them will be updated.</li><li style="margin-bottom:5px;">The third version is the classic accident. Inside <code>Manager.pay()</code>, a bare <code>pay()</code> means <code>this.pay()</code>, which dispatches straight back to <code>Manager.pay()</code>. Each call pushes a stack frame, nothing ever returns, and the stack is exhausted in milliseconds (11.8).</li><li style="margin-bottom:5px;"><code>super.</code> only reaches <strong>one</strong> level up, and only from inside the subclass. <code>super.super.pay()</code> is not valid Java, and <code>super</code> cannot be used from a static method — there is no <code>this</code> for it to work from.</li></ol><p>The same reasoning applies to <code>toString</code>. If <code>Manager</code> wanted extra detail, the right override is:</p><pre style="background:var(--surface-2); border:1px solid var(--border); border-radius:8px; padding:11px 13px; overflow-x:auto; font-size:13px; line-height:1.55; margin:10px 0;"><code>@Override public String toString() {
    return super.toString() + "  (bonus " + bonus + ")";
}</code></pre><p>which reuses the parent's formatting rather than restating the <code>%-9s %8.2f</code> layout in a second place.</p></div><div class="callout" data-lb="key" style="border-left-color:#f59e0b;"><div class="callout-label">⚠️ COMMON MISTAKE</div><p><strong>Calling the overriding method from inside itself.</strong> Writing <code>pay()</code> instead of <code>super.pay()</code> inside <code>Manager.pay()</code> compiles perfectly — a method calling another method of the same object is ordinary Java — and then recurses infinitely, ending in <code>StackOverflowError</code> the first time the line runs.</p><p>How to notice it: the stack trace is hundreds of identical lines naming the same method and the same line number. If you see one method repeating, look for a missing <code>super.</code> before deciding you have a recursion bug.</p><p>The mirror-image mistake is <strong>using <code>super.</code> when you meant <code>this</code></strong>. Writing <code>super.pay()</code> in a method that is <em>not</em> an override skips the polymorphic call deliberately, which is almost never what you want — it hard-wires the base version and defeats the dispatch that makes the hierarchy useful.</p></div><div class="callout" data-lb="key" style="border-left-color:#e11d48;"><div class="callout-label">🎯 EXAM TIP</div><p><strong>For "what does this hierarchy print?" questions, work object by object, not line by line.</strong> For each element: what is its actual class, does that class override the method, and does the override call <code>super</code>? Compute the base value first, then apply the override.</p><p>The reliable traps in this exact style of question:</p><p>① a <code>toString()</code> defined only in the parent that calls an overridden method — the parent's <em>text layout</em> with the child's <em>numbers</em>;<br>② <code>super.pay() + bonus</code> versus a restated formula — both give the same number, so the question has to be about design rather than output;<br>③ <code>println(obj)</code> with no <code>toString()</code> anywhere — the answer is <code>ClassName@hexhash</code>, not a compile error.</p><p>And when a question asks <em>why</em> the design is good, the answer is almost always the same sentence: adding another subclass requires no change to the loop, to <code>toString</code>, or to any existing code.</p></div>"},"D286/u10/z10_13":{"body":"<p>The final example is the one people get wrong under exam conditions: you cannot instantiate an abstract class, but you constantly declare variables of its type.</p><pre style="background:var(--bg-2, var(--surface-2)); padding:12px; border-radius:8px; font-size:13px; overflow-x:auto; line-height:1.55;">Shape s = new Shape("x");         // ERROR — abstract
Shape s = new Circle(2);          // FINE  — the variable type is Shape,
                                  //        the OBJECT is a Circle

Shape[] shapes = new Shape[3];    // FINE  — an array of Shape REFERENCES,
                                  //        all null, no Shape created
shapes[0] = new Circle(2);
shapes[1] = new Rectangle(3, 4);

for (Shape sh : shapes) {
    if (sh != null) { System.out.println(sh.area()); }   // null check matters
}</pre><p><code>new Shape[3]</code> creates no <code>Shape</code> objects at all — it creates three null references (5.2). That is why it is legal for an abstract type, and why the null check in the loop is not optional.</p><pre style="background:var(--bg-2, var(--surface-2)); padding:12px; border-radius:8px; font-size:13px; overflow-x:auto; line-height:1.55;">Shape[] shapes = { new Circle(2), new Rect(3, 4) };   // a Shape[] of subclasses
for (Shape s : shapes)
    System.out.printf("%s: %.2f%n", s.getName(), s.area());</pre><p>You cannot instantiate <code>Shape</code>, but you can declare an array of it — the reference type is abstract while every object in it is concrete. That combination is what makes an abstract class useful: it guarantees every element answers <code>area()</code> without needing to know which shape it is.</p><p>The subclass supplies the missing method and passes shared data up with <code>super(name)</code>. Adding a new shape needs no change to this loop at all, which is the practical payoff and the usual exam framing.</p><i data-d286u811="1" style="display:none"></i><div class="callout" data-lb="why" style="border-left-color:#4f46e5;"><div class="callout-label">📘 DEFINITION</div><p style="margin:0 0 7px;"><strong>Declared type vs actual type:</strong> the variable’s type limits what you may call; the object decides what runs</p><p style="margin:0 0 7px;"><strong>Array of abstract type:</strong> an array of references, initially null; no instances are created</p><p style="margin:0 0 7px;"><strong>Abstract instantiation error:</strong> the compile error from calling new on an abstract class</p></div><div class="callout" data-lb="warn" style="border-left-color:#f59e0b;"><div class="callout-label">⚠ COMMON MISTAKE</div><p>"Shape is abstract; cannot be instantiated" always points at a <code>new</code> on the abstract type. The fix is to instantiate a concrete subclass — the variable can stay declared as the abstract type.</p></div><i data-tbc1013="1" style="display:none"></i><div class="vl" data-mathvis="1" data-c959fig="1" style="margin-top:18px;"><div style="font-weight:700; font-size:12.5px; letter-spacing:0.05em; margin-bottom:6px;">📊 FIGURE — AN ARRAY OF AN ABSTRACT TYPE IS AN ARRAY OF REFERENCES</div><div style="border:1px solid var(--border); border-radius:12px; background:var(--surface-2); padding:14px 10px; overflow-x:auto;"><svg viewBox="0 0 820 370" style="width:100%; max-width:760px; display:block; margin:0 auto; font-family:inherit;" xmlns="http://www.w3.org/2000/svg"><defs><marker id="fk267a" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0,1 L9,5 L0,9 z" fill="var(--text)"/></marker></defs><text x="200" y="24" fill="var(--accent)" font-size="11.5" font-weight="700" text-anchor="middle">new Shape[3]</text><rect x="40" y="44" width="320" height="90" rx="8" fill="none" stroke="var(--border)" stroke-width="1.2"/><rect x="60" y="66" width="90" height="48" rx="5" fill="none" stroke="var(--text-3)" stroke-width="1.4" stroke-dasharray="4 3"/><text x="105" y="95" fill="var(--text-3)" font-size="11.5" font-weight="400" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">null</text><rect x="160" y="66" width="90" height="48" rx="5" fill="none" stroke="var(--text-3)" stroke-width="1.4" stroke-dasharray="4 3"/><text x="205" y="95" fill="var(--text-3)" font-size="11.5" font-weight="400" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">null</text><rect x="260" y="66" width="90" height="48" rx="5" fill="none" stroke="var(--text-3)" stroke-width="1.4" stroke-dasharray="4 3"/><text x="305" y="95" fill="var(--text-3)" font-size="11.5" font-weight="400" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">null</text><text x="105" y="128" fill="var(--text-3)" font-size="9" font-weight="400" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">[0]</text><text x="205" y="128" fill="var(--text-3)" font-size="9" font-weight="400" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">[1]</text><text x="305" y="128" fill="var(--text-3)" font-size="9" font-weight="400" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">[2]</text><text x="200" y="156" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-style="italic">ZERO Shape objects created — which is why it is legal</text><text x="200" y="172" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-style="italic">for an abstract type</text><line x1="370" y1="90" x2="424" y2="90" stroke="var(--text)" stroke-width="1.6" marker-end="url(#fk267a)"/><text x="397" y="80" fill="var(--text-3)" font-size="9.5" font-weight="400" text-anchor="middle">assign</text><text x="608" y="24" fill="var(--accent)" font-size="11.5" font-weight="700" text-anchor="middle">after shapes[0] = new Circle(2);</text><rect x="430" y="44" width="360" height="90" rx="8" fill="none" stroke="var(--border)" stroke-width="1.2"/><rect x="450" y="66" width="90" height="48" rx="5" fill="var(--accent-bg)" stroke="var(--accent)" stroke-width="1.6"/><text x="495" y="95" fill="var(--accent)" font-size="11" font-weight="700" text-anchor="middle">Circle</text><rect x="550" y="66" width="90" height="48" rx="5" fill="var(--accent-bg)" stroke="var(--accent)" stroke-width="1.6"/><text x="595" y="95" fill="var(--accent)" font-size="11" font-weight="700" text-anchor="middle">Rect</text><rect x="650" y="66" width="90" height="48" rx="5" fill="none" stroke="var(--text-3)" stroke-width="1.4" stroke-dasharray="4 3"/><text x="695" y="95" fill="var(--text-3)" font-size="11.5" font-weight="400" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">null</text><text x="608" y="156" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-style="italic">the DECLARED element type is abstract; every OBJECT in it is concrete</text><text x="608" y="172" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-style="italic">and slot 2 is still null — the loop must check</text><line x1="30" y1="198" x2="790" y2="198" stroke="var(--border)" stroke-width="1"/><text x="410" y="224" fill="var(--accent)" font-size="11.5" font-weight="700" text-anchor="middle">THE ONE LINE THAT DOES NOT COMPILE</text><rect x="70" y="242" width="300" height="40" rx="7" fill="var(--accent-bg)" stroke="var(--accent)" stroke-width="1.5"/><text x="220" y="259" fill="var(--text)" font-size="11.5" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">Shape s = new Circle(2);</text><text x="220" y="275" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle">variable abstract, object concrete — FINE</text><text x="462" y="270" fill="var(--text-3)" font-size="24" font-weight="700" text-anchor="middle">✗</text><rect x="484" y="242" width="290" height="40" rx="7" fill="var(--surface)" stroke="var(--text-3)" stroke-width="1.5" stroke-dasharray="5 4"/><text x="629" y="259" fill="var(--text-3)" font-size="11.5" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">Shape s = new Shape("x");</text><text x="629" y="275" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle">error: Shape is abstract; cannot be instantiated</text><text x="410" y="320" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-style="italic">the fix is never to remove abstract — it is to instantiate a concrete subclass</text><text x="410" y="338" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-style="italic">and leave the variable typed as the abstract class</text></svg></div></div><div class="callout" data-lb="key" style="border-left-color:#0ea5e9;"><div class="callout-label">▸ WORKED EXAMPLE — THREE NULL SLOTS, THEN TWO REAL SHAPES</div><p><code>new Shape[3]</code> is legal for an abstract type, and the reason is visible in the very first printed value.</p><pre style="background:var(--surface-2); border:1px solid var(--border); border-radius:8px; padding:11px 13px; overflow-x:auto; font-size:13px; line-height:1.55; margin:10px 0;"><code>static abstract class Shape {
    private String name;
    Shape(String n) { name = n; }
    String getName() { return name; }
    abstract double area();
}
static class Circle extends Shape {
    double r;
    Circle(double r) { super("Circle"); this.r = r; }
    @Override double area() { return Math.PI * r * r; }
}
static class Rect extends Shape {
    double w, h;
    Rect(double w, double h) { super("Rect"); this.w = w; this.h = h; }
    @Override double area() { return w * h; }
}

Shape[] shapes = new Shape[3];
System.out.println("length " + shapes.length + ", slot 0 = " + shapes[0]);
shapes[0] = new Circle(2);
shapes[1] = new Rect(3, 4);
for (Shape s : shapes) {
    if (s != null) System.out.printf("%s: %.2f%n", s.getName(), s.area());
    else System.out.println("(empty slot)");
}
try {
    System.out.println(shapes[2].area());
} catch (NullPointerException e) {
    System.out.println("caught " + e.getClass().getSimpleName());
}
Shape[] filled = { new Circle(1), new Rect(2, 5) };
double t = 0;
for (Shape s : filled) t += s.area();
System.out.printf("total %.4f%n", t);</code></pre><ol style="margin:8px 0 4px 18px; padding:0; line-height:1.65;"><li style="margin-bottom:5px;"><code>slot 0 = null</code> is the whole explanation. <code>new Shape[3]</code> allocates three <strong>reference slots</strong>, all null. Not one Shape was constructed, so the "cannot instantiate an abstract class" rule was never even approached.</li><li style="margin-bottom:5px;">Assigning <code>new Circle(2)</code> and <code>new Rect(3, 4)</code> fills two of them. The array is declared to hold <code>Shape</code> references; a <code>Circle</code> reference is a <code>Shape</code> reference, so it fits.</li><li style="margin-bottom:5px;">The loop calls <code>getName()</code> — a concrete inherited method — and <code>area()</code> — an abstract one, dispatched to the subclass. π × 2² = <strong>12.57</strong>, 3 × 4 = <strong>12.00</strong>.</li><li style="margin-bottom:5px;">The third slot is still <code>null</code>, so the guard prints <code>(empty slot)</code>. That check is not optional housekeeping: it is the direct consequence of the array being references.</li><li style="margin-bottom:5px;">Removing the guard proves it — <code>shapes[2].area()</code> throws <code>NullPointerException</code>. This is the single most common bug when arrays of objects are filled partially.</li><li style="margin-bottom:5px;">The array initialiser form <code>{ new Circle(1), new Rect(2, 5) }</code> avoids the problem entirely by creating and filling in one step: π + 10 = <strong>13.1416</strong>.</li></ol><div style="margin:9px 0 4px;"><span style="font-size:11px; font-weight:700; letter-spacing:0.05em; color:var(--text-3);">OUTPUT</span></div><pre style="background:var(--surface-3, var(--surface-2)); border-left:3px solid var(--accent); border-radius:0 8px 8px 0; padding:9px 13px; overflow-x:auto; font-size:13px; line-height:1.5; margin:0 0 10px;"><code>length 3, slot 0 = null
Circle: 12.57
Rect: 12.00
(empty slot)
caught NullPointerException
total 13.1416</code></pre></div><div class="callout" data-lb="key" style="border-left-color:#0ea5e9;"><div class="callout-label">▸ WORKED EXAMPLE — WHERE THE ABSTRACT TYPE IS ALLOWED AND WHERE IT IS NOT</div><p>Every use of <code>Shape</code> below is legal except one. The dividing line is simple: <strong>anything that names a type is fine; only <code>new Shape(...)</code> is refused.</strong></p><div style="overflow-x:auto; margin:14px 0;"><table style="border-collapse:collapse; width:100%; font-size:14.5px;"><thead><tr><th style="text-align:left; padding:7px 12px 7px 0; border-bottom:2px solid var(--border); font-size:12.5px; letter-spacing:0.04em;">Code</th><th style="text-align:left; padding:7px 12px 7px 0; border-bottom:2px solid var(--border); font-size:12.5px; letter-spacing:0.04em;">Legal?</th><th style="text-align:left; padding:7px 12px 7px 0; border-bottom:2px solid var(--border); font-size:12.5px; letter-spacing:0.04em;">Why</th></tr></thead><tbody><tr><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border); font-weight:600;"><code>Shape s;</code></td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);"><strong>yes</strong></td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);">declaring a variable creates no object</td></tr><tr><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border); font-weight:600;"><code>Shape s = new Circle(2);</code></td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);"><strong>yes</strong></td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);">the variable type is abstract, the object is concrete</td></tr><tr><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border); font-weight:600;"><code>Shape[] a = new Shape[3];</code></td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);"><strong>yes</strong></td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);">three null references, no Shapes</td></tr><tr><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border); font-weight:600;"><code>ArrayList&lt;Shape&gt; list</code></td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);"><strong>yes</strong></td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);">the element <em>type</em> is abstract; the elements are not</td></tr><tr><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border); font-weight:600;"><code>void draw(Shape s)</code></td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);"><strong>yes</strong></td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);">a parameter is a variable</td></tr><tr><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border); font-weight:600;"><code>Shape make() { … }</code></td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);"><strong>yes</strong></td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);">the return type is a promise about what comes back</td></tr><tr><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border); font-weight:600;"><code>new Shape("x")</code></td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);"><strong>NO</strong></td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);"><code>error: Shape is abstract; cannot be instantiated</code></td></tr></tbody></table></div><ol style="margin:8px 0 4px 18px; padding:0; line-height:1.65;"><li style="margin-bottom:5px;">Read down the table and notice that six of the seven rows are the abstract class being <em>useful</em>. Its whole purpose is to be a type — the guarantee that whatever arrives can answer <code>area()</code>.</li><li style="margin-bottom:5px;"><code>void draw(Shape s)</code> is the payoff. One method accepts every present and future shape, and calls <code>area()</code> on all of them without knowing a single subclass name.</li><li style="margin-bottom:5px;"><code>Shape make()</code> is the other half — a method that decides <em>which</em> shape to build and returns it as a <code>Shape</code>, so the caller does not have to know either.</li><li style="margin-bottom:5px;">The single illegal row is illegal for a concrete reason: <code>Shape</code> has no <code>area()</code> body, so a plain Shape object would be an object with a hole in it. The compiler refuses to create one rather than letting it fail later.</li></ol><p>The mirror-image case is worth stating too. Once the object is a <code>Circle</code>, calling something <code>Circle</code> adds needs a cast, because the <em>variable</em> is still a <code>Shape</code>:</p><pre style="background:var(--surface-2); border:1px solid var(--border); border-radius:8px; padding:11px 13px; overflow-x:auto; font-size:13px; line-height:1.55; margin:10px 0;"><code>Shape s = new Circle(2);
s.area();                          // fine — declared on Shape
// s.getRadius();                  // COMPILE ERROR — Circle-only
if (s instanceof Circle c) { c.getRadius(); }    // the safe way</code></pre><p>Which is 10.5's two rules again, arriving through abstraction instead of plain inheritance.</p></div><div class="callout" data-lb="key" style="border-left-color:#e11d48;"><div class="callout-label">🎯 EXAM TIP</div><p><strong>Find the <code>new</code>.</strong> In any question about abstract classes, scan for <code>new</code> followed by the abstract type's name. That line is the error; every other mention of the type is legal.</p><p>The four options these questions usually offer, and why three are wrong:</p><p>• <em>"<code>Shape[] a = new Shape[3];</code> does not compile"</em> — <strong>false</strong>. It creates three nulls. This is the most common wrong answer in the whole unit.<br>• <em>"<code>Shape s;</code> does not compile"</em> — <strong>false</strong>. Declaring a variable creates nothing.<br>• <em>"the array creates three Shape objects"</em> — <strong>false</strong>. It creates three references, all null.<br>• <em>"<code>new Shape("x")</code> does not compile"</em> — <strong>true</strong>, and that is the answer.</p><p>One more that appears regularly: after <code>Shape[] a = new Shape[3];</code>, what does <code>a[0].area()</code> do? Not a compile error — a <strong><code>NullPointerException</code> at run time</strong>. The slot is empty, and the compiler has no way to know.</p></div>"},"D286/u11/z11_1":{"body":"<p>Recursion is a method calling itself on a smaller version of the same problem. It is not a trick — it is the natural shape for anything defined in terms of itself, and it needs exactly two things to work.</p><pre style="background:var(--bg-2, var(--surface-2)); padding:12px; border-radius:8px; font-size:13px; overflow-x:auto; line-height:1.55;">public static int factorial(int n) {
    if (n &lt;= 1) { return 1; }              // BASE CASE — stops the recursion
    return n * factorial(n - 1);           // RECURSIVE CASE — smaller input
}

factorial(4)
  -&gt; 4 * factorial(3)
       -&gt; 3 * factorial(2)
            -&gt; 2 * factorial(1)
                 -&gt; 1              base case
            &lt;- 2
       &lt;- 6
  &lt;- 24</pre><p>Miss the base case and the calls never stop; fail to shrink the input and they never reach it. Both produce <code>StackOverflowError</code> (11.8), because each call pushes a stack frame (6.8) and nothing pops.</p><p>A recursive method calls itself on a smaller version of the same problem. Two parts are compulsory, and every recursion question turns on one of them.</p><div style="overflow-x:auto; margin:14px 0;"><table style="border-collapse:collapse; width:100%; font-size:14.5px;"><thead><tr><th style="text-align:left; padding:7px 12px 7px 0; border-bottom:2px solid var(--border); font-size:12.5px; letter-spacing:.03em; text-transform:uppercase; opacity:.75;">Part</th><th style="text-align:left; padding:7px 12px 7px 0; border-bottom:2px solid var(--border); font-size:12.5px; letter-spacing:.03em; text-transform:uppercase; opacity:.75;">Job</th><th style="text-align:left; padding:7px 12px 7px 0; border-bottom:2px solid var(--border); font-size:12.5px; letter-spacing:.03em; text-transform:uppercase; opacity:.75;">Missing it gives</th></tr></thead><tbody><tr><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;"><strong>base case</strong></td><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">answers the smallest input directly, with no further call</td><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">infinite recursion → <code>StackOverflowError</code></td></tr><tr><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;"><strong>recursive case</strong></td><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">calls itself on a <em>smaller</em> input and builds the answer</td><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">no progress → also a stack overflow</td></tr></tbody></table></div><p>"Smaller" is the part people skip. <code>f(n)</code> calling <code>f(n)</code> has a base case and still never reaches it; the argument must move towards the base case on every call.</p><p>Anything recursive can be written with a loop and the reverse is also true. Recursion costs a stack frame per call, so a loop is cheaper — recursion earns its place when the data is itself nested, as with trees and divide-and-conquer.</p><i data-d286u811="1" style="display:none"></i><div class="callout" data-lb="why" style="border-left-color:#4f46e5;"><div class="callout-label">📘 DEFINITION</div><p style="margin:0 0 7px;"><strong>Recursion:</strong> a method that calls itself on a smaller instance of the problem</p><p style="margin:0 0 7px;"><strong>Base case:</strong> the input small enough to answer without recursing</p><p style="margin:0 0 7px;"><strong>Recursive case:</strong> the branch that calls itself with a reduced input</p><p style="margin:0 0 7px;"><strong>Recursive depth:</strong> how many calls are on the stack at the deepest point</p></div><div class="callout" data-lb="key" style="border-left-color:#22c55e;"><div class="callout-label">💡 WHY IT MATTERS</div><p>Recursion is not just an alternative to loops. Trees, permutations (11.7) and merge sort (17.9) have no natural iterative form, because the problem itself branches.</p></div><i data-d286_z11_1="1" style="display:none"></i><div class="vl" data-mathvis="1" data-c959fig="1" style="margin-top:18px;"><div style="font-weight:700; font-size:12.5px; letter-spacing:0.05em; margin-bottom:6px;">📊 FIGURE — every recursive method needs both halves</div><div style="border:1px solid var(--border); border-radius:12px; background:var(--surface-2); padding:14px 10px; overflow-x:auto;"><svg viewBox="0 0 600 154" style="width:100%; max-width:600px; display:block; margin:0 auto; font-family:inherit;" xmlns="http://www.w3.org/2000/svg"><defs><marker id="fk401a" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0,1 L9,5 L0,9 z" fill="var(--text)"/></marker></defs><rect x="14" y="22" width="250" height="24" rx="5" fill="none" stroke="var(--text)" stroke-width="1.4"/><text x="24" y="39" fill="var(--text)" font-size="11.5" font-weight="700" text-anchor="start" font-family="ui-monospace,Menlo,monospace">base case</text><text x="280" y="39" fill="var(--text-3)" font-size="11" font-weight="400" text-anchor="start">the size that needs no recursion</text><rect x="14" y="52" width="250" height="24" rx="5" fill="none" stroke="var(--text)" stroke-width="1.4"/><text x="24" y="69" fill="var(--text)" font-size="11.5" font-weight="700" text-anchor="start" font-family="ui-monospace,Menlo,monospace">recursive case</text><text x="280" y="69" fill="var(--text-3)" font-size="11" font-weight="400" text-anchor="start">calls itself on something SMALLER</text><rect x="14" y="82" width="250" height="24" rx="5" fill="none" stroke="var(--text)" stroke-width="1.4"/><text x="24" y="99" fill="var(--text)" font-size="11.5" font-weight="700" text-anchor="start" font-family="ui-monospace,Menlo,monospace">progress</text><text x="280" y="99" fill="var(--text-3)" font-size="11" font-weight="400" text-anchor="start">each call must approach the base</text><rect x="14" y="112" width="250" height="24" rx="5" fill="none" stroke="var(--text)" stroke-width="1.4"/><text x="24" y="129" fill="var(--text)" font-size="11.5" font-weight="700" text-anchor="start" font-family="ui-monospace,Menlo,monospace">no base case</text><text x="280" y="129" fill="var(--text-3)" font-size="11" font-weight="400" text-anchor="start">runs until the stack runs out</text></svg></div></div><div class="callout" data-lb="key" style="border-left-color:#0ea5e9;"><div class="callout-label">▸ WORKED EXAMPLE — Counting down, then counting up</div><pre style="background:var(--surface-2); border:1px solid var(--border); border-radius:8px; padding:11px 13px; overflow-x:auto; font-size:12.5px; line-height:1.5; margin:10px 0;">countdown(3);</pre><div style="border-left:3px solid var(--accent); background:var(--surface-2); padding:8px 12px; margin:8px 0 4px; font-family:ui-monospace,Menlo,monospace; font-size:12.5px; white-space:pre-wrap;">before 3
before 2
before 1
liftoff
after 1
after 2
after 3</div><div style="font-size:11px; color:var(--text-3); font-style:italic; margin-bottom:10px;">actual output, captured from the JVM</div><ol><li>Each call prints, then calls itself with a smaller n.</li><li>The base case stops the descent.</li><li>The 'after' lines print in REVERSE order — that is the calls unwinding as they return.</li></ol></div><div class="callout" data-lb="key" style="border-left-color:#0ea5e9;"><div class="callout-label">▸ WORKED EXAMPLE — Recursion and iteration solve the same problem</div><pre style="background:var(--surface-2); border:1px solid var(--border); border-radius:8px; padding:11px 13px; overflow-x:auto; font-size:12.5px; line-height:1.5; margin:10px 0;">System.out.println(sumRec(5));
System.out.println(sumIter(5));
System.out.println(sumRec(100) == sumIter(100));</pre><div style="border-left:3px solid var(--accent); background:var(--surface-2); padding:8px 12px; margin:8px 0 4px; font-family:ui-monospace,Menlo,monospace; font-size:12.5px; white-space:pre-wrap;">15
15
true</div><div style="font-size:11px; color:var(--text-3); font-style:italic; margin-bottom:10px;">actual output, captured from the JVM</div><ol><li>Both compute the same total.</li><li>The recursive version mirrors the definition: the sum to n is n plus the sum to n−1.</li><li>The iterative version uses less memory, because there is no stack of calls.</li></ol></div><div class="callout" data-lb="key" style="border-left-color:#f59e0b;"><div class="callout-label">⚠️ COMMON MISTAKE</div>Writing a recursive case that does not get smaller. <code>f(n)</code> calling <code>f(n)</code>, or calling <code>f(n - 0)</code>, recurses for ever — the base case is never reached however correct it looks.</div><div class="callout" data-lb="key" style="border-left-color:#e11d48;"><div class="callout-label">🎯 EXAM TIP</div>Check two things in any recursive method: is there a base case, and does every recursive call move towards it? Those two questions answer most exam items in this unit.</div>"},"D286/u11/z11_2":{"body":"<p>Writing one is a two-question routine, and doing it in this order is what stops recursion feeling like guesswork.</p><p>First: what input is small enough that I can answer immediately? That is the base case. Second: assuming the method already works for a smaller input, how do I build my answer from it? That is the recursive case — and the key move is trusting the smaller call rather than tracing it.</p><pre style="background:var(--bg-2, var(--surface-2)); padding:12px; border-radius:8px; font-size:13px; overflow-x:auto; line-height:1.55;">// sum of 1..n
public static int sumTo(int n) {
    if (n == 0) { return 0; }              // base: sum of nothing is 0
    return n + sumTo(n - 1);               // trust it for n-1, add n
}

// reverse a String
public static String reverse(String s) {
    if (s.length() &lt;= 1) { return s; }
    return reverse(s.substring(1)) + s.charAt(0);
}</pre><p>Compare <code>sumTo</code> with the loop version in 6.6. They produce the same answer; the recursive one describes the definition, the loop describes the procedure.</p><pre style="background:var(--bg-2, var(--surface-2)); padding:12px; border-radius:8px; font-size:13px; overflow-x:auto; line-height:1.55;">static int factorial(int n) {
    if (n &lt;= 1) return 1;              // base case
    return n * factorial(n - 1);       // recursive case, n gets smaller
}

factorial(4)
  4 * factorial(3)
      3 * factorial(2)
          2 * factorial(1)  -&gt; 1      &lt;- base case reached, unwinding starts
          2 * 1 = 2
      3 * 2 = 6
  4 * 6 = 24</pre><p>The multiplications happen on the way <em>back up</em>: every call waits for the one below it before it can finish. <code>factorial(4)</code> makes 4 calls in total, and 4 frames exist at once at the deepest point.</p><p><code>n &lt;= 1</code> rather than <code>n == 1</code> is deliberate — it catches 0 (whose factorial is 1) and stops a negative input from recursing forever downwards.</p><i data-d286u811="1" style="display:none"></i><div class="callout" data-lb="why" style="border-left-color:#4f46e5;"><div class="callout-label">📘 DEFINITION</div><p style="margin:0 0 7px;"><strong>Recursive leap of faith:</strong> assuming the smaller call is correct rather than tracing it</p><p style="margin:0 0 7px;"><strong>Reduction step:</strong> the change that makes the argument closer to the base case</p><p style="margin:0 0 7px;"><strong>Direct recursion:</strong> a method calling itself, as opposed to two methods calling each other</p></div><div class="callout" data-lb="oa" style="border-left-color:#e11d48;"><div class="callout-label">🎯 EXAM TIP</div><p>If tracing your own recursion confuses you, that is expected and not a sign of a bug. Verify the base case and verify one level of the recursive step; the rest follows by induction.</p></div><i data-d286fx20="1" style="display:none"></i><div class="vl" data-mathvis="1" data-c959fig="1" style="margin-top:18px;"><div style="font-weight:700; font-size:12.5px; letter-spacing:0.05em; margin-bottom:6px;">📊 FIGURE — RECURSION GOES DOWN TO THE BASE CASE, THEN RESULTS CLIMB BACK UP</div><div style="border:1px solid var(--border); border-radius:12px; background:var(--surface-2); padding:14px 10px; overflow-x:auto;"><svg viewBox="0 0 500 216" style="width:100%; max-width:540px; display:block; margin:0 auto; font-family:inherit;" xmlns="http://www.w3.org/2000/svg"><defs><marker id="fk87a" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0,1 L9,5 L0,9 z" fill="var(--text)"/></marker></defs><rect x="60" y="20" width="150" height="36" rx="7" fill="none" stroke="var(--text)" stroke-width="1.4"/><text x="135" y="42" fill="var(--text)" font-size="12" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">fact(3)</text><rect x="60" y="84" width="150" height="36" rx="7" fill="none" stroke="var(--text)" stroke-width="1.4"/><text x="135" y="106" fill="var(--text)" font-size="12" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">fact(2)</text><rect x="60" y="148" width="150" height="36" rx="7" fill="#22c55e22" stroke="#22c55e" stroke-width="1.4"/><text x="135" y="165" fill="var(--text)" font-size="12" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">fact(1)</text><text x="135" y="179" fill="#22c55e" font-size="9" font-weight="700" text-anchor="middle">BASE CASE → returns 1</text><line x1="112" y1="56" x2="112" y2="82" stroke="var(--text)" stroke-width="1.6" marker-end="url(#fk87a)"/><text x="76" y="72" fill="var(--text-3)" font-size="9.5" font-weight="400" text-anchor="middle">calls</text><line x1="112" y1="120" x2="112" y2="146" stroke="var(--text)" stroke-width="1.6" marker-end="url(#fk87a)"/><line x1="160" y1="146" x2="160" y2="122" stroke="#6366f1" stroke-width="1.6" marker-end="url(#fk87a)"/><text x="206" y="137" fill="#6366f1" font-size="10" font-weight="400" text-anchor="start" font-family="ui-monospace,Menlo,monospace">returns 1</text><line x1="160" y1="82" x2="160" y2="58" stroke="#6366f1" stroke-width="1.6" marker-end="url(#fk87a)"/><text x="206" y="73" fill="#6366f1" font-size="10" font-weight="400" text-anchor="start" font-family="ui-monospace,Menlo,monospace">2 × 1 = 2</text><line x1="160" y1="18" x2="160" y2="4" stroke="#6366f1" stroke-width="1.6" marker-end="url(#fk87a)"/><text x="206" y="12" fill="#6366f1" font-size="10" font-weight="400" text-anchor="start" font-family="ui-monospace,Menlo,monospace">3 × 2 = 6</text><text x="330" y="40" fill="var(--text)" font-size="10.5" font-weight="400" text-anchor="start">going DOWN: each call waits</text><text x="330" y="56" fill="var(--text)" font-size="10.5" font-weight="400" text-anchor="start">for a smaller answer</text><text x="330" y="88" fill="#6366f1" font-size="10.5" font-weight="400" text-anchor="start">coming UP: the multiplies</text><text x="330" y="104" fill="#6366f1" font-size="10.5" font-weight="400" text-anchor="start">happen in reverse order</text><text x="250" y="208" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-style="italic">No base case (or one you never reach) means the calls never turn around — StackOverflowError.</text></svg></div></div><div class="callout" data-lb="key" style="border-left-color:#e11d48;"><div class="callout-label">🎯 EXAM TIP</div>To trace recursion fast, find the base case FIRST and compute upward from it — much faster than expanding downward and less error-prone under exam time pressure.</div><i data-d286_z11_2="1" style="display:none"></i><div class="callout" data-lb="key" style="border-left-color:#0ea5e9;"><div class="callout-label">▸ WORKED EXAMPLE — Factorial, traced by its own definition</div><pre style="background:var(--surface-2); border:1px solid var(--border); border-radius:8px; padding:11px 13px; overflow-x:auto; font-size:12.5px; line-height:1.5; margin:10px 0;">System.out.println(fact(1));
System.out.println(fact(4));
System.out.println(4 * 3 * 2 * 1);</pre><div style="border-left:3px solid var(--accent); background:var(--surface-2); padding:8px 12px; margin:8px 0 4px; font-family:ui-monospace,Menlo,monospace; font-size:12.5px; white-space:pre-wrap;">1
24
24</div><div style="font-size:11px; color:var(--text-3); font-style:italic; margin-bottom:10px;">actual output, captured from the JVM</div><ol><li><code>fact(4)</code> waits for <code>fact(3)</code>, which waits for <code>fact(2)</code>, and so on.</li><li><code>fact(1)</code> returns 1 without recursing — the base case.</li><li>The multiplications then happen on the way back up.</li></ol></div><div class="callout" data-lb="key" style="border-left-color:#0ea5e9;"><div class="callout-label">▸ WORKED EXAMPLE — The base case must come first</div><pre style="background:var(--surface-2); border:1px solid var(--border); border-radius:8px; padding:11px 13px; overflow-x:auto; font-size:12.5px; line-height:1.5; margin:10px 0;">System.out.println(goodFact(5));
System.out.println(badFact(5));</pre><div style="border-left:3px solid var(--accent); background:var(--surface-2); padding:8px 12px; margin:8px 0 4px; font-family:ui-monospace,Menlo,monospace; font-size:12.5px; white-space:pre-wrap;">120
120</div><div style="font-size:11px; color:var(--text-3); font-style:italic; margin-bottom:10px;">actual output, captured from the JVM</div><ol><li><code>goodFact</code> tests for the base case before recursing.</li><li><code>badFact</code> multiplies first and only then delegates.</li><li>Both give 120 here, but the second has no stopping rule of its own — the helper is doing all the real work.</li></ol></div><div class="callout" data-lb="key" style="border-left-color:#f59e0b;"><div class="callout-label">⚠️ COMMON MISTAKE</div>Putting the recursive call before the base-case test. The test then never gets a chance to run on the way down, and the method descends until the stack is exhausted.</div>"},"D286/u11/z11_3":{"body":"<p>Binary search is the standard recursive search, and it is recursive for a real reason: each step reduces the problem to a genuinely smaller version of the same problem.</p><pre style="background:var(--bg-2, var(--surface-2)); padding:12px; border-radius:8px; font-size:13px; overflow-x:auto; line-height:1.55;">// the array MUST be sorted
public static int bsearch(int[] a, int target, int lo, int hi) {
    if (lo &gt; hi) { return -1; }                       // base: empty range
    int mid = (lo + hi) / 2;

    if (a[mid] == target) { return mid; }             // base: found
    if (a[mid] &lt; target)  { return bsearch(a, target, mid + 1, hi); }
    return bsearch(a, target, lo, mid - 1);
}</pre><p>There are two base cases here, and both are needed: found, and searched-everything. The halving is what makes it O(log n) — 1,000,000 elements take about 20 comparisons — and that analysis is 17.2.</p><pre style="background:var(--bg-2, var(--surface-2)); padding:12px; border-radius:8px; font-size:13px; overflow-x:auto; line-height:1.55;">static int bsearch(int[] a, int target, int lo, int hi) {
    if (lo &gt; hi) return -1;                       // base case: not found
    int mid = (lo + hi) / 2;
    if (a[mid] == target) return mid;             // base case: found
    if (a[mid] &lt; target) return bsearch(a, target, mid + 1, hi);
    else                 return bsearch(a, target, lo, mid - 1);
}</pre><p>Two base cases, and both are needed: one succeeds, one gives up. The range shrinks by half each call, so 1,000 elements take about 10 calls — O(log n), and the recursion depth is that same small number.</p><p>The precondition is that <strong>the array is sorted</strong>. On unsorted data binary search does not fail loudly; it simply misses values that are there, which is worse.</p><p><code>mid + 1</code> and <code>mid - 1</code> rather than <code>mid</code> is what guarantees progress. Passing <code>mid</code> unchanged leaves the range the same size and the recursion never reaches <code>lo &gt; hi</code>.</p><i data-d286u811="1" style="display:none"></i><div class="callout" data-lb="why" style="border-left-color:#4f46e5;"><div class="callout-label">📘 DEFINITION</div><p style="margin:0 0 7px;"><strong>Binary search:</strong> repeatedly halving a sorted range to locate a value</p><p style="margin:0 0 7px;"><strong>Search space:</strong> the lo..hi range still under consideration</p><p style="margin:0 0 7px;"><strong>Divide and conquer:</strong> splitting a problem into smaller instances, solving each, combining</p><p style="margin:0 0 7px;"><strong>Precondition:</strong> binary search requires sorted data; on unsorted data it silently returns wrong answers</p></div><div class="callout" data-lb="warn" style="border-left-color:#f59e0b;"><div class="callout-label">⚠ COMMON MISTAKE</div><p><code>lo &gt; hi</code> is the empty-range test; writing <code>lo == hi</code> misses the single-element case and the recursion never terminates properly.</p></div><i data-d286_z11_3="1" style="display:none"></i><div class="vl" data-mathvis="1" data-c959fig="1" style="margin-top:18px;"><div style="font-weight:700; font-size:12.5px; letter-spacing:0.05em; margin-bottom:6px;">📊 FIGURE — binary search halves the range</div><div style="border:1px solid var(--border); border-radius:12px; background:var(--surface-2); padding:14px 10px; overflow-x:auto;"><svg viewBox="0 0 600 184" style="width:100%; max-width:600px; display:block; margin:0 auto; font-family:inherit;" xmlns="http://www.w3.org/2000/svg"><defs><marker id="fk402a" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0,1 L9,5 L0,9 z" fill="var(--text)"/></marker></defs><rect x="14" y="22" width="250" height="24" rx="5" fill="none" stroke="var(--text)" stroke-width="1.4"/><text x="24" y="39" fill="var(--text)" font-size="11.5" font-weight="700" text-anchor="start" font-family="ui-monospace,Menlo,monospace">compare the middle</text><text x="280" y="39" fill="var(--text-3)" font-size="11" font-weight="400" text-anchor="start">one comparison</text><rect x="14" y="52" width="250" height="24" rx="5" fill="none" stroke="var(--text)" stroke-width="1.4"/><text x="24" y="69" fill="var(--text)" font-size="11.5" font-weight="700" text-anchor="start" font-family="ui-monospace,Menlo,monospace">target smaller</text><text x="280" y="69" fill="var(--text-3)" font-size="11" font-weight="400" text-anchor="start">search the left half</text><rect x="14" y="82" width="250" height="24" rx="5" fill="none" stroke="var(--text)" stroke-width="1.4"/><text x="24" y="99" fill="var(--text)" font-size="11.5" font-weight="700" text-anchor="start" font-family="ui-monospace,Menlo,monospace">target larger</text><text x="280" y="99" fill="var(--text-3)" font-size="11" font-weight="400" text-anchor="start">search the right half</text><rect x="14" y="112" width="250" height="24" rx="5" fill="none" stroke="var(--text)" stroke-width="1.4"/><text x="24" y="129" fill="var(--text)" font-size="11.5" font-weight="700" text-anchor="start" font-family="ui-monospace,Menlo,monospace">low &gt; high</text><text x="280" y="129" fill="var(--text-3)" font-size="11" font-weight="400" text-anchor="start">not found — the base case</text><rect x="14" y="142" width="250" height="24" rx="5" fill="none" stroke="var(--text)" stroke-width="1.4"/><text x="24" y="159" fill="var(--text)" font-size="11.5" font-weight="700" text-anchor="start" font-family="ui-monospace,Menlo,monospace">sorted input</text><text x="280" y="159" fill="var(--text-3)" font-size="11" font-weight="400" text-anchor="start">REQUIRED</text></svg></div></div><div class="callout" data-lb="key" style="border-left-color:#0ea5e9;"><div class="callout-label">▸ WORKED EXAMPLE — Binary search, recursively</div><pre style="background:var(--surface-2); border:1px solid var(--border); border-radius:8px; padding:11px 13px; overflow-x:auto; font-size:12.5px; line-height:1.5; margin:10px 0;">int[] a = {2, 5, 8, 12, 16, 23, 38};
System.out.println(bsearch(a, 23, 0, a.length - 1));
