System.out.println(bsearch(a, 7, 0, a.length - 1));</pre><div style="border-left:3px solid var(--accent); background:var(--surface-2); padding:8px 12px; margin:8px 0 4px; font-family:ui-monospace,Menlo,monospace; font-size:12.5px; white-space:pre-wrap;">5
