51.3,223.0 156.8,221.7 162.4,220.3 168.0,218.9 173.6,217.6 179.2,216.3 184.7,214.9 190.3,213.6 195.9,212.2 201.5,210.8 207.1,209.5 212.6,208.2 218.2,206.8 223.8,205.4 229.4,204.1 234.9,202.8 240.5,201.4 246.1,200.1 251.7,198.7 257.3,197.3 262.8,196.0 268.4,194.7 274.0,193.3 279.6,191.9 285.2,190.6 290.7,189.3 296.3,187.9 301.9,186.6 307.5,185.2 313.1,183.8 318.6,182.5 324.2,181.2 329.8,179.8 335.4,178.4 340.9,177.1 346.5,175.8 352.1,174.4 357.7,173.1 363.3,171.7 368.8,170.3 374.4,169.0 380.0,167.7 385.6,166.3 391.2,164.9 396.7,163.6 402.3,162.3 407.9,160.9 413.5,159.6 419.1,158.2 424.6,156.8 430.2,155.5 435.8,154.2 441.4,152.8 446.9,151.4 452.5,150.1 458.1,148.8 463.7,147.4 469.3,146.1 474.8,144.7 480.4,143.3 486.0,142.0" fill="none" stroke="#8b5cf6" stroke-width="2.2"/><polyline points="62.0,250.0 67.6,247.8 73.2,245.3 78.7,242.4 84.3,239.2 89.9,235.8 95.5,232.2 101.1,228.3 106.6,224.3 112.2,220.2 117.8,215.8 123.4,211.4 128.9,206.8 134.5,202.1 140.1,197.3 145.7,192.3 151.3,187.3 156.8,182.2 162.4,177.0 168.0,171.6 173.6,166.2 179.2,160.8 184.7,155.2 190.3,149.6 195.9,143.9 201.5,138.1 207.1,132.3 212.6,126.4 218.2,120.4 223.8,114.4 229.4,108.3 234.9,102.1 240.5,95.9 246.1,89.7 251.7,83.4 257.3,77.0 262.8,70.6 268.4,64.2 274.0,57.7 279.6,51.1 285.2,44.5 290.7,37.9 296.3,34.0" fill="none" stroke="#e8795a" stroke-width="2.2"/><polyline points="62.0,244.6 67.6,241.6 73.2,237.8 78.7,233.5 84.3,228.4 89.9,222.7 95.5,216.3 101.1,209.2 106.6,201.4 112.2,193.0 117.8,183.8 123.4,174.1 128.9,163.6 134.5,152.5 140.1,140.7 145.7,128.2 151.3,115.0 156.8,101.2 162.4,86.7 168.0,71.5 173.6,55.6 179.2,39.1 184.7,34.0" fill="none" stroke="#e11d48" stroke-width="2.2"/><text x="494" y="248.6" fill="#10b981" font-size="11" font-weight="700" text-anchor="start">O(1)</text><text x="494" y="230.66158828760825" fill="#0ea5e9" font-size="11" font-weight="700" text-anchor="start">O(log n)</text><text x="494" y="146" fill="#8b5cf6" font-size="11" font-weight="700" text-anchor="start">O(n)</text><text x="302.0842105263158" y="38" fill="#e8795a" font-size="11" font-weight="700" text-anchor="start">O(n log n)</text><text x="176.50526315789472" y="38" fill="#e11d48" font-size="11" font-weight="700" text-anchor="end">O(n²)</text><text x="280" y="288" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-style="italic">Constants only move a curve up or down. They never change which curve it is —</text><text x="280" y="302" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-style="italic">which is why 3n + 5 and n both sit on the O(n) line as n grows.</text></svg></div></div><div class="callout" data-lb="key" style="border-left-color:#0ea5e9;"><div class="callout-label">▸ WORKED EXAMPLE — from an exact operation count to the O</div><p style="margin:10px 0; line-height:1.7;">Analysis is done in two moves: count the operations exactly, then throw away everything that does not grow fastest. Here the counting is done by the program so there is nothing to take on trust.</p><pre style="background:var(--bg-2, var(--surface-2)); padding:12px; border-radius:8px; font-size:13px; overflow-x:auto; line-height:1.55;">for (int n : new int[]{ 10, 20, 40 }) {
    int ops = 0;
    int[] a = new int[n];
    for (int i = 0; i &lt; n; i++) { a[i] = i; ops++; }        // n
    int sum = 0;
    for (int i = 0; i &lt; n; i++) { sum += a[i]; ops++; }     // n
    ops += 3;                                              // three constant lines
    System.out.println("n=" + n + "  operations = 2n+3 = " + ops);
}</pre><div style="margin:10px 0; border-left:3px solid #10b981; border-radius:0 8px 8px 0; background:var(--surface-2); padding:9px 12px;"><div style="font-size:11.5px; font-weight:700; letter-spacing:.05em; opacity:.75; margin-bottom:5px;">what it prints</div><pre style="margin:0; font-size:12.6px; line-height:1.5; overflow-x:auto;">n=10  operations = 2n+3 = 23
n=20  operations = 2n+3 = 43
n=40  operations = 2n+3 = 83</pre></div><ol style="margin:8px 0 4px 20px; padding:0; line-height:1.75;"><li style="margin-bottom:5px;">The exact count is <code>2n + 3</code>: 23, 43, 83 for n = 10, 20, 40 — the arithmetic checks out.</li><li style="margin-bottom:5px;">Drop the constant term: <code>+3</code> is the same three operations whether n is 10 or ten million, so it cannot affect growth.</li><li style="margin-bottom:5px;">Drop the coefficient: <code>2n</code> and <code>n</code> both <em>double</em> when n doubles. Look at the numbers — 23 → 43 → 83 is not exactly doubling only because of that fading <code>+3</code>.</li><li style="margin-bottom:5px;">What is left is O(<em>n</em>). Writing "O(2n + 3)" is not wrong arithmetic, it is the wrong notation: Big-O names a growth class, and 2n + 3 is in the class called <em>n</em>.</li></ol></div><div class="callout" data-lb="key" style="border-left-color:#0ea5e9;"><div class="callout-label">▸ WORKED EXAMPLE — side by side, nested, or doubling — three shapes from three loop headers</div><pre style="background:var(--bg-2, var(--surface-2)); padding:12px; border-radius:8px; font-size:13px; overflow-x:auto; line-height:1.55;">for (int n : new int[]{ 4, 8, 16 }) {
    int seq = 0, nested = 0, doubling = 0;
    for (int i = 0; i &lt; n; i++) seq++;                 // O(n)
    for (int i = 0; i &lt; n; i++) seq++;                 // + O(n)
    for (int i = 0; i &lt; n; i++)
        for (int j = 0; j &lt; n; j++) nested++;          // O(n) x O(n)
    for (int i = 1; i &lt; n; i *= 2) doubling++;         // i *= 2
    System.out.println("n=" + n + "  two loops in a row = " + seq
            + "   nested = " + nested + "   i *= 2 loop = " + doubling);
}</pre><div style="margin:10px 0; border-left:3px solid #10b981; border-radius:0 8px 8px 0; background:var(--surface-2); padding:9px 12px;"><div style="font-size:11.5px; font-weight:700; letter-spacing:.05em; opacity:.75; margin-bottom:5px;">what it prints</div><pre style="margin:0; font-size:12.6px; line-height:1.5; overflow-x:auto;">n=4  two loops in a row = 8   nested = 16   i *= 2 loop = 2
n=8  two loops in a row = 16   nested = 64   i *= 2 loop = 3
n=16  two loops in a row = 32   nested = 256   i *= 2 loop = 4</pre></div><ol style="margin:8px 0 4px 20px; padding:0; line-height:1.75;"><li style="margin-bottom:5px;">Two loops one after another <strong>add</strong>: 8, 16, 32 — doubling n doubles the work. O(n) + O(n) = O(2n) = O(n).</li><li style="margin-bottom:5px;">Nested loops <strong>multiply</strong>: 16, 64, 256 — doubling n <em>quadruples</em> the work. That is the signature of O(n²) and you can read it straight off the numbers.</li><li style="margin-bottom:5px;">The doubling counter runs 2, 3, 4 times as n goes 4, 8, 16. Each doubling of n adds exactly <strong>one</strong> pass. That is log₂n, and it is where a logarithm comes from in code with no recursion in it.</li><li style="margin-bottom:5px;">The test is mechanical: double the input, look at what happens to the count. Same → O(1). +1 → O(log n). ×2 → O(n). ×4 → O(n²).</li></ol></div><div class="callout" data-lb="key" style="border-left-color:#e11d48;"><div class="callout-label">🎯 EXAM TIP</div><p style="margin:10px 0; line-height:1.7;">Read the loop headers and nothing else. A loop from 0 to n is <em>n</em>; two of them nested is <em>n</em>²; a loop whose counter multiplies is log <em>n</em>; a loop over a fixed range such as <code>i &lt; 100</code> is a constant no matter how large the data is. Then keep only the biggest term: n² + 100n + 5000 is O(n²), because for large n the n² term dwarfs everything. The classic wrong answer is O(n² + n) — correct arithmetic, wrong notation, no marks.</p></div>"},"D286/u17/z17_4":{"body":"<p>Analysing an algorithm means counting the operation that dominates, as a function of n, in the worst case.</p><pre style="background:var(--bg-2, var(--surface-2)); padding:12px; border-radius:8px; font-size:13px; overflow-x:auto; line-height:1.55;">for (int i = 0; i &lt; n; i++) { }                 // n         -&gt; O(n)

for (int i = 0; i &lt; n; i++)
    for (int j = 0; j &lt; n; j++) { }            // n * n     -&gt; O(n^2)

for (int i = 0; i &lt; n; i++)
    for (int j = i; j &lt; n; j++) { }            // n(n+1)/2  -&gt; O(n^2) still

for (int i = 1; i &lt; n; i *= 2) { }             // log2(n)   -&gt; O(log n)

for (int i = 0; i &lt; n; i++)
    for (int j = 1; j &lt; n; j *= 2) { }         // n * log n -&gt; O(n log n)</pre><p>The third example is the instructive one. Halving the work still leaves n²/2 operations, and dropping the constant gives O(n²) — a triangular nested loop is not in a better class than a square one, even though it genuinely does half the work.</p><pre style="background:var(--bg-2, var(--surface-2)); padding:12px; border-radius:8px; font-size:13px; overflow-x:auto; line-height:1.55;">for (int i = 0; i &lt; n; i++)
    for (int j = i + 1; j &lt; n; j++)      // triangular, not square
        ...
// n-1 + n-2 + ... + 1  =  n(n-1)/2  -&gt;  still O(n²)</pre><p>A triangular nesting does half the work of a square one and is still O(n²), because the constant ½ drops out. Recognising that stops the common answer of O(n) for the inner loop "because it starts at i".</p><div style="overflow-x:auto; margin:14px 0;"><table style="border-collapse:collapse; width:100%; font-size:14.5px;"><thead><tr><th style="text-align:left; padding:7px 12px 7px 0; border-bottom:2px solid var(--border); font-size:12.5px; letter-spacing:.03em; text-transform:uppercase; opacity:.75;">Case</th><th style="text-align:left; padding:7px 12px 7px 0; border-bottom:2px solid var(--border); font-size:12.5px; letter-spacing:.03em; text-transform:uppercase; opacity:.75;">Means</th><th style="text-align:left; padding:7px 12px 7px 0; border-bottom:2px solid var(--border); font-size:12.5px; letter-spacing:.03em; text-transform:uppercase; opacity:.75;">Linear search</th></tr></thead><tbody><tr><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">best</td><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">the luckiest input</td><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">O(1) — first element</td></tr><tr><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">average</td><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">typical input</td><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">O(n)</td></tr><tr><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;"><strong>worst</strong></td><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">the unluckiest input — what Big-O usually reports</td><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">O(n)</td></tr></tbody></table></div><p><strong>Space</strong> complexity counts extra memory beyond the input. Selection and insertion sort are O(1) extra; merge sort needs O(n); recursion costs O(depth) in stack frames, which is why recursive binary search is O(log n) space and the loop version is O(1).</p><p>Watch for hidden costs. <code>s += x</code> inside a loop is O(n²) in character copies because each concatenation builds a new String — the loop looks linear and is not.</p><i data-d286u1619="1" style="display:none"></i><div class="callout" data-lb="why" style="border-left-color:#4f46e5;"><div class="callout-label">📘 DEFINITION</div><p style="margin:0 0 7px;"><strong>Basic operation:</strong> the operation being counted, usually a comparison or a swap</p><p style="margin:0 0 7px;"><strong>Worst case:</strong> the input maximising the work; the default meaning of an O() claim</p><p style="margin:0 0 7px;"><strong>Amortised analysis:</strong> the average over a sequence, as with ArrayList growth (7.16)</p></div><div class="callout" data-lb="oa" style="border-left-color:#e11d48;"><div class="callout-label">🎯 EXAM TIP</div><p>Read the loop bounds, not the body. A loop multiplying its variable is logarithmic; a loop adding to it is linear. That single observation classifies most exam code.</p></div><i data-tbD286dS174="1" style="display:none"></i><div class="vl" data-mathvis="1" data-c959fig="1" style="margin-top:18px;"><div style="font-weight:700; font-size:12.5px; letter-spacing:0.05em; margin-bottom:6px;">📊 FIGURE — A TRIANGULAR NESTING IS HALF A SQUARE ONE — AND STILL QUADRATIC</div><div style="border:1px solid var(--border); border-radius:12px; background:var(--surface-2); padding:14px 10px; overflow-x:auto;"><svg viewBox="0 0 470 284" style="width:100%; max-width:520px; display:block; margin:0 auto; font-family:inherit;" xmlns="http://www.w3.org/2000/svg"><defs><marker id="fk290a" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0,1 L9,5 L0,9 z" fill="var(--text)"/></marker></defs><text x="164" y="24" fill="var(--text)" font-size="11.5" font-weight="700" text-anchor="middle">j runs from i+1, so only the shaded half is visited</text><rect x="74" y="46" width="30" height="30" rx="0" fill="var(--surface)" stroke="var(--text-3)" stroke-width="0.9"/><rect x="104" y="46" width="30" height="30" rx="0" fill="rgba(14,165,233,0.22)" stroke="#0ea5e9" stroke-width="1.4"/><rect x="134" y="46" width="30" height="30" rx="0" fill="rgba(14,165,233,0.22)" stroke="#0ea5e9" stroke-width="1.4"/><rect x="164" y="46" width="30" height="30" rx="0" fill="rgba(14,165,233,0.22)" stroke="#0ea5e9" stroke-width="1.4"/><rect x="194" y="46" width="30" height="30" rx="0" fill="rgba(14,165,233,0.22)" stroke="#0ea5e9" stroke-width="1.4"/><rect x="224" y="46" width="30" height="30" rx="0" fill="rgba(14,165,233,0.22)" stroke="#0ea5e9" stroke-width="1.4"/><text x="64" y="66" fill="var(--text-3)" font-size="10" font-weight="400" text-anchor="end">i=0</text><text x="89" y="38" fill="var(--text-3)" font-size="10" font-weight="400" text-anchor="middle">j=0</text><rect x="74" y="76" width="30" height="30" rx="0" fill="var(--surface)" stroke="var(--text-3)" stroke-width="0.9"/><rect x="104" y="76" width="30" height="30" rx="0" fill="var(--surface)" stroke="var(--text-3)" stroke-width="0.9"/><rect x="134" y="76" width="30" height="30" rx="0" fill="rgba(14,165,233,0.22)" stroke="#0ea5e9" stroke-width="1.4"/><rect x="164" y="76" width="30" height="30" rx="0" fill="rgba(14,165,233,0.22)" stroke="#0ea5e9" stroke-width="1.4"/><rect x="194" y="76" width="30" height="30" rx="0" fill="rgba(14,165,233,0.22)" stroke="#0ea5e9" stroke-width="1.4"/><rect x="224" y="76" width="30" height="30" rx="0" fill="rgba(14,165,233,0.22)" stroke="#0ea5e9" stroke-width="1.4"/><text x="64" y="96" fill="var(--text-3)" font-size="10" font-weight="400" text-anchor="end">i=1</text><text x="119" y="38" fill="var(--text-3)" font-size="10" font-weight="400" text-anchor="middle">j=1</text><rect x="74" y="106" width="30" height="30" rx="0" fill="var(--surface)" stroke="var(--text-3)" stroke-width="0.9"/><rect x="104" y="106" width="30" height="30" rx="0" fill="var(--surface)" stroke="var(--text-3)" stroke-width="0.9"/><rect x="134" y="106" width="30" height="30" rx="0" fill="var(--surface)" stroke="var(--text-3)" stroke-width="0.9"/><rect x="164" y="106" width="30" height="30" rx="0" fill="rgba(14,165,233,0.22)" stroke="#0ea5e9" stroke-width="1.4"/><rect x="194" y="106" width="30" height="30" rx="0" fill="rgba(14,165,233,0.22)" stroke="#0ea5e9" stroke-width="1.4"/><rect x="224" y="106" width="30" height="30" rx="0" fill="rgba(14,165,233,0.22)" stroke="#0ea5e9" stroke-width="1.4"/><text x="64" y="126" fill="var(--text-3)" font-size="10" font-weight="400" text-anchor="end">i=2</text><text x="149" y="38" fill="var(--text-3)" font-size="10" font-weight="400" text-anchor="middle">j=2</text><rect x="74" y="136" width="30" height="30" rx="0" fill="var(--surface)" stroke="var(--text-3)" stroke-width="0.9"/><rect x="104" y="136" width="30" height="30" rx="0" fill="var(--surface)" stroke="var(--text-3)" stroke-width="0.9"/><rect x="134" y="136" width="30" height="30" rx="0" fill="var(--surface)" stroke="var(--text-3)" stroke-width="0.9"/><rect x="164" y="136" width="30" height="30" rx="0" fill="var(--surface)" stroke="var(--text-3)" stroke-width="0.9"/><rect x="194" y="136" width="30" height="30" rx="0" fill="rgba(14,165,233,0.22)" stroke="#0ea5e9" stroke-width="1.4"/><rect x="224" y="136" width="30" height="30" rx="0" fill="rgba(14,165,233,0.22)" stroke="#0ea5e9" stroke-width="1.4"/><text x="64" y="156" fill="var(--text-3)" font-size="10" font-weight="400" text-anchor="end">i=3</text><text x="179" y="38" fill="var(--text-3)" font-size="10" font-weight="400" text-anchor="middle">j=3</text><rect x="74" y="166" width="30" height="30" rx="0" fill="var(--surface)" stroke="var(--text-3)" stroke-width="0.9"/><rect x="104" y="166" width="30" height="30" rx="0" fill="var(--surface)" stroke="var(--text-3)" stroke-width="0.9"/><rect x="134" y="166" width="30" height="30" rx="0" fill="var(--surface)" stroke="var(--text-3)" stroke-width="0.9"/><rect x="164" y="166" width="30" height="30" rx="0" fill="var(--surface)" stroke="var(--text-3)" stroke-width="0.9"/><rect x="194" y="166" width="30" height="30" rx="0" fill="var(--surface)" stroke="var(--text-3)" stroke-width="0.9"/><rect x="224" y="166" width="30" height="30" rx="0" fill="rgba(14,165,233,0.22)" stroke="#0ea5e9" stroke-width="1.4"/><text x="64" y="186" fill="var(--text-3)" font-size="10" font-weight="400" text-anchor="end">i=4</text><text x="209" y="38" fill="var(--text-3)" font-size="10" font-weight="400" text-anchor="middle">j=4</text><rect x="74" y="196" width="30" height="30" rx="0" fill="var(--surface)" stroke="var(--text-3)" stroke-width="0.9"/><rect x="104" y="196" width="30" height="30" rx="0" fill="var(--surface)" stroke="var(--text-3)" stroke-width="0.9"/><rect x="134" y="196" width="30" height="30" rx="0" fill="var(--surface)" stroke="var(--text-3)" stroke-width="0.9"/><rect x="164" y="196" width="30" height="30" rx="0" fill="var(--surface)" stroke="var(--text-3)" stroke-width="0.9"/><rect x="194" y="196" width="30" height="30" rx="0" fill="var(--surface)" stroke="var(--text-3)" stroke-width="0.9"/><rect x="224" y="196" width="30" height="30" rx="0" fill="var(--surface)" stroke="var(--text-3)" stroke-width="0.9"/><text x="64" y="216" fill="var(--text-3)" font-size="10" font-weight="400" text-anchor="end">i=5</text><text x="239" y="38" fill="var(--text-3)" font-size="10" font-weight="400" text-anchor="middle">j=5</text><text x="270" y="68" fill="var(--text)" font-size="11.5" font-weight="700" text-anchor="start">5 + 4 + 3 + 2 + 1 + 0</text><text x="270" y="88" fill="var(--text)" font-size="11.5" font-weight="400" text-anchor="start">= 15 of the 36 cells</text><text x="270" y="108" fill="#0ea5e9" font-size="11.5" font-weight="700" text-anchor="start">= n(n−1)/2</text><text x="270" y="134" fill="var(--text-3)" font-size="11" font-weight="400" text-anchor="start">half of n² is still</text><text x="270" y="152" fill="var(--text-3)" font-size="11" font-weight="400" text-anchor="start">proportional to n²</text><text x="270" y="178" fill="#e11d48" font-size="13" font-weight="700" text-anchor="start">→ O(n²)</text><text x="230" y="256" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-style="italic">The unshaded triangle is the work the "+1" saves. It is a constant factor of one half —</text><text x="230" y="270" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-style="italic">and constant factors are exactly what Big-O discards.</text></svg></div></div><div class="callout" data-lb="key" style="border-left-color:#0ea5e9;"><div class="callout-label">▸ WORKED EXAMPLE — the half-square loop, counted rather than guessed</div><pre style="background:var(--bg-2, var(--surface-2)); padding:12px; border-radius:8px; font-size:13px; overflow-x:auto; line-height:1.55;">for (int n : new int[]{ 6, 10, 100 }) {
    int inner = 0;
    for (int i = 0; i &lt; n; i++)
        for (int j = i + 1; j &lt; n; j++)      // starts at i+1, not 0
            inner++;
    System.out.println("n=" + n + "  inner body ran " + inner
            + " times;  n(n-1)/2 = " + (n * (n - 1) / 2)
            + ";  full square n*n = " + (n * n));
}</pre><div style="margin:10px 0; border-left:3px solid #10b981; border-radius:0 8px 8px 0; background:var(--surface-2); padding:9px 12px;"><div style="font-size:11.5px; font-weight:700; letter-spacing:.05em; opacity:.75; margin-bottom:5px;">what it prints</div><pre style="margin:0; font-size:12.6px; line-height:1.5; overflow-x:auto;">n=6  inner body ran 15 times;  n(n-1)/2 = 15;  full square n*n = 36
n=10  inner body ran 45 times;  n(n-1)/2 = 45;  full square n*n = 100
n=100  inner body ran 4950 times;  n(n-1)/2 = 4950;  full square n*n = 10000</pre></div><ol style="margin:8px 0 4px 20px; padding:0; line-height:1.75;"><li style="margin-bottom:5px;">For n = 6 the inner loop runs 5, then 4, then 3, 2, 1, 0 times: 15 in total, matching <code>n(n−1)/2</code> exactly.</li><li style="margin-bottom:5px;">Compare 15 against 36 and it looks like a real saving. Now compare n = 100: 4,950 against 10,000 — the ratio is <em>still</em> about a half, and it always will be.</li><li style="margin-bottom:5px;">Growth is what matters: from n = 10 to n = 100 the count goes 45 → 4,950, roughly ×110 for a ×10 in n. That is quadratic behaviour, ½ or no ½.</li><li style="margin-bottom:5px;">So the answer is O(n²). "O(n) because the inner loop starts at i" is the standard wrong answer, and the numbers above are the fastest way to see why.</li></ol></div><div class="callout" data-lb="key" style="border-left-color:#0ea5e9;"><div class="callout-label">▸ WORKED EXAMPLE — the loop that looks linear and is not</div><p style="margin:10px 0; line-height:1.7;">Every line of this loop is O(1) to look at, so the whole thing reads as O(<em>n</em>). It is O(<em>n</em>²), because <code>s += "x"</code> builds a whole new String each time — the old text is copied character by character.</p><pre style="background:var(--bg-2, var(--surface-2)); padding:12px; border-radius:8px; font-size:13px; overflow-x:auto; line-height:1.55;">for (int n : new int[]{ 100, 200, 400 }) {
    String s = "";
    long copied = 0;
    for (int i = 0; i &lt; n; i++) {
        copied += s.length() + 1;    // the old text is copied, then one char added
        s += "x";
    }
    System.out.println("n=" + n + "  characters copied = " + copied
            + "   (n(n+1)/2 = " + ((long) n * (n + 1) / 2) + ")"
            + "   final length = " + s.length());
}
StringBuilder sb = new StringBuilder();
for (int i = 0; i &lt; 400; i++) sb.append("x");
System.out.println("StringBuilder: 400 appends, length " + sb.length()
                   + ", each append copies 1 character");</pre><div style="margin:10px 0; border-left:3px solid #10b981; border-radius:0 8px 8px 0; background:var(--surface-2); padding:9px 12px;"><div style="font-size:11.5px; font-weight:700; letter-spacing:.05em; opacity:.75; margin-bottom:5px;">what it prints</div><pre style="margin:0; font-size:12.6px; line-height:1.5; overflow-x:auto;">n=100  characters copied = 5050   (n(n+1)/2 = 5050)   final length = 100
n=200  characters copied = 20100   (n(n+1)/2 = 20100)   final length = 200
n=400  characters copied = 80200   (n(n+1)/2 = 80200)   final length = 400
StringBuilder: 400 appends, length 400, each append copies 1 character</pre></div><ol style="margin:8px 0 4px 20px; padding:0; line-height:1.75;"><li style="margin-bottom:5px;">Doubling n from 100 to 200 takes the copying from 5,050 to 20,100 — <strong>four</strong> times the work for twice the input. Quadratic, from a loop with one statement in it.</li><li style="margin-bottom:5px;">The final string is only 400 characters long, but producing it copied 80,200. The visible result is linear; the hidden cost is not.</li><li style="margin-bottom:5px;">The cause is immutability: a String cannot be extended, so <code>s += "x"</code> allocates a new one and copies the old contents in.</li><li style="margin-bottom:5px;"><code>StringBuilder</code> keeps a growable buffer and appends in place, so 400 appends copy 400 characters — O(n). Any loop that concatenates onto a String should be a <code>StringBuilder</code>.</li></ol></div><div class="callout" data-lb="key" style="border-left-color:#f59e0b;"><div class="callout-label">⚠️ COMMON MISTAKE</div><p style="margin:10px 0; line-height:1.7;">Two traps sit next to each other. The first is reading nesting as multiplication without checking what the inner loop actually depends on: <code>for (j = 0; j &lt; 10; j++)</code> inside a loop over n is O(10n) = O(n), not O(n²), because 10 does not grow. The second is counting only what you can see — a <code>contains()</code> on a list inside a loop over the same list is O(n²), and <code>s += x</code> in a loop is O(n²), even though each is written on one line. Ask what the call <em>does</em>, not how long the line is.</p></div>"},"D286/u17/z17_5":{"body":"<p>Sorting is the most-studied problem in this course, and the algorithms split cleanly into two groups by their cost.</p><pre style="background:var(--bg-2, var(--surface-2)); padding:12px; border-radius:8px; font-size:13px; overflow-x:auto; line-height:1.55;">O(n^2)  — simple, fine for small n
    selection sort   17.6
    insertion sort   17.7
    bubble sort

O(n log n) — what real libraries use
    merge sort       17.9   — stable, needs O(n) extra space
    quicksort        17.8   — in place, O(n^2) worst case
    Collections.sort / Arrays.sort</pre><p>Two properties beyond speed decide which one is chosen in practice. <strong>Stability</strong> means equal elements keep their original relative order, which matters when you sort by one field after another. <strong>In-place</strong> means the algorithm needs no significant extra memory.</p><div style="overflow-x:auto; margin:14px 0;"><table style="border-collapse:collapse; width:100%; font-size:14.5px;"><thead><tr><th style="text-align:left; padding:7px 12px 7px 0; border-bottom:2px solid var(--border); font-size:12.5px; letter-spacing:.03em; text-transform:uppercase; opacity:.75;">Property</th><th style="text-align:left; padding:7px 12px 7px 0; border-bottom:2px solid var(--border); font-size:12.5px; letter-spacing:.03em; text-transform:uppercase; opacity:.75;">Means</th><th style="text-align:left; padding:7px 12px 7px 0; border-bottom:2px solid var(--border); font-size:12.5px; letter-spacing:.03em; text-transform:uppercase; opacity:.75;">Matters when</th></tr></thead><tbody><tr><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;"><strong>stable</strong></td><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">equal elements keep their original order</td><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">sorting by a second key after a first</td></tr><tr><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;"><strong>in place</strong></td><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">O(1) extra memory</td><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">the data is large</td></tr><tr><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;"><strong>adaptive</strong></td><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">faster on nearly-sorted input</td><td style="padding:7px 12px 7px 0; border-bottom:1px solid var(--border); vertical-align:top;">data arrives mostly ordered</td></tr></tbody></table></div><p>Stability is what lets you sort by name, then by grade, and still have equal grades in name order. An unstable sort scrambles the first ordering as it applies the second.</p><pre style="background:var(--bg-2, var(--surface-2)); padding:12px; border-radius:8px; font-size:13px; overflow-x:auto; line-height:1.55;">Arrays.sort(intArray);                       // primitives: dual-pivot quicksort
Collections.sort(list);                      // objects: Timsort, STABLE
list.sort(Comparator.comparing(Student::getName).reversed());</pre><p>Java sorts primitives with quicksort (unstable, but primitives are indistinguishable so it cannot matter) and objects with a stable merge-based sort — a deliberate choice, not an accident.</p><p>No comparison sort can beat O(n log n) in the worst case; that is a proven lower bound, which is why the good sorts all cluster there.</p><i data-d286u1619="1" style="display:none"></i><div class="callout" data-lb="why" style="border-left-color:#4f46e5;"><div class="callout-label">📘 DEFINITION</div><p style="margin:0 0 7px;"><strong>Sorting:</strong> arranging elements according to an ordering, usually compareTo (13.5)</p><p style="margin:0 0 7px;"><strong>Stable sort:</strong> preserves the relative order of equal elements</p><p style="margin:0 0 7px;"><strong>In-place sort:</strong> uses O(1) extra space beyond the input array</p><p style="margin:0 0 7px;"><strong>Comparison sort:</strong> any sort based on comparing pairs; O(n log n) is the theoretical floor</p></div><div class="callout" data-lb="oa" style="border-left-color:#e11d48;"><div class="callout-label">🎯 EXAM TIP</div><p>In real code you call <code>Arrays.sort</code> or <code>Collections.sort</code>. The algorithms here are taught because the exam asks you to trace them and to state their complexity.</p></div><i data-tbD286dS175="1" style="display:none"></i><div class="vl" data-mathvis="1" data-c959fig="1" style="margin-top:18px;"><div style="font-weight:700; font-size:12.5px; letter-spacing:0.05em; margin-bottom:6px;">📊 FIGURE — WHAT STABILITY ACTUALLY BUYS YOU</div><div style="border:1px solid var(--border); border-radius:12px; background:var(--surface-2); padding:14px 10px; overflow-x:auto;"><svg viewBox="0 0 640 262" style="width:100%; max-width:680px; display:block; margin:0 auto; font-family:inherit;" xmlns="http://www.w3.org/2000/svg"><defs><marker id="fk291a" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0,1 L9,5 L0,9 z" fill="var(--text)"/></marker></defs><text x="96" y="22" fill="#8b5cf6" font-size="12" font-weight="700" text-anchor="middle">sorted by NAME first</text><rect x="14" y="34" width="164" height="28" rx="5" fill="var(--surface)" stroke="var(--text-3)" stroke-width="1"/><text x="24" y="53" fill="var(--text)" font-size="11.5" font-weight="600" text-anchor="start">Alvarez</text><text x="166" y="53" fill="var(--text-3)" font-size="11" font-weight="400" text-anchor="end">45 min</text><rect x="14" y="66" width="164" height="28" rx="5" fill="#8b5cf622" stroke="#8b5cf6" stroke-width="1.4"/><text x="24" y="85" fill="var(--text)" font-size="11.5" font-weight="600" text-anchor="start">Baptiste</text><text x="166" y="85" fill="var(--text-3)" font-size="11" font-weight="400" text-anchor="end">39 min</text><rect x="14" y="98" width="164" height="28" rx="5" fill="#8b5cf622" stroke="#8b5cf6" stroke-width="1.4"/><text x="24" y="117" fill="var(--text)" font-size="11.5" font-weight="600" text-anchor="start">Lindqvist</text><text x="166" y="117" fill="var(--text-3)" font-size="11" font-weight="400" text-anchor="end">42 min</text><rect x="14" y="130" width="164" height="28" rx="5" fill="#8b5cf622" stroke="#8b5cf6" stroke-width="1.4"/><text x="24" y="149" fill="var(--text)" font-size="11.5" font-weight="600" text-anchor="start">Nakamura</text><text x="166" y="149" fill="var(--text-3)" font-size="11" font-weight="400" text-anchor="end">39 min</text><rect x="14" y="162" width="164" height="28" rx="5" fill="#8b5cf622" stroke="#8b5cf6" stroke-width="1.4"/><text x="24" y="181" fill="var(--text)" font-size="11.5" font-weight="600" text-anchor="start">Okafor</text><text x="166" y="181" fill="var(--text-3)" font-size="11" font-weight="400" text-anchor="end">42 min</text><text x="96" y="212" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle">the starting order</text><text x="320" y="22" fill="#10b981" font-size="12" font-weight="700" text-anchor="middle">then by time — STABLE</text><rect x="238" y="34" width="164" height="28" rx="5" fill="#10b98122" stroke="#10b981" stroke-width="1.4"/><text x="248" y="53" fill="var(--text)" font-size="11.5" font-weight="600" text-anchor="start">Baptiste</text><text x="390" y="53" fill="var(--text-3)" font-size="11" font-weight="400" text-anchor="end">39 min</text><rect x="238" y="66" width="164" height="28" rx="5" fill="#10b98122" stroke="#10b981" stroke-width="1.4"/><text x="248" y="85" fill="var(--text)" font-size="11.5" font-weight="600" text-anchor="start">Nakamura</text><text x="390" y="85" fill="var(--text-3)" font-size="11" font-weight="400" text-anchor="end">39 min</text><rect x="238" y="98" width="164" height="28" rx="5" fill="#10b98122" stroke="#10b981" stroke-width="1.4"/><text x="248" y="117" fill="var(--text)" font-size="11.5" font-weight="600" text-anchor="start">Lindqvist</text><text x="390" y="117" fill="var(--text-3)" font-size="11" font-weight="400" text-anchor="end">42 min</text><rect x="238" y="130" width="164" height="28" rx="5" fill="#10b98122" stroke="#10b981" stroke-width="1.4"/><text x="248" y="149" fill="var(--text)" font-size="11.5" font-weight="600" text-anchor="start">Okafor</text><text x="390" y="149" fill="var(--text-3)" font-size="11" font-weight="400" text-anchor="end">42 min</text><rect x="238" y="162" width="164" height="28" rx="5" fill="var(--surface)" stroke="var(--text-3)" stroke-width="1"/><text x="248" y="181" fill="var(--text)" font-size="11.5" font-weight="600" text-anchor="start">Alvarez</text><text x="390" y="181" fill="var(--text-3)" font-size="11" font-weight="400" text-anchor="end">45 min</text><text x="320" y="212" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle">ties still in name order ✓</text><text x="544" y="22" fill="#e11d48" font-size="12" font-weight="700" text-anchor="middle">then by time — unstable</text><rect x="462" y="34" width="164" height="28" rx="5" fill="#e11d4822" stroke="#e11d48" stroke-width="1.4"/><text x="472" y="53" fill="var(--text)" font-size="11.5" font-weight="600" text-anchor="start">Nakamura</text><text x="614" y="53" fill="var(--text-3)" font-size="11" font-weight="400" text-anchor="end">39 min</text><rect x="462" y="66" width="164" height="28" rx="5" fill="#e11d4822" stroke="#e11d48" stroke-width="1.4"/><text x="472" y="85" fill="var(--text)" font-size="11.5" font-weight="600" text-anchor="start">Baptiste</text><text x="614" y="85" fill="var(--text-3)" font-size="11" font-weight="400" text-anchor="end">39 min</text><rect x="462" y="98" width="164" height="28" rx="5" fill="#e11d4822" stroke="#e11d48" stroke-width="1.4"/><text x="472" y="117" fill="var(--text)" font-size="11.5" font-weight="600" text-anchor="start">Okafor</text><text x="614" y="117" fill="var(--text-3)" font-size="11" font-weight="400" text-anchor="end">42 min</text><rect x="462" y="130" width="164" height="28" rx="5" fill="#e11d4822" stroke="#e11d48" stroke-width="1.4"/><text x="472" y="149" fill="var(--text)" font-size="11.5" font-weight="600" text-anchor="start">Lindqvist</text><text x="614" y="149" fill="var(--text-3)" font-size="11" font-weight="400" text-anchor="end">42 min</text><rect x="462" y="162" width="164" height="28" rx="5" fill="var(--surface)" stroke="var(--text-3)" stroke-width="1"/><text x="472" y="181" fill="var(--text)" font-size="11.5" font-weight="600" text-anchor="start">Alvarez</text><text x="614" y="181" fill="var(--text-3)" font-size="11" font-weight="400" text-anchor="end">45 min</text><text x="544" y="212" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle">ties scrambled ✗</text><line x1="190" y1="110" x2="232" y2="110" stroke="var(--text-3)" stroke-width="1.3" marker-end="url(#fk291a)"/><line x1="414" y1="110" x2="456" y2="110" stroke="var(--text-3)" stroke-width="1.3" marker-end="url(#fk291a)"/><text x="320" y="236" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-style="italic">Same second sort, same times. A stable sort never reorders elements the comparator calls equal,</text><text x="320" y="250" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-style="italic">so the first sort survives inside each tie group. That is how two-key sorting is done.</text></svg></div></div><div class="callout" data-lb="key" style="border-left-color:#0ea5e9;"><div class="callout-label">▸ WORKED EXAMPLE — sorting twice to sort by two keys</div><p style="margin:10px 0; line-height:1.7;">Five runners. Sort by name, then by time. If the sort is stable, runners on the same time come out in name order without anyone asking for it.</p><pre style="background:var(--bg-2, var(--surface-2)); padding:12px; border-radius:8px; font-size:13px; overflow-x:auto; line-height:1.55;">record Runner(String name, String club, int minutes) {
    public String toString(){ return name + "/" + club + "/" + minutes; }
}

List&lt;Runner&gt; field = new ArrayList&lt;&gt;(List.of(
    new Runner("Okafor", "Harriers", 42),
    new Runner("Baptiste", "Striders", 39),
    new Runner("Lindqvist", "Harriers", 42),
    new Runner("Nakamura", "Striders", 39),
    new Runner("Alvarez", "Pacers", 45)));

field.sort(Comparator.comparing(Runner::name));
System.out.println("by name:   " + field);
field.sort(Comparator.comparingInt(Runner::minutes));
System.out.println("by time:   " + field);</pre><div style="margin:10px 0; border-left:3px solid #10b981; border-radius:0 8px 8px 0; background:var(--surface-2); padding:9px 12px;"><div style="font-size:11.5px; font-weight:700; letter-spacing:.05em; opacity:.75; margin-bottom:5px;">what it prints</div><pre style="margin:0; font-size:12.6px; line-height:1.5; overflow-x:auto;">by name:   [Alvarez/Pacers/45, Baptiste/Striders/39, Lindqvist/Harriers/42, Nakamura/Striders/39, Okafor/Harriers/42]
by time:   [Baptiste/Striders/39, Nakamura/Striders/39, Lindqvist/Harriers/42, Okafor/Harriers/42, Alvarez/Pacers/45]</pre></div><ol style="margin:8px 0 4px 20px; padding:0; line-height:1.75;"><li style="margin-bottom:5px;">After the first sort the list is alphabetical. Nothing surprising yet.</li><li style="margin-bottom:5px;">The second sort compares <em>only</em> minutes. Baptiste and Nakamura are both 39, so as far as this comparator is concerned they are equal.</li><li style="margin-bottom:5px;">They come out Baptiste then Nakamura — alphabetical — because <code>List.sort</code> is stable and refuses to reorder elements it considers equal. Lindqvist before Okafor, on 42, is the same effect.</li><li style="margin-bottom:5px;">The rule to remember: sort by the <strong>secondary</strong> key first, then by the primary. It reads backwards and it is correct.</li></ol><p style="margin:10px 0; line-height:1.7;">The same result in a single pass, which is what you would normally write:</p><pre style="background:var(--bg-2, var(--surface-2)); padding:12px; border-radius:8px; font-size:13px; overflow-x:auto; line-height:1.55;">again.sort(Comparator.comparingInt(Runner::minutes).thenComparing(Runner::name));
System.out.println("one pass:  " + again);
System.out.println("equal?     " + again.equals(field));</pre><div style="margin:10px 0; border-left:3px solid #10b981; border-radius:0 8px 8px 0; background:var(--surface-2); padding:9px 12px;"><div style="font-size:11.5px; font-weight:700; letter-spacing:.05em; opacity:.75; margin-bottom:5px;">what it prints</div><pre style="margin:0; font-size:12.6px; line-height:1.5; overflow-x:auto;">one pass:  [Baptiste/Striders/39, Nakamura/Striders/39, Lindqvist/Harriers/42, Okafor/Harriers/42, Alvarez/Pacers/45]
equal?     true</pre></div></div><div class="callout" data-lb="key" style="border-left-color:#0ea5e9;"><div class="callout-label">▸ WORKED EXAMPLE — the library calls, and where reversed() attaches</div><pre style="background:var(--bg-2, var(--surface-2)); padding:12px; border-radius:8px; font-size:13px; overflow-x:auto; line-height:1.55;">int[] nums = { 34, 7, 23, 32, 5, 62 };
Arrays.sort(nums);
System.out.println("Arrays.sort(int[]):   " + Arrays.toString(nums));

List&lt;String&gt; towns = new ArrayList&lt;&gt;(List.of("Reno", "Akron", "Boise", "Casper"));
Collections.sort(towns);
System.out.println("Collections.sort:     " + towns);
towns.sort(Comparator.reverseOrder());
System.out.println("reverseOrder:         " + towns);
towns.sort(Comparator.comparingInt(String::length)
                     .thenComparing(Comparator.naturalOrder()));
System.out.println("by length then name:  " + towns);

Integer[] boxed = { 34, 7, 23, 32, 5, 62 };
Arrays.sort(boxed, Comparator.reverseOrder());
System.out.println("Integer[] descending: " + Arrays.toString(boxed));</pre><div style="margin:10px 0; border-left:3px solid #10b981; border-radius:0 8px 8px 0; background:var(--surface-2); padding:9px 12px;"><div style="font-size:11.5px; font-weight:700; letter-spacing:.05em; opacity:.75; margin-bottom:5px;">what it prints</div><pre style="margin:0; font-size:12.6px; line-height:1.5; overflow-x:auto;">Arrays.sort(int[]):   [5, 7, 23, 32, 34, 62]
Collections.sort:     [Akron, Boise, Casper, Reno]
reverseOrder:         [Reno, Casper, Boise, Akron]
by length then name:  [Reno, Akron, Boise, Casper]
Integer[] descending: [62, 34, 32, 23, 7, 5]</pre></div><ol style="margin:8px 0 4px 20px; padding:0; line-height:1.75;"><li style="margin-bottom:5px;"><code>Arrays.sort</code> takes an array, <code>Collections.sort</code> and <code>list.sort</code> take a <code>List</code>. Passing the wrong one is a compile error, so this is a spot-the-signature question rather than a trap.</li><li style="margin-bottom:5px;">Descending on primitives has no one-argument form: there is no <code>Arrays.sort(int[], Comparator)</code>. Sort ascending and reverse, or box to <code>Integer[]</code> as the last block does.</li><li style="margin-bottom:5px;"><code>comparingInt(String::length).thenComparing(naturalOrder())</code> gives Reno (4), then the three fives in alphabetical order — the tie-break only runs when the lengths match.</li><li style="margin-bottom:5px;"><code>reversed()</code> reverses the comparator it is attached to. <code>comparing(A).thenComparing(B).reversed()</code> reverses <em>both</em> keys; to reverse only the first, write <code>comparing(A).reversed().thenComparing(B)</code>.</li></ol></div><div class="callout" data-lb="key" style="border-left-color:#f59e0b;"><div class="callout-label">⚠️ COMMON MISTAKE</div><p style="margin:10px 0; line-height:1.7;">Two habits break sorting quietly. Writing a comparator as <code>(a, b) -&gt; a.score - b.score</code> looks tidy and overflows for large or negative values — <code>Integer.compare(a.score, b.score)</code> or <code>comparingInt</code> is the correct form. And calling <code>Collections.sort(list)</code> on your own class throws <code>ClassCastException</code> at run time unless the class implements <code>Comparable</code>; the compiler cannot catch it, so the first sign is a crash on a line that contains no sorting logic at all.</p></div>"},"D286/u17/z17_6":{"body":"<p>Selection sort repeatedly finds the smallest remaining element and swaps it into place. It is the easiest to trace, and its cost never changes with the input.</p><pre style="background:var(--bg-2, var(--surface-2)); padding:12px; border-radius:8px; font-size:13px; overflow-x:auto; line-height:1.55;">for (int i = 0; i &lt; a.length - 1; i++) {
    int minIdx = i;
    for (int j = i + 1; j &lt; a.length; j++) {       // find the smallest in the rest
        if (a[j] &lt; a[minIdx]) { minIdx = j; }
    }
    int temp = a[i]; a[i] = a[minIdx]; a[minIdx] = temp;   // swap (5.6)
}

// {5, 2, 9, 1}
// i=0: min is 1 -&gt; {1, 2, 9, 5}
// i=1: min is 2 -&gt; {1, 2, 9, 5}   (swaps with itself)
// i=2: min is 5 -&gt; {1, 2, 5, 9}</pre><p>It performs the same n(n+1)/2 comparisons whether the array is already sorted or completely reversed — best case equals worst case equals O(n²). What it minimises instead is <em>swaps</em>: exactly n-1, which mattered historically when writing was expensive.</p><pre style="background:var(--bg-2, var(--surface-2)); padding:12px; border-radius:8px; font-size:13px; overflow-x:auto; line-height:1.55;">for (int i = 0; i &lt; n - 1; i++) {
    int min = i;
    for (int j = i + 1; j &lt; n; j++)
        if (a[j] &lt; a[min]) min = j;          // find the smallest remaining
    swap(a, i, min);                         // ONE swap per pass
}</pre><p>Selection sort finds the smallest remaining element and puts it in place. After <em>k</em> passes the first <em>k</em> positions hold the <em>k</em> smallest values, finished and never touched again.</p><p>It is O(n²) in <strong>every</strong> case — best, average and worst — because the inner loop always scans the whole remainder regardless of the data. It is not adaptive: already-sorted input takes exactly as long.</p><p>Its one distinction is the swap count: at most <em>n</em> − 1 swaps, one per pass, far fewer than bubble sort. That matters only when a swap is expensive. It is not stable, because the long-distance swap can jump an equal element over another.</p><i data-d286u1619="1" style="display:none"></i><div class="callout" data-lb="why" style="border-left-color:#4f46e5;"><div class="callout-label">📘 DEFINITION</div><p style="margin:0 0 7px;"><strong>Selection sort:</strong> repeatedly select the minimum of the unsorted part and swap it into place</p><p style="margin:0 0 7px;"><strong>Sorted prefix:</strong> the front of the array, already in final position after pass i</p><p style="margin:0 0 7px;"><strong>Swap count:</strong> n-1, the fewest of any simple sort</p><p style="margin:0 0 7px;"><strong>Unstable:</strong> a long-distance swap can reorder equal elements</p></div><div class="callout" data-lb="oa" style="border-left-color:#e11d48;"><div class="callout-label">🎯 EXAM TIP</div><p>Trace questions usually ask for the array after k passes. After pass k, the first k+1 elements are in their final sorted positions — you do not need to trace the rest.</p></div><i data-d286fx28="1" style="display:none"></i><p style="margin-top:16px;"><b>Selection sort, one frozen prefix at a time.</b> Each pass scans the UNSORTED part for its minimum and swaps it to the front of that part; the bold prefix never moves again:</p><div style="overflow-x:auto; margin:14px 0;"><table style="border-collapse:collapse; width:100%; font-size:14.5px;"><thead><tr><th style="text-align:left; padding:7px 12px 7px 0; border-bottom:2px solid var(--border); font-size:12.5px; letter-spacing:0.04em;">pass</th><th style="text-align:left; padding:7px 12px 7px 0; border-bottom:2px solid var(--border); font-size:12.5px; letter-spacing:0.04em;">array after the pass</th><th style="text-align:left; padding:7px 12px 7px 0; border-bottom:2px solid var(--border); font-size:12.5px; letter-spacing:0.04em;">what happened</th></tr></thead><tbody><tr><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border); font-weight:600;">start</td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);"><code>29&nbsp; 10&nbsp; 14&nbsp; 37&nbsp; 13</code></td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);"></td></tr><tr><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border); font-weight:600;">1</td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);"><code><b>10</b>&nbsp; 29&nbsp; 14&nbsp; 37&nbsp; 13</code></td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);">min of ALL five (10) swaps into index 0</td></tr><tr><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border); font-weight:600;">2</td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);"><code><b>10&nbsp; 13</b>&nbsp; 14&nbsp; 37&nbsp; 29</code></td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);">min of the last four (13) swaps into index 1</td></tr><tr><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border); font-weight:600;">3</td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);"><code><b>10&nbsp; 13&nbsp; 14</b>&nbsp; 37&nbsp; 29</code></td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);">14 already in place — swap with itself</td></tr><tr><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border); font-weight:600;">4</td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);"><code><b>10&nbsp; 13&nbsp; 14&nbsp; 29</b>&nbsp; 37</code></td><td style="padding:6px 12px 6px 0; border-bottom:1px solid var(--border);">min of the last two (29) swaps into index 3</td></tr></tbody></table></div><div class="callout" data-lb="key" style="border-left-color:#e11d48;"><div class="callout-label">🎯 EXAM TIP</div>n elements need n−1 passes, and pass counting is the OA’s favourite: after pass k, the first k slots hold the k smallest values in final position. Selection sort does the same work even on sorted input — O(n²) always — while insertion sort on sorted input is O(n).</div><i data-tbD286dS176="1" style="display:none"></i><div class="vl" data-mathvis="1" data-c959fig="1" style="margin-top:18px;"><div style="font-weight:700; font-size:12.5px; letter-spacing:0.05em; margin-bottom:6px;">📊 FIGURE — SELECTION SORT: THE GREEN PREFIX NEVER MOVES AGAIN</div><div style="border:1px solid var(--border); border-radius:12px; background:var(--surface-2); padding:14px 10px; overflow-x:auto;"><svg viewBox="0 0 620 318" style="width:100%; max-width:660px; display:block; margin:0 auto; font-family:inherit;" xmlns="http://www.w3.org/2000/svg"><defs><marker id="fk292a" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0,1 L9,5 L0,9 z" fill="var(--text)"/></marker></defs><text x="252" y="20" fill="#10b981" font-size="11" font-weight="700" text-anchor="middle">frozen prefix — never touched again</text><text x="72" y="51" fill="var(--text-3)" font-size="11" font-weight="700" text-anchor="end">start</text><rect x="84" y="32" width="56" height="28" rx="5" fill="var(--surface)" stroke="var(--text)" stroke-width="1.2"/><text x="112" y="51" fill="var(--text)" font-size="12" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">71</text><rect x="140" y="32" width="56" height="28" rx="5" fill="var(--surface)" stroke="var(--text)" stroke-width="