ect x="252" y="112" width="56" height="28" rx="5" fill="var(--surface)" stroke="var(--text)" stroke-width="1.2"/><text x="280" y="131" fill="var(--text)" font-size="12" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">71</text><rect x="308" y="112" width="56" height="28" rx="5" fill="var(--surface)" stroke="var(--text)" stroke-width="1.2"/><text x="336" y="131" fill="var(--text)" font-size="12" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">77</text><rect x="364" y="112" width="56" height="28" rx="5" fill="rgba(232,121,90,0.24)" stroke="#e8795a" stroke-width="1.6"/><text x="392" y="131" fill="var(--text)" font-size="12" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">64</text><text x="434" y="131" fill="#e8795a" font-size="10.5" font-weight="400" text-anchor="start">smallest of the rest is 64</text><text x="72" y="171" fill="var(--text-3)" font-size="11" font-weight="700" text-anchor="end">pass 3</text><rect x="84" y="152" width="56" height="28" rx="5" fill="rgba(16,185,129,0.20)" stroke="#10b981" stroke-width="1.6"/><text x="112" y="171" fill="#10b981" font-size="12" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">59</text><rect x="140" y="152" width="56" height="28" rx="5" fill="rgba(16,185,129,0.20)" stroke="#10b981" stroke-width="1.6"/><text x="168" y="171" fill="#10b981" font-size="12" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">62</text><rect x="196" y="152" width="56" height="28" rx="5" fill="rgba(16,185,129,0.20)" stroke="#10b981" stroke-width="1.6"/><text x="224" y="171" fill="#10b981" font-size="12" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">64</text><rect x="252" y="152" width="56" height="28" rx="5" fill="rgba(232,121,90,0.24)" stroke="#e8795a" stroke-width="1.6"/><text x="280" y="171" fill="var(--text)" font-size="12" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">71</text><rect x="308" y="152" width="56" height="28" rx="5" fill="var(--surface)" stroke="var(--text)" stroke-width="1.2"/><text x="336" y="171" fill="var(--text)" font-size="12" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">77</text><rect x="364" y="152" width="56" height="28" rx="5" fill="var(--surface)" stroke="var(--text)" stroke-width="1.2"/><text x="392" y="171" fill="var(--text)" font-size="12" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">88</text><text x="434" y="171" fill="#e8795a" font-size="10.5" font-weight="400" text-anchor="start">smallest of the rest is 71</text><text x="72" y="211" fill="var(--text-3)" font-size="11" font-weight="700" text-anchor="end">pass 4</text><rect x="84" y="192" width="56" height="28" rx="5" fill="rgba(16,185,129,0.20)" stroke="#10b981" stroke-width="1.6"/><text x="112" y="211" fill="#10b981" font-size="12" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">59</text><rect x="140" y="192" width="56" height="28" rx="5" fill="rgba(16,185,129,0.20)" stroke="#10b981" stroke-width="1.6"/><text x="168" y="211" fill="#10b981" font-size="12" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">62</text><rect x="196" y="192" width="56" height="28" rx="5" fill="rgba(16,185,129,0.20)" stroke="#10b981" stroke-width="1.6"/><text x="224" y="211" fill="#10b981" font-size="12" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">64</text><rect x="252" y="192" width="56" height="28" rx="5" fill="rgba(16,185,129,0.20)" stroke="#10b981" stroke-width="1.6"/><text x="280" y="211" fill="#10b981" font-size="12" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">71</text><rect x="308" y="192" width="56" height="28" rx="5" fill="rgba(232,121,90,0.24)" stroke="#e8795a" stroke-width="1.6"/><text x="336" y="211" fill="var(--text)" font-size="12" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">77</text><rect x="364" y="192" width="56" height="28" rx="5" fill="var(--surface)" stroke="var(--text)" stroke-width="1.2"/><text x="392" y="211" fill="var(--text)" font-size="12" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">88</text><text x="434" y="211" fill="#e8795a" font-size="10.5" font-weight="400" text-anchor="start">smallest of the rest is 77</text><text x="72" y="251" fill="var(--text-3)" font-size="11" font-weight="700" text-anchor="end">pass 5</text><rect x="84" y="232" width="56" height="28" rx="5" fill="rgba(16,185,129,0.20)" stroke="#10b981" stroke-width="1.6"/><text x="112" y="251" fill="#10b981" font-size="12" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">59</text><rect x="140" y="232" width="56" height="28" rx="5" fill="rgba(16,185,129,0.20)" stroke="#10b981" stroke-width="1.6"/><text x="168" y="251" fill="#10b981" font-size="12" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">62</text><rect x="196" y="232" width="56" height="28" rx="5" fill="rgba(16,185,129,0.20)" stroke="#10b981" stroke-width="1.6"/><text x="224" y="251" fill="#10b981" font-size="12" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">64</text><rect x="252" y="232" width="56" height="28" rx="5" fill="rgba(16,185,129,0.20)" stroke="#10b981" stroke-width="1.6"/><text x="280" y="251" fill="#10b981" font-size="12" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">71</text><rect x="308" y="232" width="56" height="28" rx="5" fill="rgba(16,185,129,0.20)" stroke="#10b981" stroke-width="1.6"/><text x="336" y="251" fill="#10b981" font-size="12" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">77</text><rect x="364" y="232" width="56" height="28" rx="5" fill="rgba(16,185,129,0.20)" stroke="#10b981" stroke-width="1.6"/><text x="392" y="251" fill="#10b981" font-size="12" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">88</text><text x="434" y="251" fill="#10b981" font-size="10.5" font-weight="400" text-anchor="start">all six frozen — done</text><text x="300" y="292" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-style="italic">Each pass scans the whole unsorted remainder — 5 + 4 + 3 + 2 + 1 = 15 comparisons —</text><text x="300" y="306" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-style="italic">and makes exactly one swap. Passes 4 and 5 change nothing and still cost the full scan.</text></svg></div></div><div class="callout" data-lb="key" style="border-left-color:#0ea5e9;"><div class="callout-label">▸ WORKED EXAMPLE — six temperatures, one pass at a time</div><pre style="background:var(--bg-2, var(--surface-2)); padding:12px; border-radius:8px; font-size:13px; overflow-x:auto; line-height:1.55;">int[] temps = { 71, 64, 88, 59, 77, 62 };

for (int i = 0; i &lt; temps.length - 1; i++) {
    int min = i;
    for (int j = i + 1; j &lt; temps.length; j++)
        if (temps[j] &lt; temps[min]) min = j;
    int t = temps[i]; temps[i] = temps[min]; temps[min] = t;
    System.out.println("pass " + (i + 1) + ": smallest of the rest is " + temps[i]
            + " (was at index " + min + ") -&gt; " + Arrays.toString(temps));
}</pre><div style="margin:10px 0; border-left:3px solid #10b981; border-radius:0 8px 8px 0; background:var(--surface-2); padding:9px 12px;"><div style="font-size:11.5px; font-weight:700; letter-spacing:.05em; opacity:.75; margin-bottom:5px;">what it prints</div><pre style="margin:0; font-size:12.6px; line-height:1.5; overflow-x:auto;">pass 1: smallest of the rest is 59 (was at index 3) -&gt; [59, 64, 88, 71, 77, 62]
pass 2: smallest of the rest is 62 (was at index 5) -&gt; [59, 62, 88, 71, 77, 64]
pass 3: smallest of the rest is 64 (was at index 5) -&gt; [59, 62, 64, 71, 77, 88]
pass 4: smallest of the rest is 71 (was at index 3) -&gt; [59, 62, 64, 71, 77, 88]
pass 5: smallest of the rest is 77 (was at index 4) -&gt; [59, 62, 64, 71, 77, 88]</pre></div><ol style="margin:8px 0 4px 20px; padding:0; line-height:1.75;"><li style="margin-bottom:5px;">Pass 1 finds 59 at index 3 and swaps it with index 0. Note what happens to the 71 that was there: it goes to index 3. The swap moves <em>two</em> elements, not one.</li><li style="margin-bottom:5px;">Pass 2 searches indices 1–5 only. The smallest is 62, at index 5; it swaps with 64, which lands at index 5.</li><li style="margin-bottom:5px;">After pass k the first k slots are final. Read the output down the left edge: 59, then 59 62, then 59 62 64 — the prefix grows by one and never changes again.</li><li style="margin-bottom:5px;">Passes 4 and 5 print an array identical to pass 3’s. The element was already in the right place, so the swap was with itself — and the full inner scan still happened.</li><li style="margin-bottom:5px;">Five passes for six elements. The last element needs no pass: once the first n−1 are the n−1 smallest, the leftover is the largest by elimination. That is why the outer loop stops at <code>length - 1</code>.</li></ol></div><div class="callout" data-lb="key" style="border-left-color:#0ea5e9;"><div class="callout-label">▸ WORKED EXAMPLE — the input makes no difference at all</div><p style="margin:10px 0; line-height:1.7;">The claim "O(n²) in every case" is easy to say and easy to doubt. Counting settles it.</p><pre style="background:var(--bg-2, var(--surface-2)); padding:12px; border-radius:8px; font-size:13px; overflow-x:auto; line-height:1.55;">int[][] inputs = {
    { 10, 20, 30, 40, 50, 60 },      // already sorted
    { 60, 50, 40, 30, 20, 10 },      // reverse sorted
    { 71, 64, 88, 59, 77, 62 }       // shuffled
};
String[] labels = { "already sorted", "reverse sorted", "shuffled" };
for (int k = 0; k &lt; inputs.length; k++) {
    comps = 0; swaps = 0;
    selectionSort(inputs[k].clone());    // the loop from the worked example above
    System.out.println(labels[k] + ": comparisons " + comps + ", swaps " + swaps);
}</pre><div style="margin:10px 0; border-left:3px solid #10b981; border-radius:0 8px 8px 0; background:var(--surface-2); padding:9px 12px;"><div style="font-size:11.5px; font-weight:700; letter-spacing:.05em; opacity:.75; margin-bottom:5px;">what it prints</div><pre style="margin:0; font-size:12.6px; line-height:1.5; overflow-x:auto;">already sorted: comparisons 15, swaps 5
reverse sorted: comparisons 15, swaps 5
shuffled: comparisons 15, swaps 5</pre></div><ol style="margin:8px 0 4px 20px; padding:0; line-height:1.75;"><li style="margin-bottom:5px;">Fifteen comparisons every time, and <code>n(n−1)/2 = 6×5/2 = 15</code>. The inner loop has no early exit — it always scans to the end of the array looking for a smaller value.</li><li style="margin-bottom:5px;">Five swaps every time: one per pass, whether or not anything needed moving. That is the algorithm’s one genuine virtue — at most n−1 swaps, which matters when a swap is expensive.</li><li style="margin-bottom:5px;">Already-sorted input costs exactly as much as reverse-sorted. Selection sort is <strong>not adaptive</strong>, which is the sharpest contrast with insertion sort in the next section.</li><li style="margin-bottom:5px;">Best = average = worst = O(n²). It is the only sort in this unit where all three are the same, and exam questions lean on that.</li></ol></div><div class="callout" data-lb="key" style="border-left-color:#f59e0b;"><div class="callout-label">⚠️ COMMON MISTAKE</div><p style="margin:10px 0; line-height:1.7;">Three specific slips. Forgetting <code>int min = i;</code> at the top of each pass carries the previous pass’s index forward and corrupts the array. Starting the inner loop at <code>j = 0</code> instead of <code>j = i + 1</code> re-finds an already-placed element and swaps the sorted prefix apart. And swapping inside the inner loop, rather than once after it, turns selection sort into a much slower bubble sort that still happens to produce the right answer — right output, wrong algorithm, and the "how many swaps" question will catch it.</p></div>"},"D286/u17/z17_7":{"body":"<p>Insertion sort takes each element and slides it back into the sorted portion, the way you sort a hand of cards. Unlike selection sort, its cost depends heavily on the input.</p><pre style="background:var(--bg-2, var(--surface-2)); padding:12px; border-radius:8px; font-size:13px; overflow-x:auto; line-height:1.55;">for (int i = 1; i &lt; a.length; i++) {
    int key = a[i];
    int j = i - 1;
    while (j &gt;= 0 &amp;&amp; a[j] &gt; key) {       // shift larger elements right
        a[j + 1] = a[j];
        j--;
    }
    a[j + 1] = key;                       // drop the key into the gap
}</pre><p>On already-sorted data the inner <code>while</code> never runs, so the whole thing is O(n) — the best case of any comparison sort. On reversed data it shifts everything every time, giving O(n²). That adaptivity is why real library sorts fall back to insertion sort for small or nearly-sorted segments.</p><pre style="background:var(--bg-2, var(--surface-2)); padding:12px; border-radius:8px; font-size:13px; overflow-x:auto; line-height:1.55;">for (int i = 1; i &lt; n; i++) {            // starts at 1 — a[0] is sorted alone
    int key = a[i], j = i - 1;
    while (j &gt;= 0 &amp;&amp; a[j] &gt; key) {       // j &gt;= 0 FIRST — short-circuit matters
        a[j + 1] = a[j];                 // shift right
        j--;
    }
    a[j + 1] = key;                      // drop it into the gap
}</pre><p>Insertion sort grows a sorted region at the front, taking each next element and shifting larger ones right to make room. It is what people actually do with a hand of cards.</p><p>Unlike selection sort it is <strong>adaptive</strong>: on already-sorted input the inner <code>while</code> never runs, giving O(n) best case, against O(n²) worst. That is why it is the algorithm real libraries switch to for small or nearly-sorted subarrays.</p><p>The condition order is not stylistic. <code>j &gt;= 0</code> must come first so short-circuit evaluation stops before <code>a[j]</code> is read with <code>j == -1</code> — the exact mechanism from 1.3, with an out-of-bounds crash as the penalty for reversing it.</p><p>It is stable, because it shifts only elements strictly greater than the key.</p><i data-d286u1619="1" style="display:none"></i><div class="callout" data-lb="why" style="border-left-color:#4f46e5;"><div class="callout-label">📘 DEFINITION</div><p style="margin:0 0 7px;"><strong>Insertion sort:</strong> insert each element into its place in the already-sorted prefix</p><p style="margin:0 0 7px;"><strong>Best case O(n):</strong> sorted input; each element is already in position</p><p style="margin:0 0 7px;"><strong>Adaptive:</strong> runs faster on partially sorted input</p><p style="margin:0 0 7px;"><strong>Stable:</strong> the strict &gt; comparison never moves an equal element past another</p></div><div class="callout" data-lb="oa" style="border-left-color:#e11d48;"><div class="callout-label">🎯 EXAM TIP</div><p>Selection sort versus insertion sort is a standard compare-and-contrast question. Both are O(n²) worst case; only insertion sort is O(n) at best, and only insertion sort is stable.</p></div><i data-tbD286dS177="1" style="display:none"></i><div class="vl" data-mathvis="1" data-c959fig="1" style="margin-top:18px;"><div style="font-weight:700; font-size:12.5px; letter-spacing:0.05em; margin-bottom:6px;">📊 FIGURE — INSERTION SORT: ONE PASS, IN THREE STAGES</div><div style="border:1px solid var(--border); border-radius:12px; background:var(--surface-2); padding:14px 10px; overflow-x:auto;"><svg viewBox="0 0 620 326" style="width:100%; max-width:660px; display:block; margin:0 auto; font-family:inherit;" xmlns="http://www.w3.org/2000/svg"><defs><marker id="fk293a" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0,1 L9,5 L0,9 z" fill="var(--text)"/></marker></defs><text x="40" y="20" fill="var(--text)" font-size="11.5" font-weight="700" text-anchor="start">① i = 3.  Lift the key out — index 3 is now a gap</text><rect x="40" y="30" width="58" height="30" rx="5" fill="rgba(16,185,129,0.18)" stroke="#10b981" stroke-width="1.4"/><text x="69" y="50" fill="#10b981" font-size="12.5" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">8</text><rect x="98" y="30" width="58" height="30" rx="5" fill="rgba(16,185,129,0.18)" stroke="#10b981" stroke-width="1.4"/><text x="127" y="50" fill="#10b981" font-size="12.5" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">23</text><rect x="156" y="30" width="58" height="30" rx="5" fill="rgba(16,185,129,0.18)" stroke="#10b981" stroke-width="1.4"/><text x="185" y="50" fill="#10b981" font-size="12.5" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">41</text><rect x="214" y="30" width="58" height="30" rx="5" fill="none" stroke="var(--text-3)" stroke-width="1.4" stroke-dasharray="4 3"/><rect x="272" y="30" width="58" height="30" rx="5" fill="var(--surface)" stroke="var(--text)" stroke-width="1.4"/><text x="301" y="50" fill="var(--text)" font-size="12.5" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">4</text><rect x="330" y="30" width="58" height="30" rx="5" fill="var(--surface)" stroke="var(--text)" stroke-width="1.4"/><text x="359" y="50" fill="var(--text)" font-size="12.5" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">16</text><rect x="214" y="88" width="58" height="30" rx="5" fill="rgba(232,121,90,0.24)" stroke="#e8795a" stroke-width="1.6"/><text x="243" y="108" fill="#e8795a" font-size="12.5" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">15</text><text x="284" y="108" fill="#e8795a" font-size="10.5" font-weight="400" text-anchor="start">key = 15, held in a variable</text><line x1="243" y1="84" x2="243" y2="64" stroke="#e8795a" stroke-width="1.3" marker-end="url(#fk293a)"/><text x="40" y="142" fill="var(--text)" font-size="11.5" font-weight="700" text-anchor="start">② Walk left while the neighbour is bigger, copying it one slot right</text><rect x="40" y="172" width="58" height="30" rx="5" fill="rgba(16,185,129,0.18)" stroke="#10b981" stroke-width="1.4"/><text x="69" y="192" fill="var(--text)" font-size="12.5" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">8</text><rect x="98" y="172" width="58" height="30" rx="5" fill="rgba(16,185,129,0.18)" stroke="#10b981" stroke-width="1.4"/><text x="127" y="192" fill="var(--text)" font-size="12.5" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">23</text><rect x="156" y="172" width="58" height="30" rx="5" fill="rgba(14,165,233,0.20)" stroke="#0ea5e9" stroke-width="1.4"/><text x="185" y="192" fill="var(--text)" font-size="12.5" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">23</text><rect x="214" y="172" width="58" height="30" rx="5" fill="rgba(14,165,233,0.20)" stroke="#0ea5e9" stroke-width="1.4"/><text x="243" y="192" fill="var(--text)" font-size="12.5" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">41</text><rect x="272" y="172" width="58" height="30" rx="5" fill="var(--surface)" stroke="var(--text)" stroke-width="1.4"/><text x="301" y="192" fill="var(--text)" font-size="12.5" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">4</text><rect x="330" y="172" width="58" height="30" rx="5" fill="var(--surface)" stroke="var(--text)" stroke-width="1.4"/><text x="359" y="192" fill="var(--text)" font-size="12.5" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">16</text><path d="M185,170 Q214,150 243,170" fill="none" stroke="#0ea5e9" stroke-width="1.5" marker-end="url(#fk293a)"/><text x="214" y="157.6" fill="#0ea5e9" font-size="10.5" font-weight="700" text-anchor="middle">41</text><text x="402" y="192" fill="#0ea5e9" font-size="10.5" font-weight="400" text-anchor="start">23 > 15, so 23 must move too</text><text x="40" y="236" fill="var(--text)" font-size="11.5" font-weight="700" text-anchor="start">③ 8 is not bigger than 15 — stop, and drop the key into the gap</text><rect x="40" y="246" width="58" height="30" rx="5" fill="rgba(16,185,129,0.18)" stroke="#10b981" stroke-width="1.4"/><text x="69" y="266" fill="#10b981" font-size="12.5" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">8</text><rect x="98" y="246" width="58" height="30" rx="5" fill="rgba(232,121,90,0.24)" stroke="#e8795a" stroke-width="1.4"/><text x="127" y="266" fill="#e8795a" font-size="12.5" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">15</text><rect x="156" y="246" width="58" height="30" rx="5" fill="rgba(16,185,129,0.18)" stroke="#10b981" stroke-width="1.4"/><text x="185" y="266" fill="#10b981" font-size="12.5" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">23</text><rect x="214" y="246" width="58" height="30" rx="5" fill="rgba(16,185,129,0.18)" stroke="#10b981" stroke-width="1.4"/><text x="243" y="266" fill="#10b981" font-size="12.5" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">41</text><rect x="272" y="246" width="58" height="30" rx="5" fill="var(--surface)" stroke="var(--text)" stroke-width="1.4"/><text x="301" y="266" fill="var(--text)" font-size="12.5" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">4</text><rect x="330" y="246" width="58" height="30" rx="5" fill="var(--surface)" stroke="var(--text)" stroke-width="1.4"/><text x="359" y="266" fill="var(--text)" font-size="12.5" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">16</text><text x="402" y="266" fill="#10b981" font-size="10.5" font-weight="400" text-anchor="start">sorted prefix is now four long</text><text x="300" y="300" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-style="italic">The green prefix is sorted but NOT final — a later key can still be inserted inside it.</text><text x="300" y="314" fill="var(--text-3)" font-size="10.5" font-weight="400" text-anchor="middle" font-style="italic">That is the difference from selection sort, where the prefix is finished for good.</text></svg></div></div><div class="callout" data-lb="key" style="border-left-color:#0ea5e9;"><div class="callout-label">▸ WORKED EXAMPLE — jersey numbers, one insertion at a time</div><pre style="background:var(--bg-2, var(--surface-2)); padding:12px; border-radius:8px; font-size:13px; overflow-x:auto; line-height:1.55;">int[] jerseys = { 23, 8, 41, 15, 4, 16 };

for (int i = 1; i &lt; jerseys.length; i++) {        // starts at 1
    int key = jerseys[i], j = i - 1;
    while (j &gt;= 0 &amp;&amp; jerseys[j] &gt; key) { jerseys[j + 1] = jerseys[j]; j--; }
    jerseys[j + 1] = key;
    System.out.println("i=" + i + " key=" + key + " -&gt; " + Arrays.toString(jerseys)
            + "   sorted prefix: "
            + Arrays.toString(Arrays.copyOfRange(jerseys, 0, i + 1)));
}</pre><div style="margin:10px 0; border-left:3px solid #10b981; border-radius:0 8px 8px 0; background:var(--surface-2); padding:9px 12px;"><div style="font-size:11.5px; font-weight:700; letter-spacing:.05em; opacity:.75; margin-bottom:5px;">what it prints</div><pre style="margin:0; font-size:12.6px; line-height:1.5; overflow-x:auto;">i=1 key=8 -&gt; [8, 23, 41, 15, 4, 16]   sorted prefix: [8, 23]
i=2 key=41 -&gt; [8, 23, 41, 15, 4, 16]   sorted prefix: [8, 23, 41]
i=3 key=15 -&gt; [8, 15, 23, 41, 4, 16]   sorted prefix: [8, 15, 23, 41]
i=4 key=4 -&gt; [4, 8, 15, 23, 41, 16]   sorted prefix: [4, 8, 15, 23, 41]
i=5 key=16 -&gt; [4, 8, 15, 16, 23, 41]   sorted prefix: [4, 8, 15, 16, 23, 41]</pre></div><ol style="margin:8px 0 4px 20px; padding:0; line-height:1.75;"><li style="margin-bottom:5px;">The loop starts at <code>i = 1</code> because a single element is already a sorted list of one — there is nothing for <code>i = 0</code> to do.</li><li style="margin-bottom:5px;">At <code>i = 2</code> the key is 41 and the neighbour 23 is smaller, so the <code>while</code> body never runs and the array is unchanged. Zero shifts for an element already in order.</li><li style="margin-bottom:5px;">At <code>i = 3</code> the key 15 walks past 41 and 23, shifting each one right, and lands between 8 and 23. Two shifts.</li><li style="margin-bottom:5px;">At <code>i = 4</code> the key 4 walks all the way to the front — four shifts, the most expensive insertion here.</li><li style="margin-bottom:5px;">Watch the prefix in the right-hand column: sorted at every step, and growing by one each pass. Unlike selection sort, its <em>contents</em> keep changing — 23 was in the prefix at i=1 and is still being pushed around at i=4.</li></ol></div><div class="callout" data-lb="key" style="border-left-color:#0ea5e9;"><div class="callout-label">▸ WORKED EXAMPLE — why libraries switch to insertion sort for small runs</div><pre style="background:var(--bg-2, var(--surface-2)); padding:12px; border-radius:8px; font-size:13px; overflow-x:auto; line-height:1.55;">int[][] inputs = {
    { 4, 8, 15, 16, 23, 41 },      // already sorted
    { 41, 23, 16, 15, 8, 4 },      // reverse sorted
    { 23, 8, 41, 15, 4, 16 }       // shuffled
};
String[] labels = { "already sorted", "reverse sorted", "shuffled" };
for (int k = 0; k &lt; inputs.length; k++) {
    shifts = 0;
    insertionSort(inputs[k].clone());   // counting every a[j + 1] = a[j]
    System.out.println(labels[k] + ": elements shifted " + shifts);
}</pre><div style="margin:10px 0; border-left:3px solid #10b981; border-radius:0 8px 8px 0; background:var(--surface-2); padding:9px 12px;"><div style="font-size:11.5px; font-weight:700; letter-spacing:.05em; opacity:.75; margin-bottom:5px;">what it prints</div><pre style="margin:0; font-size:12.6px; line-height:1.5; overflow-x:auto;">already sorted: elements shifted 0
reverse sorted: elements shifted 15
shuffled: elements shifted 9</pre></div><ol style="margin:8px 0 4px 20px; padding:0; line-height:1.75;"><li style="margin-bottom:5px;">Already sorted costs <strong>zero</strong> shifts. Every key is bigger than its left neighbour, so the <code>while</code> condition fails immediately and the pass is a single comparison — the whole sort is O(n).</li><li style="margin-bottom:5px;">Reverse sorted costs 15 = <code>n(n−1)/2</code>: every key has to travel to the front. That is the O(n²) worst case.</li><li style="margin-bottom:5px;">Shuffled sits between them at 9. The work is proportional to how out of order the data actually is, which is the definition of <strong>adaptive</strong>.</li><li style="margin-bottom:5px;">Compare with selection sort’s 15 comparisons on all three inputs. This difference — not the Big-O, which is the same — is why real library sorts fall back to insertion sort on small or nearly-ordered runs.</li></ol></div><div class="callout" data-lb="key" style="border-left-color:#f59e0b;"><div class="callout-label">⚠️ COMMON MISTAKE</div><p style="margin:10px 0; line-height:1.7;">Swap the two halves of the <code>while</code> condition and the sort crashes. <code>while (a[j] &gt; key &amp;&amp; j &gt;= 0)</code> reads <code>a[-1]</code> as soon as a key belongs at the front, and Java confirms it: <code>ArrayIndexOutOfBoundsException: Index -1 out of bounds for length 2</code>. The guard must come first so <code>&amp;&amp;</code> short-circuits before the array is touched. The other slip is writing <code>a[j] = key</code> at the end instead of <code>a[j + 1] = key</code> — the loop leaves <code>j</code> one position <em>past</em> the gap, and using it directly overwrites a value you just shifted.</p></div>"},"D286/u17/z17_8":{"body":"<p>Quicksort partitions around a pivot: smaller elements to the left, larger to the right, then sorts each side recursively. The partition step is what does the work, and the recursion just repeats it.</p><pre style="background:var(--bg-2, var(--surface-2)); padding:12px; border-radius:8px; font-size:13px; overflow-x:auto; line-height:1.55;">void quicksort(int[] a, int lo, int hi) {
    if (lo &gt;= hi) { return; }              // base case (11.1)
    int p = partition(a, lo, hi);
    quicksort(a, lo, p - 1);
    quicksort(a, p + 1, hi);
}

int partition(int[] a, int lo, int hi) {
    int pivot = a[hi];
    int i = lo - 1;
    for (int j = lo; j &lt; hi; j++) {
        if (a[j] &lt; pivot) { i++; swap(a, i, j); }
    }
    swap(a, i + 1, hi);
    return i + 1;                          // the pivot’s final position
}</pre><p>Average case is O(n log n) and in place. The worst case is O(n²), and it happens on <em>already-sorted</em> data with a last-element pivot — every partition puts nothing on one side. Choosing a random or median pivot is the standard defence.</p><pre style="background:var(--bg-2, var(--surface-2)); padding:12px; border-radius:8px; font-size:13px; overflow-x:auto; line-height:1.55;">static void quicksort(int[] a, int lo, int hi) {
    if (lo &gt;= hi) return;                     // base case
    int p = partition(a, lo, hi);             // the WORK happens here, before
    quicksort(a, lo, p - 1);
    quicksort(a, p + 1, hi);                  // p is already in its final place
}</pre><p>Choose a pivot, partition so everything smaller is left of it and everything larger is right, then recurse on the two sides. The pivot lands in its final position immediately and is excluded from both recursive calls — which is what guarantees progress.</p><p>Average O(n log n) and in place with O(log n) stack. Worst case <strong>O(n²)</strong>, and the input that triggers it is the surprising one: already sorted data with a first-or-last pivot, which splits off one element at a time. Random or median-of-three pivot selection is the standard defence.</p><p>Quicksort does its work <em>before</em> recursing; merge sort does it after. That one sentence separates them, and it is the usual exam question.</p><p>It is not stable.</p><i data-d286u1619="1" style="display:none"></i><div class="callout" data-lb="why" style="border-left-color:#4f46e5;"><div class="callout-label">📘 DEFINITION</div><p style="margin:0 0 7px;"><strong>Quicksort:</strong> partition around a pivot, then sort each side recursively</p><p style="margin:0 0 7px;"><strong>Pivot:</strong> the element everything is compared against</p><p style="margin:0 0 7px;"><strong>Partition:</strong> rearranging so smaller elements precede the pivot and larger follow it</p><p style="margin:0 0 7px;"><strong>Worst case O(n²):</strong> consistently unbalanced partitions, as with sorted input and a poor pivot</p></div><div class="callout" data-lb="warn" style="border-left-color:#f59e0b;"><div class="callout-label">⚠ COMMON MISTAKE</div><p>Quicksort being "fastest" is only true on average. Its worst case is the same as selection sort’s, and the input that triggers it — sorted data — is common in practice.</p></div><i data-tbD286dS178="1" style="display:none"></i><div class="vl" data-mathvis="1" data-c959fig="1" style="margin-top:18px;"><div style="font-weight:700; font-size:12.5px; letter-spacing:0.05em; margin-bottom:6px;">📊 FIGURE — PARTITION: THE PIVOT FINDS ITS FINAL SLOT IN ONE PASS</div><div style="border:1px solid var(--border); border-radius:12px; background:var(--surface-2); padding:14px 10px; overflow-x:auto;"><svg viewBox="0 0 700 310" style="width:100%; max-width:720px; display:block; margin:0 auto; font-family:inherit;" xmlns="http://www.w3.org/2000/svg"><defs><marker id="fk294a" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0,1 L9,5 L0,9 z" fill="var(--text)"/></marker></defs><text x="46" y="20" fill="var(--text)" font-size="11" font-weight="700" text-anchor="start">pivot = 31 (the last element). Walk j left to right; everything ≤ 31 gets swapped to the front.</text><rect x="46" y="40" width="58" height="28" rx="5" fill="var(--surface)" stroke="var(--text)" stroke-width="1.2"/><text x="75" y="59" fill="var(--text)" font-size="12" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">38</text><rect x="104" y="40" width="58" height="28" rx="5" fill="var(--surface)" stroke="var(--text)" stroke-width="1.2"/><text x="133" y="59" fill="var(--text)" font-size="12" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">12</text><rect x="162" y="40" width="58" height="28" rx="5" fill="var(--surface)" stroke="var(--text)" stroke-width="1.2"/><text x="191" y="59" fill="var(--text)" font-size="12" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">55</text><rect x="220" y="40" width="58" height="28" rx="5" fill="var(--surface)" stroke="var(--text)" stroke-width="1.2"/><text x="249" y="59" fill="var(--text)" font-size="12" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">27</text><rect x="278" y="40" width="58" height="28" rx="5" fill="var(--surface)" stroke="var(--text)" stroke-width="1.2"/><text x="307" y="59" fill="var(--text)" font-size="12" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">44</text><rect x="336" y="40" width="58" height="28" rx="5" fill="var(--surface)" stroke="var(--text)" stroke-width="1.2"/><text x="365" y="59" fill="var(--text)" font-size="12" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">19</text><rect x="394" y="40" width="58" height="28" rx="5" fill="rgba(139,92,246,0.24)" stroke="#8b5cf6" stroke-width="1.6"/><text x="423" y="59" fill="#8b5cf6" font-size="12" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">31</text><text x="75" y="36" fill="#0ea5e9" font-size="9.5" font-weight="700" text-anchor="middle">j</text><text x="464" y="59" fill="var(--text-3)" font-size="10" font-weight="400" text-anchor="start">j=0: 38 > 31 — leave it</text><rect x="46" y="82" width="58" height="28" rx="5" fill="rgba(16,185,129,0.20)" stroke="#10b981" stroke-width="1.6"/><text x="75" y="101" fill="#10b981" font-size="12" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">12</text><rect x="104" y="82" width="58" height="28" rx="5" fill="var(--surface)" stroke="var(--text)" stroke-width="1.2"/><text x="133" y="101" fill="var(--text)" font-size="12" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">38</text><rect x="162" y="82" width="58" height="28" rx="5" fill="var(--surface)" stroke="var(--text)" stroke-width="1.2"/><text x="191" y="101" fill="var(--text)" font-size="12" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">55</text><rect x="220" y="82" width="58" height="28" rx="5" fill="var(--surface)" stroke="var(--text)" stroke-width="1.2"/><text x="249" y="101" fill="var(--text)" font-size="12" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">27</text><rect x="278" y="82" width="58" height="28" rx="5" fill="var(--surface)" stroke="var(--text)" stroke-width="1.2"/><text x="307" y="101" fill="var(--text)" font-size="12" font-weight="700" text-anchor="middle" font-family="ui-monospace,Menlo,monospace">44</text><rect x="336" y=