ter list","different parameters","a different return type only"],"correct":1,"explain":"Override = same name and parameter list as the parent method.","__rebal":1}],"D286/cheat/s4":[{"id":"q1","topic":"2D dimensions","text":"int[][] grid = new int[4][6]; grid.length is:","options":["24","4","6","10"],"correct":1,"explain":"grid.length = number of rows = 4. grid[0].length = columns = 6.","distractors":{"0":"4×6=24 is total elements.","1":"grid[0].length = 6 (columns).","2":"4+6=10 is sum."},"__rebal":1},{"id":"q3","topic":"array.length","text":"int[] arr = {5,10,15,20}; arr.length is:","options":["arr.length()","4","5","3"],"correct":1,"explain":"arr.length (no parentheses) = 4 — number of elements.","distractors":{"1":"5 is not the length.","2":"3 = last valid index.","3":"length is property, not method."},"__rebal":1},{"id":"q10","topic":"length trio","text":"The correct trio is:","options":["array.length / string.length() / list.size()","All three use .length()","array.size() / string.length() / list.length","array.length() / string.length / list.size()"],"correct":0,"explain":"Array length is a FIELD (no parens); String length() is a method; ArrayList size() is a method. Mixing them up is a top compile-error source.","distractors":{"0":"Arrays don't have size(); lists don't have length.","1":"Only String uses length().","3":"Reversed — array has no parens, String does."},"__rebal":1},{"id":"m17","topic":"IOException","text":"IOException is:","options":["a RuntimeException","unchecked","not an exception","checked"],"correct":3,"explain":"IOException is a checked exception.","__rebal":1},{"id":"q5","topic":"Checked handling","text":"For a method that reads a file, the compiler requires you to:","options":["catch RuntimeException around the file access","declare the method static so it can throw","catch IOException or declare throws IOException","nothing; IOException is unchecked in Java"],"correct":2,"explain":"IOException/FileNotFoundException are checked, so you must catch them or add throws to the method signature.","__rebal":1},{"id":"q2","topic":"ArrayList size after adds","text":"ArrayList&lt;String> list = new ArrayList&lt;>(); list.add('A'); list.add('B'); list.add(0,'Z'); list.size() is:","options":["1","2","3","4"],"correct":2,"explain":"3 add operations → size 3.","distractors":{"1":"All three succeed.","2":"Three adds occurred.","3":"Only 3 added."},"__rebal":1},{"id":"q6","topic":"for-each sum","text":"int[] nums = {2,4,6}; for(int n : nums) sum += n; sum is?","options":["12","3","246","6"],"correct":0,"explain":"2+4+6 = 12.","distractors":{"0":"Only first two.","1":"That's the count.","3":"Concatenation, not sum."},"__rebal":1},{"id":"u09","topic":"Array stats","text":"For array max/min you should initialize max and min to:","options":["arr[0]","1","Integer.MAX_VALUE for max","0"],"correct":0,"explain":"Seed with the first element so negatives are handled.","__rebal":1},{"id":"tp3","topic":"Divide by zero","text":"int x = 5 / 0; throws:","options":["ArithmeticException","IOException","no exception","NullPointerException"],"correct":0,"explain":"Integer division by zero throws ArithmeticException.","__rebal":1},{"id":"q4","topic":"Missing file","text":"Reading a file that doesn't exist throws which checked exception?","options":["NullPointerException","FileNotFoundException","ArithmeticException","ArrayIndexOutOfBoundsException"],"correct":1,"explain":"Opening a non-existent file for reading throws FileNotFoundException, a checked exception you must handle or declare.","distractors":{"0":"NPE is unchecked and unrelated.","2":"That's for arrays.","3":"That's for math like divide-by-zero."},"__rebal":1}],"D286/cheat/s5":[{"id":"px286_over_8","topic":"To call a parent's overridden method from a chil","text":"To call a parent's overridden method from a child, you use:","options":["super.method()","base.method()","this.method()","parent.method()"],"correct":0,"explain":"super.method() invokes the superclass's version.","distractors":{"0":"this.method() would call the child's own (overriding) version, causing recursion, not the parent's.","2":"this.method() would call the child's own (overriding) version, causing recursion, not the parent's.","3":"this.method() would call the child's own (overriding) version, causing recursion, not the parent's."},"_practice":true,"__rebal":1},{"id":"p11","topic":"Abstract contents","text":"An abstract class:","options":["can have abstract methods only, never concrete","can have both abstract and concrete methods","can have concrete methods only, never abstract","can be instantiated directly with new"],"correct":1,"explain":"Abstract classes can mix abstract and concrete methods.","__rebal":1},{"id":"px286_inh_1","topic":"Which keyword makes class  Dog  inherit from cla","text":"Which keyword makes class  Dog  inherit from class  Animal ?","options":["Dog inherits Animal","Dog extends Animal","Dog : Animal","Dog implements Animal"],"correct":1,"explain":"A class inherits from another using extends: class Dog extends Animal.","distractors":{"0":"implements is for interfaces; extends is for class inheritance.","2":"implements is for interfaces; extends is for class inheritance.","3":"implements is for interfaces; extends is for class inheritance."},"_practice":true,"__rebal":1},{"id":"tuw1_d286_u2_5","topic":"equals signature","text":"The correct signature to override equals is:","options":["public boolean equals(Object o)","int equals(Object o)","void equals(Object o)","boolean equals(MyType o)"],"correct":0,"explain":"It must be public boolean equals(Object o); using a parameter other than Object overloads rather than overrides."},{"id":"q5","topic":"Anonymous class","text":"What is an anonymous class?","options":["A class whose methods all have completely empty bodies","A class with no name, declared and created in one expression","A class declared inside a method and given a name","A class that cannot be instantiated at all, ever"],"correct":1,"explain":"An anonymous class is defined and instantiated at once with no name, usually to implement an interface/extend a class inline.","__rebal":1},{"id":"o19","topic":"Polymorphic array","text":"Animal[] zoo = {new Dog(), new Cat()}; for(Animal x:zoo) x.speak(); calls:","options":["Animal’s speak() each time","each object’s own speak()","nothing","a compile error"],"correct":1,"explain":"Each element dispatches to its actual type’s method.","__rebal":1},{"id":"p15","topic":"Multiple interfaces","text":"A class can:","options":["implement only one","implement many interfaces","not use interfaces","extend many classes"],"correct":1,"explain":"A class may implement multiple interfaces.","__rebal":1},{"id":"n13","topic":"Construction order","text":"When new Dog() runs (Dog extends Animal), constructors run:","options":["only child","child first","parent first, then child","only parent"],"correct":2,"explain":"Construction is top-down: the parent constructor runs first.","__rebal":1},{"id":"q6_d2","topic":"equals signature","text":"What is the correct signature to OVERRIDE equals?","options":["public boolean equals(Point p)","public void equals(Object o)","public int equals(Object o)","public boolean equals(Object o)"],"correct":3,"explain":"Overriding requires the exact inherited signature: public boolean equals(Object o). A different parameter type only overloads.","distractors":{"0":"Parameter must be Object, or it just overloads.","2":"Return type must be boolean.","3":"Return type must be boolean, not void."},"__rebal":1},{"id":"tuw1_d286_u5_6","topic":"Local class","text":"A local class is a class declared:","options":["At the top level","In another package","Inside a method body","As an interface"],"correct":2,"explain":"A local class is defined within a method and is visible only inside that method."}],"D286/u1/z1_1":[{"id":"zya1_1_0","topic":"Program definition","text":"A computer program is best described as:","options":["A physical component inside the computer","A file that stores user data","A network connection between machines","A sequence of instructions a computer executes"],"correct":3,"explain":"A program is an ordered sequence of instructions. The hardware executes them; the program itself is not hardware and is not merely stored data."},{"id":"zya1_1_1","topic":"Source vs machine code","text":"What is the relationship between source code and machine code?","options":["Machine code is written first, then translated to source code","Source code runs directly on the CPU","They are two names for the same file","Source code is human-readable; machine code is what the processor executes"],"correct":3,"explain":"Programmers write human-readable source code. A compiler or interpreter turns it into machine code (in Java, into bytecode first). The CPU only executes machine code."},{"id":"zya1_1_3","topic":"Program vs algorithm","text":"What distinguishes a program from an algorithm?","options":["An algorithm must contain loops; a program need not","There is no difference","A program is shorter","A program is an algorithm expressed in a specific programming language"],"correct":3,"explain":"The algorithm is the idea; the program is one concrete expression of it in a language a computer can run."},{"id":"zya1_1_4","topic":"Deterministic execution","text":"A computer executing a correct program with the same input twice will:","options":["Produce output only the first time","Refuse to run the second time","Sometimes produce different output because of processor speed","Produce the same output both times"],"correct":3,"explain":"Computers are deterministic: same program, same input, same result. Apparent randomness comes from something in the input changing — a random seed, a clock reading, user input."},{"id":"zya1_1_5","topic":"Why precision matters","text":"Why must program instructions be unambiguous?","options":["Because the compiler asks the user to clarify","Because ambiguity uses more memory","Because ambiguous instructions run slowly","Because the computer cannot infer intent"],"correct":3,"explain":"This is the core difference from human instruction-giving. The machine has no judgment to fall back on; anything unstated is simply not done. It does exactly what is written."},{"id":"zya1_1_6","topic":"Input-process-output","text":"Nearly every beginning program follows which shape?","options":["Processing only","Input and output with no processing","Output, then input, then processing","Input, then processing, then output"],"correct":3,"explain":"Read the data, compute something from it, report the result. Recognizing this shape makes unfamiliar problems easier to start."},{"id":"zya1_1_7","topic":"Hardware vs software","text":"Which of the following is software?","options":["A hard drive","The CPU","RAM","A compiler"],"correct":3,"explain":"A compiler is a program — software. CPU, RAM and drives are physical hardware."},{"id":"zya1_1_8","topic":"Programming language purpose","text":"A programming language exists primarily to:","options":["Let machines translate one human language into another one","Let hardware describe its own capabilities to the software","Let humans express instructions precisely enough for a machine to execute","Let a computer decide for itself which task to perform next"],"correct":2,"explain":"Languages are a human convenience layer. The machine would be satisfied with binary; the language exists so people can write and read the logic."},{"id":"q3","topic":"JVM role","text":".class file runs on Windows, macOS, Linux without recompilation. What makes this possible?","options":["Java source runs directly","Each OS has its own JVM executing the same bytecode",".class is executable for all OSes","OS auto-converts bytecode"],"correct":1,"explain":"Each OS has a JVM that interprets/JIT-compiles the same bytecode.","distractors":{"0":"Bytecode is not a native executable.","1":"JVM converts, not the OS.","2":"Source requires compilation."},"__rebal":1},{"id":"q5","topic":"javac","text":"Which JDK tool translates .java source to .class bytecode?","options":["jvm","java (launcher)","javadoc","javac (compiler)"],"correct":3,"explain":"javac is the Java compiler: source.java → bytecode.class.","distractors":{"0":"java executes bytecode.","2":"JVM is the virtual machine.","3":"javadoc generates API docs."},"__rebal":1},{"id":"q6","topic":"Run only","text":"Production server only runs pre-compiled Java application. Install?","options":["JRE","Source compiler","JDK","javac only"],"correct":0,"explain":"JRE sufficient to run Java. JDK adds compilation tools not needed in production.","distractors":{"0":"Not a valid installation option.","1":"javac is part of JDK; JRE is the choice.","3":"JDK includes unnecessary dev tools."},"__rebal":1},{"id":"q8","topic":"Java execution flow","text":"Correct Java execution flow:","options":["JVM → javac → source.java","bytecode.class → javac → JVM","source.java → bytecode.class → JVM executes","source.java → binary.exe → runs"],"correct":2,"explain":"Write .java → compile with javac to .class → JVM executes .class.","distractors":{"0":"javac compiles source; JVM runs bytecode.","1":"Java produces bytecode, not .exe.","3":"Reversed order."},"__rebal":1},{"id":"a10","topic":"JRE contents","text":"The JRE consists of:","options":["the JVM plus the standard class libraries","the JVM plus the compiler and developer tools","the compiler alone, without any runtime","the bytecode verifier and the source files"],"correct":0,"explain":"JRE = JVM + core class libraries (enough to run, not develop).","__rebal":1},{"id":"a11","topic":"javac","text":"The javac tool translates:","options":[".java into an .exe",".java source into .class bytecode",".class into machine code","bytecode into .java"],"correct":1,"explain":"javac compiles .java source files into .class bytecode.","__rebal":1},{"id":"a12","topic":"Run command","text":"To run a compiled class Hello.class, the command is:","options":["run Hello.java","java Hello.class","javac Hello","java Hello"],"correct":3,"explain":"Run with java Hello — no .class extension.","__rebal":1},{"id":"a14","topic":"main: static","text":"main is declared static so that:","options":["the JVM can call it without creating an object","the JVM can call it before the class is loaded","it can be overridden by any subclass","it can access the instance fields directly"],"correct":0,"explain":"static lets the JVM invoke main before any object exists.","__rebal":1},{"id":"a15","topic":"main: void","text":"The void in main means:","options":["main returns nothing to the JVM","main takes no arguments","main is abstract","main returns an int"],"correct":0,"explain":"void means main hands no return value back to the JVM.","__rebal":1},{"id":"a16","topic":"main: args","text":"In public static void main(String[] args), args holds:","options":["the command-line arguments","the return value","system properties","the class name"],"correct":0,"explain":"args receives command-line arguments (java Hello a b → {"a","b"}).","__rebal":1},{"id":"a17","topic":"File name","text":"A file containing public class Hello must be named:","options":["Hello.class","hello.java","Main.java","Hello.java"],"correct":3,"explain":"The file name must exactly match the public class name.","__rebal":1},{"id":"a19","topic":"Compile vs runtime","text":"Accessing a[5] on a size-3 array is:","options":["a syntax error","a runtime error","a compile-time error","caught by javac"],"correct":1,"explain":"Bad array indices are discovered while running — a runtime exception.","__rebal":1},{"id":"a20","topic":"JDK use","text":"To both write and run Java programs you install:","options":["the JDK","the JVM","the JRE","bytecode"],"correct":0,"explain":"The JDK adds the compiler and tools needed to develop.","__rebal":1},{"id":"a21","topic":"JRE use","text":"A production server that only runs (never develops) Java needs:","options":["the JDK","javac","the JRE","a debugger"],"correct":2,"explain":"Running only requires the JRE; the compiler is unnecessary.","__rebal":1},{"id":"a22","topic":"JIT","text":"The JIT compiler improves performance by:","options":["compiling frequently-run bytecode to native machine code","compiling source code to bytecode before execution","checking bytecode for safety before it runs","reclaiming memory from objects no longer used"],"correct":0,"explain":"The JIT compiles hot bytecode paths to native code for speed.","__rebal":1},{"id":"a23","topic":"Execution flow","text":"The correct Java pipeline is:","options":["source.java → JVM → bytecode.class → javac","source.java → javac → bytecode.class → JVM","source.class → javac → bytecode.java → JVM","source.java → JIT → machine code → javac"],"correct":1,"explain":"You compile source to bytecode, then the JVM executes it.","__rebal":1},{"id":"a24","topic":"Misspelled main","text":"Misspelling main as Main causes:","options":["a warning","nothing, it still runs","a compile error","a runtime error"],"correct":3,"explain":"It compiles, but the JVM can’t find main → runtime error. Main method not found.","__rebal":1},{"id":"px286_jvm_1","topic":"Which tool is required to COMPILE Java source co","text":"Which tool is required to COMPILE Java source code into bytecode?","options":["The JDK (javac)","The JVM","The JRE","A web browser"],"correct":0,"explain":"Compilation needs javac, which ships with the JDK; the JRE and JVM only run bytecode.","distractors":{"0":"The JRE can RUN programs but contains no compiler — it cannot turn .java into .class.","1":"The JRE can RUN programs but contains no compiler — it cannot turn .java into .class.","3":"The JRE can RUN programs but contains no compiler — it cannot turn .java into .class."},"_practice":true,"__rebal":1},{"id":"px286_jvm_2","topic":"What does the JVM actually execute","text":"What does the JVM actually execute?","options":["HTML","Bytecode (.class files)","Machine code written by the programmer","Java source code directly"],"correct":1,"explain":"The JVM executes platform-neutral bytecode produced by the compiler.","distractors":{"0":"The JVM never runs .java source directly — that must be compiled to bytecode first.","2":"The JVM never runs .java source directly — that must be compiled to bytecode first.","3":"The JVM never runs .java source directly — that must be compiled to bytecode first."},"_practice":true,"__rebal":1},{"id":"j1a1","topic":"Compilation","text":"The Java compiler (javac) turns .java source into:","options":["native machine code for the current processor","an executable that runs without any runtime","platform-independent bytecode (.class)","an intermediate C file compiled by the OS"],"correct":2,"explain":"javac produces bytecode that the JVM then executes, enabling ‘write once, run anywhere’.","__rebal":1}],"D286/u1/z1_3":[{"id":"zya1_3_0","topic":"Line comment","text":"Which symbol begins a single-line comment in Java?","options":["#","//","/*","--"],"correct":1,"explain":"// comments out the rest of that line. /* */ is the multi-line form; # and -- are comments in other languages, not Java."},{"id":"zya1_3_1","topic":"Block comment","text":"What does /* ... */ do?","options":["Comments out everything between the markers, over many lines","Comments out the rest of the current line only","Marks a documentation block the compiler reads","Groups statements into a block for the compiler"],"correct":0,"explain":"Block comments span lines. The compiler ignores everything from /* to the first */."},{"id":"zya1_3_2","topic":"Javadoc comment","text":"A comment beginning with /** is:","options":["A syntax error","A Javadoc comment that documentation tools can extract","Executed at runtime","The same as // to the compiler only"],"correct":1,"explain":"To the compiler /** behaves like an ordinary block comment, but the javadoc tool reads it and generates API documentation from it — which is why @param and @return live there."},{"id":"zya1_3_3","topic":"Comment effect on execution","text":"What effect do comments have on a running program?","options":["They slow it down slightly","They are removed at compile time and have no runtime effect","They are printed to the console","They increase memory usage"],"correct":1,"explain":"Comments never reach the bytecode. Write as many as clarity requires — they cost nothing at runtime."},{"id":"zya1_3_4","topic":"Whitespace significance","text":"In Java, does indentation change the meaning of code?","options":["Yes — like Python, blocks are defined by indentation","No — blocks are defined by braces; indentation is for humans","Yes, but only inside loops","Only in switch statements"],"correct":1,"explain":"Java is free-form: braces delimit blocks. Indentation is convention, not syntax — which means badly indented code can still compile and mislead you about what a block contains."},{"id":"zya1_3_5","topic":"Statement termination","text":"What actually ends a Java statement?","options":["A newline","A semicolon","A closing brace","A period"],"correct":1,"explain":"The semicolon. This is why one statement can wrap across several lines, and why a missing semicolon reports an error on the following line."},{"id":"zya1_3_6","topic":"Good comment content","text":"Which comment is most useful?","options":["// i++","// skip the header row","// this is a loop","// increment i by 1"],"correct":1,"explain":"Comments should explain WHY, not restate the syntax. The reader can see that i++ increments; what they cannot see is the reason. Is not data."},{"id":"zya1_3_7","topic":"Commenting out code","text":"A programmer wraps a block in /* */ to test without it. This is:","options":["A compile error, since blocks cannot be commented","A way to make the code run faster while testing","A documentation comment the compiler extracts","A common debugging technique that disables the code"],"correct":3,"explain":"Temporarily disabling code is a legitimate debugging move, though nested /* */ do not work — a /* inside the block ends at the first */."},{"id":"zya1_3_8","topic":"Comment placement","text":"Where does a comment describing a method conventionally go?","options":["After the closing brace","Inside the method body at the end","Immediately above the method signature","In a separate file"],"correct":2,"explain":"Documentation goes directly above what it documents, so it stays attached when code moves."},{"id":"n_n1_3_a","topic":"Comments","text":"Which is a valid single-line comment in Java?","options":["// note","# note","-- note","<!-- note -->"],"correct":0,"explain":"// begins a comment that runs to the end of the line. # is Python, -- is SQL, and <!-- --> is HTML."},{"id":"n_n1_3_b","topic":"Comments","text":"A block comment is written as:","options":["// ... //","{- ... -}","""" ... """","/* ... */"],"correct":3,"explain":"/* opens and */ closes, and it may span many lines. Block comments do not nest in Java."},{"id":"n_n1_3_c","topic":"Comments","text":"A Javadoc comment starts with:","options":["/***","/**","/*","//"],"correct":1,"explain":"The extra asterisk is what the javadoc tool looks for when it generates API documentation."},{"id":"n_n1_3_d","topic":"Whitespace","text":"Java treats extra spaces and newlines between tokens as:","options":["A syntax error","Significant, as in Python","String content","Insignificant"],"correct":3,"explain":"Java is free-form. Indentation is for humans; the compiler needs only the semicolons and braces. That is exactly why a consistent style matters. They only affect readability."},{"id":"n_n1_3_e","topic":"Whitespace","text":"Where does whitespace change the meaning of a program?","options":["Before a closing brace","Inside a string literal","Between statements","Around operators"],"correct":1,"explain":""a b" and "ab" are different strings. Everywhere else, spacing is free."},{"id":"n_n1_3_f","topic":"Comments","text":"Why comment out a line of code while debugging?","options":["To make it run faster","To hide it from the user","To convert it into documentation","To disable it without deleting it"],"correct":3,"explain":"Commenting is a reversible experiment. Deleting is not, and reconstructing a deleted line under time pressure is where mistakes get made. The change is easy to undo."},{"id":"zf18","topic":"","text":"A // comment extends:","options":["to the next semicolon","to the end of the current line","to the closing brace","across multiple lines until */"],"correct":1,"explain":"Single-line comments stop at the line break.","difficulty":"medium"},{"id":"zf19","topic":"","text":"A /* ... */ comment:","options":["must fit on one line","is required before every method","can span multiple lines","is printed when the program runs"],"correct":2,"explain":"Block comments run from /* to the next */, across as many lines as needed.","difficulty":"medium"},{"id":"zf20","topic":"","text":"What effect do comments have on a compiled program?","options":["They slow the program down slightly","They are printed at the start of execution","None - the compiler ignores them completely","They increase the .class file size in proportion"],"correct":2,"explain":"Comments exist for human readers; the compiler strips them.","difficulty":"medium"},{"id":"zf21","topic":"","text":"Extra spaces and blank lines outside of string literals:","options":["cause compile errors","change the program output","are only allowed inside main","are ignored by the compiler"],"correct":3,"explain":"Whitespace between tokens is for readability; the compiler does not care.","difficulty":"medium"},{"id":"zf22","topic":"","text":"Why does text inside "quotes" keep its exact spacing?","options":["String literals are output character-for-character","The compiler reformats string literals","Quotes remove all spaces","Spacing in strings is random"],"correct":0,"explain":"Inside a string literal, every space is part of the data.","difficulty":"medium"},{"id":"zf23","topic":"","text":"The main purpose of indentation in Java is to:","options":["tell the compiler where blocks end","show the structure of the code to human readers","make the program run faster","separate statements instead of semicolons"],"correct":1,"explain":"Unlike Python, Java braces define blocks - indentation is purely for people.","difficulty":"medium"},{"id":"zf24","topic":"","text":"Which is a correctly written comment?","options":["\\ totals the daily sales","/* totals the daily sales","// totals the daily sales","# totals the daily sales"],"correct":2,"explain":"Java uses // for line comments; /* must be closed with */ and # and \\ are not comment markers.","difficulty":"medium"},{"id":"zf25","topic":"","text":"The text System.out.println("// hello"); prints:","options":["hello","nothing - it is all comment","a compile error message","// hello"],"correct":3,"explain":"Inside a string literal, // is just two characters, not a comment.","difficulty":"medium"},{"id":"zf26","topic":"","text":"The best comments explain:","options":["why the code does what it does","what each obvious statement literally says","who wrote every line and when they had lunch","how to spell each variable"],"correct":0,"explain":"Restating the code adds noise; recording intent adds value.","difficulty":"medium"},{"id":"zf27","topic":"","text":"Can block comments be nested, as in /* outer /* inner */ still outer? */","options":["Yes - Java matches them like braces","No - the first */ ends the comment","Yes, but only two levels deep","Only inside methods"],"correct":1,"explain":"Block comments end at the FIRST */; the leftover text is parsed as code and fails.","difficulty":"medium"}],"D286/u1/z1_4":[{"id":"zya1_4_0","topic":"Error categories","text":"The three error categories in Java are:","options":["Syntax, runtime, and logic","Fatal, warning, and notice","Compile, link, and load","Hardware, software, and user"],"correct":0,"explain":"Syntax errors break the compile. Runtime errors crash a running program. Logic errors run to completion and produce wrong answers — the hardest to detect."},{"id":"zya1_4_1","topic":"Syntax error detection","text":"A missing semicolon is detected:","options":["At compile time, before the program runs","Only if the line is reached","By the JVM garbage collector","At runtime, when that line executes"],"correct":0,"explain":"Syntax errors stop compilation, so no class file is produced and the program never runs."},{"id":"zya1_4_2","topic":"Runtime error example","text":"Which of these is a runtime error, not a syntax error?","options":["Dividing an int by a variable that happens to be 0","Declaring two variables with the same name","Forgetting a closing brace","Misspelling System.out.printn"],"correct":0,"explain":"Division by zero compiles fine — the compiler cannot know the value. It throws ArithmeticException when that line actually runs."},{"id":"zya1_4_3","topic":"Logic error","text":"A program computes an average as (a + b) / 2 but should use / 3. This is:","options":["A logic error","A compiler warning","A syntax error","A runtime error"],"correct":0,"explain":"It compiles and runs without complaint and produces a plausible-looking wrong number. Only testing against known answers catches it."},{"id":"zya1_4_4","topic":"Hardest error to find","text":"Which error type is generally hardest to detect?","options":["Logic — nothing reports it","Warnings — they are hidden","Syntax — the message is cryptic","Runtime — it crashes"],"correct":0,"explain":"Syntax and runtime errors announce themselves. A logic error is silent; the program looks like it worked."},{"id":"zya1_4_5","topic":"Warning vs error","text":"A compiler warning means:","options":["The code compiles but something looks suspicious","The program has already crashed","A comment is malformed","The program will not compile"],"correct":0,"explain":"Warnings are advisory — unused variables, unchecked casts. The class file is still produced, but a warning often marks a real bug."},{"id":"zya1_4_6","topic":"Error message line numbers","text":"A syntax error reported on line 15 means the mistake is:","options":["On line 15 or shortly before it","Always on line 14","In a different file","Definitely on line 15"],"correct":0,"explain":"A missing semicolon on line 14 is often reported at 15, because the compiler only realizes something is wrong when it hits the next token. Always check the preceding lines. The compiler reports where it noticed."},{"id":"zy1_4_7_a18","topic":"Compile vs runtime","text":"int x = "hello"; produces:","options":["a compile-time error","a runtime error","no error","a warning only"],"correct":0,"explain":"A type mismatch is caught by javac — a compile-time error.","__rebal":1},{"id":"n_n1_4_a","topic":"Errors","text":"A missing semicolon produces:","options":["A logic error","A warning only","A compile-time (syntax) error","A runtime exception"],"correct":2,"explain":"The compiler cannot parse the statement, so nothing is produced to run. Syntax errors are caught before the program ever executes."},{"id":"n_n1_4_b","topic":"Errors","text":"Dividing an int by zero at run time produces:","options":["An ArithmeticException","A compile error","Infinity","Zero"],"correct":0,"explain":"Integer division by zero throws ArithmeticException: / by zero. Note that DOUBLE division by zero does not throw — it yields Infinity."},{"id":"n_n1_4_c","topic":"Errors","text":"System.out.println(1.0 / 0); prints:","options":["throws ArithmeticException","Infinity","0.0","NaN"],"correct":1,"explain":"Floating-point division follows IEEE 754, which defines division by zero as Infinity rather than an error. Only INTEGER division by zero throws."},{"id":"n_n1_4_d","topic":"Errors","text":"A program compiles and runs but prints the wrong average. This is:","options":["A compiler warning","A logic error","A syntax error","A runtime exception"],"correct":1,"explain":"Nothing is malformed and nothing crashed — the instructions are simply not the ones that solve the problem. Logic errors are the only kind the computer cannot point at for you."},{"id":"n_n1_4_e","topic":"Errors","text":"The three kinds of error, in the order they are usually met, are:","options":["Syntax, logic, runtime","Syntax, runtime, logic","Logic, syntax, runtime","Runtime, syntax, logic"],"correct":1,"explain":"Syntax errors stop compilation, runtime errors stop execution, and logic errors let the program finish while producing the wrong answer."},{"id":"zf28","topic":"","text":"int x = 5 (with no semicolon) causes:","options":["a runtime error","a logic error","a compile-time error","a warning, but the program runs"],"correct":2,"explain":"Missing semicolons break the syntax, so the compiler rejects the file.","difficulty":"medium"},{"id":"zf29","topic":"","text":"A program that compiles, runs to completion, but prints the wrong average has:","options":["a syntax error","a runtime error","a compiler warning","a logic error"],"correct":3,"explain":"The code is legal Java and does not crash; the algorithm itself is wrong.","difficulty":"medium"},{"id":"zf30","topic":"","text":"System.out.println(10 / 0); with int values causes:","options":["a compile-time error","a logic error only","the output Infinity","a runtime error (ArithmeticException)"],"correct":3,"explain":"Integer division by zero compiles fine but throws when executed. (10.0 / 0 with doubles would print Infinity instead.)","difficulty":"medium"},{"id":"zf31","topic":"","text":"Using a variable name that was never declared causes:","options":["a compile-time error","a runtime crash after some output","a logic error","an automatic declaration"],"correct":0,"explain":"The compiler must know every name; "cannot find symbol" stops compilation.","difficulty":"medium"},{"id":"zf32","topic":"","text":"A compiler warning differs from an error in that:","options":["warnings only appear at runtime","the program still compiles and can run","warnings stop compilation","warnings fix themselves"],"correct":1,"explain":"Warnings flag suspicious-but-legal code; errors block the build.","difficulty":"medium"},{"id":"zf33","topic":"","text":"Which error type produces NO message at all?","options":["a syntax error","a runtime exception","a logic error","an unclosed string literal"],"correct":2,"explain":"Logic errors give wrong results silently - which is why they are the hardest to find.","difficulty":"medium"},{"id":"zf34","topic":"","text":"An unclosed string literal like System.out.println("Hi); causes:","options":["a runtime error","the output Hi)","a warning only","a compile-time error"],"correct":3,"explain":"The compiler reaches the end of the line still inside the string and rejects it.","difficulty":"medium"},{"id":"zf35","topic":"","text":"accessing myArray[10] when the array has 10 elements causes:","options":["a runtime ArrayIndexOutOfBoundsException","a compile-time error","the value 0","the last element to be returned"],"correct":0,"explain":"Valid indexes are 0-9; index 10 is checked when the program runs, not by the compiler.","difficulty":"medium"},{"id":"zf36","topic":"","text":"Which is caught FIRST in the development process?","options":["runtime errors","compile-time errors","logic errors","user-reported bugs"],"correct":1,"explain":"The compiler runs before the program can execute, so syntax problems surface first.","difficulty":"medium"},{"id":"zf37","topic":"","text":"A "cannot find symbol" message usually means:","options":["the computer is out of memory","a file was deleted while running","a name was misspelled or never declared","the JVM is not installed"],"correct":2,"explain":"The compiler could not match the identifier to any declaration in scope.","difficulty":"medium"},{"id":"zf38","topic":"","text":"The average of a and b coded as a + b / 2 is wrong because:","options":["Java cannot divide by 2","a + b must be on its own line","the / operator rounds up","only b is halved - division binds first"],"correct":3,"explain":"Precedence makes it a + (b/2). Correct is (a + b) / 2 - a classic logic error.","difficulty":"medium"},{"id":"zf39","topic":"","text":"A program crashes with an exception message and a line number. This is:","options":["a runtime error","a syntax error","a logic error","a warning"],"correct":0,"explain":"It compiled successfully and failed while executing - the definition of a runtime error.","difficulty":"medium"}],"D286/u1/z1_5":[{"id":"zya1_5_0","topic":"CPU role","text":"The CPU is responsible for:","options":["Displaying graphics only","Connecting to the internet","Permanently storing files","Fetching and executing instructions"],"correct":3,"explain":"The CPU is the execution engine: fetch an instruction, decode it, execute it, repeat."},{"id":"zya1_5_1","topic":"RAM characteristic","text":"RAM is described as volatile because:","options":["Its contents change whenever the CPU reads them","Its contents are lost when power is removed","Its contents are compressed and must be decoded","Its contents can be accessed only in sequence"],"correct":1,"explain":"Volatile means it needs power to retain data — which is why work must be saved to non-volatile storage such as an SSD or hard drive."},{"id":"zya1_5_2","topic":"Bit","text":"A bit holds:","options":["One character","Eight values","Any digit 0-9","One of two values, 0 or 1"],"correct":3,"explain":"A bit is a single binary digit. Eight bits make a byte."},{"id":"zya1_5_3","topic":"Byte size","text":"How many bits are in a byte?","options":["16","32","4","8"],"correct":3,"explain":"Eight. A byte can therefore represent 2^8 = 256 distinct values."},{"id":"zya1_5_4","topic":"Memory vs storage","text":"The practical difference between RAM and a hard drive is:","options":["They are the same thing","Storage is used only for programs","RAM is larger","RAM is much faster but temporary; storage is slower but persistent"],"correct":3,"explain":"Programs run from RAM because it is fast; files persist on disk because it survives power loss."},{"id":"zya1_5_5","topic":"Where a running program lives","text":"While a program is running, its instructions and data are held mainly in:","options":["The monitor","The network card","The hard drive","RAM"],"correct":3,"explain":"The program is loaded from storage into RAM to run. This is why a machine with insufficient RAM slows down badly."},{"id":"zya1_5_6","topic":"Binary representation","text":"Computers represent all data — text, images, sound — using:","options":["Hexadecimal only","ASCII exclusively","Decimal digits","Binary (patterns of 0s and 1s)"],"correct":3,"explain":"Everything reduces to binary. What differs is the interpretation: the same byte can be a number, a character, or part of a pixel."},{"id":"zya1_5_7","topic":"Clock speed meaning","text":"A higher CPU clock speed generally means:","options":["Better graphics","More RAM","More storage capacity","More instruction cycles per second"],"correct":3,"explain":"Clock speed measures cycles per second. It is only one factor in real performance — core count and memory speed matter too."},{"id":"fs_z1_5_2","topic":"Hardware layers","text":"In the layered view of a computer, which sequence is ordered from the lowest layer to the highest?","options":["Logic gates, transistors, machine instructions, circuits","Circuits, machine instructions, transistors, logic gates","Transistors, logic gates, circuits, machine instructions","Machine instructions, circuits, logic gates, transistors"],"correct":2,"explain":"Transistors form logic gates, gates form circuits, and circuits execute machine instructions. Each layer hides the one below it, which is why you can program without thinking about gates."},{"id":"fs_z1_5_3","topic":"Fixed-width types","text":"Why does every numeric type in Java have a hard maximum value?","options":["It is a Java quirk that other languages avoid","The garbage collector removes digits from very large values","The limit only exists when running on 32-bit hardware","Each type is stored in a fixed number of bits"],"correct":3,"explain":"A fixed number of bits can represent only finitely many values, so every numeric type has a ceiling. That is the hardware showing through, not a Java quirk, and it is what makes integer overflow possible. Only a finite set of values can be represented."},{"id":"fs_z1_5_4","topic":"Machine instructions","text":"A machine instruction is best described as:","options":["A line of Java source code","A method call in the standard library","A file stored on disk","A single operation the processor executes directly"],"correct":3,"explain":"A machine instruction is one operation the processor executes directly. Java source is far above this layer: it is compiled to bytecode, which is eventually turned into machine instructions."},{"id":"fs_z1_5_5","topic":"Memory organization","text":"In a computer's memory, each numbered storage location holds:","options":["One machine instruction","One Java variable","One file","One byte"],"correct":3,"explain":"Memory is a sequence of numbered locations, each holding one byte (eight bits) - the smallest normally addressable unit. Larger values like an int span several consecutive bytes."},{"id":"fs_z1_5_6","topic":"Abstraction layers","text":"You can write x + y in Java without knowing anything about logic gates. Why?","options":["Java programs do not use the hardware","Logic gates are only involved when a program crashes","The compiler removes all arithmetic before the program runs","Each layer of the computer hides the details of the layer below it"],"correct":3,"explain":"Each layer - transistors, gates, circuits, machine instructions - hides the layer below. That hiding is what lets you write arithmetic without hardware knowledge, until a hidden limit like overflow shows through."},{"id":"zf40","topic":"","text":"A computer program is:","options":["a sequence of instructions to execute","a physical part of the processor","any file stored on disk","a diagram of hardware"],"correct":0,"explain":"Programs are instruction lists; hardware carries them out.","difficulty":"medium"},{"id":"zf41","topic":"","text":"The processor (CPU) is the component that:","options":["permanently stores files","executes program instructions","displays the output on screen","connects to the internet"],"correct":1,"explain":"The CPU fetches and runs instructions one after another, very fast.","difficulty":"medium"},{"id":"zf42","topic":"","text":"RAM (memory) is best described as:","options":["permanent storage for files","the part that executes instructions","fast temporary storage, erased at power off","a type of screen"],"correct":2,"explain":"RAM holds running programs and their data; it is volatile.","difficulty":"medium"},{"id":"zf43","topic":"","text":"A disk drive or SSD differs from RAM because it:","options":["is faster than RAM","executes instructions","is erased on shutdown","keeps its contents when the power is off"],"correct":3,"explain":"Storage is persistent; memory is not. That is the key distinction.","difficulty":"medium"},{"id":"zf44","topic":"","text":"Which pairing of device and role is right?","options":["Keyboard - input; screen - output","Keyboard - output; screen - input","Both are processors","Both are storage devices"],"correct":0,"explain":"Input devices send data to the computer; output devices present results.","difficulty":"medium"},{"id":"zf45","topic":"","text":"Before a stored program can run, it is:","options":["printed to the console","loaded from storage into memory","converted into comments","emailed to the processor"],"correct":1,"explain":"The OS copies the program from disk into RAM, where the CPU can execute it.","difficulty":"medium"},{"id":"zf46","topic":"","text":"At the lowest level, computers store all data as:","options":["decimal digits","letters and words","0s and 1s (binary)","tiny images"],"correct":2,"explain":"Every number, character, and picture is ultimately bits.","difficulty":"medium"},{"id":"zf47","topic":"","text":"A processor described as 3 GHz carries out roughly:","options":["3 million instructions per day","3 thousand cycles per second","300 cycles per second","3 billion clock cycles per second"],"correct":3,"explain":"Giga = billion; the clock rate sets the beat the CPU works to.","difficulty":"medium"},{"id":"zf48","topic":"","text":"The instructions a processor directly understands are called:","options":["machine instructions","Java statements","pseudocode","comments"],"correct":0,"explain":"Each CPU family has its own binary machine instruction set.","difficulty":"medium"},{"id":"zf49","topic":"","text":"Getting from a Java source file to a running program requires:","options":["printing it, then scanning it","compiling it, then executing the result","zipping it, then unzipping it","renaming it to .class"],"correct":1,"explain":"javac compiles source to bytecode; the JVM then executes that bytecode.","difficulty":"medium"},{"id":"zf50","topic":"","text":"Cache memory exists because:","options":["it is bigger than the disk","it is much faster than RAM","RAM cannot hold numbers","it survives power loss"],"correct":1,"explain":"Small, fast cache between CPU and RAM speeds up repeated access.","difficulty":"medium"},{"id":"zf51","topic":"","text":"Which lists storage from FASTEST to slowest?","options":["disk, RAM, cache","RAM, disk, cache","cache, RAM, disk","disk, cache, RAM"],"correct":2,"explain":"The closer to the CPU, the faster (and smaller) the storage.","difficulty":"medium"}],"D286/u1/z1_6":[{"id":"zya1_6_0","topic":"IDE meaning","text":"IDE stands for:","options":["Interpreted Debug Engine","Interface Design Editor","Integrated Development Environment","Internal Data Exchange"],"correct":2,"explain":"An IDE bundles the tools of development into one application."},{"id":"zya1_6_1","topic":"IDE components","text":"Which set best describes what an IDE typically provides?","options":["Operating system, drivers, and hardware management","Editor, compiler integration, debugger and project management","A runtime that executes bytecode on any machine","Version control hosting with review and pipelines"],"correct":1,"explain":"The value of an IDE is integration — edit, build, run and debug without leaving the tool."},{"id":"zya1_6_2","topic":"Java IDE examples","text":"Which of these is a Java IDE?","options":["Chrome","Photoshop","Eclipse","Excel"],"correct":2,"explain":"Eclipse, IntelliJ IDEA and NetBeans are the common Java IDEs."},{"id":"zya1_6_3","topic":"Is an IDE required","text":"Can Java be written without an IDE?","options":["Only on Linux","No, the JDK requires one","Yes — a text editor plus javac and java is sufficient","Only for programs under 50 lines"],"correct":2,"explain":"An IDE is a convenience. The JDK command-line tools javac and java are all that is strictly required."},{"id":"zya1_6_4","topic":"Syntax highlighting","text":"Syntax highlighting helps by:","options":["Underlining every line that fails to compile","Reformatting the code to the project's style","Colouring keywords, strings and comments so structure shows","Renaming variables to follow the conventions"],"correct":2,"explain":"It is a readability aid — an unterminated String, for example, becomes obvious because the colouring runs on past where it should stop."},{"id":"zya1_6_5","topic":"Debugger purpose","text":"An IDE debugger lets you:","options":["Rewrite the code so the defect no longer occurs","Pause execution and inspect variable values as it runs","Compile the program more quickly than javac does","Predict which lines are most likely to be wrong"],"correct":1,"explain":"Stepping line by line and watching values change is the fastest way to find a logic error, and far better than scattering print statements."},{"id":"zya1_6_6","topic":"Breakpoint","text":"A breakpoint is:","options":["A marked line where execution pauses so state can be seen","A line the compiler refuses to translate","A point at which the program throws an exception","A comment that disables the following statement"],"correct":0,"explain":"You set a breakpoint just before the code you suspect, then inspect variables at that moment."},{"id":"zya1_6_7","topic":"Auto-complete caution","text":"IDE auto-complete is useful but:","options":["It only works for classes in the standard library","It rewrites the surrounding lines without warning","It slows compilation because of the extra imports","It can insert a method that compiles but is not the one meant"],"correct":3,"explain":"Accepting the wrong suggestion produces code that compiles and does something subtly different — a common source of logic errors."},{"id":"zya1_6_8","topic":"Project structure","text":"An IDE project typically organizes source files by:","options":["Alphabetical order of the class names within the project","The order in which the source files were first created","Package/folder structure matching the package declarations","The size of each source file as stored on disk"],"correct":2,"explain":"Package names mirror folders; the IDE enforces that structure so the compiler can locate classes."},{"id":"zya1_6_9","topic":"IDE vs compiler","text":"The IDE itself:","options":["Runs Java without bytecode","Compiles Java using its own private language","Invokes the JDK compiler on your behalf","Replaces the JVM"],"correct":2,"explain":"The IDE is a front end. Underneath, the same javac and java tools do the work."},{"id":"n_n1_6_a","topic":"IDE","text":"The compiler turns source code into:","options":["An executable installer","Bytecode in a .class file","Machine code for the current CPU","A .java file"],"correct":1,"explain":"javac produces platform-independent bytecode. The JVM then executes that bytecode, which is what makes the same .class file run anywhere."},{"id":"n_n1_6_b","topic":"IDE","text":"The JVM is responsible for:","options":["Executing bytecode on a particular machine","Translating source code into bytecode","Providing the editor and debugger tools","Managing the computer's hardware resources"],"correct":0,"explain":"javac compiles; the JVM runs. Splitting the two is what "write once, run anywhere" actually means."},{"id":"n_n1_6_c","topic":"IDE","text":"A Java source file containing "public class Dog" must be named:","options":["Main.java","Dog.java","dog.java","Dog.class"],"correct":1,"explain":"The file name must match the public class exactly, including capitals. Java is case-sensitive here even on file systems that are not."},{"id":"zf52","topic":"","text":"An IDE (integrated development environment) combines:","options":["a browser, a spreadsheet, and email","only a text editor","the JVM and the operating system","editor, compiler, and debugger in one"],"correct":3,"explain":"That integration is what the I in IDE means.","difficulty":"medium"},{"id":"zf53","topic":"","text":"A breakpoint set in an IDE:","options":["pauses the program at that line","deletes the line","marks the line as a comment","makes the line run twice"],"correct":0,"explain":"Execution stops before the marked line; you can then view variable values.","difficulty":"medium"},{"id":"zf54","topic":"","text":"While paused at a breakpoint, the variables panel shows:","options":["the history of every keystroke","each in-scope variable’s current value","the compiled bytecode","the program’s final output"],"correct":1,"explain":"Inspecting live values is the main payoff of a debugger.","difficulty":"medium"},{"id":"zf55","topic":"","text":"The debugger’s "step over" command:","options":["skips the current line without running it","restarts the program","runs the current line and stops at the next one","jumps to the last line"],"correct":2,"explain":"Step-over executes one line at a time so you can watch the state change.","difficulty":"medium"},{"id":"zf56","topic":"","text":"Modern IDEs flag many compile errors:","options":["only after the program runs","once per day","never - errors appear only in the console","as you type, before you even build"],"correct":3,"explain":"Live analysis underlines problems immediately, shortening the fix loop.","difficulty":"medium"},{"id":"zf57","topic":"","text":"The IDE’s console window is where:","options":["your program’s output and typed input","bytecode is edited by hand","breakpoints are stored","the compiler saves .java files"],"correct":0,"explain":"System.out and Scanner both talk to the console.","difficulty":"medium"},{"id":"zf58","topic":"","text":"The "build" (or compile) action in an IDE:","options":["uploads the code to the internet","compiles the source files into bytecode","formats your comments","runs the tests twice"],"correct":1,"explain":"Build = compile; run = execute what was built.","difficulty":"medium"},{"id":"zf59","topic":"","text":"An IDE project is:","options":["a single line of code","the JVM installation","one program’s source files and settings","a printout of the program"],"correct":2,"explain":"Projects keep sources, libraries, and configuration together.","difficulty":"medium"},{"id":"zf60","topic":"","text":"Autocomplete in an IDE helps by:","options":["running the program automatically","choosing your algorithm","suggesting names as you type","writing your comments"],"correct":2,"explain":"It reduces typos and shows what methods are available on an object.","difficulty":"medium"},{"id":"zf61","topic":"","text":"Running a program in DEBUG mode differs from a normal run because:","options":["the program output changes","debug mode skips the main method","the compiler is not used","breakpoints pause execution in debug mode"],"correct":3,"explain":"Same program, but the debugger honors breakpoints and stepping.","difficulty":"medium"},{"id":"zf62","topic":"","text":"Compared with a plain text editor plus command line, an IDE mainly adds:","options":["integrated checking, debugging, running","faster hardware","a different Java language","automatic bug-free code"],"correct":0,"explain":"The language is identical - the tooling around it is what improves.","difficulty":"medium"},{"id":"zf858","topic":"","text":"Stepping INTO a method call while debugging:","options":["skips over the call entirely","enters the method, tracing line by line","deletes the method","recompiles the project"],"correct":1,"explain":"Step-into follows execution inside the called method; step-over stays at the call site.","difficulty":"medium"}],"D286/u1/z1_7":[{"id":"zya1_7_0","topic":"Main hardware components","text":"The four main hardware components of a computer are:","options":["Monitor, keyboard, mouse, printer","Processor, memory, storage, and input/output devices","Java, JVM, JDK, and JRE","Compiler, debugger, editor, and linker"],"correct":1,"explain":"Everything else is a variation on these four roles."},{"id":"zya1_7_1","topic":"Input device","text":"Which is an input device?","options":["Printer","Keyboard","Speaker","Monitor"],"correct":1,"explain":"Input devices carry data into the computer; monitors, printers and speakers carry it out."},{"id":"zya1_7_2","topic":"Output device","text":"Which is an output device?","options":["Microphone","Monitor","Scanner","Mouse"],"correct":1,"explain":"A monitor presents results to the user. Mice, microphones and scanners are inputs."},{"id":"zya1_7_3","topic":"Motherboard","text":"The motherboard is:","options":["The chip that carries out the instructions","The memory that holds the running program","The main circuit board connecting the components","The unit that supplies power to the machine"],"correct":2,"explain":"It provides the sockets and buses through which the CPU, RAM and peripherals communicate."},{"id":"zya1_7_4","topic":"Storage examples","text":"Which is persistent storage?","options":["Cache","Solid-state drive","CPU register","RAM"],"correct":1,"explain":"An SSD retains data without power. RAM, cache and registers are all volatile."},{"id":"zya1_7_5","topic":"Speed hierarchy","text":"Order these from fastest to slowest access:","options":["Hard drive, RAM, CPU register","CPU register, RAM, hard drive","RAM, CPU register, hard drive","They are all equally fast"],"correct":1,"explain":"Registers are on the CPU itself, RAM is nearby, disk is far away. Each step down is roughly an order of magnitude slower."},{"id":"zya1_7_6","topic":"Operating system role","text":"The operating system:","options":["Manages hardware resources and provides services to programs","Translates source code into executable instructions","Executes Java bytecode on a particular machine","Connects the components on the main circuit board"],"correct":0,"explain":"Programs ask the OS for memory, files and screen access rather than touching hardware directly."},{"id":"zya1_7_7","topic":"Cache purpose","text":"CPU cache exists to:","options":["Store the program permanently between runs","Extend main memory by paging out to disk","Buffer data waiting to be written to a device","Hold recently used data near the CPU to avoid slower RAM"],"correct":3,"explain":"It is a small, very fast buffer. Code that accesses memory in a predictable order benefits most — which is why array traversal outperforms scattered access."},{"id":"zya1_7_8","topic":"Peripheral","text":"A peripheral is:","options":["A chip inside the processor that speeds up access","A device attached to the computer, outside the core unit","A program that manages one hardware device","A connector on the board that holds the CPU"],"correct":1,"explain":"Keyboards, printers and external drives are peripherals."},{"id":"zya1_7_9","topic":"Why hardware knowledge matters","text":"For a programmer, understanding hardware mainly helps explain:","options":["Which programming language a project should use","Why some programs are slow and why memory limits exist","How to design the user interface of a program","Which coding conventions a team should adopt"],"correct":1,"explain":"Performance and memory behaviour — including why an O(n^2) algorithm on a large array becomes unusable — trace back to hardware realities."},{"id":"fs_z1_7_1","topic":"Fetch-decode-execute","text":"The cycle a processor repeats billions of times per second is:","options":["Compile, link, load, run","Read a file, parse it, print it","Boot, idle, sleep, wake","Fetch an instruction, decode it, execute it, store the result"],"correct":3,"explain":"The fetch-decode-execute cycle is the processor's basic rhythm: fetch an instruction from memory, decode it, execute it, and store the result, billions of times per second."},{"id":"fs_z1_7_2","topic":"Registers","text":"Registers are effectively instant to access because:","options":["They are made of faster silicon than RAM","They store data in a compressed format","The operating system gives them priority","They are located inside the processor itself"],"correct":3,"explain":"The speed differences in the memory hierarchy come from distance. Registers live inside the CPU, cache is close by, RAM is further away, and disk is furthest and slowest by orders of magnitude."},{"id":"fs_z1_7_3","topic":"Device categories","text":"A touchscreen is classified as which kind of device?","options":["Input only","Output only","Storage","Both an input and an output device"],"correct":3,"explain":"A touchscreen displays results (output) and accepts touches (input), making it the standard example of a device in both categories."},{"id":"fs_z1_7_4","topic":"Memory hierarchy and code","text":"Reading data from a file is treated very differently in code from reading a variable because:","options":["Files can only be read once per program run","Variables are stored on disk while files are kept in RAM","The compiler forbids file access inside loops","Disk access is orders of magnitude slower than accessing memory or registers"],"correct":3,"explain":"A variable lives in registers or cache and is effectively free to read; a file lives on disk, which is thousands of times slower. That distance is why file access gets special treatment."},{"id":"zf63","topic":"","text":"How many bits are in one byte?","options":["4","8","16","2"],"correct":1,"explain":"A byte is 8 bits - enough for 256 distinct values.","difficulty":"medium"},{"id":"zf64","topic":"","text":"Which component is volatile (loses data without power)?","options":["SSD","hard disk","RAM","ROM"],"correct":2,"explain":"RAM is working memory only; storage devices persist.","difficulty":"medium"},{"id":"zf65","topic":"","text":"The motherboard’s role is to:","options":["execute instructions","store files permanently","display graphics","connect CPU, memory, and devices"],"correct":3,"explain":"It is the circuit board everything else plugs into.","difficulty":"medium"},{"id":"zf66","topic":"","text":"Compared with a hard disk (HDD), a solid-state drive (SSD):","options":["has no moving parts and is faster","is always larger in capacity","loses data when powered off","must spin faster"],"correct":0,"explain":"Flash-based SSDs beat spinning platters on speed and durability.","difficulty":"medium"},{"id":"zf67","topic":"","text":"A GPU is specialized for:","options":["storing files","graphics and parallel computation","network routing","powering the fans"],"correct":1,"explain":"GPUs run many simple operations at once - graphics, and nowadays ML too.","difficulty":"medium"},{"id":"zf68","topic":"","text":"CPU registers are:","options":["files on the desktop","a kind of external drive","tiny, fastest storage inside the CPU","rows of the keyboard"],"correct":2,"explain":"Registers hold the values the CPU is working on this very instant.","difficulty":"medium"},{"id":"zf69","topic":"","text":"Which is the correct size ordering, smallest to largest?","options":["MB, KB, TB, GB","GB, TB, KB, MB","TB, GB, MB, KB","KB, MB, GB, TB"],"correct":3,"explain":"Kilo, mega, giga, tera - each step is about a thousand times bigger.","difficulty":"medium"},{"id":"zf70","topic":"","text":"A peripheral device is:","options":["the processor core","a section of RAM","part of the operating system","an external device like a mouse"],"correct":3,"explain":"Peripherals attach to the computer to provide input, output, or storage.","difficulty":"medium"},{"id":"zf71","topic":"","text":"The operating system’s job includes:","options":["managing programs, memory, and devices","compiling Java source","designing web pages","executing bytecode inside the CPU"],"correct":0,"explain":"Windows, macOS, and Linux allocate the machine’s resources to programs.","difficulty":"medium"},{"id":"zf72","topic":"","text":"When a program runs, its instructions are fetched by the CPU from:","options":["the printer","memory (RAM)","the screen","the power supply"],"correct":1,"explain":"The fetch-decode-execute cycle pulls instructions from RAM.","difficulty":"medium"},{"id":"zf73","topic":"","text":"A network interface (Wi-Fi or Ethernet) lets the computer:","options":["run without RAM","execute two programs at once","exchange data with other computers","cool the processor"],"correct":2,"explain":"It is the doorway to local networks and the internet.","difficulty":"medium"}],"D286/u1/z1_8":[{"id":"zya1_8_0","topic":"Bytecode target","text":"javac compiles Java source into:","options":["Bytecode stored in .class files","An executable .exe file","Assembly language","Machine code for the current processor"],"correct":0,"explain":"Bytecode is an intermediate form. The JVM then executes it, which is what makes the same .class file run on any platform."},{"id":"zy1_8_1_fresh_D286_1","topic":"Java Basics > JVM/JRE/JDK","text":"Which component of the Java platform contains the javac compiler needed to turn .java source files into .class bytecode?","options":["JIT compiler","JDK","JRE","JVM"],"correct":1,"explain":"The JDK (Java Development Kit) includes development tools such as the javac compiler; the JRE and JVM only run bytecode."},{"id":"zy1_8_3_q2","topic":"Bytecode","text":"Java's 'write once, run anywhere' is possible because Java compiles to:","options":["Platform-independent bytecode executed by JVM","Native machine code produced for each processor","Source code interpreted directly by the OS","An intermediate C file compiled on each machine"],"correct":0,"explain":"Java compiles to bytecode (.class) that any JVM can execute regardless of OS.","__rebal":1},{"id":"zy1_8_4_q4","topic":"JDK contains","text":"JDK contains JRE. JRE contains JVM. Which statement is FALSE?","options":["JDK is needed to compile","JDK ⊃ JRE","JVM ⊃ JRE","JRE ⊃ JVM"],"correct":2,"explain":"JVM does not contain JRE. Relationship: JDK ⊃ JRE ⊃ JVM.","distractors":{"0":"True.","2":"True.","3":"True."},"__rebal":1},{"id":"zy1_8_5_q1","topic":"JDK vs JRE","text":"Developer needs to write, compile, and run Java programs. Install?","options":["JRE — includes JVM","JVM only","Separate compiler","JDK — includes compiler plus JRE"],"correct":3,"explain":"JDK contains JRE (which contains JVM) plus compiler (javac) and development tools.","distractors":{"1":"JDK includes the compiler.","2":"JRE runs but cannot compile.","3":"JVM lacks libraries and compiler."},"__rebal":1},{"id":"zy1_8_6_q7","topic":"JIT","text":"Java JVM uses JIT to improve performance. JIT:","options":["Only works on Java 8","Compiles frequently-run bytecode to native machine code during execution","Compiles source before program runs","Replaces javac"],"correct":1,"explain":"JIT compiles hot code paths to native machine code at runtime.","distractors":{"0":"That's AOT compilation.","1":"JIT has been in Java for decades.","2":"JIT runs during execution."},"__rebal":1},{"id":"zy1_8_7_a13","topic":"Bytecode","text":"Bytecode is platform-independent because:","options":["bytecode is plain text that any OS can read","the JDK recompiles the bytecode on each machine","bytecode contains machine code for every processor","each OS has its own JVM that runs the same bytecode"],"correct":3,"explain":"One .class runs everywhere because each platform ships its own JVM.","__rebal":1},{"id":"zy1_8_8_a25","topic":"Portability","text":"Java achieves "write once, run anywhere" by:","options":["supporting only one OS","compiling to bytecode the JVM runs on any platform","not compiling at all","compiling to machine code per CPU"],"correct":1,"explain":"Bytecode plus a per-platform JVM is what makes Java portable.","__rebal":1},{"id":"fs_z1_8_1","topic":"Design decisions","text":"Java removed the pointer arithmetic that C++ allowed. What did this buy?","options":["It made every Java program run faster than C++","It removed the need for a compiler","It let programs run without using memory","It eliminated a whole family of crashes and security holes"],"correct":3,"explain":"Pointer arithmetic in C++ enabled a whole class of crashes and security bugs. Removing it removed that class entirely - the typical pattern behind Java's design decisions."},{"id":"fs_z1_8_2","topic":"Garbage collection","text":"Automatic garbage collection means the programmer no longer has to:","options":["Explicitly free memory that is no longer in use","Declare the type of every variable in advance","Close files and network connections after use","Check array indices before accessing elements"],"correct":0,"explain":"Garbage collection automatically reclaims memory no longer reachable by the program, removing the crashes C++ allowed from freeing memory twice or never freeing it at all."},{"id":"fs_z1_8_3","topic":"Platform independence","text":"C++ programs must be recompiled for each platform, but Java programs do not. Why?","options":["C++ has no compilers for modern platforms","Java source code is executed directly by the CPU","C++ compiles straight to one platform's machine code, while Java compiles to bytecode that any JVM can run","Java programs are never compiled at all"],"correct":2,"explain":"C and C++ compile directly to machine code for a specific platform. Java compiles once to bytecode and lets each platform's JVM absorb the differences - compile once, run anywhere."},{"id":"fs_z1_8_4","topic":"Checked exceptions","text":"Enforced (checked) exception handling was designed to:","options":["Speed up method calls","Replace the need for testing","Make possible failures explicit in the code rather than hidden","Prevent all runtime errors from ever occurring"],"correct":2,"explain":"Checked exceptions make failure visible in the method signature rather than in a comment, so callers must acknowledge what can go wrong. They do not prevent errors - they surface them."},{"id":"fs_z1_8_5","topic":"Java history","text":"Which company originally released Java, and in what year?","options":["Oracle, in 2005","IBM, in 1985","Sun Microsystems, in 1995","Microsoft, in 1990"],"correct":2,"explain":"Java was released by Sun Microsystems in 1995, designed to compile once and run on any machine with a JVM. Oracle acquired Sun much later."},{"id":"fs_z1_8_6","topic":"Java SE","text":"Java SE refers to:","options":["The search engine built into the JDK","A special edition licensed only for servers","Java Standard Edition","A security extension added in Java 10"],"correct":2,"explain":"Java SE is the Standard Edition: the core language and standard libraries that this course covers. The core language and libraries."},{"id":"zf74","topic":"","text":"Java was created at Sun Microsystems and released in:","options":["1975","2005","2015","1995"],"correct":3,"explain":"James Gosling’s team released Java in 1995; Oracle later acquired Sun.","difficulty":"medium"},{"id":"zf75","topic":"","text":"Java’s slogan "write once, run anywhere" works because:","options":["compiled bytecode runs on any machine with a JVM","Java programs never need compiling","every CPU understands Java directly","the source code is emailed to each computer"],"correct":0,"explain":"The JVM abstracts away the hardware differences.","difficulty":"medium"},{"id":"zf76","topic":"","text":"Machine language is:","options":["a spoken language for engineers","binary instructions tied to one CPU type","the same as Java","a type of comment"],"correct":1,"explain":"Each CPU architecture has its own machine instruction set.","difficulty":"medium"},{"id":"zf77","topic":"","text":"Assembly language is:","options":["a high-level language like Java","a database language","mnemonics for machine instructions","bytecode for the JVM"],"correct":2,"explain":"ADD, MOV, JMP - one mnemonic per machine instruction.","difficulty":"medium"},{"id":"zf78","topic":"","text":"The main advantage of high-level languages over assembly is:","options":["they run with zero overhead everywhere","they need no compiler","they cannot contain bugs","logic closer to human reasoning, portable"],"correct":3,"explain":"One high-level line can replace many machine instructions and is far easier to read.","difficulty":"medium"},{"id":"zf79","topic":"","text":"Java’s syntax (braces, semicolons, types) was most influenced by:","options":["C and C++","Python","HTML","SQL"],"correct":0,"explain":"Java deliberately looked familiar to the C/C++ programmers of the 1990s.","difficulty":"medium"},{"id":"zf80","topic":"","text":"JavaScript is:","options":["a different language despite the name","the newest version of Java","Java compiled for browsers","a Java debugging tool"],"correct":0,"explain":"The name was a 1990s marketing choice; the languages are unrelated in design.","difficulty":"medium"},{"id":"zf81","topic":"","text":"An interpreted language differs from a compiled one because:","options":["it cannot use variables","translated and run line-by-line","it only runs on servers","it has no syntax rules"],"correct":1,"explain":"Compilers translate everything ahead of time; interpreters translate as they go.","difficulty":"medium"},{"id":"zf82","topic":"","text":"Which language came FIRST?","options":["Java","Python","C","C#"],"correct":2,"explain":"C dates to the early 1970s; Python 1991, Java 1995, C# 2000.","difficulty":"medium"},{"id":"zf83","topic":"","text":"Python was first released in:","options":["1971","2001","2011","1991"],"correct":3,"explain":"Guido van Rossum released Python in 1991 - a few years before Java.","difficulty":"medium"},{"id":"zf84","topic":"","text":"New programming languages keep being created mainly because:","options":["different problems reward different trade-offs","old languages stop working every decade","computers forget old languages","each company is required to invent one"],"correct":0,"explain":"Languages evolve toward safety, productivity, or performance for their niche.","difficulty":"medium"}],"D286/u1/z1_9":[{"id":"zya1_9_0","topic":"First step","text":"The first step in solving a programming problem should be:","options":["Write the method signatures before any logic","Choose the data structures the solution will use","Understand the problem and identify its inputs and outputs","Set up the project folders and build configuration"],"correct":2,"explain":"Time spent clarifying what is required saves far more time than it costs. Code written before the problem is understood usually has to be rewritten."},{"id":"zya1_9_1","topic":"Pseudocode","text":"Pseudocode is:","options":["A type of comment required by javac","A debugging tool","A Java dialect that compiles","An informal, language-independent description of the algorithm"],"correct":3,"explain":"It lets you work out the logic without fighting syntax at the same time."},{"id":"zya1_9_2","topic":"Decomposition","text":"Decomposing a problem means:","options":["Compressing the source file","Converting it to binary","Deleting unnecessary requirements","Breaking it into smaller sub-problems that can be solved separately"],"correct":3,"explain":"Each sub-problem typically becomes a method — which is the practical link between problem solving and Unit 6."},{"id":"zya1_9_3","topic":"Test cases before coding","text":"Writing example inputs and expected outputs before coding helps because:","options":["It satisfies the compiler's requirement for test data","It lets the IDE generate the method automatically","It removes the need to test the finished program","It defines what correct means and exposes edge cases early"],"correct":3,"explain":"You cannot tell whether code works without knowing the right answer. Deciding that first also surfaces cases the description left vague."},{"id":"zya1_9_4","topic":"Edge case","text":"An edge case is:","options":["Any input that causes a syntax error","An input the user never provides","The most common input","An input at the boundary of what is valid"],"correct":3,"explain":"Most bugs live at boundaries. Empty arrays, zero, and the first/last index are where off-by-one and division errors surface. Empty, zero, maximum, negative."},{"id":"zya1_9_6","topic":"Tracing","text":"Tracing a program by hand means:","options":["Stepping through the code recording each variable value","Running the program and reading its printed output","Reading the code aloud to check for typing errors","Drawing a flowchart of the finished program"],"correct":0,"explain":"A trace table with a column per variable and a row per iteration is the single most reliable way to answer "what is printed" questions."},{"id":"zya1_9_7","topic":"Reusing a known pattern","text":"When a new problem resembles one you have solved before, the best move is:","options":["Start from scratch to avoid bias","Ask for a different problem","Copy the old code without reading it","Adapt the approach, checking where the differences matter"],"correct":3,"explain":"Pattern recognition is most of practical problem solving — but the differences are where the bugs hide, so the adaptation must be deliberate."},{"id":"zya1_9_8","topic":"Simplify first","text":"If a problem feels too large, a useful tactic is:","options":["Write the whole solution and debug it at the end","Solve a simpler version first, then generalize","Split the work across several source files","Choose a language better suited to the problem"],"correct":1,"explain":"Solve it for one element before n elements, or for a fixed value before a variable one. The simple version usually reveals the structure."},{"id":"zya1_9_9","topic":"Verification","text":"After the program runs without crashing, you should:","options":["Assume it is correct, since no exception was thrown","Check its output against independently known correct answers","Reformat the code to match the style guide","Add comments explaining what each line does"],"correct":1,"explain":"Running without crashing rules out syntax and runtime errors only. Logic errors are invisible until output is checked against a known answer."},{"id":"fs_z1_9_1","topic":"Problem-solving order","text":"Which order of steps best matches the recommended problem-solving process?","options":["Translate to code, decompose, work an example, understand","Understand the problem, work an example by hand, write steps in plain language, translate to code","Write code, run it, then figure out what the problem was asking","Write Java syntax first, then decide what the program should do"],"correct":1,"explain":"The order that survives real problems is: understand, work one example by hand, write the steps in plain language, then translate to code - syntax comes last."},{"id":"fs_z1_9_2","topic":"Hand-worked examples","text":"A student cannot compute the answer for one specific input on paper. What does this indicate?","options":["The problem cannot be solved in Java","They do not yet fully understand what the program must do","They need a faster computer","The problem requires recursion"],"correct":1,"explain":"If you cannot compute the answer for one input by hand, you do not yet know what you are asking the machine to do - no amount of Java fixes that."},{"id":"fs_z1_9_3","topic":"Tracing catches bugs","text":"Three test scores 88, 92, and 79 should average to 86.33. What does this print?

System.out.println((88 + 92 + 79) / 3);","options":["Compiler error","86","86.33","86.0"],"correct":1,"explain":"All operands are int, so 259 / 3 is integer division and the fraction is discarded, printing 86. Knowing the hand-computed 86.33 is what reveals the truncation immediately."},{"id":"fs_z1_9_4","topic":"Algorithms","text":"Which property must every algorithm have?","options":["It is a finite sequence of unambiguous steps","It is written in a specific programming language","It runs in time proportional to the input size","It produces output for every conceivable input"],"correct":0,"explain":"An algorithm is a finite sequence of unambiguous steps that solves a problem. It is independent of any particular language and need not involve loops."},{"id":"zf85","topic":"","text":"The FIRST step in solving a programming problem is:","options":["typing code as fast as possible","understanding what the program must do","choosing variable names","compiling an empty file"],"correct":1,"explain":"Requirements before algorithm; algorithm before code.","difficulty":"medium"},{"id":"zf86","topic":"","text":"Breaking a large problem into smaller subproblems is called:","options":["compilation","duplication","decomposition","recursion"],"correct":2,"explain":"Each piece is easier to solve, test, and reuse.","difficulty":"medium"},{"id":"zf87","topic":"","text":"A flowchart represents:","options":["the folder structure of a project","the history of a language","memory addresses","an algorithm’s steps as a diagram"],"correct":3,"explain":"Boxes for actions, diamonds for decisions, arrows for flow.","difficulty":"medium"},{"id":"zf88","topic":"","text":"Tracing an algorithm by hand with sample values is called:","options":["desk checking","refactoring","packaging","obfuscation"],"correct":0,"explain":"Walking through the steps on paper catches logic mistakes before coding.","difficulty":"medium"},{"id":"zf89","topic":"","text":"Good test cases should include:","options":["only values you know will work","typical values AND edge cases like 0","one random value","only the largest possible value"],"correct":1,"explain":"Bugs live at the boundaries; tests must go there deliberately.","difficulty":"medium"},{"id":"zf90","topic":"","text":"If your solution seems too complicated, a good tactic is to:","options":["add more variables","solve a simpler version first","delete the requirements","skip testing to save time"],"correct":1,"explain":"A working small case reveals the pattern the full solution needs.","difficulty":"medium"},{"id":"zf91","topic":"","text":"Writing the algorithm before the code matters because:","options":["compilers require an algorithm file","code cannot be edited later","clear steps are easy to translate","algorithms make programs run faster automatically"],"correct":2,"explain":"The hard part is the logic - settle it first, then translating is mechanical.","difficulty":"medium"},{"id":"zf92","topic":"","text":"A requirement describes:","options":["which keyboard to use","HOW every loop must be written","the color of the IDE","WHAT the program must accomplish"],"correct":3,"explain":"Requirements define success; design decides how to achieve it.","difficulty":"medium"},{"id":"zf93","topic":"","text":"After writing a small piece of a program you should:","options":["compile and test it before adding more","write the rest before any testing","delete the tests","comment it out"],"correct":0,"explain":"Frequent compile-test cycles keep errors small and local.","difficulty":"medium"},{"id":"zf94","topic":"","text":"Comparing your program’s output against results you computed by hand:","options":["is never necessary","verifies the logic on known cases","replaces the compiler","only works for text programs"],"correct":1,"explain":"Expected-vs-actual comparison is the core of all testing.","difficulty":"medium"},{"id":"zf859","topic":"","text":"An algorithm must be unambiguous, meaning:","options":["steps can be guessed at runtime","steps may contradict each other","each step has exactly one interpretation","only computers can read it"],"correct":2,"explain":"If a step can be read two ways, different executions produce different results.","difficulty":"medium"},{"id":"zj14","topic":"Problem solving","text":"Before writing any code, the FIRST thing to establish about a problem is:","options":["which Java version the program will be compiled with","what the inputs are and what output is required","how many variables the finished program will use","whether to use an IDE or a plain text editor"],"correct":1,"explain":"You cannot design a solution until you know what you are given and what you must produce. The tooling and the variable count follow from the design, not before it.","difficulty":"medium"}],"D286/u1/z1_10":[{"id":"zya1_10_0","topic":"Automation benefit","text":"The core practical benefit of programming is:","options":["It removes the need to understand the problem","Programs never need maintenance","Computers never make mistakes","Repetitive, well-defined tasks can be performed quickly and consistently"],"correct":3,"explain":"A computer executes a correct procedure identically every time. It also executes an incorrect one identically every time — the accuracy comes from the program, not the machine."},{"id":"zya1_10_1","topic":"Scale","text":"Programs are especially valuable when a task must be done:","options":["Exactly once, on a small amount of data","Only when the task cannot be done by hand","Thousands of times or on large data sets","Only when the result must be perfectly precise"],"correct":2,"explain":"The setup cost of writing a program pays off through repetition and scale."},{"id":"zya1_10_2","topic":"Programming beyond software jobs","text":"Programming skills are commonly used by:","options":["Only IT support staff","Only game developers","Only professional software engineers","People in science, finance, healthcare, and many other fields"],"correct":3,"explain":"Data analysis, automation and modelling appear across nearly every technical field."},{"id":"zya1_10_3","topic":"Problem-solving transfer","text":"Learning to program tends to improve:","options":["Memory capacity","Mathematical talent automatically","Typing speed only","Structured, precise thinking about problems"],"correct":3,"explain":"The discipline of specifying every step exactly transfers to non-programming work."},{"id":"zya1_10_4","topic":"Java popularity reason","text":"A major reason Java remains widely used is:","options":["It requires no memory management ever","It has the shortest syntax","It is the newest language","Platform independence and a large ecosystem of libraries and tools"],"correct":3,"explain":"Write-once-run-anywhere plus decades of libraries and enterprise adoption keep it in demand."},{"id":"zya1_10_5","topic":"Software maintenance","text":"Most professional programming time is spent:","options":["Writing brand-new code from a blank file","Designing the user interface and its layout","Reading, understanding and modifying existing code","Configuring the build and deployment tools"],"correct":2,"explain":"This is why readability, naming and comments matter far more than they appear to when writing code for the first time."},{"id":"zya1_10_6","topic":"Correctness responsibility","text":"If a program produces a wrong result, the responsibility lies with:","options":["The compiler that translated the source","The programmer who specified the logic","The hardware that executed the instructions","The user who supplied the input values"],"correct":1,"explain":"The machine executed exactly what it was told. Wrong output means wrong instructions."},{"id":"zya1_10_7","topic":"Abstraction benefit","text":"Abstraction in programming means:","options":["Hiding detail behind a simpler interface to manage complexity","Breaking a program into several separate source files","Removing every comment from the finished source code","Replacing every named constant with a literal value"],"correct":0,"explain":"You call Math.sqrt without knowing its algorithm. The same principle scales up to methods, classes, and whole systems."},{"id":"zya1_10_8","topic":"Collaboration","text":"Programs are usually written by teams, which makes what important?","options":["Using the shortest possible variable names","Each developer choosing their own conventions","Writing every method in a single source file","Consistent style, clear naming and documentation"],"correct":3,"explain":"Code that only its author can understand has a short useful life."},{"id":"zya1_10_9","topic":"Learning approach","text":"The most effective way to learn programming is:","options":["Memorizing syntax tables","Watching videos only","Reading about it exclusively","Writing and debugging code regularly"],"correct":3,"explain":"The skill is procedural. Recognizing correct code is not the same ability as producing it."},{"id":"fs_z1_10_1","topic":"Course foundations","text":"Why does mastering this course's material matter for later software courses?","options":["Later courses do not involve any programming","Later courses assume these concepts as vocabulary","Later courses repeat the same material with nothing added","It is the only course in the degree that uses computers"],"correct":1,"explain":"This course is the gate to every later software course: loops and arrays become data structures, classes become object-oriented design, and Big-O becomes algorithms. Loops and arrays lead into data structures, classes into object-oriented design."},{"id":"fs_z1_10_2","topic":"Exam weighting","text":"Which units carry the majority of the exam's questions?","options":["All units are weighted equally","Units 2 through 7 - variables, branches, loops, arrays, methods, and classes","Units 15, 16, and 18 - GUI and AI topics","Unit 1 only"],"correct":1,"explain":"Units 2 to 7 carry most of the questions, and they are also the foundation everything later builds on - so time spent there pays twice."},{"id":"fs_z1_10_3","topic":"Automation","text":"Within Java, the direct payoff of programming is automating tasks that are:","options":["Already performed by the hardware","Repetitive and exact","Creative and one-off","Impossible to specify precisely"],"correct":1,"explain":"Automation means having a program perform a repetitive task reliably and identically each time - which is precisely what a loop is. Much of the course is tools for describing that repetition."},{"id":"fs_z1_10_4","topic":"Concept building blocks","text":"Exceptions, collections, and inheritance are later built from which earlier ideas?","options":["Registers, cache, and RAM","Branches on failure, arrays that grow, and classes reusing classes","Files, threads, and network sockets","Pointers, macros, and templates"],"correct":1,"explain":"Exceptions are branches on failure, collections are arrays that grow, and inheritance is classes reusing classes - which is why the early units matter so much."},{"id":"zf95","topic":"","text":"Programs excel at tasks that are:","options":["vague and undefined","impossible to describe","repetitive and precisely defined","purely emotional"],"correct":2,"explain":"A computer happily does the same exact steps a billion times.","difficulty":"medium"},{"id":"zf96","topic":"","text":"Software is embedded in cars, thermostats, and appliances. Such systems are called:","options":["spreadsheets","compilers","mainframes","embedded systems"],"correct":3,"explain":"Small dedicated computers run fixed programs inside larger devices.","difficulty":"medium"},{"id":"zf97","topic":"","text":"Learning to program primarily trains you to:","options":["express solutions as ordered steps","memorize hardware part numbers","type faster","avoid mathematics"],"correct":0,"explain":"Computational thinking - precision and decomposition - transfers everywhere.","difficulty":"medium"},{"id":"zf98","topic":"","text":"Computers follow instructions:","options":["approximately, guessing intent","literally and exactly as written","only when convenient","in random order"],"correct":1,"explain":"The machine does what you SAID, not what you MEANT - hence debugging.","difficulty":"medium"},{"id":"zf99","topic":"","text":"A key reason programming skills help in science and business is:","options":["they replace the need for domain knowledge","they make presentations prettier","one person can analyze data at huge scale","they are required by law"],"correct":2,"explain":"A short script can process millions of records in seconds.","difficulty":"medium"},{"id":"zf100","topic":"","text":"Once you know one programming language, learning another is usually:","options":["harder, because languages conflict","easier - the core concepts transfer","impossible without formal courses","pointless"],"correct":1,"explain":"Syntax differs; the underlying ideas are the same.","difficulty":"medium"},{"id":"zf101","topic":"","text":"Debugging is best viewed as:","options":["proof that you are a bad programmer","optional for small programs","a normal, expected part of programming","the compiler’s job alone"],"correct":2,"explain":"Every programmer debugs; the skill is doing it systematically.","difficulty":"medium"},{"id":"zf102","topic":"","text":"The difference between a program USER and a PROGRAMMER is:","options":["users must know Java","programmers never run programs","there is no difference","the programmer writes the instructions"],"correct":3,"explain":"Programming means authoring behavior, not just consuming it.","difficulty":"medium"},{"id":"zf103","topic":"","text":"Robust programs are ones that:","options":["handle invalid input sensibly","never receive input","only run once","compile without warnings"],"correct":0,"explain":"Real users mistype; good programs check and respond rather than crash.","difficulty":"medium"},{"id":"zf104","topic":"","text":"Automating a manual task with a program pays off most when the task:","options":["happens exactly once","must be repeated many times","has no clear rules","cannot be described"],"correct":1,"explain":"The effort to code it is repaid on every subsequent run.","difficulty":"medium"},{"id":"zf105","topic":"","text":"Which is a realistic beginner program?","options":["a complete operating system","a full self-driving car","computing weekly pay from hours and rate","a worldwide social network"],"correct":2,"explain":"Small, well-defined calculations are exactly where programming starts.","difficulty":"medium"}],"D286/u1/z1_11":[{"id":"zya1_11_0","topic":"Case sensitivity","text":"Java identifiers are case sensitive, so main and Main are:","options":["Different identifiers","Interchangeable in method names","Only different inside classes","The same identifier"],"correct":0,"explain":"This is why System.out.Println fails: the method is println with a lowercase p."},{"id":"zya1_11_1","topic":"Missing semicolon","text":"Omitting a semicolon at the end of a statement causes:","options":["A compile-time syntax error","A logic error","A warning only","A runtime exception"],"correct":0,"explain":"The compiler cannot tell where the statement ends, so compilation fails before the program can run."},{"id":"zya1_11_2","topic":"String literal quotes","text":"A String literal in Java must be enclosed in:","options":["Double quotes","Backticks","Either single or double quotes","Single quotes"],"correct":0,"explain":"Double quotes make a String; single quotes make a char. 'a' and "a" are different types."},{"id":"zya1_11_3","topic":"Brace mismatch","text":"An unmatched closing brace produces:","options":["A syntax error at compile time","A warning that can be ignored","No effect","A logic error at runtime"],"correct":0,"explain":"Braces define block structure. The compiler cannot guess the intended nesting."},{"id":"zya1_11_4","topic":"Whitespace between tokens","text":"Which of these compiles?","options":["Both the first and second","int x=5;","int    x   =   5   ;","intx = 5;"],"correct":0,"explain":"Java ignores the amount of whitespace between tokens, but whitespace is required to separate keywords from identifiers — intx would be read as one identifier."},{"id":"zya1_11_5","topic":"Method name typo","text":"System.out.printIn("Hi"); with a capital I fails because:","options":["println must always be called on System.err instead","The capital I is reserved for interface names","Java is case sensitive and no method named printIn exists","print and println cannot be used in one class"],"correct":2,"explain":"A very common typo — capital I instead of lowercase l in println."},{"id":"zya1_11_6","topic":"Precision in output","text":"If a test expects "Total: 42" and the program prints "Total:42", the test:","options":["Fails, because output is compared exactly","Passes with a warning","Cannot be evaluated","Passes, since the numbers match"],"correct":0,"explain":"Automated graders compare character for character. A missing space is a failure even though the logic is right."},{"id":"zya1_11_7","topic":"Consistency benefit","text":"Consistent indentation matters because:","options":["It makes block structure visible so nesting mistakes show","The compiler uses it to determine the block structure","It reduces the size of the compiled class file","It is required by the Java language specification"],"correct":0,"explain":"The compiler does not care. Humans do — misleading indentation hides which statements are actually inside a block."},{"id":"zya1_11_8","topic":"Reserved words","text":"Using class as a variable name causes:","options":["A syntax error","No problem if it is lowercase","A runtime exception","A warning"],"correct":0,"explain":"Reserved words cannot be identifiers. Neither can int, for, if, new, and the rest of the keyword list. Class is a reserved keyword."},{"id":"n_n1_11_a","topic":"Precision","text":"Why is "Hello" different from "hello" in Java?","options":["Strings ignore case","The compiler lowercases identifiers","Only class names are case-sensitive","Java is case-sensitive"],"correct":3,"explain":"Case matters in identifiers, keywords, class names and string comparisons alike. It is the most common source of "but it looks the same" bugs."},{"id":"n_n1_11_b","topic":"Output","text":"System.out.println("Hello".equals("hello")); prints:","options":["Hello","Compile error","false","true"],"correct":2,"explain":"equals compares content exactly, including case. Use equalsIgnoreCase when case should not matter."},{"id":"n_n1_11_c","topic":"Precision","text":"Which is required at the end of a Java statement?","options":["A semicolon","A newline","A period","A closing brace"],"correct":0,"explain":"Java uses the semicolon as its statement terminator, which is why line breaks are free and indentation is only for readability."},{"id":"zf106","topic":"","text":"Java is case-sensitive, which means:","options":["uppercase letters are not allowed","keywords may be capitalized freely","case only matters inside strings","total and Total are two different identifiers"],"correct":3,"explain":"Every name is matched exactly, capital letters included.","difficulty":"medium"},{"id":"zf107","topic":"","text":"Typing system.out.println (lowercase s) causes:","options":["a compile error - the class is System","the same output as System","a runtime warning","slower printing"],"correct":0,"explain":"There is no class named system; case must match exactly.","difficulty":"medium"},{"id":"zf108","topic":"","text":"What is the output? System.out.println("A  B"); (two spaces between A and B)","options":["A B - spaces collapse to one","A  B - both spaces are kept","AB","A, then B on a new line"],"correct":1,"explain":"Inside quotes, every character including each space is output verbatim.","difficulty":"medium"},{"id":"zf109","topic":"","text":"Misspelling a method name, as in System.out.printn("Hi");, causes:","options":["the text Hi to print anyway","a runtime exception after printing","a compile error (cannot find symbol)","an automatic correction"],"correct":2,"explain":"The compiler finds no method named printn on System.out.","difficulty":"medium"},{"id":"zf110","topic":"","text":"What is the output? System.out.print("Hi"); System.out.print("There");","options":["Hi There","Hi, then There on a new line","HiThere","There Hi"],"correct":2,"explain":"print adds nothing between calls - no space, no newline.","difficulty":"medium"},{"id":"zf111","topic":"","text":"System.out.println(); with nothing between the parentheses:","options":["is a compile error","prints the word null","prints a space","prints just a newline"],"correct":3,"explain":"Empty println is the standard way to output a blank line.","difficulty":"medium"},{"id":"zf112","topic":"","text":"An automated grader expects "Total: 10" but your program prints "Total:10". The result is:","options":["a mismatch - the space matters","a pass - spaces are ignored","a compile error","a crash"],"correct":0,"explain":"Expected output must match character-for-character, spaces included.","difficulty":"medium"},{"id":"zf113","topic":"","text":"A missing closing quote in a string literal causes:","options":["the rest of the file to print","a compile error","an empty string","a runtime exception"],"correct":1,"explain":"The compiler cannot tell where the string ends, so it rejects the line.","difficulty":"medium"},{"id":"zf114","topic":"","text":"Mismatched braces - an opening { without its closing } - cause:","options":["nothing, braces are optional","a warning only","a compile error","an infinite loop"],"correct":2,"explain":"Every block must be closed; the compiler counts braces exactly.","difficulty":"medium"},{"id":"zf115","topic":"","text":"Which statement about indentation in Java is TRUE?","options":["Wrong indentation is a compile error","Indentation controls which block a statement is in","Tabs are forbidden by the compiler","It never changes meaning, but consistent style is expected"],"correct":3,"explain":"Braces define blocks in Java; indentation exists for human readers - unlike Python.","difficulty":"medium"},{"id":"zf116","topic":"","text":"Why must beginners be extra careful with ; placement?","options":["a stray semicolon changes the meaning","semicolons are optional in Java","extra semicolons speed up the code","the JVM removes them all"],"correct":0,"explain":"For example, a stray ; right after an if-condition ends the if with an empty body.","difficulty":"medium"},{"id":"zf117","topic":"","text":"Main and main in the same class are:","options":["the same method","two different names","both entry points","a compile error just for existing"],"correct":1,"explain":"Case-sensitivity means the JVM will not treat Main as the starting method.","difficulty":"medium"},{"id":"zf118","topic":"","text":"What is the output? System.out.println("Name:"); System.out.println("Ava");","options":["Name:Ava on one line","Ava then Name:","Name: then Ava on the next line","Name: Ava with a space"],"correct":2,"explain":"Each println ends the line, so the two strings appear on separate lines.","difficulty":"medium"}],"D286/u1/z1_12":[{"id":"zya1_12_0","topic":"Concatenation with +","text":"What does System.out.println("Ann" + " " + "Lee"); print?","options":["Ann + Lee","Ann Lee","AnnLee"],"correct":1,"explain":"The + operator joins Strings exactly as given, including the explicit space literal in the middle."},{"id":"zya1_12_1","topic":"Missing space","text":"System.out.println("Ann" + "Lee"); prints:","options":["Ann Lee","AnnLee","Ann,Lee","A compile error"],"correct":1,"explain":"Concatenation adds nothing of its own. Any space you want must be written into a literal."},{"id":"zya1_12_2","topic":"Building a couple name","text":"Given String first = "Ann", last = "Lee"; which produces "Ann Lee"?","options":["first + last","first + " " + last","first " " last","first, last"],"correct":1,"explain":"Each piece must be joined with +, and the separating space is its own String literal."},{"id":"zya1_12_3","topic":"Print vs println","text":"The difference between print and println is:","options":["println adds a newline after the output; print does not","print adds a newline after the output; println does not","println writes to the error stream; print to standard out","println accepts only strings; print accepts any type"],"correct":0,"explain":"Using print twice puts both outputs on the same line, which is often what these formatting exercises are testing."},{"id":"zya1_12_4","topic":"Concatenating in stages","text":"String s = "A"; s = s + "B"; s = s + "C"; System.out.println(s); prints:","options":["A","ABC","CBA","ABC with spaces"],"correct":1,"explain":"Each assignment builds a new String from the old one. Strings are immutable, so s is reassigned rather than modified in place."},{"id":"zy1_12_6_c22","topic":"Concatenation","text":"System.out.println("5" + 3 + 2); prints:","options":["55","532","5 3 2","10"],"correct":1,"explain":"Left-to-right, + with a String concatenates → "532".","__rebal":1},{"id":"zy1_12_7_x286_ba2","topic":"String concatenation","_dom":"basics","text":"In Java, which operator joins two Strings together?","options":["+","concat only","&","."],"correct":0,"explain":"The + operator concatenates Strings (String has a concat() method too).","__rebal":1},{"id":"zy1_12_8_lg_D286_2_9","topic":"Concatenation","text":"The expression 1 + 2 + &quot;a&quot; evaluates to:","options":["12a","a12","error","3a"],"correct":3,"explain":"Left to right: 1+2=3, then 3+"a" is the string 3a.","__rebal":1},{"id":"n_n1_12_a","topic":"Output","text":"String a = "Ann", b = "Lee"; System.out.println(a + " " + b); prints:","options":["a b","Ann Lee","AnnLee","Ann+Lee"],"correct":1,"explain":"Concatenation joins the pieces exactly as given. The space appears only because a literal " " was concatenated between them."},{"id":"n_n1_12_b","topic":"Output","text":"System.out.println("Ann" + 1 + 2); prints:","options":["Ann3","3Ann","Ann 1 2","Ann12"],"correct":3,"explain":"Evaluation is left to right. "Ann" + 1 is already a String, so + 2 appends rather than adds."},{"id":"n_n1_12_c","topic":"Output","text":"System.out.println(1 + 2 + "Ann"); prints:","options":["3Ann","12Ann","Ann3","Ann12"],"correct":0,"explain":"The two ints are added first because no String is involved yet; only then does the String appear and switch + to concatenation. Compare with "Ann" + 1 + 2."},{"id":"fs_z1_12_1","topic":"String concatenation","text":"What does this print?

String first = "Grace";
String last = "Hopper";
System.out.println("Mr. and Mrs. " + first + " " + last);","options":["Mr. and Mrs. Grace Hopper","Mr. and Mrs. GraceHopper","Mr. and Mrs. first last","Mr. and Mrs.Grace Hopper"],"correct":0,"explain":"When an operand of + is a String, + concatenates. The literal " " between the variables supplies the space; without it the names would run together."},{"id":"fs_z1_12_2","topic":"Scanner next()","text":"A user runs a program and types Ada Lovelace on one line, then presses Enter. What does a single call to scnr.next() return?","options":["Lovelace","An empty string","Ada","Ada Lovelace"],"correct":2,"explain":"next() reads a single whitespace-delimited word, so it stops at the space and returns only Ada. Reading the whole line including the space requires nextLine()."},{"id":"fs_z1_12_3","topic":"Why two next() calls","text":"In the married-couple names program, why does the code call next() twice rather than nextLine() once?","options":["It needs the two names as separate values so it can join them with its own text in between","nextLine() does not exist on Scanner","next() reads input faster than nextLine()","nextLine() can only be called once per program"],"correct":0,"explain":"The program relies on reading exactly one word per call so it can rebuild the sentence around the pieces. Swapping in nextLine() would silently change what gets read, with no error message."},{"id":"zf119","topic":"","text":"String w = "Ana"; String h = "Luis"; System.out.println(w + " and " + h); prints:","options":["AnaandLuis","Luis and Ana","w and h","Ana and Luis"],"correct":3,"explain":"Each + joins the pieces exactly as given; the variable VALUES are used, not the names.","difficulty":"medium"},{"id":"zf120","topic":"","text":"String w = "Mia"; String h = "Noah"; System.out.println(w + " and " + h); prints:","options":["MiaandNoah","Noah and Mia","w and h","Mia and Noah"],"correct":3,"explain":"Each + joins the pieces exactly as given; the variable VALUES are used, not the names.","difficulty":"medium"},{"id":"zf121","topic":"","text":"String w = "Zoe"; String h = "Eli"; System.out.println(w + " and " + h); prints:","options":["Zoe and Eli","ZoeandEli","Eli and Zoe","w and h"],"correct":0,"explain":"Each + joins the pieces exactly as given; the variable VALUES are used, not the names.","difficulty":"medium"},{"id":"zf122","topic":"","text":"String first = "Ivy"; System.out.println(first + " " + "Max"); prints:","options":["IvyMax","Ivy Max","first Max",""Ivy" "Max""],"correct":1,"explain":"The + operator concatenates the value of first, a space, and the literal.","difficulty":"medium"},{"id":"zf123","topic":"","text":"String first = "Lea"; System.out.println(first + " " + "Sam"); prints:","options":["LeaSam","first Sam","Lea Sam",""Lea" "Sam""],"correct":2,"explain":"The + operator concatenates the value of first, a space, and the literal.","difficulty":"medium"},{"id":"zf124","topic":"","text":"In System.out.println("Mr. " + lastName);, the + operator:","options":["adds their lengths numerically","compares the two strings","prints them on two lines","joins them into one string"],"correct":3,"explain":"With a string operand, + always means concatenation.","difficulty":"medium"},{"id":"zf125","topic":"","text":"String concatenation with + inserts spaces:","options":["never - you must add them in the quotes","automatically between every operand","only between two variables","only at the end of the line"],"correct":0,"explain":"Forgetting the space inside the literal is the classic run-together-names bug.","difficulty":"medium"},{"id":"zf126","topic":"","text":"String couple = "Ann" + " & " + "Ben"; The variable couple holds:","options":["Ann&Ben","Ann & Ben",""Ann" & "Ben"","Ann + Ben"],"correct":1,"explain":"Concatenation runs left to right, keeping the spaces inside " & ".","difficulty":"medium"},{"id":"zf127","topic":"","text":"System.out.println("Lopez" + ", " + "Rio"); prints:","options":["Lopez,Rio","Rio, Lopez","Lopez, Rio","Lopez , Rio"],"correct":2,"explain":"The literal ", " supplies both the comma and the single space.","difficulty":"medium"},{"id":"zf128","topic":"","text":"If name holds "Kim", System.out.println("Hello " + name + "!"); prints:","options":["Hello name!","Hello Kim !","HelloKim!","Hello Kim!"],"correct":3,"explain":"The variable’s value drops into the middle; the ! follows with no space.","difficulty":"medium"},{"id":"zf129","topic":"","text":"Concatenating a string and an int, as in "Age: " + 30, produces:","options":["the string Age: 30","a compile error","the number 30 alone","Age: plus a random number"],"correct":0,"explain":"Java converts the int to text and joins it - handy for building output.","difficulty":"medium"}],"D286/u2/z2_2":[{"id":"zya2_2_0","topic":"int declaration","text":"Which correctly declares an int variable and gives it the value 7?","options":["integer x = 7;","x int = 7;","int x == 7;","int x = 7;"],"correct":3,"explain":"Type, then name, then = for assignment. integer is not a Java type, and == is comparison, not assignment."},{"id":"zya2_2_1","topic":"Uninitialized local","text":"int count; System.out.println(count); produces:","options":["A runtime exception","0","null","A compile error"],"correct":3,"explain":"Local variables get no default value. Fields do default to 0, which is why this trips people who have seen fields work. Variable count might not have been initialized."},{"id":"zya2_2_2","topic":"Declaration vs assignment","text":"In int x = 5;, the "= 5" part is called:","options":["A cast","A declaration","A comparison","Initialization"],"correct":3,"explain":"Declaring introduces the name and type; initializing gives it its first value. Both happen in one statement here."},{"id":"zya2_2_3","topic":"Reassignment","text":"int x = 3; x = 8; After these lines x holds:","options":["11","A compile error","3","8"],"correct":3,"explain":"Assignment replaces the value. The variable holds one value at a time — the most recent one assigned."},{"id":"zya2_2_4","topic":"Multiple declaration","text":"Which declares three ints on one line?","options":["int a + b + c;","int a, b, c;","int a; b; c;","int a and b and c;"],"correct":1,"explain":"Commas separate names sharing one type. You may also initialize them: int a = 1, b = 2;"},{"id":"zy2_2_6_b10","topic":"int size","text":"An int occupies how many bits?","options":["8","64","16","32"],"correct":3,"explain":"int is 32-bit (range about ±2.1 billion).","__rebal":1},{"id":"zy2_2_8_lg_D286_0_2","topic":"int size","text":"How many bits does a Java int occupy?","options":["64 bits","16 bits","8 bits","32 bits"],"correct":3,"explain":"A Java int is a 32-bit signed integer.","__rebal":1},{"id":"n_n2_2_a","topic":"Variables","text":"int x; System.out.println(x); inside a method:","options":["Throws an exception","Does not compile","Prints 0","Prints null"],"correct":1,"explain":"Java refuses to read a local variable that has not been assigned. FIELDS get a default of 0, but locals do not — this distinction is examined. Local variables must be initialised."},{"id":"n_n2_2_b","topic":"Variables","text":"The range of an int is about:","options":["0 to 4,294,967,295","-32,768 to 32,767","unlimited","-2,147,483,648 to 2,147,483,647"],"correct":3,"explain":"int is 32 bits, signed, so the range is -2^31 to 2^31 - 1. Needing more means using long."},{"id":"n_n2_2_c","topic":"Output","text":"int a = 5; int b = a; a = 9; System.out.println(b); prints:","options":["5","9","0","Compile error"],"correct":0,"explain":"b received a COPY of the value at the time of assignment. Changing a afterwards cannot reach b, because primitives are copied by value."},{"id":"fs_z2_2_1","topic":"Field default values","text":"What does this program print?

public class Demo {
    static int startCount;
    public static void main(String[] args) {
        System.out.println(startCount);
    }
}","options":["A random leftover value","null","0","Compiler error: startCount might not have been initialized"],"correct":2,"explain":"Fields automatically get their type's default value - 0 for int - so this prints 0. Only local variables have no default and must be assigned before use."},{"id":"fs_z2_2_2","topic":"Definite assignment","text":"int result;
if (score > 90) { result = 1; }
System.out.println(result);

Why does the compiler reject this, even if score is in fact always above 90?","options":["The compiler rejects any path where result might be unassigned","int variables cannot be assigned inside an if statement","result went out of scope inside the if block","println cannot print an int"],"correct":0,"explain":"The compiler is deliberately strict: it rejects any path where a local might be read unassigned, even one you can prove never happens. Initialize at declaration or assign in every branch. As far as it knows, the condition could be false."},{"id":"fs_z2_2_3","topic":"int range","text":"Which value is too large to store in an int?","options":["-2,000,000,000","65,536","3,000,000,000","2,000,000,000"],"correct":2,"explain":"An int holds roughly -2.1 billion to +2.1 billion (max 2,147,483,647). Three billion exceeds that ceiling and needs a long."},{"id":"zf141","topic":"","text":"The int type stores:","options":["numbers with decimal points","single characters","whole numbers, positive or negative","text"],"correct":2,"explain":"int is for integers; double handles fractional values.","difficulty":"medium"},{"id":"zf142","topic":"","text":"int price = 8.99; causes:","options":["price to become 8","price to become 9","a runtime exception","a compile error"],"correct":3,"explain":"Java will not silently drop the .99; you would need a double or a cast.","difficulty":"medium"},{"id":"zf143","topic":"","text":"Which literal is a valid int value?","options":["-250","3.14",""42"","2,500"],"correct":0,"explain":"ints are plain whole numbers - no decimal point, quotes, or commas.","difficulty":"medium"},{"id":"zf144","topic":"","text":"int t = 5; t = t - 4; t = t + 2; System.out.println(t); prints:","options":["-1","3","11","5"],"correct":1,"explain":"5 - 4 = 1, then 1 + 2 = 3. Each assignment uses the latest value.","difficulty":"medium"},{"id":"zf145","topic":"","text":"int t = 11; t = t - 3; t = t + 6; System.out.println(t); prints:","options":["2","20","14","11"],"correct":2,"explain":"11 - 3 = 8, then 8 + 6 = 14. Each assignment uses the latest value.","difficulty":"medium"},{"id":"zf146","topic":"","text":"counter++; does the same thing as:","options":["counter = counter * 2;","counter = 1;","System.out.println(counter);","counter = counter + 1;"],"correct":3,"explain":"The ++ operator is shorthand for adding one.","difficulty":"medium"},{"id":"zf147","topic":"","text":"int k = 9; k--; System.out.println(k); prints:","options":["8","9","10","-9"],"correct":0,"explain":"k-- subtracts one, leaving 8.","difficulty":"medium"},{"id":"zf148","topic":"","text":"Two int variables x and y can swap values using:","options":["x = y; y = x; alone","a third temporary variable","the swap keyword","parentheses"],"correct":1,"explain":"x = y; y = x; loses the original x. Save it first: temp = x; x = y; y = temp;","difficulty":"medium"},{"id":"zf149","topic":"","text":"int mile = 1; int run = mile; mile = mile + mile; System.out.println(run + " " + mile); prints:","options":["2 2","1 1","1 2","2 1"],"correct":2,"explain":"run copied the original 1; mile then became 1 + 1 = 2.","difficulty":"medium"},{"id":"zf150","topic":"","text":"The result of adding two int values in Java is:","options":["always a double","a String","an int","a long"],"correct":2,"explain":"int op int stays int - including division, where the fraction is dropped.","difficulty":"medium"},{"id":"zf151","topic":"","text":"A good type for counting how many students are in a class is:","options":["double","char","String","int"],"correct":3,"explain":"Counts are whole numbers - exactly what int is for.","difficulty":"medium"},{"id":"zj10","topic":"int variables","text":"int count = 5; count = count + 3; count = count * 2; What is count?","options":["13","16","11","10"],"correct":1,"explain":"Each assignment replaces the value in order: 5 + 3 = 8, then 8 * 2 = 16. The right side is worked out first, then stored.","difficulty":"medium"}],"D286/u2/z2_3":[{"id":"zya2_3_0","topic":"Valid identifier","text":"Which is a legal Java identifier?","options":["_total","class","2ndPlace","my-score"],"correct":0,"explain":"Identifiers may start with a letter, underscore or dollar sign — not a digit. Hyphens are not allowed, and class is a reserved word."},{"id":"zya2_3_1","topic":"Illegal first character","text":"Why is 3rdValue invalid as a variable name?","options":["Identifiers cannot begin with a digit","It contains uppercase letters","Numbers are never allowed","It is too long"],"correct":0,"explain":"Digits are allowed inside an identifier, just not as the first character."},{"id":"zya2_3_2","topic":"Convention for variables","text":"Java convention names a variable holding a student count as:","options":["studentCount","student_count","STUDENT_COUNT","StudentCount"],"correct":0,"explain":"camelCase for variables and methods, PascalCase for class names, ALL_CAPS for constants. Convention, not syntax — but graders and readers expect it."},{"id":"zy2_3_3_zb2","topic":"Identifiers","text":"Java identifiers are:","options":["case-sensitive","limited to 8 characters","allowed to be keywords","case-insensitive"],"correct":0,"explain":"count and Count are different identifiers.","__rebal":1},{"id":"zy2_3_7_lg_D286_1_51","topic":"Identifiers","text":"Java identifiers are case-sensitive:","options":["only for classes","false","true","only for methods"],"correct":2,"explain":"count and Count are distinct names.","__rebal":1},{"id":"zy2_3_8_lg_D286_2_10","topic":"Identifiers","text":"Which identifier will NOT compile?","options":["total2","_count","2total","$price"],"correct":2,"explain":"Identifiers cannot start with a digit.","__rebal":1},{"id":"zyf2_3_0","topic":"Dollar sign","text":"Is $count a legal Java identifier?","options":["No, identifiers may start only with a letter","No, $ is reserved for compiler-generated names","Yes, $ is permitted though conventionally avoided","Yes, and $ is the conventional prefix for fields"],"correct":2,"explain":"Legal but by convention reserved for generated code."},{"id":"n_n2_3_b","topic":"Identifiers","text":"The conventional style for a variable name is:","options":["camelCase starting lowercase","PascalCase","ALL_CAPS","snake_case"],"correct":0,"explain":"Variables and methods use camelCase, classes use PascalCase, and constants use ALL_CAPS. Following it makes the role of a name visible at a glance."},{"id":"fs_z2_3_1","topic":"Identifier rules","text":"The declaration int my-score = 5; fails to compile because:","options":["Identifiers may not contain lowercase letters","Variable names may not be longer than seven characters","score is a reserved word","Hyphens are not allowed in identifiers"],"correct":3,"explain":"Identifiers may use letters, digits, underscore, and dollar sign, but never hyphens or spaces. Java would parse my-score as my minus score. Java reads the hyphen as a minus sign."},{"id":"fs_z2_3_2","topic":"Rules vs conventions","text":"The declaration int Total = 10; is:","options":["Legal and perfectly conventional","Legal, but it breaks the convention that variable names start with a lowercase letter","A compile error, because identifiers cannot start with an uppercase letter","A compile error, because Total is a reserved word"],"correct":1,"explain":"The compiler accepts Total - the uppercase start is only a style violation. Convention reserves PascalCase for class names and camelCase for variables."},{"id":"fs_z2_3_3","topic":"Reserved words","text":"Why can the name class not be used for a variable?","options":["It starts with a lowercase letter","It conflicts with the camelCase convention","It can be used - the code compiles fine","It is a reserved word that Java has claimed for itself"],"correct":3,"explain":"Reserved words like class, int, for, and new are claimed by the language and can never be used as identifiers. This is a compiler rule, not a style convention."},{"id":"zf152","topic":"","text":"Which of these can be used as a Java variable name?","options":["maxValue","2ndPlace","max-value","max value"],"correct":0,"explain":"Identifiers may not start with a digit or contain hyphens or spaces.","difficulty":"medium"},{"id":"zf153","topic":"","text":"Which identifier is ILLEGAL in Java?","options":["wheels4","4wheels","_wheels","$wheels"],"correct":1,"explain":"The first character must be a letter, underscore, or $ - never a digit.","difficulty":"medium"},{"id":"zf154","topic":"","text":"Why is my-score not a valid identifier?","options":["it is too short","score is a reserved word","the hyphen is read as a minus operator","identifiers cannot contain lowercase letters"],"correct":2,"explain":"my-score parses as my minus score. Use myScore or my_score.","difficulty":"medium"},{"id":"zf155","topic":"","text":"Why can’t a variable be named class?","options":["it starts with c","it is too common","class is a method name","class is a reserved keyword"],"correct":3,"explain":"Keywords like class, int, for, and while can never be identifiers.","difficulty":"medium"},{"id":"zf156","topic":"","text":"price and Price in the same program are:","options":["two different variables","the same variable","a compile error just for existing","automatically merged"],"correct":0,"explain":"Java is case-sensitive, so the capital P makes a different name.","difficulty":"medium"},{"id":"zf157","topic":"","text":"Which identifier follows Java’s camelCase convention for variables?","options":["GrossPayAmount","grossPay","gross-pay","GROSS_PAY"],"correct":1,"explain":"Variables start lowercase with each later word capitalized; GrossPayAmount is styled like a class name, GROSS_PAY like a constant.","difficulty":"medium"},{"id":"zf158","topic":"","text":"Digits may appear in an identifier:","options":["nowhere","only at the start","anywhere except the first character","only if the name is all digits"],"correct":2,"explain":"count2 and top10 are fine; 2count is not.","difficulty":"medium"},{"id":"zf159","topic":"","text":"Which character may legally START an identifier?","options":["a digit","a hyphen","a space","an underscore _"],"correct":3,"explain":"Letters, _ and $ can start a name; digits can only appear later.","difficulty":"medium"},{"id":"zf160","topic":"","text":"The identifier $revenue is:","options":["a compile error","legal only inside strings","reserved for the JVM","legal, though $ is discouraged"],"correct":3,"explain":"The dollar sign is allowed by the language but by convention left to generated code.","difficulty":"medium"},{"id":"zf161","topic":"","text":"total_sum and totalSum are:","options":["two distinct legal identifiers","the same identifier","both compile errors","legal only as class names"],"correct":0,"explain":"Underscores are allowed; the two spellings are simply distinct variables.","difficulty":"medium"},{"id":"zf162","topic":"","text":"A good variable name like hoursWorked beats a name like h because:","options":["longer names run faster","it tells the reader what the value means","the compiler requires 5+ characters","single letters are compile errors"],"correct":1,"explain":"Both compile - but only one makes the program understandable.","difficulty":"medium"},{"id":"zf163","topic":"","text":"Which of these is a reserved word that cannot be an identifier?","options":["whilst","loop","while","repeat"],"correct":2,"explain":"while is a Java keyword; the others are ordinary (legal) names.","difficulty":"medium"},{"id":"zf164","topic":"","text":"An identifier containing a space, like first name:","options":["is legal in quotes","works only for Strings","is treated as one name","is a compile error"],"correct":3,"explain":"The compiler sees two separate tokens. Use firstName instead.","difficulty":"medium"},{"id":"zf165","topic":"","text":"firstName. and first.name as a variable name:","options":["illegal - periods are not allowed","is legal everywhere","means the same as firstName","is a constant"],"correct":0,"explain":"The dot is the member-access operator, so it cannot be part of a name.","difficulty":"medium"},{"id":"zy2_1_3_z286_ba6","topic":"Identifiers","_dom":"basics","text":"Which of the following are valid Java identifiers (variable names)? (Select all that apply.)","options":["count","_total","2nd","myValue"],"multi":true,"correctSet":[0,1,3],"explain":"Identifiers may start with a letter, _ or $, but not a digit, so 2nd is invalid."}],"D286/u2/z2_4":[{"id":"zya2_4_0","topic":"Precedence","text":"What is the value of 2 + 3 * 4?","options":["20","14","24","9"],"correct":1,"explain":"Multiplication binds tighter than addition, so 3 * 4 evaluates first. Parentheses are the way to override this."},{"id":"zy2_4_8_bp_D286_q7_6","topic":"Concatenation trap","text":"System.out.println(n + " x " + i + " = " + n * i); — why does n * i print correctly without parentheses?","options":["* has higher precedence than +, so n * i computes before joining the string","It doesn't — it prints the concatenation of n and i","println adds them automatically","Java evaluates right to left"],"correct":0,"explain":"Multiplication binds tighter than +. But (n + i) would NOT work unparenthesized: + would concatenate. Parenthesizing arithmetic in print statements is the safe habit.","distractors":{"0":"* wins precedence; the multiply happens first.","2":"println prints what it's given.","3":"Java is left-to-right within equal precedence."},"__rebal":1},{"id":"fs_z2_4_1","topic":"Left-to-right evaluation","text":"What does this print?

System.out.println(20 / 5 * 2);","options":["20","50","8","2"],"correct":2,"explain":"Division and multiplication have equal precedence, so Java works strictly left to right: (20 / 5) * 2 = 8. Reading 5 * 2 as the divisor gives the wrong answer 2."},{"id":"fs_z2_4_2","topic":"Modulo precedence","text":"What does this print?

System.out.println(10 + 7 % 3);","options":["11","2","5","1"],"correct":0,"explain":"% ranks with * and /, binding tighter than +. So 7 % 3 = 1 happens first, then 10 + 1 = 11. Computing (10 + 7) % 3 would give the tempting wrong answer 2."},{"id":"fs_z2_4_3","topic":"Chained division","text":"What does this print?

System.out.println(100 / 10 / 2);","options":["2","5","20","10"],"correct":1,"explain":"Equal-precedence operators evaluate left to right: (100 / 10) / 2 = 5. Grouping the right side first, 100 / (10 / 2), would give 20 - but Java never groups that way."},{"id":"fs_z2_4_4","topic":"Associativity","text":"When two operators of equal precedence appear in an expression such as 10 - 4 - 3, Java evaluates:","options":["In an unspecified order that may vary","Left to right, giving (10 - 4) - 3 = 3","Right to left, giving 10 - (4 - 3) = 9","Whichever order produces the larger result"],"correct":1,"explain":"Java's arithmetic operators are left-associative: equal-precedence operators apply strictly left to right, so 10 - 4 - 3 is (10 - 4) - 3 = 3."},{"id":"fs_z2_4_5","topic":"The invisible division bar","text":"For int variables a, b, and c, the expression a + b + c / 3 computes:","options":["A compile error","a + b + (c / 3)","(a + b + c) / 3, the average of the three","a + (b + c) / 3"],"correct":1,"explain":"Division outranks addition, so only c is divided by 3. A formula written as a fraction has implied parentheses around the whole numerator: the average needs (a + b + c) / 3. Division binds tighter than addition."},{"id":"fs_z2_4_6","topic":"No power operator","text":"Which correctly computes 2 raised to the 5th power in Java?","options":["pow(2, 5) with no class name","Math.pow(2, 5)","2 ^ 5","2 ** 5"],"correct":1,"explain":"Java has no exponent operator: ^ is bitwise XOR, not a power, and ** does not exist. Use Math.pow (or repeated multiplication)."},{"id":"zf166","topic":"","text":"System.out.println(3 + 4 * 6); prints:","options":["42","27","18","13"],"correct":1,"explain":"* binds tighter than +: 3 + 24 = 27.","difficulty":"medium"},{"id":"zf167","topic":"","text":"System.out.println(7 + 2 * 5); prints:","options":["45","19","17","14"],"correct":2,"explain":"* binds tighter than +: 7 + 10 = 17.","difficulty":"medium"},{"id":"zf168","topic":"","text":"System.out.println((4 + 5) * 2); prints:","options":["14","11","13","18"],"correct":3,"explain":"Parentheses first: 9 * 2 = 18.","difficulty":"medium"},{"id":"zf169","topic":"","text":"System.out.println((8 + 3) * 4); prints:","options":["44","20","15","35"],"correct":0,"explain":"Parentheses first: 11 * 4 = 44.","difficulty":"medium"},{"id":"zf170","topic":"","text":"System.out.println(10 - 4 - 3); prints:","options":["3","9","11","-3"],"correct":0,"explain":"Same-precedence operators evaluate left to right: (10 - 4) - 3 = 3.","difficulty":"medium"},{"id":"zf171","topic":"","text":"System.out.println(20 - 7 - 5); prints:","options":["18","8","22","-8"],"correct":1,"explain":"Same-precedence operators evaluate left to right: (20 - 7) - 5 = 8.","difficulty":"medium"},{"id":"zf172","topic":"","text":"Which operators does Java evaluate FIRST in a * b + c?","options":["the addition b + c","left to right regardless of operator","the multiplication a * b","whichever is larger"],"correct":2,"explain":"* and / outrank + and -; only parentheses override that.","difficulty":"medium"},{"id":"zf173","topic":"","text":"System.out.println(2 * 3 + 4 * 5); prints:","options":["70","50","120","26"],"correct":3,"explain":"Both products happen first: 6 + 20 = 26.","difficulty":"medium"},{"id":"zf174","topic":"","text":"The ^ symbol in Java:","options":["is NOT exponentiation","raises to a power","is a compile error everywhere","rounds a number"],"correct":0,"explain":"^ is bitwise XOR. 2 ^ 3 is 1, not 8 - a classic trap.","difficulty":"medium"},{"id":"zf175","topic":"","text":"System.out.println(-4 + 10); prints:","options":["-6","6","14","-14"],"correct":1,"explain":"Unary minus applies to the 4 alone; -4 + 10 = 6.","difficulty":"medium"},{"id":"zf176","topic":"","text":"int r = 3 + 4; r = r * 2; System.out.println(r); prints:","options":["11","7","14","24"],"correct":2,"explain":"r becomes 7, then doubles to 14.","difficulty":"medium"},{"id":"zf177","topic":"","text":"Adding parentheses that match the default precedence, like a + (b * c):","options":["causes a compile error","forces the addition first","slows the program","changes nothing; clarifies intent"],"correct":3,"explain":"Redundant parentheses are legal and often good documentation.","difficulty":"medium"},{"id":"zf178","topic":"","text":"System.out.println(18 - 3 * 4); prints:","options":["6","60","3","30"],"correct":0,"explain":"Multiplication first: 18 - 12 = 6.","difficulty":"medium"},{"id":"zj5","topic":"Operator precedence","text":"What is the value of 2 + 3 * 4 in Java?","options":["20","14","24","9"],"correct":1,"explain":"Multiplication binds tighter than addition, so 3 * 4 is evaluated first and 2 is added: 2 + 12 = 14.","difficulty":"medium"},{"id":"zj6","topic":"Parentheses","text":"double avg = a + b / 2; with a = 4 and b = 10. Why does this NOT give the average?","options":["Because a and b must both be double to divide","Because integer division truncates the result to 9","Division runs before addition, so only b is halved","Because addition and division cannot mix in one expression"],"correct":2,"explain":"It evaluates as a + (b / 2) = 4 + 5 = 9, not (4 + 10) / 2 = 7. Averaging needs parentheses: (a + b) / 2.","difficulty":"medium"},{"id":"zj7","topic":"Precedence of %","text":"int result = 9 + 12 % 5; What is result?","options":["1","4","21","11"],"correct":3,"explain":"% sits at the same precedence as * and /, so it binds before +. 12 % 5 is 2, then 9 + 2 = 11.","difficulty":"medium"},{"id":"zj8","topic":"Same-precedence operators","text":"Which operators sit at the SAME precedence level as each other in Java?","options":["* / and %","+ and *","- and /","% and +"],"correct":0,"explain":"Multiplication, division and remainder share one level and are evaluated left to right; addition and subtraction share a lower one.","difficulty":"medium"}],"D286/u2/z2_6":[{"id":"zya2_6_0","topic":"BMI formula in code","text":"BMI is weight / (height * height). Which expression is correct in Java for doubles w and h?","options":["(w / h) * h","w / h ^ 2","w / h * h","w / (h * h)"],"correct":3,"explain":"Without parentheses, w / h * h evaluates left to right and cancels out to w. Java also has no exponent operator — ^ is bitwise XOR."},{"id":"zya2_6_1","topic":"Choosing the type","text":"Weight in kilograms with a decimal part should be stored as:","options":["char","boolean","int","double"],"correct":3,"explain":"Any quantity with a fractional part needs double. Using int would silently truncate 70.5 to 70."},{"id":"zya2_6_2","topic":"Integer division trap","text":"int total = 7, count = 2; double avg = total / count; What is avg?","options":["3","A compile error","3.5","3.0"],"correct":3,"explain":"Both operands are int, so integer division runs first and gives 3. Widening to double happens after, producing 3.0 — the loss is already done."},{"id":"zya2_6_3","topic":"Fixing the division","text":"How do you make total / count produce 3.5 for the ints above?","options":["double avg = (double)(total / count);","double avg = total / (int) count;","double avg = total / count;","double avg = (double) total / count;"],"correct":3,"explain":"Cast one operand before dividing. Casting the result, as in option 3, is too late — the truncation already happened."},{"id":"zya2_6_4","topic":"Formatted output","text":"Which prints a double bmi to two decimal places?","options":["System.out.printf("%d%n", bmi);","System.out.print(bmi, 2);","System.out.println(bmi);","System.out.printf("%.2f%n", bmi);"],"correct":3,"explain":"%.2f formats a floating-point value to two decimals. %d is for integers and throws an exception if given a double."},{"id":"zya2_6_5","topic":"Averaging three values","text":"For int a, b, c, which computes the true average as a double?","options":["a + b + c / 3","(double)(a + b + c) / 3.0","(a + b + c) / 3","(a + b + c) / 3.0"],"correct":3,"explain":"Dividing by 3.0 makes the division floating-point. Option 3 is also wrong for a second reason: precedence divides only c by 3."},{"id":"zya2_6_6","topic":"Percentage calculation","text":"To compute what percent int part is of int whole:","options":["part * (100 / whole)","part / whole * 100","100 * part / whole","100.0 * part / whole"],"correct":3,"explain":"Starting with 100.0 promotes the whole expression to double. The other forms perform integer division first and lose the fraction."},{"id":"zya2_6_7","topic":"Reading a double","text":"Which Scanner call reads a decimal number?","options":["in.next()","in.nextLine()","in.nextInt()","in.nextDouble()"],"correct":3,"explain":"nextDouble reads a floating-point token. nextInt would fail on input like 70.5."},{"id":"zya2_6_8","topic":"Unit conversion","text":"Pounds to kilograms is divide by 2.205. For double lbs, the correct expression is:","options":["lbs * 2.205","(int) lbs / 2.205","lbs / 2205","lbs / 2.205"],"correct":3,"explain":"Divide by the conversion factor as a double literal. Multiplying converts the wrong direction."},{"id":"zya2_6_9","topic":"Order of operations in a formula","text":"Which correctly computes (a + b) / 2 in Java?","options":["a + (b / 2)","a / 2 + b","a + b / 2","(a + b) / 2"],"correct":3,"explain":"Parentheses force the addition first. Without them, division binds tighter and only b is halved."},{"id":"fs_z2_6_1","topic":"Missing parentheses in a formula","text":"What does this print?

double w = 70.0, h = 1.75;
System.out.println(w / h * h);","options":["Compiler error","70.0","22.857142857142858","40.0"],"correct":1,"explain":"Left-to-right evaluation makes this (w / h) * h, which cancels back to exactly w. BMI needs the denominator parenthesized: w / (h * h)."},{"id":"fs_z2_6_2","topic":"Division by zero with doubles","text":"What does this print?

System.out.println(70.5 / 0.0);","options":["0.0","Infinity","ArithmeticException at runtime","NaN"],"correct":1,"explain":"Dividing a positive double by 0.0 produces Infinity - no exception is thrown, unlike int division by zero. 0.0 / 0.0 is the case that gives NaN."},{"id":"fs_z2_6_3","topic":"Guard clauses","text":"A BMI program checks if (heightM <= 0) and rejects the input before computing. Why is this guard necessary for doubles?","options":["Negative numbers cannot be stored in a double","Dividing by 0.0 yields Infinity with no exception","Division by zero would crash the JVM","Scanner cannot read the value 0"],"correct":1,"explain":"Double division by zero throws nothing - it produces Infinity, which flows onward into later calculations. A guard clause stops the bad input before the damage starts. Without the guard a bad value would spread silently."},{"id":"fs_z2_6_4","topic":"Formatted output","text":"What does this print?

System.out.printf("BMI: %.1f%n", 22.857142857142858);","options":["BMI: 23","BMI: 22.9","BMI: 22.8","BMI: 22.857142857142858"],"correct":1,"explain":"%.1f rounds the value to one decimal place, so 22.857... becomes 22.9. A raw println would print all the digits."},{"id":"zf190","topic":"","text":"int steps = 4200; steps = steps + 2500; System.out.println(steps); prints:","options":["4200","2500","6700","6600"],"correct":2,"explain":"The afternoon walk adds on: 4200 + 2500 = 6700 steps.","difficulty":"medium"},{"id":"zf191","topic":"","text":"int steps = 6100; steps = steps + 3800; System.out.println(steps); prints:","options":["6100","3800","9800","9900"],"correct":3,"explain":"The afternoon walk adds on: 6100 + 3800 = 9900 steps.","difficulty":"medium"},{"id":"zf192","topic":"","text":"int bpm = 72; int minutes = 5; System.out.println(bpm * minutes); prints:","options":["360","77","432","365"],"correct":0,"explain":"Beats = rate x time: 72 x 5 = 360.","difficulty":"medium"},{"id":"zf193","topic":"","text":"int bpm = 65; int minutes = 10; System.out.println(bpm * minutes); prints:","options":["75","650","715","660"],"correct":1,"explain":"Beats = rate x time: 65 x 10 = 650.","difficulty":"medium"},{"id":"zf194","topic":"","text":"int h = 2; int m = 45; int totalMin = h * 60 + m; System.out.println(totalMin); prints:","options":["47","75","165","245"],"correct":2,"explain":"2 hours is 120 minutes; plus 45 gives 165.","difficulty":"medium"},{"id":"zf195","topic":"","text":"int h = 3; int m = 20; int totalMin = h * 60 + m; System.out.println(totalMin); prints:","options":["23","160","320","200"],"correct":3,"explain":"3 hours is 180 minutes; plus 20 gives 200.","difficulty":"medium"},{"id":"zf196","topic":"","text":"int calPerMin = 9; int workout = 30; System.out.println(calPerMin * workout); prints:","options":["270","39","300","2700"],"correct":0,"explain":"9 calories per minute for 30 minutes burns 270 calories.","difficulty":"medium"},{"id":"zf197","topic":"","text":"int ozPerDay = 64; System.out.println(ozPerDay * 7); prints:","options":["71","448","420","464"],"correct":1,"explain":"64 ounces a day for a week is 448 ounces.","difficulty":"medium"},{"id":"zf198","topic":"","text":"Why store health readings in variables instead of retyping numbers?","options":["numbers cannot appear twice in Java","variables make the math more accurate","one change updates every use","the compiler requires it"],"correct":2,"explain":"Variables give the value one authoritative home - the point of the whole example.","difficulty":"medium"},{"id":"zf199","topic":"","text":"int weekOneMiles = 8; int weekTwoMiles = weekOneMiles + 2; System.out.println(weekTwoMiles); prints:","options":["8","2","82","10"],"correct":3,"explain":"Week two builds on week one: 8 + 2 = 10.","difficulty":"medium"},{"id":"zf200","topic":"","text":"int heartRate = 88; heartRate = heartRate - 12; System.out.println(heartRate); prints:","options":["88","100","76","12"],"correct":2,"explain":"After resting, the rate drops: 88 - 12 = 76.","difficulty":"medium"}],"D286/u2/z2_7":[{"id":"zya2_7_0","topic":"double literal","text":"Which is a valid double literal?","options":["3.14","3,14","3.14d only",""3.14""],"correct":0,"explain":"3.14 is a double by default. A comma is not a decimal separator in Java, and quotes make it a String."},{"id":"zya2_7_1","topic":"float suffix","text":"float f = 3.14; produces:","options":["A compile error","A runtime error","A warning only","A valid float"],"correct":0,"explain":"Decimal literals default to double, and double does not narrow to float automatically. Write 3.14f. 3.14 is a double and needs an f suffix."},{"id":"zya2_7_2","topic":"Precision limits","text":"Why does 0.1 + 0.2 == 0.3 evaluate to false?","options":["Binary floating-point cannot represent 0.1 and 0.2 exactly","== compares references, so the doubles are boxed","Java evaluates the sum before the literal 0.3","double has too few digits to hold three decimals"],"correct":0,"explain":"These fractions are repeating in binary, so tiny rounding errors accumulate. Compare using Math.abs(a - b) < 0.0001 instead."},{"id":"zya2_7_3","topic":"double vs int storage","text":"double x = 5; is:","options":["Legal","Legal but stores 5 as an int","A runtime error","A compile error"],"correct":0,"explain":"Widening from int to double is automatic and lossless. The reverse requires an explicit cast. The int 5 widens to 5.0."},{"id":"zya2_7_4","topic":"Default printing","text":"double d = 5.0; System.out.println(d); prints:","options":["5.0","5.00","5.0d","5"],"correct":0,"explain":"Java prints a double with at least one decimal place, which is how you can tell a double result from an int one in output."},{"id":"zya2_7_5","topic":"Very large double","text":"Assigning a value beyond double range produces:","options":["Infinity","0.0","An exception","A compile error"],"correct":0,"explain":"Doubles overflow to Infinity rather than wrapping around the way ints do. Division by 0.0 also yields Infinity, not an exception."},{"id":"zy2_7_8_bp_D286_r23_22","topic":"printf decimals","text":"To print a double with 2 decimals you use:","options":["print(x)","format(x)","printf("%.2f", x)","println(x)"],"correct":2,"explain":"printf("%.2f", x) formats to two decimal places.","__rebal":1},{"id":"zy2_7_9_bp_D286_t09_8","topic":"printf","text":"To print (double)a/b with 2 decimals you write:","options":["printf("%.2f%n", (double)a/b)","println((double)a/b)","printf("%d", a/b)","print(a/b)"],"correct":0,"explain":"%.2f formats two decimals; cast before dividing.","__rebal":1},{"id":"n_n2_7_a","topic":"Doubles","text":"Why can 0.1 + 0.2 == 0.3 be false in Java?","options":["The compiler reorders the addition","== is not defined for double","Binary floating-point cannot represent 0.1 or 0.2 exactly","double has too few digits"],"correct":2,"explain":"Those values are stored as the nearest representable binary fractions, so a tiny error survives the addition. Compare doubles with a tolerance instead of ==."},{"id":"n_n2_7_b","topic":"Output","text":"System.out.println(0.1 + 0.2 == 0.3); prints:","options":["false","true","0.3","Compile error"],"correct":0,"explain":"The sum is 0.30000000000000004, which is not exactly 0.3. This is the standard demonstration of why == is unsafe for doubles."},{"id":"n_n2_7_c","topic":"Doubles","text":"The safe way to compare two doubles a and b is:","options":["Double.compare(a, b) == 1","Math.abs(a","a == b","a.equals(b)"],"correct":1,"explain":"You test whether they are close enough rather than identical, because exact equality is rarely achievable in binary floating point. B) < a small tolerance."},{"id":"fs_z2_7_2","topic":"NaN","text":"What does this print?

System.out.println(0.0 / 0.0);","options":["0.0","NaN","Infinity","ArithmeticException at runtime"],"correct":1,"explain":"0.0 / 0.0 is mathematically undefined, so doubles produce NaN (not a number) rather than throwing. A nonzero value divided by 0.0 gives Infinity instead."},{"id":"fs_z2_7_3","topic":"Money and doubles","text":"Why should a money balance never be stored in a double?","options":["double is too small to hold large balances","double values cannot be printed with two decimal places","Arithmetic on doubles is forbidden by the compiler","Binary floating point cannot represent most decimal fractions exactly"],"correct":3,"explain":"Fractions like 0.1 have no exact binary form, so repeated arithmetic drifts. Money should be stored as whole cents in an int or long, where every value is exact. Balances accumulate rounding errors."},{"id":"zf201","topic":"","text":"System.out.println(7.0 / 2); prints:","options":["3","3.0","4.0","3.5"],"correct":3,"explain":"One double operand makes the whole division floating-point.","difficulty":"medium"},{"id":"zf202","topic":"","text":"System.out.println(9 / 2.0); prints:","options":["4.5","4","4.0","5.0"],"correct":0,"explain":"The 2.0 promotes the division to double: 4.5.","difficulty":"medium"},{"id":"zf203","topic":"","text":"System.out.println(5.0); prints:","options":["5","5.0","5.00","05"],"correct":1,"explain":"Doubles always print with a decimal point, even for whole values.","difficulty":"medium"},{"id":"zf204","topic":"","text":"double x = 1.5; x = x + 2.25; System.out.println(x); prints:","options":["3.5","4.0","3.75","3.25"],"correct":2,"explain":"1.5 + 2.25 = 3.75; the variable is updated in place.","difficulty":"medium"},{"id":"zf205","topic":"","text":"System.out.println(1 / 2 + 0.5); prints:","options":["1.0","1","0","0.5"],"correct":3,"explain":"Trap: 1 / 2 is INT division = 0. Then 0 + 0.5 = 0.5.","difficulty":"medium"},{"id":"zf206","topic":"","text":"System.out.println(1 / 2.0 + 0.5); prints:","options":["1.0","0.5","1","0.75"],"correct":0,"explain":"Now the division is 0.5 (double), and 0.5 + 0.5 = 1.0.","difficulty":"medium"},{"id":"zf207","topic":"","text":"double d = 3; System.out.println(d); prints:","options":["3","3.0","error","0.3"],"correct":1,"explain":"The int 3 widens to double 3.0 automatically.","difficulty":"medium"},{"id":"zf208","topic":"","text":"System.out.println(10.0 / 4); prints:","options":["2","2.0","2.5","2.50"],"correct":2,"explain":"10.0 / 4 is double division: 2.5.","difficulty":"medium"},{"id":"zf209","topic":"","text":"A double is the right type for:","options":["a count of people","a single letter grade","a phone number to dial","a temperature like 98.6"],"correct":3,"explain":"Fractional measurements need floating point.","difficulty":"medium"},{"id":"zf210","topic":"","text":"Java stores doubles as:","options":["exact decimal digits","text","fractions with numerator and denominator","binary approximations - some decimals are not exact"],"correct":3,"explain":"That is why 0.1 + 0.2 famously prints 0.30000000000000004.","difficulty":"medium"},{"id":"zf211","topic":"","text":"For exact money arithmetic, the common advice is to:","options":["count whole cents in an int","use double and hope","round every line","use char"],"correct":0,"explain":"Whole cents avoid binary-fraction error entirely.","difficulty":"medium"},{"id":"zf212","topic":"","text":"double avg = (4 + 7) / 2.0; System.out.println(avg); prints:","options":["5.0","5.5","5","6.0"],"correct":1,"explain":"11 / 2.0 is double division = 5.5. With / 2 it would have been the int 5.","difficulty":"medium"}],"D286/u2/z2_8":[{"id":"zya2_8_0","topic":"Scientific notation form","text":"How is 2.5 x 10^3 written as a Java literal?","options":["2.5^3","2.5e3","2.5*10^3","2.5E-3"],"correct":1,"explain":"The e (or E) means "times ten to the power of". 2.5e3 is 2500.0."},{"id":"zya2_8_1","topic":"Value of 1e-3","text":"What is the value of 1e-3?","options":["1000.0","0.001","-1000.0","0.1"],"correct":1,"explain":"A negative exponent divides: 1 x 10^-3 = 0.001."},{"id":"zya2_8_2","topic":"Type of e-literals","text":"What type is the literal 5e2?","options":["int","double","float","long"],"correct":1,"explain":"Any literal in scientific notation is a double, even when the value is whole. 5e2 is 500.0, not 500."},{"id":"zya2_8_3","topic":"Large value readability","text":"Which literal is clearest for 6.02 x 10^23?","options":["602000000000000000000000.0","6.02e23","6.02^23","6.02*10e23"],"correct":1,"explain":"Scientific notation avoids counting zeros. Note 6.02*10e23 would be wrong anyway — it means 6.02 x 10 x 10^23."},{"id":"zya2_8_4","topic":"Printing e-notation","text":"System.out.println(1e7); prints:","options":["1e7","1.0E7","10000000","10000000.0"],"correct":1,"explain":"Java switches to E notation when printing doubles at or above 10^7."},{"id":"zya2_8_5","topic":"Small value","text":"0.00025 in scientific notation is:","options":["2.5e4","2.5e-4","25e-3","0.25e-4"],"correct":1,"explain":"Move the decimal point four places right to get 2.5, so the exponent is -4."},{"id":"zya2_8_6","topic":"e-notation with int type","text":"int n = 1e3; is:","options":["Valid, n is 1000","A compile error","Valid but n is 1","A runtime error"],"correct":1,"explain":"Assigning a double to an int requires an explicit cast: int n = (int) 1e3; 1e3 is a double."},{"id":"zya2_8_7","topic":"Underscore separator","text":"Which is a legal way to write one million as an int literal?","options":["1,000,000","1_000_000","1 000 000","1e6"],"correct":1,"explain":"Java allows underscores as digit separators for readability. Commas and spaces are not permitted, and 1e6 is a double."},{"id":"zy2_8_8_zb3","topic":"Scientific notation","text":"The literal 6.02e23 has type:","options":["float by default","int","double","String"],"correct":2,"explain":"e-notation floating-point literals are doubles.","__rebal":1},{"id":"fs_z2_8_1","topic":"e-notation value","text":"What does this print?

System.out.println(2.5e3);","options":["2.5000","2500.0","2500","250.0"],"correct":1,"explain":"The e means times ten to the power of, so 2.5e3 is 2500. Any literal in scientific notation is a double, so it prints with a decimal point: 2500.0."},{"id":"fs_z2_8_2","topic":"10e vs e","text":"Why is 6.02 * 10e23 the wrong way to write 6.02 times 10 to the 23rd power?","options":["10e23 already means 10 times 10 to the 23rd","Multiplication of literals is not allowed","e notation only works with negative exponents","6.02 cannot appear in scientific notation"],"correct":0,"explain":"The e already contains the times ten to the, so 10e23 is 1e24. The correct literal is simply 6.02e23. The result is ten times too large."},{"id":"fs_z2_8_3","topic":"Casting an e-notation literal","text":"What does this print?

int n = (int) 1e3;
System.out.println(n);","options":["Compiler error: a double cannot be cast to int","999","1000","1000.0"],"correct":2,"explain":"1e3 is the double 1000.0, so assigning it to an int requires the explicit cast, which truncates to 1000. Without the cast, int n = 1e3; is a compile error."},{"id":"fs_z2_8_4","topic":"Digit separators","text":"What does this print?

int big = 1_000_000;
System.out.println(big);","options":["1000000","1_000_000","Compiler error: underscores are not allowed in literals","1,000,000"],"correct":0,"explain":"Underscores inside a numeric literal are ignored by the compiler and exist purely for readability, so big holds one million and prints without separators. Commas, by contrast, are illegal."},{"id":"fs_z2_8_5","topic":"Mantissa and exponent","text":"A double literal like 6.02e23 is stored internally as:","options":["Two separate int variables","An exact decimal fraction","A mantissa and an exponent, mirroring scientific notation in binary","The full string of 24 decimal digits"],"correct":2,"explain":"A double's bits are split between a mantissa and an exponent - scientific notation in binary. The exponent buys range and the mantissa buys precision, and the fixed bit budget means one is always traded for the other."},{"id":"zf213","topic":"","text":"System.out.println(3e2); prints:","options":["30.0","3000.0","300.0","3e2"],"correct":2,"explain":"3e2 means the mantissa times ten to the exponent: 300.0.","difficulty":"medium"},{"id":"zf214","topic":"","text":"System.out.println(2.5e3); prints:","options":["250.0","25000.0","2.5e3","2500.0"],"correct":3,"explain":"2.5e3 means the mantissa times ten to the exponent: 2500.0.","difficulty":"medium"},{"id":"zf215","topic":"","text":"System.out.println(7.5e1); prints:","options":["75.0","7.5","750.0","7.5e1"],"correct":0,"explain":"7.5e1 means the mantissa times ten to the exponent: 75.0.","difficulty":"medium"},{"id":"zf216","topic":"","text":"System.out.println(1.2e-2); prints:","options":["0.12","0.012","0.0012","1.2e-2"],"correct":1,"explain":"1.2e-2 means the mantissa times ten to the exponent: 0.012.","difficulty":"medium"},{"id":"zf217","topic":"","text":"The letter e in the literal 6.1e3 means:","options":["the math constant e (2.718...)","an error marker","times ten raised to the power 3","times 3"],"correct":2,"explain":"6.1e3 = 6.1 x 10^3 = 6100.0.","difficulty":"medium"},{"id":"zf218","topic":"","text":"The type of the literal 3e2 is:","options":["int","float","String","double"],"correct":3,"explain":"Scientific-notation literals are floating point - double by default.","difficulty":"medium"},{"id":"zf219","topic":"","text":"45000.0 written in standard scientific notation is:","options":["4.5e4","4.5e-4","4.5e5","45.0e4"],"correct":0,"explain":"Standard form puts one digit before the point: 4.5 x 10^4 = 45000.","difficulty":"medium"},{"id":"zf220","topic":"","text":"0.0035 written in standard scientific notation is:","options":["3.5e-3","3.5e3","3.5e-4","35e-2"],"correct":0,"explain":"Move the point three places right: 3.5 x 10^-3 = 0.0035.","difficulty":"medium"},{"id":"zf221","topic":"","text":"A NEGATIVE exponent, as in 2e-3, indicates:","options":["a negative number","a value smaller than 1 (0.002)","an error","a very large value"],"correct":1,"explain":"Negative exponents divide by ten each step: 2e-3 = 0.002.","difficulty":"medium"},{"id":"zf222","topic":"","text":"Scientific notation is most useful for:","options":["counting small groups of people","storing names","very large or very small measurements","loop counters"],"correct":2,"explain":"Distances to stars or sizes of atoms are unreadable as plain decimals.","difficulty":"medium"},{"id":"zf223","topic":"","text":"double d = 4e0; System.out.println(d); prints:","options":["4","0.4","40.0","4.0"],"correct":3,"explain":"Ten to the zero is 1, so 4e0 is just 4.0.","difficulty":"medium"}],"D286/u2/z2_9":[{"id":"zya2_9_0","topic":"Declaring a constant","text":"Which declares a constant that cannot be changed?","options":["double final PI = 3.14;","const double PI = 3.14;","final double PI = 3.14;","static double PI = 3.14;"],"correct":2,"explain":"Java uses final, not const. The modifier goes before the type."},{"id":"zya2_9_1","topic":"Reassigning a final","text":"final int MAX = 10; MAX = 20; causes:","options":["A warning","A runtime exception","A compile error","MAX to become 20"],"correct":2,"explain":"The compiler enforces finality, so the mistake is caught before the program runs. Cannot assign a value to final variable."},{"id":"zya2_9_2","topic":"Constant naming convention","text":"Java convention names constants using:","options":["camelCase","PascalCase","ALL_CAPS with underscores","lowercase"],"correct":2,"explain":"MAX_SIZE, PI, DAYS_IN_WEEK. The visual difference signals "this never changes"."},{"id":"zya2_9_3","topic":"Why use constants","text":"The main benefit of a named constant over a literal is:","options":["The compiler substitutes it faster than a literal","It allows the value to be changed while running","It reduces the size of the compiled class file","One place to change the value, and the name explains it"],"correct":3,"explain":"Replacing scattered 0.08 literals with TAX_RATE means a rate change is a one-line edit, and the reader knows what the number means."},{"id":"zya2_9_4","topic":"Magic number","text":"A "magic number" is:","options":["Any number over 1000","A number that improves performance","An unexplained literal appearing directly in code","A constant declared final"],"correct":2,"explain":"if (x > 86400) is a magic number; if (x > SECONDS_PER_DAY) is not."},{"id":"zya2_9_5","topic":"final with static","text":"In a class, constants are usually declared:","options":["volatile","private int","public static final","final only inside methods"],"correct":2,"explain":"static means one shared copy rather than one per object; final means it cannot change. Together they express a class-level constant."},{"id":"zya2_9_6","topic":"final reference","text":"final int[] a = {1,2,3}; a[0] = 9; is:","options":["Allowed only for size 3","A compile error","Allowed","A runtime error"],"correct":2,"explain":"final locks the reference, not the object it points to. a = new int[5]; would be the error. Final prevents reassigning a, not modifying its contents."},{"id":"zya2_9_7","topic":"Constant initialization","text":"A final variable must be assigned:","options":["Any number of times, as long as the type matches","Only at declaration; a constructor cannot set it","Only inside a static initialiser block","Exactly once, at declaration or in the constructor"],"correct":3,"explain":"Assigning it a second time is a compile error; leaving it unassigned is also an error."},{"id":"zya2_9_8","topic":"Constant in a calculation","text":"final double TAX = 0.07; double total = price * (1 + TAX); This is preferred because:","options":["The multiplication is computed faster at runtime","final forces the compiler to use higher precision","The intent is readable and the rate changes in one place","The value can then be updated while running"],"correct":2,"explain":"Readability and single-point-of-change are the whole argument for constants."},{"id":"zya2_9_9","topic":"Compile-time constant","text":"final int SIZE = 10; int[] a = new int[SIZE]; is:","options":["A runtime error","Illegal — array sizes must be literals","Legal and idiomatic","Legal only if SIZE is static"],"correct":2,"explain":"Array sizes can be any int expression. Using a constant makes the size meaningful and easy to change."},{"id":"n_n2_9_a","topic":"Constants","text":"A constant is declared with:","options":["constant","final","const","static"],"correct":1,"explain":"final means the variable may be assigned once and never reassigned. const is a reserved but unused word in Java."},{"id":"n_n2_9_b","topic":"Constants","text":"Reassigning a final variable causes:","options":["Nothing — the last value wins","A compile error","A runtime exception","A warning"],"correct":1,"explain":"The compiler enforces finality, so the mistake is caught before the program runs."},{"id":"n_n2_9_c","topic":"Constants","text":"Naming a constant MAX_SPEED rather than maxSpeed:","options":["Follows the convention that constants are ALL_CAPS","Is required by the compiler for final variables","Makes the constant accessible from other classes","Marks the value as a compile-time constant"],"correct":0,"explain":"It is a convention, not a rule — but it signals to a reader that the value never changes."},{"id":"zf224","topic":"","text":"The keyword that makes a variable unchangeable after initialization is:","options":["final","const","static","fixed"],"correct":0,"explain":"final int DAYS = 7; Java has no usable const keyword - final is the tool.","difficulty":"medium"},{"id":"zf225","topic":"","text":"final int MAX_SEATS = 100; MAX_SEATS = 120; causes:","options":["MAX_SEATS to become 120","a compile error","a runtime exception","a warning only"],"correct":1,"explain":"Assigning to a final variable is rejected at compile time.","difficulty":"medium"},{"id":"zf226","topic":"","text":"By convention, Java constants are named:","options":["in camelCase, like taxRate","with a leading number","in ALL_CAPS with underscores","in quotes"],"correct":2,"explain":"The loud spelling signals "this never changes".","difficulty":"medium"},{"id":"zf227","topic":"","text":"Replacing a bare 0.07 scattered through code with final double TAX_RATE = 0.07;:","options":["makes the program run faster","is required by the compiler","changes the math","gives the value one authoritative home"],"correct":3,"explain":"Named constants kill "magic numbers" and prevent inconsistent edits.","difficulty":"medium"},{"id":"zf228","topic":"","text":"Math.PI is:","options":["a predefined double constant for pi","a method that computes pi","an int","a String"],"correct":0,"explain":"Java ships useful constants; Math.PI is about 3.141592653589793.","difficulty":"medium"},{"id":"zf229","topic":"","text":"final double RATE = 0.25; double fee = 40 * RATE; System.out.println(fee); prints:","options":["10","10.0","0.25","100.0"],"correct":1,"explain":"40 x 0.25 = 10.0 - printed with the decimal point because fee is a double.","difficulty":"medium"},{"id":"zf230","topic":"","text":"Which declaration best represents a value that should never change?","options":["int monthsPerYear = 12;","final int MONTHS_PER_YEAR = 12;","final int monthsPerYear;","MONTHS_PER_YEAR = 12;"],"correct":1,"explain":"final plus ALL_CAPS naming plus immediate initialization is the full pattern.","difficulty":"medium"},{"id":"zf231","topic":"","text":"Using a constant instead of retyping 9.8 for gravity helps because:","options":["doubles cannot be retyped","9.8 is illegal as a literal","a one-spot typo can no longer sneak in","constants use less memory"],"correct":2,"explain":"One definition means one place to be right.","difficulty":"medium"},{"id":"zf232","topic":"","text":"A final variable initialized from a calculation, like final int LIMIT = base + 10;:","options":["is a compile error","makes base final too","recomputes when base changes","legal - final locks the computed result"],"correct":3,"explain":"final freezes the RESULT; it does not track the inputs afterwards.","difficulty":"medium"},{"id":"zf233","topic":"","text":"Trying to use const as a keyword, as in const int x = 5;:","options":["does not compile","works exactly like final","declares a constant faster","is the preferred style"],"correct":0,"explain":"const is reserved-but-unused; final is the Java way.","difficulty":"medium"},{"id":"zf234","topic":"","text":"Good candidates for constants include:","options":["loop counters","values fixed by the problem","user input","running totals"],"correct":1,"explain":"Things that vary belong in variables; things that cannot vary belong in constants.","difficulty":"medium"},{"id":"zf860","topic":"","text":"final int LIMIT = 50; System.out.println(LIMIT + 5); prints:","options":["50","5","55","a compile error"],"correct":2,"explain":"Reading a constant is always fine - only reassignment is forbidden.","difficulty":"medium"}],"D286/u2/z2_10":[{"id":"zya2_10_0","topic":"Math.pow return type","text":"What does Math.pow(2, 3) return?","options":["8.0 as a double","2^3 as a String","A compile error","8 as an int"],"correct":0,"explain":"Math.pow always returns a double, so assigning to an int needs a cast."},{"id":"zya2_10_1","topic":"Math.abs","text":"Math.abs(-7) returns:","options":["7","0","7.0","-7"],"correct":0,"explain":"abs is overloaded — given an int it returns an int, given a double it returns a double."},{"id":"zya2_10_2","topic":"Math.sqrt of a negative","text":"Math.sqrt(-4) returns:","options":["NaN","A runtime exception","2.0","-2.0"],"correct":0,"explain":"NaN means "not a number". It does not throw, so a negative slipping into sqrt silently poisons later arithmetic — every comparison with NaN is false."},{"id":"zy2_10_3_zb4","topic":"Math methods","text":"Math.pow and Math.sqrt always return:","options":["double","int","boolean","String"],"correct":0,"explain":"Both return double even for whole-number results.","__rebal":1},{"id":"zy2_10_4_lg_D286_2_3","topic":"Math","text":"What does Math.pow(3, 2) + Math.sqrt(9) evaluate to?","options":["6.0","12.0","12","9.0"],"correct":1,"explain":"9.0 + 3.0 = 12.0 (both return double).","__rebal":1},{"id":"zy2_10_5_zb1","topic":"Math.pow","text":"Math.pow(2, 3) returns:","options":["6.0","8","9.0","8.0"],"correct":3,"explain":"pow returns a double, so the result is 8.0.","__rebal":1},{"id":"zy2_10_6_zb2","topic":"Math.sqrt","text":"Math.sqrt(16) returns:","options":["2.0","4","4.0","8.0"],"correct":2,"explain":"sqrt returns a double: 4.0.","__rebal":1},{"id":"zy2_10_7_zb3","topic":"Math.max","text":"Math.max(3, 7) returns:","options":["21","7","10","3"],"correct":1,"explain":"max picks the larger of the two arguments.","__rebal":1},{"id":"zy2_10_8_lg_D286_1_50","topic":"Math","text":"Math.sqrt returns which type?","options":["int","float","double","long"],"correct":2,"explain":"Math.sqrt always returns double.","__rebal":1},{"id":"zy2_10_9_lg_D286_1_64","topic":"Math.round","text":"Math.round(2.6) returns:","options":["2.6","2","2.5","3"],"correct":3,"explain":"round goes to the nearest whole number: 3.","__rebal":1},{"id":"fs_z2_10_1","topic":"pow returns double","text":"What does this print?

