static <K, V> V lookupEquals(K[] keys, V[] values, K target, V fallback) {
    for (int i = 0; i < keys.length; i++) {
        if (keys[i].equals(target)) { return values[i]; }
    }
    return fallback;
}
static <K, V> V lookupSame(K[] keys, V[] values, K target, V fallback) {
    for (int i = 0; i < keys.length; i++) {
        if (keys[i] == target) { return values[i]; }
    }
    return fallback;
}

