public static boolean hasValidChars(String d) {
    for (int i = 0; i < d.length(); i++) {
        char c = d.charAt(i);
        if (!Character.isLetterOrDigit(c) && c != '.' && c != '-') {
            return false;
        }
    }
    return true;
}

public static boolean isValidDomain(String d) {
    return d != null && d.length() >= 3 && d.contains(".") && hasValidChars(d);
}

System.out.println(isValidDomain("my site.com"));
