static void permute(char[] a, int k) {
    if (k == a.length) {
        System.out.println(new String(a));
        return;
    }
    for (int i = k; i < a.length; i++) {
        swap(a, k, i);
        permute(a, k + 1);
        swap(a, k, i);
    }
}

static void swap(char[] a, int i, int j) {
    char t = a[i];
    a[i] = a[j];
    a[j] = t;
}

